// PvP online · canal efímero de FX. El snapshot conserva el estado lógico;
// este canal reproduce el trayecto visual exacto en el segundo navegador.
let ONLINE_FX_REPLAY_DEPTH = 0;

function emitOnlineVisualEvent(type, payload = {}) {
  if (ONLINE_FX_REPLAY_DEPTH > 0) return false;
  try {
    if (!ROK_ONLINE_MATCH_ACTIVE || typeof window.ROK_ONLINE_PVP?.emitVisualEvent !== 'function') return false;
    void window.ROK_ONLINE_PVP.emitVisualEvent(type, payload);
    return true;
  } catch (_) {
    return false;
  }
}

function commitOnlineStateBarrier(reason = 'critical-state') {
  try {
    if (!ROK_ONLINE_MATCH_ACTIVE || typeof window.ROK_ONLINE_PVP?.commitStateBarrier !== 'function') return Promise.resolve(true);
    return Promise.resolve(window.ROK_ONLINE_PVP.commitStateBarrier(reason)).catch(error => {
      reportDebugError(`online-state-barrier:${reason}`, error);
      return false;
    });
  } catch (error) {
    reportDebugError(`online-state-barrier:${reason}`, error);
    return Promise.resolve(false);
  }
}

function markOnlineStateDirty(reason = 'state-change') {
  try {
    if (!ROK_ONLINE_MATCH_ACTIVE || typeof window.ROK_ONLINE_PVP?.markStateDirty !== 'function') return false;
    return Boolean(window.ROK_ONLINE_PVP.markStateDirty(reason));
  } catch (_) {
    return false;
  }
}


// v487 · Todos los modales/HUD estructurales viven dentro del lienzo lógico.
// Los FX que trabajan con coordenadas físicas del viewport permanecen en body.
function getRokUiStage() {
  return document.getElementById('rokAppStage') || document.body;
}

function appendRokUiNode(node) {
  if (!node) return node;
  getRokUiStage().appendChild(node);
  return node;
}

function snapshotOnlineFxUnit(playerId, unit) {
  if (!unit) return null;
  return {
    playerId: Number(playerId || 0),
    unitId: unit.id || null,
    cardId: unit.cardId || null,
    row: Number(unit.row ?? 0),
    col: Number(unit.col ?? 0),
  };
}

function snapshotOnlineFxTarget(target) {
  if (!target) return null;
  const pos = typeof getTargetBoardPosition === 'function' ? getTargetBoardPosition(target) : null;
  return {
    type: target.type || 'cell',
    playerId: Number(target.playerId || 0),
    unitId: target.unitId || null,
    guardianId: target.guardianId || null,
    row: Number(target.row ?? pos?.row ?? 0),
    col: Number(target.col ?? pos?.col ?? 0),
  };
}

function onlineFxVirtualUnit(payload = {}) {
  return {
    id: payload.unitId || `online-fx-${Date.now()}`,
    cardId: payload.cardId || '',
    row: Number(payload.row ?? 0),
    col: Number(payload.col ?? 0),
    status: 'active',
  };
}

