function getOnlineFxInvocationFromRef(ref) {
  if (!ref || ref.unitId == null || ref.playerId == null) return null;
  const unit = getUnitById(Number(ref.playerId), ref.unitId);
  return unit ? { ownerPlayerId: Number(ref.playerId), unit } : null;
}

function shouldSuppressOnlineFxForHiddenOpponent(type, payload = {}) {
  if (!isOnlineMatchActive() || LOCAL_PLAYER_ID == null) return false;
  const sourceRef = getOnlineFxInvocationFromRef(payload.source || payload);
  const targetRef = getOnlineFxInvocationFromRef(payload.target || null);
  const sourceHidden = sourceRef && isOnlineUnitConcealedFromViewer(sourceRef.ownerPlayerId, sourceRef.unit);
  const targetHidden = targetRef && isOnlineUnitConcealedFromViewer(targetRef.ownerPlayerId, targetRef.unit);
  if (sourceHidden) return true;
  if (targetHidden) {
    const targetRevealingTypes = new Set([
      'floating-text', 'floating-damage', 'critical-damage', 'critical-slash',
      'armor-reduction', 'blindness-debuff', 'kurayami-execution-cue',
      'kurayami-execution-damage', 'shirahadori-redirect', 'minokage-hit-slash'
    ]);
    if (targetRevealingTypes.has(String(type || ''))) return true;
  }
  return false;
}

function getOnlineFxPolicy(type) {
  const definition = ONLINE_FX_DEFINITIONS[String(type || '')];
  if (!definition) return null;
  return {
    playbackMode: definition.playbackMode === 'parallel' ? 'parallel' : 'serial',
    maxReplayAgeMs: Math.max(1000, Number(definition.maxReplayAgeMs || 9000)),
  };
}

async function playOnlineVisualEvent(event = {}) {
  const type = String(event.type || '');
  const definition = ONLINE_FX_DEFINITIONS[type];
  if (!definition) {
    ONLINE_FX_RUNTIME_STATS.unsupported += 1;
    return false;
  }
  const generation = ONLINE_FX_RUNTIME_GENERATION;
  const payload = event.payload || {};
  if (shouldSuppressOnlineFxForHiddenOpponent(type, payload)) return false;
  let playbackResult;
  ONLINE_FX_REPLAY_DEPTH += 1;
  try {
    if (generation !== ONLINE_FX_RUNTIME_GENERATION) return false;
    // Los handlers emiten, si corresponde, al inicio síncrono de la función.
    // El guard solo cubre ese tramo para no silenciar acciones LOCALES mientras
    // una animación remota larga continúa con awaits o timers.
    playbackResult = definition.play(payload, event);
  } catch (error) {
    ONLINE_FX_RUNTIME_STATS.failed += 1;
    try { reportDebugError(`online-fx-play:${type}`, error); } catch (_) {}
    return false;
  } finally {
    ONLINE_FX_REPLAY_DEPTH = Math.max(0, ONLINE_FX_REPLAY_DEPTH - 1);
  }
  try {
    await playbackResult;
    if (generation !== ONLINE_FX_RUNTIME_GENERATION) {
      removeOnlineVisualFxNodes();
      return false;
    }
    registerOnlineFxPlay(type);
    return true;
  } catch (error) {
    ONLINE_FX_RUNTIME_STATS.failed += 1;
    try { reportDebugError(`online-fx-play:${type}`, error); } catch (_) {}
    return false;
  }
}


window.ROK_ONLINE_FX = {
  play: playOnlineVisualEvent,
  getPolicy: getOnlineFxPolicy,
  cancelAll: cancelOnlineVisualFxRuntime,
  getStats: () => ({ ...ONLINE_FX_RUNTIME_STATS, byType: { ...ONLINE_FX_RUNTIME_STATS.byType }, generation: ONLINE_FX_RUNTIME_GENERATION }),
  resetStats: () => {
    ONLINE_FX_RUNTIME_STATS.played = 0;
    ONLINE_FX_RUNTIME_STATS.cancelled = 0;
    ONLINE_FX_RUNTIME_STATS.unsupported = 0;
    ONLINE_FX_RUNTIME_STATS.failed = 0;
    ONLINE_FX_RUNTIME_STATS.byType = {};
  },
  getSupportedTypes: () => Object.keys(ONLINE_FX_DEFINITIONS),
};

const PATCH_NOTES = [
  'v543: PvP Online · corrige la compuerta real de inicio. Al entrar ambos jugadores en LISTO, la presentación VS pasa al frente y el lobby se oculta durante la cinemática. Piedra/Papel/Tijera se vuelve una pausa local explícita del gameplay online y la guardia de inactividad queda desactivada hasta terminar iniciativa + introducción de elementos. El cliente invitado ya infiere correctamente el estado awaiting-initiative desde openingElementsDealt=false, por lo que también abre RPS en la primera partida. La compuerta de intro se identifica por sala+matchSerial para que una sala nueva con serial 1 no herede el bloqueo de una partida anterior. Tras resolver RPS, ambos clientes establecen localmente opening-intro, esperan el reparto autoritativo y desbloquean la partida solo al concluir la introducción inicial.',
  'v542: Restaura los Spellbooks base permanentes Deck básico Hattori (27/30) y Deck básico Tokugawa (30/30). Los presets se fusionan con los Spellbooks locales aunque localStorage esté vacío, aparecen en Mis Spellbooks, Player vs Bot y Versus Online, y son utilizables como mazos de prueba sin exigir colección. Los presets son de solo lectura para evitar que se pierdan; se pueden duplicar para editar. El almacenamiento local conserva únicamente mazos creados por el usuario y evita duplicados históricos por nombre/id.',
  'v541: Segunda calibración experimental de Estasis de Spellbook para cartas iniciales/baratas. La duración base por Costo se mantiene (0→5, 1→4, 2→3, 3→2, 4→1, 5+→0), pero el descuento PB se escala linealmente desde 5 fases=-800 hasta 0 fases=0: 4=-640, 3=-480, 2=-320 y 1=-160. El objetivo es que el tempo barato no convierta por sí solo cartas comunes en rarezas altas.',
  'v540: Calibración experimental de Estasis de Spellbook para reducir la inflación de PB en Invocaciones de bajo costo. La duración base por Costo no cambia (0→5, 1→4, 2→3, 3→2, 4→1, 5+→0 fases), pero el descuento PB se vuelve más agresivo: 5 fases=-450, 4=-350, 3=-250, 2=-150, 1=-50 y 0=0. Costo, Kasteo y Restauración conservan sus curvas positivas actuales; este ajuste se prueba antes de seguir recalibrando rarezas carta por carta.',
  'v539: Junkai butai #2 sustituye Parálisis 2 por Atadura 2. Atadura usa dos comprobaciones PDA por cambio de fase —Movimiento y Ataque— con el mismo margen del nivel, mantiene duración por nivel y usa el nuevo icono de cadenas. Velocidad de ataque y Atadura usan modales semánticos normalizados y PB Universal.',
  'v581: Revisión de Kurokage · Kurokagi butai #3 pasa a llamarse Kurokage. Buki Utsushi migra al sistema semántico como un único Poder dividido en tres etapas: disparador de Desarmar al dañar, captura activa de un arma caída y cambio activo entre armas disponibles. Usa Poder → Disparador / Activa → Físico → Táctico → Desarmar y pbEffects universales; el escalado multiobjetivo de Desarmar se declara mediante factorApplications. Desarmar deja de indicar que Restauración recupera el arma: permanece hasta recuperarla, elimina la línea redundante de Probabilidad en su modal y Kurokage ya no requiere Kusarigama conjuntamente para habilitarlo; Asesino continúa como fuente. Desarmar 3 de Kurokage usa 3 PDA de forma explícita.',
  'v580: Revisión de Junkai butai #1 · pasa a Ataque 3 / Vida 3, Costo 0, Kasteo 0 y Restauración 0; conserva Golpe 1 al quedar sin Espada, Golpe crítico 1 y Penetración de armadura 1. Penetración de armadura usa su icono correcto aportado por el usuario. El PB Universal incorpora la capacidad de Habilidades como +35 PB por cada slot disponible para todas las cartas; el antiguo +35 provisional por Habilidad legada deja de duplicarse. Golpe crítico se normaliza para no multiplicar el daño cuando una defensa Física efectiva sigue interponiéndose, salvo efectos que ignoren Factores Físicos Defensivos como Shizukesa no Shi-in.',
  'v579: Revisión de Ichikawa Goemon · Densetsu no Sennyū migra al sistema semántico como Poder → Disparador → Virtual → Táctico → Movilidad y deja de mostrar prosa técnica de rutas, estelas o sinergias. Botín valioso migra como Habilidad → Pasiva → Virtual → Táctica → Saqueo, elimina la descripción visual y usa pbEffects universales para el robo de 1 recurso con 3 PDA tras causar al menos 1 de daño real al Kaster rival. Goemon deja de usar PB legado para Poder/Habilidad y su tag general deriva Movilidad · Saqueo. La taxonomía añade Habilidad, Táctico como orientación y los enfoques Movilidad/Saqueo. El segundo Poder de Kurayami recibe el nombre Shinobi no Kōshin.',
  'v578: Estasis de Spellbook recibe modal informativo propio y reutilizable bajo Estadística de casteo → Estasis de Spellbook. El chip ahora es clicable incluso cuando la Estasis base es 0 en una Invocación, explica la relación inversa con el Costo, separa Estasis de Restauración y muestra por separado la base y los modificadores aprendidos. La fila de Costo / Tiempo de casteo / Restauración / Estasis se normaliza a cuatro posiciones alineadas para que la Estasis no caiga visualmente por debajo de las otras estadísticas.',
  'v577: Etapa 6 · reemplaza el perfil general estimado por tags semánticos reales. Daño/Vida solo aportan Daño o Resistencia cuando cumplen los umbrales acordados (diferencia de 5 o ambos valores fuertes), Velocidad aporta tag únicamente desde 6, y los Enfoques finales de Factores y Poderes semánticos se incorporan automáticamente sin duplicados. Se eliminan el ranking arbitrario, los modificadores focusScoreModifiers, el relleno forzado a tres tags y los fallbacks Resistencia/Movilidad/Tempo. Habilidades quedan preparadas para entrar al mismo sistema cuando reciban semanticBranches. La búsqueda de Biblioteca incorpora la taxonomía semántica de Factores/Poderes, incluyendo orientación Ofensivo/Defensivo y sus alias naturales.',
  'v576: Etapa 5 · Poderes semánticos y PB Universal de Kurayami. La carta puede exponer varios Poderes independientes sin romper la referencia primaria usada por combate. Shizukesa no Shi-in queda como Poder activo y la antigua aura Ninja se separa como segundo Poder pasivo con nombre técnico provisional hasta recibir nombre canónico. Cada Poder usa Poder → activación → categoría → orientación → enfoque(s), y el calculador PB suma efectos estructurados por Poder, incluyendo costos, canalización, Oculto, daño, bypass físico-defensivo, ejecución, enfriamiento y los bonos de Velocidad/Precisión. Las aplicaciones de Factores dentro de Poderes soportan escalado adicional por cantidad de objetivos sin duplicar el valor base de un Factor ya nativo.',
  'v575: Etapa 4 de normalización de modales · los Factores usan una taxonomía global Factor → activación → categoría → orientación → enfoque, con las tres primeras capas consultables y colores jerárquicos derivados del Dominion de la carta. Se elimina Clasificación y el listado legado de tags del modal de Factor. Golpe crítico adopta Factor → PDA → Físico → Ofensivo → Daño y su explicación integra PDA/multiplicador sin repetir Probabilidad de acierto. Se deja una base semántica reutilizable para todos los Factores y para filtros/perfiles posteriores.',
  'v574: Etapa 3 de normalización de modales · unifica Costo, Tiempo de casteo y Restauración bajo Estadística de casteo; separa Restauración de Estasis de Spellbook y corrige su definición al retorno al Nexo tras combate/ataque al Kaster. Movilidad, Velocidad y Biotipo pasan a Estadística de desplazamiento. La Movilidad describe el patrón de desplazamiento, Velocidad cuántas casillas puede recorrer al aplicarlo y Biotipo únicamente la adaptación al entorno propio sin mezclar penalizaciones de otros biomas. El modal de Tiempo de casteo aclara que mientras el Kaster ejecuta el casteo no puede atacar ni defenderse.',
  'v573: Etapa 2 de normalización de modales · unifica la línea ofensiva y Vida bajo tags semánticos reutilizables. Arma/Ataque distingue arma base de ataque nativo, elimina Consumo en armas base no consumibles y deja Espada como Arma → Base → Cuerpo a cuerpo. Modo de combate usa un único tag con su modo; Alcance y Precisión usan Estadística ofensiva → propiedad, con Precisión explicada mediante PDA. Tipo y aplicación de daño también reducen sus tags a una cadena semántica estable. Vida usa Estadística defensiva → Vida máxima, elimina la repetición del valor base y aclara curación frente a Vida máxima.',
  'v572: Etapa 1 de normalización de modales · establece una base reutilizable para Tipo de carta, Familia, Raza y Cualidad; el modal de Tipo deja de mostrar datos de arma y usa definiciones del ruling, Raza deja de superponer el género sobre su icono y Raza/Cualidad eliminan Clasificación redundante. Los tags identitarios pasan a jerarquía semántica (Familia → nombre → enfoques, Raza → nombre → enfoques, Cualidad → nombre → enfoques). Kurayami cambia de Humano a Demonio y Asesino recibe descripción global no dependiente de una carta concreta.',
  'v571: Corrige Estasis de Spellbook según la relación inversa canónica con el costo: Costo 0→5 fases, 1→4, 2→3, 3→2, 4→1 y 5+→0. El descuento PB usa la misma curva de Costo en sentido inverso por duración: 5 fases=-200, 4=-160, 3=-120, 2=-85, 1=-55 y 0=0. Así una invocación de Costo 1 muestra Estasis 4 y descuenta -160 PB.',
  'v570: PB universal v1 · reemplaza la valoración aislada de Factores por un motor semántico común para efectos, Poderes y Habilidades estructuradas. Daño+Vida pasan a una sola curva combinada hasta 70; Precisión escala hasta 15; Velocidad suma desde 1 hasta 10; Costo/Kasteo/Restauración conservan curvas independientes y Estasis de Spellbook aplica la curva inversa acordada. La cantidad de objetivos usa una curva marginal con crecimiento fuerte en 6–8 y caída de aporte hasta 0 en el objetivo 13; aliados/rivales se valoran algebraicamente según si el efecto es positivo o negativo. Duración, frecuencia, probabilidad, condiciones y cobertura de tipo actúan como moduladores acotados. Poderes/Habilidades todavía no migrados conservan un fallback legado identificado en DEBUG PB hasta revisarlos carta por carta. La rareza visual de cartas normales vuelve a salir exclusivamente del PB calculado; forceRarityId queda reservado para muestras/debug explícitos.',
  'v569: Rarezas · actualiza la jerarquía lógica canónica a 1 Ordinaria, 2 Poco ordinaria, 3 Infrecuente, 4 Inhabitual, 5 Extraordinaria, 6 Extraña, 7 Singular, 8 Legendaria y 9 Mítica. Conserva los sprites/íconos actuales sin añadir numeración visual. Los rangos PB, bonos, orden de sorteo y pesos de booster se reasignan por nivel. El ícono de rareza del modal de carta ahora abre una consulta informativa con nivel, grupo y descripción.',
  'v568: Ajustar Tokens · corrige el fallo de render al combinar una misma pieza visual presente en ambos jugadores: el conjunto de propietarios se normaliza a Array antes de componer la etiqueta Tuyo / Rival. El panel ya no interrumpe renderAll ni rompe la arena al refrescar su listado.',
  'v568: Ajustar Tokens · elimina por completo el foil/clon y cualquier clase de selección aplicada a la ficha durante la edición. La pieza seleccionada conserva exactamente su render y tamaño real; el editor solo añade una pequeña burbuja azul como indicador, sin wrappers ni transformaciones adicionales.',
  'v567: Editor VS · el ajuste universal de Kasters e invocaciones se refleja inmediatamente incluso sobre la pieza individual seleccionada, combinando en vivo universal + ajuste individual sin guardar. La invocación destacada del Spellbook deja de usar transparencia al completar su entrada y el Kaster recibe una sombra paralela coloreada según su Dominion.',
  'v567: Ajustar Tokens deja de transformar el contenedor completo de la ficha: escala/offset afectan únicamente al sprite y a su hitbox compartiendo las mismas variables, sin alterar estadísticas ni overlays. La selección del editor usa foil + indicador azul sin cambiar geometría. El rango de escala sube a x6. Abrir la herramienta adquiere pausa global de gameplay y pausa las animaciones de arena hasta cerrarla.',
  'v566: Corrige la herramienta Ajustar Tokens: ahora enumera las piezas visibles de ambos jugadores (Kasters, invocaciones y Guardianes/estructuras presentes en arena), y la transformación visual se aplica de forma aislada a cada .unit completa para que cambiar la selección nunca transfiera ni multiplique la escala/offset de otra ficha. Token e hitbox se escalan y desplazan juntos. Guardar CSS exporta la nueva lógica estable.',
  'v565: Farolera · Farol Enlazado usa una sola miniatura/persistente de acción para ambas etapas: el mismo botón cambia entre Poder · Etapa 1 y Poder · Etapa 2 y la ventana permanece capturada hasta confirmar/cancelar cada targeting. Se evita cualquier duplicado por unidad. Regla global: una invocación que ya atacó en la Resolución no recupera movimiento al restaurarse, incluso con Restauración 0.',
  'v564: Etapa 3/4 · sustituye por completo el proyectil visual de Magia: ya no reutiliza la flecha del ataque a distancia. Los ataques mágicos disparan un orbe-cometa circular con núcleo luminoso, varias estelas/afterimages y una pequeña explosión arcana al impactar.',
  'v564: Etapa 4/4 · Herramienta temporal de ajuste de tokens: botón superior izquierdo durante combate, listado de Kaster/invocaciones/estructuras/Guardianes relevantes del jugador local, escala y offsets X/Y en vivo para token + hitbox, persistencia local y exportación mediante Guardar CSS.',
  'v561: Farolera del Umbral · Farol Enlazado pasa a dos activaciones reales: Etapa 1 fija solo el círculo y conserva movilidad; Etapa 2 abre después la selección del farol, lo lanza con vuelo desde la Farolera y escala +35% a mitad de trayectoria, y bloquea nuevas activaciones al completar el portal. El círculo se reduce 30% y sus FX persistentes ya no reinician en cada render. Los ataques con Magia usan ahora un orbe-cometa con estela e impacto mágico en lugar de la flecha genérica. El HUD compacto muestra Kiara sin el subtítulo largo.',
  'v560: Kiara · integra Farolera del Umbral como primera invocación Hechicero de Agua: 2/2, Magia a distancia, alcance 3, PDA 4, velocidad 2, costo 0 y 1 slot. Farol Enlazado crea un círculo en su casilla y permite lanzar la lámpara a radio 4; cualquier invocación Hechicero que ENTRE al círculo se teletransporta a la lámpara. Reutiliza el círculo de invocación, sprite dedicado de lámpara y vínculo mágico con lógica de color.',
  'v559: Revancha · unifica el ciclo de vida de Player vs Bot y PvP Online: al terminar un match se cancelan inmediatamente los runtimes pendientes; la revancha reconstruye el estado completo y Piedra/Papel/Tijera vuelve a ejecutarse antes de repartir elementos o entrar en Extracción. Aventura muestra el nivel asignado del Kaster rival también en la ficha y Preparar combate.',
  'v558: Aventura · completa la base de progresión/recompensas de Kaster: XP por primera victoria y repetición, recompensa única con booster elemental Nivel 1 reservado + carta aleatoria del Spellbook rival, y recompensas repetibles de recurso elemental + 2 rarezas aleatorias. La recompensa queda preparada para conectarse al cierre real del combate.',
  'v557: Aventura · la selección de Kaster en la dungeon muestra el nivel de cada rival. En la primera campaña de Agua, los encuentros 1–4 son nivel 1 y el jefe Aurek es nivel 4.',
  'v556: Aventura · navegación directa: las tarjetas de región disponibles entran al área al hacer clic y las tarjetas de Kaster disponibles abren Preparar combate directamente. Se eliminan los botones redundantes Entrar al área y Preparar combate; hover/focus conserva la previsualización sin navegar.',
  'v552: Estabiliza los elementos agrupados del HUD rival. El layout agrupado/individual se decide en una sonda invisible antes de tocar el HUD visible, evitando que cada render muestre primero los elementos sueltos y un frame después vuelva a agruparlos.',
  'v551: Etapa 1 completa · todas las acciones activas de invocaciones implementadas usan una sola ventana de oportunidad y el mismo stack persistente Info/Poder. Yasugana, Kurokagi, Gioshonin y Kishimoto se integran al flujo unificado; se retira la ventana heredada independiente de Mercancía de guerra y los modales encadenados conservan el bloqueo hasta resolver o cancelar.',
  'v550: Etapa 1 · unifica las ventanas de acción de invocaciones: Kaguya, Minokage y cualquier unidad elegible ya no crean una segunda miniatura. Al capturar la oportunidad se resaltan simultáneamente todas las fichas elegibles y se usan sus miniaturas persistentes normales con Info/Poder; el flujo permanece único hasta activar o descartar y libera correctamente la fase.',
  'v549: PvP · Oculto se vuelve privacidad real de combate: la invocación rival no genera token ni capas persistentes, queda fuera de toda selección directa (ataques, poderes, Emboscada e Interceptar) y no revela daño/retorno visual al oponente; los impactos indirectos de área, barrido o trayectoria siguen resolviendo normalmente.',
  'v548: Aventura · Kiara recibe una arena propia con preview dedicado en Preparar combate y arte cenital de batalla; el sistema de encuentros queda preparado para asignar preview/arena individual a cada Kaster. El Kaster inicial del jugador pasa a llamarse Lioren.',
  'v534: Restaura la composición canónica de la zona de kasteo sobre el lienzo lógico 1600x900: carril de 150 px, slots 100x138, miniaturas 58x74/54x54, reloj y contador en tamaño original, ACTIVO/COLA por encima del token y cola sin scrollbar interno.',
  'v533: Unifica la geometría de FX heredados con el sistema lógico 1600x900: Minokage (Shippū Ugachi, pasiva y Evasión), proyectiles a distancia, Shirahadori, cadena persistente de Parálisis de Junkai, caída/recuperación de armas, recompensas del Guardián y extracción elemental dejan de mezclar píxeles físicos del viewport con coordenadas internas de boardContent.',
  'v532: Corrige la trayectoria de los cuervos de Genyutsu, Shinigami Karasu de Yasugana Hattori: los anclajes de salida y objetivo se convierten de coordenadas físicas del viewport a coordenadas lógicas de #rokAppStage antes de dibujar el proyectil, evitando que la animación salga corrida al redimensionar.',
  'v531: Corrige la zona de kasteo tras la escala universal: restaura el slot lógico 100x138 y las coordenadas base de token, hechizo, reloj/contador y etiquetas ACTIVO/COLA. Los hijos dejan de recalcularse por porcentajes del slot reducido y ahora escalan únicamente con #rokAppStage.',
  'v530: Sustituye el aviso flotante de clic derecho por un botón Cancelar la acción dentro del HUD de fases, justo sobre Movimiento asistido. El clic derecho en PC y el botón táctil/móvil ejecutan la misma cancelación sin quedar detrás del HUD rival.',
  'v516: Repara la regresión estructural introducida en v512 que eliminó accidentalmente 160 funciones del flujo principal (kasteo, restauración, render general, HUD overlay, mini HUD rival y controles de arena). Restituye el bloque funcional sin retirar los cambios posteriores de v513/v514.',
  'v505: Minokage: corrige el trail de sombras desalineado por mezcla de coordenadas viewport/stage, aplica el mismo trail al dash final de Shippū, sustituye la X de impacto por 2–3 slashes del nuevo asset, mantiene el giro lento durante acercamiento y rápido al impacto, fuerza el retiro con fallback, excluye Guardianes del salto pasivo y vuelve a trabarlo con estructuras; restauración natural 3 y restauración forzada posterior al poder 6.',
  'v504: Biblioteca: permite elegir copias de una carta antes de tener un Spellbook activo y, al confirmar, abre un selector de Spellbook de destino que valida compatibilidad, dominios, copias y espacio. Constructor: al salir con cambios sin guardar pregunta si deseas Guardar y salir, Salir sin guardar o Cancelar.',
  'v513: Separa Estasis de Spellbook y habilidades aprendidas por copia física de carta mediante un ID persistente de instancia. Varias Kagero/Kaguya iguales ya no comparten enfriamiento ni estado aprendido al morir, regresar o rekastearse.',
  'v512: Unifica la selección visual de fichas en arena: cualquier invocación, Guardián o Kaster seleccionable usa el mismo foil de acción y punto amarillo. Retira glifos especiales de Minokage, Kaguya, Kurayami y Yasugana y elimina el halo distinto usado por Shirahadori/Despliegue.',
  'v525: Shirahadori ahora puede responder a otro Shirahadori. Cada contraataque reflejado se trata como una nueva instancia física y encadena nuevas comprobaciones PDA hasta que una falla y recibe el impacto, o una devolución queda fuera de rango.',
  'v526: Shirahadori muestra disponibilidad directa en el Spellbook con foil y burbuja amarilla cuando realmente puede usarse, sin crear ventana de acción. Cuando no hay usuario legal permanece únicamente en gris, sin rótulo BLOQUEADA.',
  'v527: Shirahadori sanea habilidades aprendidas por copia para que una misma habilidad nunca acumule su +3 más de una vez, y espacia cada eslabón de las cadenas de contraataques para que detección, PDA, desvío e impacto se lean visualmente antes del siguiente Shirahadori.',
  'v528: Bomba de humo deja de usar el anclaje dinámico junto a Sutoka y vuelve a la ventana de acción normal; la zona de kasteo normaliza miniaturas y contadores con coordenadas relativas para conservar su alineación bajo la escala universal.',
  'v520: Reescribe la compatibilidad de Shirahadori con una cadena estricta y centralizada: Invocación → Guerrero/Asesino → Espada explícitamente compatible → Cuerpo a cuerpo. El arma base nunca cuenta; una espada pesada/no marcada tampoco. Carta y habilidad se bloquean dinámicamente usando el mismo evaluador.',
  'v519: Shirahadori queda gris en el Spellbook cuando no existe ningún usuario legal en arena y no puede arrastrarse/activarse. Si una invocación que ya aprendió Shirahadori pierde su arma principal y no conserva una secundaria cuerpo a cuerpo válida, la habilidad permanece aprendida pero aparece BLOQUEADA y deja de dispararse hasta recuperar un arma compatible.',
  'v518: Shirahadori se resuelve universalmente por objetivo sin interrumpir animaciones multiblanco; el contraataque de Oscilación parcial se difiere hasta terminar el barrido. Excluye por regla el arma base y exige Guerrero/Asesino con arma principal o secundaria cuerpo a cuerpo.',
  'v517: Corrige Shirahadori con ataques de Rango/Oscilación parcial por objetivo sin cancelar el barrido, restaura clic derecho para cancelar movimiento extra del Kaster y Bomba de humo, alinea Junkai #2 y reubica las acciones rápidas para no quedar detrás del HUD.',
  'v511: Corrige el arranque del modo de prueba: la constante del Spellbook de prueba ya no referencia SHIRAHADORI_ABILITY_CARD_ID antes de su inicialización; usa el id estable abilityShirahadori y evita el ReferenceError que detenía init().',
  'v510: Reconfigura exclusivamente el bot del modo de prueba para validar Shirahadori: reemplaza Minokage/Táctica por 3 Kagero + 3 Shirahadori y fuerza en su primer Kasteo que despliegue las tres Kagero y enseñe Shirahadori a cada copia durante ese mismo turno.',
  'v509: Corrige la entrega del slash de contraataque de Shirahadori actualizando el cache-busting de todos los recursos; el código de v508 ya disparaba el FX, pero index.html seguía solicitando game.js con la URL de v506 y podía cargar una copia antigua desde caché.',
  'v506: Corrige la persistencia real de Shirahadori al rekastear una invocación: el estado aprendido viaja del Spellbook a la cola de kasteo y vuelve a la unidad al entrar. Las fichas de la zona de kasteo ahora son inspeccionables en todo momento y muestran las habilidades aprendidas de esa copia.',
  'v503: Implementa aprendizaje permanente de Shirahadori y Estasis de Spellbook: enfriamiento base por costo, bonificación por habilidades aprendidas, persistencia por copia y modal de habilidad basado en su poder de aprendizaje.',
  'v502: Corrige de raíz el selector de Kaster en Biblioteca: la fila real de acciones recibe un layout dedicado y los wrappers intermedios dejan de participar visualmente; Seleccionar/Cambiar Kaster pasa a ser el botón central completo.',
  'v501: Corrige el botón Seleccionar/Cambiar Kaster en Biblioteca en todos sus estados: el estilo ya no depende del modo selectCaster y se aplica también cuando el botón está deshabilitado.',
  'v500: Biblioteca: el selector Seleccionar/Cambiar Kaster vuelve a ser un botón completo, centrado y redondeado; el wrapper central deja de dibujar un segundo contenedor visual.',
  'v499: Corrige la iconografía de Penetración de armadura: deja de reutilizar el icono de la aplicación de daño Penetración y usa el icono del factor Armadura. La aplicación Daño de penetración conserva su icono propio y su lógica de trayectoria.',
  'v497: Añade una línea decorativa bajo el nombre del modal usando el color elemental real de la carta y devuelve el límite derecho del modal al inicio del Spellbook, manteniéndolo visible durante la inspección de cartas.',
  'v496: Unifica de forma real la geometría del modal de carta en partida: cabecera, cuerpo y acciones usan alturas fijas compartidas para invocaciones, hechizos, habilidades, Kaster y guardianes; el contenido ya no puede recolocar ni estrechar el modal padre.',
  'v495: Unifica la lógica exterior de todos los modales de carta en partida: el padre deja de autoescalarse por el contenido, hechizos/habilidades ocupan la columna completa de estadísticas, guardianes respetan la misma proporción y todas las variantes comparten ancho, márgenes y acciones.',
  'v494: Elimina el clipping superior restante del dominio flotante del modal de carta en partida: se reserva headroom real en el bloque principal y el conjunto deja de apoyarse en coordenadas negativas recortadas.',
  'v493: Completa el dominio flotante del modal de carta en partida: fondo, símbolo elemental y atributo vuelven a renderizarse como un solo conjunto unido, conservando la posición visual anterior fuera del contenedor de la miniatura.',
  'v492: El dominio/atributo del modal de carta vuelve a su posición visual original, pero ahora es hermano de la miniatura dentro del bloque principal en partida; deja de ser hijo del preview y por eso ya no puede ser recortado por ese contenedor.',
  'v491: Reancla el grupo de dominio/atributo del modal de carta en partida para que quede dentro de la miniatura y deje de recortarse en la parte superior.',
  'v490: Corrige el recorte real del título del modal de carta en partida: libera el overflow vertical del bloque superior, aumenta el line-height del nombre y añade colchón interno para que el texto deje de cortarse arriba.',
  'v489: Recoloca más abajo el modal de carta en partida: añade margen superior adicional para que toda la composición deje de verse corrida hacia arriba, manteniendo el cierre del hueco vertical y la geometría pareja de Kastear/Salir.',
  'v488: Ajusta el modal de carta en partida: baja la cabecera para evitar recortes en la parte superior y elimina el hueco excesivo entre el contenido y Kastear/Salir, manteniendo la misma geometría de ambos botones.',
  'v487: Escala universal por lienzo lógico 1600x900: resolución, zoom y tamaño de ventana ya no reorganizan la interfaz; modales y submodales conservan jerarquía, márgenes seguros y ajuste uniforme, y Kastear recupera la misma geometría exterior de Salir.',
  'v486: Estabiliza PvP: corrige el reporter DEBUG faltante, elimina el falso error del visor de poderes, fuerza cache-busting v486, recupera limpiamente kasteos de invocación fallidos para evitar nexos huérfanos y permite que Evasión de Minokage se reposicione también ante ataques del Kaster.',
  'v482: Reemplaza el acceso por código del Versus Online por un sistema de partidas entre amigos: Crear/Unirse, bandeja en vivo de salas abiertas de amigos, lobby con selección de Spellbook y arena del Host, estado Listo independiente para ambos jugadores y cuenta regresiva automática 3-2-1 antes de iniciar el duelo.',
  'v472: Etapa 3 PvP: agrega un canal efímero de eventos visuales independiente del snapshot y reproduce en ambos clientes Kouuten, Guren Gan, Carga Real, desplazamientos/canalizaciones de Minokage, ataques, restauraciones, retornos al Spellbook, traslados de nexo, Táctica de guerra, defensas del Kaster y entradas de invocaciones.',
  'v471: Etapa 2 PvP: amplía el snapshot autoritativo con lámparas, Larga Noche, vínculos de hechizos, cargas de Minokage, armas caídas y Kasteo progresivo de Kouuten; limpia correctamente colecciones vacías omitidas por RTDB y separa el estado lógico de devolución/restauración de sus animaciones para evitar divergencias entre J1 y J2.',
  'v470: Etapa 1 de saneamiento: corrige la composición de costos de Naito Sutoka, Kurokagi butai #3 y Yasugana Hattori según el costo total; elimina los botones duplicados del estado sin Spellbook y restaura el ancho útil de las miniaturas de Biblioteca para que la banda de costo no quede comprimida.',
  'v469: Permite arrastrar con clic izquierdo cualquier carta del Spellbook hacia la arena. Al soltarla, inicia exactamente el mismo flujo de Kastear/Equipar de su modal y habilita la colocación o selección de objetivo correspondiente sin alterar el clic normal para abrir la ficha.',
  'v468: Agrega la primera carta de Habilidad, Shirahadori, como Catalizadora con Técnica; solo Guerrero o Asesino pueden equiparla, reutiliza la lógica Shirahadori de O-sensei Ueshiba y no requiere costo, kasteo ni enfriamiento.',
  'v466: Restaura la Biblioteca visual de v460 como base exacta y mantiene el Creador aislado; corrige especialmente los modales de hechizos para que sus contenedores conserven altura y no se compriman.',
  'v462: Mejora el Creador de Cartas con cantidades independientes para Descomponer y Crear, operaciones por lote, modal persistente, navegación entre cartas, contador de copias/mezclador y señalización inmediata de recursos faltantes.',
  'v457: Amplía las cartas de Apertura completada manteniendo máximo 10 por fila, renombra la acción a Abrir todos y consolida la Etapa 4 de boosters: tirada de rareza y carta separadas, filtros de origen/tipo, foil progresivo y efectos de revelado escalonados para rarezas medias, altas y Legendaria.',
  'v458: Refuerza la diferenciación visual por rareza en boosters/resultados con patrones, auras, partículas y estelas específicos por rareza; mantiene e intensifica las cartas temporales de muestra para rarezas sin catálogo pleno.',
  'v459: Corrige el error de arranque de v458: las cartas temporales ya no leen CARD_RARITY_LABELS antes de su inicialización, y forceRarityId se respeta directamente en la selección de boosters.',
  'v460: Rehace el acabado de rareza: foil principal recortado al skin real de la carta; rarezas medias usan destellos especulares sobre el skin; Extraña/Mítica/Legendaria añaden luces ascendentes y halo exterior; Legendaria suma partículas externas y borde iridiscente móvil.',
  'v461: Etapa 5: activa Creador de Cartas, elimina muestras temporales de rareza, agrega recursos persistentes de elementos/rareza al HUD, taller con mezclador de hasta 50 cartas, descomposición y creación de copias mediante Cristal Puro, elementos y rareza.',
  'v450: Corrige Tienda dentro de Biblioteca/Spellbooks para usar los botones nativos de esas pantallas, rehace la apertura para extraer las cinco cartas una por una hacia arriba desde dentro del sobre y luego presentarlas de izquierda a derecha, y agrega al HUD principal un desplegable con Reiniciar usuario que limpia colección/boosters y restaura 9,000 Cristales Puros.',
  'v453: Compacta la pantalla de boosters adquiridos para mantener las acciones visibles sin scroll y corrige la apertura: la capa frontal del sobre queda siempre por encima de las cartas, que salen entre frente y trasera con una cadencia mucho más rápida y solapada.',
  'v452: Corrige la probabilidad de boosters a dos tiradas: primero se determina la rareza según su peso y después se elige uniformemente una carta válida de esa rareza, evitando que la cantidad de cartas de una rareza altere su probabilidad base.',
  'v448: Compacta la vista de Colecciones de la Tienda para que no requiera scroll, suaviza y recorta el foil de los booster packs a la silueta real del sobre, y agrega la Etapa 3 de apertura: sobre cerrado, capas frontal/trasera abiertas, cartas saliendo desde dentro, revelado de cinco cartas, Abrir siguiente/Abrir todos, foil por rareza y entrega persistente a la colección.',
  'v446: Agrega Cristal Puro como recurso persistente de Modo Usuario con saldo inicial 9,000, HUD en menú y Biblioteca, precios reales de 350 por booster y 1,500 por grupo de cinco, validación de saldo y botón definitivo de Tienda.',
  'v445: Corrige la etapa 1 y agrega la etapa 2 del sistema de boosters: Tienda accesible desde menú/Biblioteca/Spellbooks, booster box Japón con iluminación y partículas, selección de 1 o paquetes de 5, contador de lotes, foil en sobres y persistencia de packs sin abrir. El sello Japón se reduce 40% y las cartas bloqueadas quedan únicamente en gris.',
  'v444: Inicia la etapa 1 del sistema de boosters con Modo Usuario local persistente, colección por copias, bloqueo gris de cartas no obtenidas en Biblioteca, límites del Spellbook según copias poseídas, Kasters libres, validación de Spellbooks y sello de origen Japón en el modal principal; Gloria latente queda como carta neutral.',
  'v443: Corrige el collider y el indicador de movimiento de Saqueador novato; añade miniaturas de las cartas que solicitan ventana de acción, acceso directo a su página del Spellbook, foco exacto para Emboscada y un aviso con clic derecho para cancelar después de aceptar la oportunidad.',
  'v442: Reconstruye por completo la interacción de Emboscada reutilizando la estructura visual y el flujo de Táctica de guerra: selección detallada del invasor, selección múltiple con orden y costo visual de Agua, cursor de nexo con la carta activa, colocación secuencial y controlador propio para Defensa rápida.',
  'v441: Agrega Emboscada, hechizo de Agua con Defensa rápida. Selecciona un invasor rival y varias invocaciones aliadas, paga 1 Agua por cada una, reposiciona sus nexos dentro de radio 3, las restaura a 0, concede Movilidad completa y restringe sus objetivos al invasor hasta su próxima restauración; si el invasor muere, todas se restauran.',
  'v440: Reduce la canalización del ataque del Guardián de 9 a 6 fases y actualiza sus descripciones, etiquetas y modales para reflejar el nuevo ciclo.',
  'v427: Interceptar conserva el consumo real del ataque básico de ambas invocaciones. Establece el combate sin reiniciar ataques: solo golpea quien todavía no haya gastado su ataque en la Resolución actual y, si ambos lo gastaron, quedan enfrentados sin ataque adicional.',
  'v426: Interceptar abre una ventana de acción inmediata en el instante en que una invocación rival cruza al lado aliado, antes de que pueda continuar moviéndose o atacar. Mientras siga disponible por Artimaña, la oportunidad vuelve a ofrecerse una vez al comenzar cada nueva fase del turno rival.',
  'v425: Restaura la ventana de acción de Artimaña para Interceptar. El recolector global de reacciones vuelve a incluir la carta cuando hay una invasora rival válida, recursos suficientes y una copia lista en el Spellbook; desde la ventana se abre el flujo manual corregido sin que el escudo invisible bloquee sus modales.',
  'v423: El bot del modo de prueba reemplaza Kouuten por Minokage no Kurai y Táctica de guerra. Fuerza a Tokugawa a kastear primero a Minokage; al entrar en arena consume Táctica de guerra mediante Defensa rápida y traslada su nexo a la línea frontal legal más cercana al campo del jugador.',
  'v422: Agrega Interceptar como hechizo de Agua con Artimaña. Selecciona una invocación aliada y un invasor rival, reposiciona automáticamente el nexo una casilla frente al invasor, restaura a 0 y fuerza el combate inmediato. Reutiliza el FX acuático de Táctica de guerra y recibe gris, foil, punto amarillo y aviso de página según disponibilidad.',
  'v421: Táctica de guerra usa Kasteo 2 en el flujo normal. Defensa rápida solo la vuelve instantánea fuera de la fase de Kasteo y únicamente permite seleccionar invocaciones situadas en el lado aliado de la arena.',
  'v420: Reconstruye Táctica de guerra con selección múltiple en modal, costo acumulativo por dominio, colocación secuencial de nexos, resolución acuática y disponibilidad visual completa con gris, foil, punto amarillo y aviso de página.',
  'v419: Hattori pasa a Asesino/Guerrero; la Biblioteca filtra invocaciones solo por cualidades y hechizos por sus requisitos reales de usuario; se elimina Razas compatibles del modal de Kaster, Invocador recupera su icono, los modales toman siempre el dominio de la propia carta y se separan Kasteo y Enfriamientos en el modal de Kaster.',
  'v418: Corrige la miniatura de Táctica de guerra en Biblioteca: el contenedor de Costo ? vuelve a usar el estilo estándar de las demás cartas y deja de teñirse con los colores de Agua.',
  'v417: Agrega Táctica de guerra, hechizo de Agua con costo variable según el elemento de la invocación objetivo, Kasteo 0, Defensa rápida, selección de una invocación aliada, reposicionamiento de su nexo en el campo aliado y restauración al resolverse.',
  'v415: Ajusta Larga Noche: el aumento de crítico se integra sin duplicar factores visibles, la miniatura persistente omite ese crítico temporal, la transición al anochecer se suaviza y las luciérnagas pasan a ser muchas menos, más lentas y totalmente aleatorias en los bordes.',
  'v414: Agrega Nagayoru / Larga Noche como hechizo de Oscuridad de costo 6 y kasteo 5. Durante 20 fases oscurece toda la arena con niebla decorativa y luciérnagas, extiende Tentoro a 20 fases, concede Oculto a todos los Asesinos, potencia el Daño crítico de los Ninjas asesinos y reduce en 2 niveles el Esquive y la Evasión del rival.',
  'v413: Corrige Tentoro: el nombre deja de mostrarse en japonés y las Lámparas Celestiales aparecen también en la bandeja inferior izquierda de efectos activos con su miniatura y contador de 10 fases.',
  'v412: Agrega Tentoro, hechizo de Luz de costo 2 y kasteo 3. Invoca durante 10 fases cuatro lámparas aleatorias —tres en el lado aliado y una en el rival— cuyos halos de primer anillo impiden Oculto en enemigos y conceden Movilidad completa a aliados.',
  'v408: Separa el cálculo PB de hechizos e invocaciones. Los hechizos dejan de sumar precisión, restauración, rango, movilidad y velocidad; incorporan disponibilidad de usuarios y objetivos, rasgos, factores y poderes. El bot de prueba usa únicamente Kouuten, espera invocaciones rivales activas y centra el bombardeo sobre ellas.',
  'v411: Elimina los botones duplicados de filtros/ordenar en el encabezado de Biblioteca y libera los FX de Gloria latente/Curación para que fluyan fuera de la casilla sin recorte cuadrado.',
  'v407: Separa los efectos de Gloria latente y Curación. Al terminar la restauración, Gloria latente genera rayos amarillos ascendentes; después Curación 1 recupera vida y muestra cruces amarillo-blancas y partículas dentro de la casilla.',
  'v401: Ajusta Kōu Ten: Guren Gan a costo total 6 (4 Fuego + 2 aleatorios) y tiempo de kasteo 5.',
  'v400: Agrega Kōu Ten: Guren Gan como nuevo hechizo de Fuego basado en Kouuten. Selecciona un patrón de radio 3, impacta el área efectiva con 4 de daño, lanza 8 salpicaduras externas de 2 de daño, aplica Quemadura 3, reduce a la mitad el daño contra estructuras y reproduce una bola de cañón incendiaria bidireccional con iluminación escalonada.',
  'v399: Ordena los contadores agrupados del HUD rival y corrige Carga Real: daña y empuja Kasters, desplaza inmediatamente al impacto, permite saltar una invocación o Kaster si la segunda casilla está libre y mantiene estructuras como bloqueos absolutos.',
  'v396: Kouuten resuelve el daño al aterrizar cada flecha, garantiza sus 9 casillas centrales y 4 impactos externos, alcanza Kasters y Guardianes, retira la ficha derrotada sin cortar su regreso al Spellbook, elimina la persistente sin Fuego y evita indicadores amarillos sobre estructuras.',
  'v395: Kouuten daña estructuras dentro de sus casillas de impacto, mueve el punto amarillo al lado izquierdo, ofrece el rekasteo en cada transición posterior a su resolución aunque falten recursos y elimina sin pausa la ficha de una invocación derrotada por la lluvia.',
  'v388: Hace la formación de Carga Real más orgánica y aleatoria, ralentiza su recorrido un 35% y prolonga las partículas de polvo y brasas durante al menos 1.5 segundos después del paso de la caballería.',
  'v391: Agrega Kouuten como hechizo de Fuego con Kasteo progresivo, selección de área 5×5, lluvia irregular de flechas incendiarias, Quemadura 2 en el núcleo central y soporte de rekasteo con costo creciente.',
  'v392: Corrige Kouuten: kasteo 2, consumo inicial desde el Spellbook, miniatura persistente, ventana de acción por fase, foil y punto amarillo, confirmación de rekasteo, costo creciente exclusivamente de Fuego y flechas bidireccionales del tamaño de Kaguya desde el fondo completo del escenario.',
  'v385: Agrega los modales informativos de poder de Carga Real y Gloria latente. También incorpora un contenido genérico de respaldo para que cualquier poder registrado abra siempre un modal aunque todavía no tenga una plantilla especializada.',
  'v384: Corrige la composición de costos de los hechizos nuevos de Fuego: Carga Real y Despliegue anticipado cuestan 2 Fuego + 1 aleatorio. Corrige también el control maestro de costos para que Oda Nobunaga y Takeda Shingen tengan costo total 4, distribuido como 3 Fuego + 1 aleatorio.',
  'v383: Agrega Carga Real como hechizo de Fuego de costo 3 y kasteo 5. Selecciona una franja de cuatro columnas, reproduce una carga cenital bidireccional, causa 1 de daño directo, aplica Aturdimiento durante 3 fases y empuja hasta 2 casillas. Despliegue anticipado sube a costo 3 y kasteo 4; todas las invocaciones de Fuego reducen su kasteo en 1, y Nobunaga y Takeda quedan con costo total 4.',
  'v376: Sustituye el foil inventado de los botones de página por el mismo barrido visual que usa la carta reactiva disponible. La capa queda detrás del texto, recortada dentro del único botón correspondiente y conserva la página exacta indicada por la reacción.',
  'v372: El desplegable de hechizos vinculados se renderiza en una capa fija global, cambia de lado según el espacio y ya no queda recortado por la columna persistente. Gloria latente por Kasteo rápido aplica primero el vínculo sin curar, cancela el daño y usa la restauración real para obtener Restauración 0 y +1 de vida por vínculo.',
  'v370: La ventana de acción local activa una pausa global de jugabilidad. La IA, sus movimientos, ataques encadenados, efectos posteriores, restauraciones y cambios de fase esperan hasta que la reacción se resuelva, se cancele o expire; la interfaz de la propia reacción permanece operativa durante la pausa.',
  'v369: Repara de forma persistente el flujo manual de Kasteo rápido de Gloria latente, registra el clic global antes del bloqueo rival, conserva un contexto de reacción por etapas, cambia de página mediante la ranura exacta y actualiza las versiones de carga de JS/CSS para impedir que el navegador reutilice la lógica anterior.',
  'v368: Rehace el Kasteo rápido manual de Gloria latente: la ventana visible congela el daño letal, al aceptarla cambia a la página exacta, resalta solo la copia utilizable, permite abrirla y pulsar Kastear fuera de fase, exige confirmar el objetivo amenazado y solo entonces consume y resuelve el hechizo. El foil de página queda recortado al botón correcto.',
  'v367: Gloria latente acepta también Caudillos como objetivo. Al capturar una ventana de acción de una carta disponible en el Spellbook, el juego cambia a su página, hace parpadear esa copia y atenúa las demás sin oscurecerlas en exceso. También suaviza el oscurecimiento normal de hechizos sin objetivo válido.',
  'v366: Gloria latente deja de activarse automáticamente ante daño letal. Ahora valida usuario, objetivo, costo y copia disponible, pausa el flujo mediante la ventana de acción y permite Activar o No activar antes de continuar. Todos los hechizos son consumibles: Gloria latente y Despliegue anticipado ya no regresan al Spellbook al terminar o fallar su vínculo.',
  'v364: La vida del modal separa vida actual/máxima efectiva del bono de vida máxima. La burbuja principal se expande para mostrar valores como 5 / 7, el +2 aparece en una cápsula independiente con desglose de fuentes y al terminar un bono temporal se recorta únicamente el excedente que supere el nuevo máximo.',
  'v361: Las cartas de hechizo vinculadas de las miniaturas persistentes comparten con el Versus las mismas variables de dirección, separación, escala, opacidad y orden de profundidad: se superponen hacia abajo y a la derecha detrás de la invocación, conservando la carta completa y el borde/brillo de su elemento.',
  'v357: Sincroniza Fuerza de unión con el límite de arena. El disparador aparece antes del aviso de límite, el aviso muestra invocaciones físicas y capacidad física real (por ejemplo 6/6 cuando una copia ocupa 0 espacios), y no anuncia límite alcanzado si todavía existe en el Spellbook una copia que puede entrar sin consumir otro espacio efectivo.',
  'v356: Corrige la selección previa de Despliegue anticipado. Al pulsar Kastear, los Caudillos válidos muestran foil y punto amarillo, aparece la indicación Selecciona un Caudillo en arena bajo la fila frontal aliada, y solo después de tocar un objetivo se paga el costo y la carta entra en kasteo.',
  'v353: Generaliza el consumo de ataque por Resolución, impide que una unidad ataque una estructura y luego otro objetivo, mantiene Cuerpo a cuerpo y Rango anclados a la estructura hasta destruirla o entrar en combate rival, deja Distancia sin anclaje, extiende el círculo y las restricciones de kasteo a los hechizos y añade contadores de enfriamiento junto a poderes, habilidades y factores en el modal.',
  'v349: Limpia la canalización de Minokage: elimina núcleo y mancha, reduce anillos y cortes al 50% y conserva el haz de objetivo con menor opacidad. Una fase antes del ataque inicia el giro previo al 50% de tamaño/opacidad. Al resolver Shippū Ugachi oculta los indicadores de la ficha, asciende hasta 135%, ejecuta una embestida continua aproximadamente tres veces más rápida y desciende progresivamente al tamaño normal sin pausas.',
  'v348: Recupera de forma real el primer efecto de canalización de Minokage usado en v340 —anillos, núcleo y cortes negros/blancos— dentro de la capa persistente actual. Conserva el haz tenue de fijación, el seguimiento del objetivo, la cancelación por objetivo perdido y el reloj de animación sin reinicios.',
  'v347: Restaura la canalización visual anterior de Minokage, conserva únicamente un haz de fijación tenue y persistente, evita reinicios visuales al renderizar y cancela Shippū Ugachi en cuanto la invocación objetivo muere o deja de estar activa, devolviendo la activación al usuario.',
  'v346: Separa Shippū Ugachi en fase activa y pasiva. La activa atraviesa estructuras sin detenerse, termina al borde de la arena, daña un corredor de radio 1 y prepara el giro en la última fase. La pasiva permite seleccionar invocaciones a radio 3, saltar hasta alcance 1, ejecutar Oscilación completa y regresar. La canalización conserva su fase visual sin reiniciarse al renderizar.',
  'v345: Restablece Shippū Ugachi en la ventana de acción y corrige su flujo manual. La miniatura de la ventana desaparece al pulsar Poder, la selección de objetivo queda vinculada a esa misma oportunidad y la fase solo se libera después de confirmar o cancelar, evitando que el aviso aparezca una segunda vez.',
  'v344: Retira Shippū Ugachi de la ventana de acción contextual. Minokage conserva su poder activo manual en los controles de su unidad y solo lo inicia cuando el jugador decide usarlo directamente.',
  'v343: Minokage fija una invocación móvil mediante un haz blanco y negro persistente que no reinicia con los renderizados. Shippū Ugachi recalcula la posición actual del objetivo, usa una trayectoria con una sola corrección al borde, ejecuta un vuelo continuo con ascenso y descenso progresivos y mantiene el giro un segundo después del aterrizaje. Añade controles superiores de tamaño y posición X/Y para Minokage, Bushi iniciado, O-sensei, Regente Kishimoto y Goemon.',
  'v342: Corrige Minokage no Kurai. Su Yari baja a daño físico 2; Shippū Ugachi solo fija invocaciones rivales, conserva Golpe crítico 3 con daño crítico final 6, cuenta exactamente cada transición global y se resuelve al completar la quinta sin esperar otra Resolución. La canalización cambia a una carga de ki negra y blanca, y el token viaja sincronizado con el giro durante la embestida.',
  'v341: Rediseña la acción Agregar al Spellbook dentro del modal de Biblioteca. Incorpora un selector integrado − / cantidad / +, permite elegir varias copias respetando el límite normal o Límites forzados, muestra avisos por límite de copias o Spellbook lleno, agrega las copias en una sola confirmación y mantiene el modal abierto para seguir navegando hasta pulsar Salir.',
  'v340: Agrega “Ninja” Minokage no Kurai con Yari, Puño 2, Alcance 2, Evasión 4 y Oscilación completa. Shippū Ugachi consume su ataque básico del turno, canaliza 5 fases, fija objetivo a 6 casillas y ejecuta una embestida de hasta 8 casillas que atraviesa enemigos con Golpe crítico 3 independiente. El poder no restaura a Minokage; su ataque normal sí lo restaura con 10 fases. Evasión reposiciona a Minokage alrededor del atacante.',
  'v339: Restringe Jinchi Tenkan de Tokugawa a casillas libres de su propio campo y únicamente a la primera fila del campo rival que toca su lado de la arena. El resto de la zona rival deja de mostrarse y de aceptarse como destino, tanto para el jugador como para la IA.',
  'v338: Cada copia de Kaguya conserva una oportunidad independiente de Disparo energizado por fase: tras activar una, la ventana vuelve a ofrecer las copias restantes y la IA procesa todas sus Kaguyas elegibles, incluso durante sus propias fases. Kishimoto muestra LLAMADO A LA GUERRA al entrar en arena. Legado del Imbatible de Musashi beneficia únicamente a Samuráis y Ronin aliados.',
  'v337: La Kaguya de la IA deja de inmovilizarse por la formación de apertura y vuelve a usar su movilidad Básica normal. La ventana de acción de Kaguya identifica cada transición con un serial propio, incluyendo explícitamente el relevo Espera → Extracción, sin duplicarse al comenzar las acciones de la fase.',
  'v336: Kaguya vuelve a Vida 1. Disparo energizado conserva su enfriamiento y restricciones, pero su ventana de acción se identifica por la fase real y se ofrece una vez al comenzar cada fase mientras el poder esté disponible; se añade una comprobación de respaldo antes de ejecutar las acciones normales para que ninguna transición pueda omitirla.',
  'v335: Corrige el bloqueo de Disparo energizado de Kaguya para el jugador humano. La selección manual iniciada desde la ventana de acción recibe clics aunque la IA mantenga su bloqueo, evita duplicar la miniatura seleccionada y libera siempre la ventana aun si la resolución del poder falla.',
  'v334: Corrige a Regente Kishimoto: agrega el factor Campeo 1 y cambia su movilidad a Retroceso, usando la lógica general de Campeo para asentarse en la zona de riesgo rival.',
  'v333: Agrega Regente Kishimoto como Invocador catalizador de costo 3 y kasteo 3. Llamado a la guerra reduce el kasteo de Guerreros aliados en 1 y de Guerreros Samurai en 2 mientras Kishimoto está activo. Límites Superados consume 2 elementos cualesquiera una vez por turno, aumenta en 1 el límite de invocaciones mientras Kishimoto esté en arena y puede acumularse hasta 2 veces. Invocador usa su icono definitivo.',
  'v332: Unifica Disparo energizado de Kaguya para el jugador humano. La ventana de acción y el botón Poder usan el mismo modo de selección, eliminan miniaturas duplicadas, permiten elegir objetivos desde la arena o el panel lateral y liberan correctamente el bloqueo al activar o cancelar.',
  'v331: Agrega un aviso compacto al alcanzar o intentar superar el límite de 5 espacios de invocación. Corrige el kasteo de la IA para que todas sus invocaciones se coloquen exclusivamente en casillas adyacentes a su Kaster, eliminando las coordenadas fijas de apertura. Shirahadori usa el mismo aviso flotante transparente de los demás buffs, sin panel invasivo.',
  'v330: Agrega O-sensei Ueshiba con Campeo, Dominio territorial y Habilidad definitiva. Los Guerreros no Samurái reciben Desvío 3 físico; los Guerreros Samurái reciben Shirahadori 4 PDA, que redirige ataques físicos mientras están en combate. Su restauración base 2 aumenta +1 por cada Samurai con Shirahadori concedido por su poder. También tipa todos los Desvíos existentes como físicos, corrige la Armadura física de Takeda y generaliza Campeo y Dominio territorial.',
  'v329: Corrige el límite de invocaciones a 5 espacios efectivos, cuenta también restauraciones, colas y entradas instantáneas pendientes, y revalida antes de pagar. Fuerza de unión pasa a Disparador Virtual/Táctica y muestra su icono con un gran aviso al completar cada grupo.',
  'v328: Agrega el rasgo de adaptación Límites forzados a Bushi iniciado. Permite hasta 4 copias en el Spellbook, muestra su icono bajo los tags del modal y en la esquina superior izquierda de la miniatura de Biblioteca, y devuelve los indicadores de ataque/vida al borde derecho de la carta.',
  'v327: Agrega Bushi iniciado como invocación catalizadora de costo universal 1, Kasteo 0, Restauración 0, Espada 1, Puño 1, Vida 1, Velocidad 3 y Fuerza de unión 1. El factor ocupa la línea de Kasteo/Restauración y reduce el límite efectivo por grupos de copias iguales.',
  'v325: Agrega Samurai Bushi inquebrantable como invocación catalizadora de costo 3, kasteo 1 y restauración 2; Espada 2, Golpe 1, Vida 2, Velocidad 3, Armadura 2 y Desvío 1 provenientes de Guerrero. Puede aprender 3 habilidades y no tiene poder ni Arma extra.',
  'v324: Shizukesa no Shi-in entra en enfriamiento durante 6 fases después de resolverse o interrumpirse. Kurayami no vuelve a aparecer en ventanas de acción ni puede activar el poder hasta completar el contador; el enfriamiento se muestra en su miniatura y modal.',
  'v323: Ajusta la progresión visual de Shizukesa no Shi-in: Kurayami permanece totalmente visible al iniciar la canalización y baja a 80% y 60% de opacidad en las fases siguientes; el efecto conservado aumenta a 25%, 40% y 80% antes de aplicar Oculto.',
  'v322: Shizukesa no Shi-in simplifica su canalización visible: retira del montaje activo el fondo energético giratorio, el aura central, los tres anillos mágicos y el núcleo de energía. Sus estilos y animaciones se conservan en la reserva visual para reutilizarlos más adelante.',
  'v321: La canalización de Kurayami reduce la invasividad visual con opacidad progresiva de 10%, 30% y 50%. Su reloj de animación se conserva entre renderizados para que anillos, aura, partículas y pulso no se reinicien al ejecutar otras acciones.',
  'v320: La ventana de acción conserva congelada la transición y usa los candidatos exactos de la oportunidad mostrada; el escudo de entrada acepta clic izquierdo sin que el bloqueo rival lo intercepte. Kurayami canaliza 3 fases y aumenta su transparencia por etapas: 25%, 40% y 80%.',
  'v319: La ventana de acción usa una capa invisible de captura para que el clic izquierdo nunca adelante los banderines de transición. Kurayami elimina el rótulo persistente de canalización, muestra el efecto por encima del token y escalona daño, ejecución y 999 sin cápsulas negras.',
  'v318: La ventana de acción acepta clic izquierdo global de forma robusta, además de Enter, y mantiene clic derecho para descartar. Kurayami recibe una canalización visual reforzada con sello giratorio, haz oscuro, ecos del token, partículas y aura persistente.',
  'v317: Corrige la ventana de acción: el aviso conserva 8 segundos, pero al aceptarlo se detiene todo temporizador y la transición queda pausada hasta resolver o cancelar. Kurayami solo entra si hay una invocación rival a alcance 5. El movimiento normal del Kaster queda fuera; Ansatsu no Kokuin entra únicamente en transiciones con una invocación aliada en batalla y Elemento puro suficiente.',
  'v316: Rehecha desde v314 la ventana de acción sin el rediseño invasivo: aviso inferior centrado de 8 segundos, clic izquierdo/Enter para abrir y clic derecho para descartar. Los tokens con oportunidad muestran foil y un indicador luminoso mínimo. Kurayami entra como reacción por ruta real de hasta 9 movimientos, cambia Poder a Seleccionar y muestra objetivos en el panel izquierdo y sobre la arena. Goemon recupera costo total 3.',
  'v314: Goemon vuelve a costo 3 y Botín valioso 3 PDA. Kurayami recibe canalización visual persistente, Oculto visible, estela doble de movimiento, limpieza completa al restaurarse, movilidad base restaurada y modal funcional de Shizukesa no Shi-in.',
  'v313: Botín valioso roba solo 1 elemento. Densetsu no Sennyū usa una estela persistente de máximo dos copias: la más reciente al 50%, la anterior al 25% y la más antigua desaparece al siguiente paso. El desplazamiento automático es 25% más rápido que en v312.',
  'v312: Densetsu no Sennyū deja de medir la casilla de Goemon contra la casilla del Kaster: ahora calcula la ruta válida hasta una casilla adyacente de ataque y se activa cuando esa ruta requiere de 1 a 3 movimientos. Botín valioso queda temporalmente en 6 PDA para pruebas; su valor de diseño queda registrado en 3 PDA.',
  'v311: Densetsu no Sennyū se comprueba globalmente cada vez que cambia o se redibuja la arena, por lo que Goemon lo activa al entrar, ser desplazado o cuando el Kaster rival queda a 3 casillas; Botín valioso conserva el origen atacante a través de la defensa del Kaster y vuelve a ejecutar el dropeo/transferencia de recursos.',
  'v310: Densetsu no Sennyū reproduce el desplazamiento de Goemon más lentamente para mostrar el rastro de sombras; Botín valioso reutiliza la caída, flotación y viaje visual del Elemento puro; Goemon y Kurayami cuestan 0 temporalmente para pruebas.',
  'v308: Restaura los costos normales de Yasugana Hattori, Naito Sutoka y Kurokagi butai #3; Kurokagi vuelve a Desarmar 3, Junkai butai #2 conserva Atadura 2 y costo 1; las miniaturas de Miyamoto Musashi dejan de mostrar el caption redundante.',
  'v307: Agrega Kurayami con Shizukesa no Shi-in, persecución canalizada, ataque que ignora defensas, ejecución a 3 de vida, aura Ninja en lado rival; Kaguya baja a 9 de vida y Kurayami usa Golpe crítico 5 para pruebas.',
  'v306: Agrega Ichikawa Goemon con carta/ficha correctas, poder pasivo Densetsu no Sennyū (+2 velocidad y movilidad completa a 4 casillas del Kaster rival) y habilidad Botín valioso para robar hasta 2 elementos del stock rival al dañar al Kaster con 4 PDA.',
  'v304: La ventana de acción rápida también se abre con clic derecho. Se agrega Junkai butai #1 con carta/ficha correctas, Espada 2, Golpe 1, Crítico 1 y Penetración de armadura 1.',
  'v303: Kurokagi reserva Buki Utsushi antes de animar, Desarmar 5 usa correctamente la escala máxima de 6 PDA y el dropeo respeta el snapshot planificado aunque el objetivo entre en restauración después del impacto.',
  'v302: Buki Utsushi conserva el snapshot completo del arma desde el dropeo hasta la captura y migra perfiles v2 incompletos usando la carta propietaria original.',
  'v301: Buki Utsushi muestra y equipa directamente el arma alterna; los perfiles capturados se hidratan con alcance, precisión, modo y naturaleza reales del arma original; Kaguya usa Golpe con 6 PDA al quedar desarmada y Desarmar deja de mostrarse como factor propio en su modal.',
  'v300: Buki Utsushi equipa de verdad el arma capturada: Kurokagi adopta su tipo de arma, modo de combate, alcance, precisión, daño y naturaleza sin copiar factores ni poderes. Al volver a tocar el poder con un arma capturada, aparece un menú separado con Activar Buki Utsushi y Cambiar de arma.',
  'v299: Las invocaciones con Oscilación sustituyen la embestida frontal por un giro corto dentro de su propia casilla, manteniendo fijo el origen de la cadena. Buki Utsushi recupera su animación aislada de extensión, enganche y retracción, con coordenadas de origen y arma corregidas para cualquier nivel de zoom.',
  'v298: Oscilación vuelve a la geometría original de Sutoka: sector y resultados se planifican antes de animar, la cadena barre líneas independientes de los objetivos y solo se detiene por Parálisis ya resuelta. Kurokagi separa el ataque de Buki Utsushi: primero deja caer armas y luego activa manualmente el poder para escoger y recoger una. Sutoka queda a costo 0 para pruebas.',
  'v297: Los respawn dejan de bloquear rutas intermedias; Parálisis solo muestra miniatura persistente a su propietario; Junkai conserva Oscilación durante el vínculo; el barrido fluye sin pausas salvo Parálisis; Kurokagi desarma a todos los objetivos dañados, permite elegir un arma caída y copia únicamente su daño; las invocaciones en estasis respetan la profundidad sobre el Kaster.',
  'v290: Naito Sutoka, Junkai butai #2 y Kurokagi butai #3 reciben barridos de cadena propios sincronizados objetivo por objetivo; Junkai y Kurokagi normalizan la velocidad visual de su arco al ritmo de Sutoka.',
  'v289: Kurokagi butai #3 conserva costo 0 para pruebas y vuelve a usar exactamente el flujo estándar de movimiento de las demás invocaciones: sin recargas, seriales ni hitbox especial.',
  'v288: Kurokagi butai #3 cuesta 0 para pruebas y recupera su movimiento de Resolución si entró con movesLeft en 0; el seguro por serial evita recargar movimiento después de haberlo usado.',
  'v286: Corrige la asignación carta/ficha de Kurokagi butai #3, amplía su hitbox para poder seleccionarlo y atacar con normalidad, y eleva temporalmente Desarmar a nivel 5 para probar Buki Utsushi.',
  'v285: Agrega Kurokagi butai #3 con Kusarigama, Oscilación parcial, Desarmar 3 y Buki Utsushi: captura el arma desarmada, copia solo su perfil básico y permite alternar entre la Kusarigama y el arma capturada. Junkai butai #2 queda únicamente con Atadura 2.',
  'v284: Oscilación parcial separa visualmente ataque, daño objetivo por objetivo y Parálisis: la atadura solo comienza después de retirar el barrido y terminar todos los daños permitidos hasta el objetivo que detuvo la secuencia.',
  'v283: Parálisis muestra su duración exacta por nivel, cancela Disparo energizado y otros estados activos que dependen de atacar o desplazarse, y bloquea Evasión, Esquive, Desvío y respuestas equivalentes sin desactivar Armadura, escudos ni poderes que no requieren movimiento o ataque.',
  'v281: El efecto persistente de Parálisis de Junkai elimina el candado visual y cambia sus cadenas, aros y resplandores de azul a morado.',
  'v280: Reduce 25% el icono circular del arma caída y oscurece su fondo; Tokugawa prioriza recuperar armas desarmadas con animación de retorno y nombre del arma; Junkai pasa a Desarmar 2 y Parálisis 5, con cadena persistente hasta terminar o romperse el vínculo.',
  'v279: Aumenta 4× el icono del arma durante la caída y en el marcador persistente, reduce a la mitad el efecto visual de Desarmar y limita la miniatura persistente de Desarmar al propietario de la invocación afectada.',
  'v278: Desarmar usa una caída pequeña y arqueada después del efecto de cadenas, crea el marcador solo al aterrizar, actualiza arma/ataque/factores del modal y hace que Oscilación parcial avance y resuelva objetivo por objetivo, deteniéndose en el primer Desarmar o Parálisis exitoso.',
  'Kaguya sube a 10 de vida para pruebas; Yasugana, Saqueador novato y Junkai butai #2 recuperan Ninja★ como familia sin duplicarlo en el nombre; se agregan controles superiores de tamaño/posición para Saqueador y Junkai; Junkai detiene la comprobación de factores en cuanto aplica el primero.',
  'Corrige Biblioteca vacía tras borrar un Spellbook: restaura el perfil de arma de las miniaturas, cierra modales obsoletos y evita que Seleccionar Kaster caiga al flujo de batalla cuando ya no existe un constructor activo.',
  'Agrega “Ninja” Junkai butai #2 con arma con cadena principal, espada extra, Velocidad de ataque 1, Desarmar 5 y Parálisis 2; la Oscilación parcial se detiene y fija el combate en el primer objetivo que recibe uno de esos factores.',
  'Velocidad de ataque pasa a comparar niveles: Oda no Kage 2, Miyamoto Musashi 5 y Junkai butai #2 1.',
  'Desarmar ahora hace caer visualmente el arma en una casilla aleatoria alrededor del objetivo, deja un marcador persistente del arma en el suelo y cambia al arma extra si la carta la tiene; de lo contrario usa puño. La unidad puede recuperarla al moverse sobre su marcador, y Kaguya cancela Disparo energizado si queda desarmada o recupera el arma.',
  'Yasugana Hattori, Saqueador novato y Junkai butai #2 dejan de mostrar el chip de familia Ninja y el prefijo “Ninja” en el nombre.',
  'v270: Enseñar Vigilia elimina el icono de Centinela y usa miniaturas persistentes de selección con botón Seleccionar; al elegir, todas desaparecen, la unidad recibe Vigilia y aparece el texto VIGILIA.',
  'v269: Ceguera envía los cuervos visualmente desde Yasugana hasta el objetivo antes de dejarlos orbitando de forma persistente.',
  'v268: Ceguera usa la misma secuencia flotante de Ogonaga/Taicho: CEGUERA, icono de Precisión con −4 e icono de Velocidad con −1; el hover de toda la fila Elegir aplica foil y palpitación real al token.',
  'v267: Ceguera muestra penalizaciones separadas de Precisión y Velocidad solo al propietario de la unidad afectada; el botón Poder del modal vuelve a ser informativo y la activación queda exclusiva de la miniatura de comando de Yasugana.',
  'v266: Disparo energizado de Kaguya baja a +1 PDA real; Yasugana usa el CSS actualizado, su foil respeta tamaño/posición, los cuervos suben y reducen 25%, y toda la fila Elegir activa foil y palpitación.',
  'v264: integra controles superiores para el token de Yasugana y cambia Genyutsu a selección de objetivos dentro del mismo modal, con foil de movimiento al pasar el cursor.',
  'Corrige Genyutsu, Shinigami Karasu: Ceguera y Vigilia se validan de forma totalmente independiente, el botón de Poder abre el modal real desde la ficha en arena, el panel informativo ya no queda vacío, Yasugana cuesta 0 para pruebas y Gioshonin vuelve a velocidad 1.',
  'Corrige Genyutsu, Shinigami Karasu: reemplaza el menú oculto por un modal funcional con Ceguera/Vigilia y añade una animación morada de cuervos estilizados al aplicar Ceguera.',
  'Agrega “Ninja” Yasugana Hattori con costo 4 Oscuridad + 1 aleatorio, arte/ficha propios, Golpe crítico 2, Dominio territorial, factor Ceguera y poder activo Genyutsu, Shinigami Karasu con Ceguera o Vigilia temporal.',
  'Corrige el daño acumulativo de Takeda Shingen: el bono de El viejo amigo entra en el perfil efectivo usado contra invocaciones, Kasters y Guardianes, incluidos los ataques sostenidos contra estructuras.',
  'Corrige la ventana de acción del Kaster: sus controles quedan habilitados durante el bloqueo de la secuencia y el clic inicial ya no puede tragarse el siguiente clic sobre la habilidad.',
  'Mercancía de guerra deja de usar la ventana global de acciones: cuando hay un aliado reabastecible en radio 2 aparece un aviso propio de 5 segundos con Usar/No usar; conserva prioridad y pausa PvP solo durante esa decisión y su resolución.',
  'Corrige Mis Spellbooks: miniatura cuadrada construida con la carta real del Kaster, dominios con sus tres capas originales y sección vacía de Distribución de elementos, sin inventar datos antes de implementar la Fuente.',
  'Habilita Biblioteca y Mis Spellbooks: creación guiada con selección inicial de Kaster, límite real de 30 cartas en tres páginas, guardado persistente en localStorage, recuperación de borrador y colección local con editar, duplicar, renombrar y borrar.',
  'Impide superposiciones en movimiento asistido, agrupa en el HUD VS cada Guardián con sus objetivos apilados, corrige Jinchi Tenkan como rescate inmediato sin estasis con +2 vida máxima/+2 curación, añade rescate táctico de IA, fin de partida con revancha y victorias del match, y libera la prioridad de Takeda cuando Tokugawa ya puede pagarlo.',
  'Reformula la estrategia de Tokugawa: apertura fija con Kaguyas en D5/F5, reserva de recursos para Takeda y El viejo amigo, avance condicionado, secuencia Takeda/Musashi/Nobunaga/Oda no Kage/Hideyoshi/Taicho y respuesta situacional con Akari. Akari pasa a ataque a distancia y Colegas de guerra queda completamente funcional solo con Nobunaga aliado.',
  'Corrige Defender del Kaster con Defensa 2 real y efecto visual; las auras de Guardianes solo suprimen efectos rivales, los contadores de humo abren información propia, la Bomba de humo finaliza su reacción de forma idempotente y el Counter usa el color del dominio.',
  'Elimina la segunda carcasa visual del HUD rival: recursos y cola de kasteo pasan a ser filas internas transparentes del único contenedor de Tokugawa, sin fondo, borde, sombra ni posicionamiento independiente.',
  'Integra la habilidad de Hattori en la ventana de acción contextual de 1 segundo; unifica el HUD rival, corrige Bomba de humo, contadores de consumibles, combate Kaster contra Kaster, canalización de Kaguya y cadencia de Elemento puro cada tres Kasteos.',
  'Agrega Oda no Kage con raza Demonio, cusarigama/Oscilación parcial, espada extra, ejecución de 2 PDA contra objetivos de ataque igual o menor y vínculo activo de guardaespaldas con Nobunaga.',
  'Alinea ATAQUE con VIDA, CAST y COUNTER en el HUD inferior del Kaster eliminando el margen heredado del primer bloque de estadísticas.',
  'Monta el HUD compacto de Tokugawa también dentro de la capa overlay y lo devuelve correctamente al escenario al cambiar a modo anclado.',
  'Retira el ataque del HUD superior rival para mostrar completa la reserva de Elemento puro; conserva solo icono de Kaster, reserva, vida y Counter. La generación de Elemento puro cae, permanece flotando un instante y después viaja al medidor.',
  'Compacta el HUD superior rival: conserva solo icono de Kaster, Elemento puro, ataque, vida y Counter; elimina retrato, nombre, etiquetas y Cast, reduce su ancho/altura y usa el mismo fondo translúcido del HUD elemental. Fuera del turno rival, su contenido queda al 40% salvo hover.',
  'Aumenta a 3 Elementos puros el costo de Ansatsu no Kokuin por objetivo y de Jinchi Tenkan por activación; muestra tres gotas junto al nombre de cada habilidad.',
  'Fija el HUD de Hattori en la parte inferior y agrega el HUD permanente de Tokugawa en la parte superior, ambos con icono de Kaster, medidor de Elemento puro, ataque, vida, estado de kasteo y Counter especial. Hattori y Tokugawa empiezan en 0/8 y generan 2 por Extracción; se elimina Crítico de ambos.',
  'Agrega a Tokugawa la habilidad nativa Jinchi Tenkan: consume 1 Elemento puro, traslada el nexo de una invocación aliada a una casilla libre, la restaura sin kasteo, cura 1 y aumenta en 2 su vida máxima, con animación de traslado y asentamiento.',
  'La generación de Elemento puro emerge y cae junto al Kaster antes de viajar al medidor; los huecos vacíos ganan contraste. Las invocaciones marcadas por Ansatsu no Kokuin muestran una carga visual persistente hasta consumir o perder la marca.',
  'Activa Hattori Hanzo como Kaster funcional: vida 12, ataque físico 2 sin Crítico, Elemento puro 0/2/8, medidor y generación animada, Counter especial por cada 5 de daño al Kaster rival y habilidad nativa Ansatsu no Kokuin para convertir el siguiente ataque físico de invocaciones seleccionadas en daño directo seguido de 6 fases de estasis.',
  'Ordena el modal del Guardián en cuatro chips únicos y centrados, amplía el poder con la explicación completa, adapta los modales al color del dominio y cambia el Núcleo elemental a drops probabilísticos por cada punto de daño; la extracción básica baja de 3 a 2 cartas.',
  'Reestructura el modal del Guardián con la misma composición de los demás conjuros: estadísticas en sus filas normales, Resistencia con el escudo cuadriculado del token y capacidades con los iconos Aura y contención, Daño canalizado y Núcleo elemental en el panel derecho.',
  'Ajusta efectos y mitigación: aura del Guardián al 25% inactiva y 50% solo por hover o invasores rivales, círculo persistente del Kaster 40% menor, círculo de entrada de invocaciones 15% menor y chip de Armadura con la reducción real sin mostrar -0.',
  'Ajusta Guardianes y Kaster: aura visual al 10% inactiva/50% activa, canalización de 9 fases, anclaje sostenido de ataques a distancia contra Guardianes y círculo persistente sobre el Kaster durante kasteos de invocaciones de 1+ fases.',
  'Activa Guardianes defensivos: aura circular radio 3, bloqueo de ocultación/niebla/intangibilidad, Velocidad 1 para rivales, rayo canalizado de 3 fases por 1 daño y recompensa de 2 elementos al destruirlos; reduce 35% el círculo de invocación.',
  'El aviso de confirmación de una acción rival permanece abierto y mantiene la secuencia pausada hasta pulsar OK o Enter; se elimina el autocierre, el clic general y la confirmación con Espacio.',
  'Permite al Kaster atacar activamente durante su Resolución sin botón extra: al seleccionarlo muestra objetivos rivales en alcance, acepta selección directa o desde el panel izquierdo y restaura a la invocación enemiga si sobrevive al golpe.',
  'Repara la respuesta del Kaster durante ataques rivales: el bloqueo global permite usar el menú de defensa y los ataques a distancia muestran únicamente Defender, sin opción ni ejecución de Contraatacar.',
  'Limpia el estado fantasma de ventanas de acción rápida al ocultarse: la IA puede cerrar Resolución después de la acción del Kaster sin quedar bloqueada por active/locked/executing residuales.',
  'Corrige la reanudación tras la acción del Kaster: la IA ya no intenta resolver Disparo energizado como ventana rápida durante su propia Resolución; retoma su lógica normal y los avisos automáticos rivales ya no pueden bloquear la cola indefinidamente.',
  'Reanuda la Resolución rival como una sola secuencia después de la acción especial del Kaster local; elimina el temporizador desprendido que podía dejar a la IA detenida tras kastear las dos Kaguyas.',
  'Corrige la estrategia de apertura de la IA rival: tras las dos Kaguyas, el Kaster avanza antes de Takeda y su acción especial fuera de turno ya no queda bloqueada por el kasteo del turno anterior.',
  'Restaura la cadencia original del movimiento asistido para las unidades y fija el contador del Kaster dentro de la esquina superior izquierda de la miniatura.',
  'Ordena la transición Kasteo → acción de Kaster → Resolución: sin movimiento prematuro, con pausas orgánicas, contador arriba a la izquierda y miniatura oculta al iniciar el movimiento.',
  'La acción del Kaster entre Kasteo y Resolución reutiliza la misma miniatura lateral de acciones; el foil queda recortado exactamente al skin de la miniatura.',
  'Corrige el calculador de PB/rareza según el documento base: elimina base de tipo, usa tablas reales y calibra factores/poderes sin infladores duplicados.',
  'Agrega calculador interno de PB/rareza y panel debug secundario visible solo al abrir cartas desde la Biblioteca del constructor.',
  'Agrega Esquive como factor defensivo anti-distancia, asigna Esquive 5 a Samurai Shinra Hitokiri y sube su costo total a 6 para compensar la mecánica.',
  'Limpia la fase final de Sukiru Charenji: deja solo GUARDIA como contador visible, elimina los textos SUKIRU/EVASIÓN X/4 y convierte el límite anti-bucle en seguridad interna invisible.',
  'Activa la fase 2F de Sukiru Charenji: al completar 4 marcas, Guardia rota dispara el ataque final automático de Shinra con crítico nivel 5 y Letalidad nivel 5 forzada para la resolución.',
  'Activa la fase 2E de Sukiru Charenji: Desvío exitoso suma marcas de guardia y sube temporalmente el nivel de Desvío; Evasión no suma marca. Sin ataque final todavía.',
  'Ajusta la defensa inicial de Samurai Shinra Hitokiri para pruebas: Desvío baja a 2 y Evasión queda en 4, dejando margen de daño antes del leveo futuro.',
  'Sube la defensa de Samurai Shinra Hitokiri para pruebas: Desvío 4 y Evasión 4.',
  'Activa la fase 2D de Sukiru Charenji: si Shinra desvía o evade, el rival repite el ataque hasta 4 intentos seguros. Sin marcas ni guardia rota todavía.',
  'Activa la fase 2C de Sukiru Charenji: Shinra calcula Desvío antes que Evasión; si Desvía, el ataque falla sin daño. Sin marcas ni cadena todavía.',
  'Activa la fase 2B de Sukiru Charenji: Shinra Hitokiri nunca toma el primer golpe del par de combate y fuerza al rival a iniciar el intercambio.',
  'Registra el poder Sukiru Charenji para Samurai Shinra Hitokiri, lo asigna a la carta y deja su modal preparado sin activar todavía la lógica especial de combate.',
  'Mueve Samurai Shinra Hitokiri al primer slot del spellbook rival para testear su casteo de costo 1 antes de ajustar la IA estratégica.',
  'Repara el bloqueo global de secuencias de combate por referencia source indefinida, ajusta PDA de Daño crítico y sube Shinra Hitokiri a crítico nivel 5.',
  'Agrega la nueva invocación Samurai Shinra Hitokiri al dominio Luz con costo 1 para pruebas, la integra a Biblioteca y al spellbook rival, y registra el nuevo factor visual Desvío.',
  'Agrega la nueva invocación Shiro no Bushi con dominio Luz y la integra al spellbook rival para pruebas de consumo elemental de Luz.',
  'Fukurō no Me ajusta precisión a 3, usa Distancia con arco, corrige trayectoria/impacto de flecha y mueve Arma extra a Humano.',
  'Costo de invocaciones pasa a control CSS por costo total y se recalcula automáticamente como dominio base + costo aleatorio según el total.',
  'Balance: Naito Sutoka sube a costo 5, kasteo 5, restauración 5 y enfriamiento registrado 5; Kagero baja a costo 1 y kasteo 0.',
  'Corrige modal/HUD de Sutoka, Back contextual, fuentes de Acechar/Oculto/Movilidad completa y reactiva Ataque extra tras el intercambio.',
  'Naito Sutoka recibe Acechar por la cualidad Acechador: 3 huecos de habilidad, movilidad completa en área rival, modal clicable y botón Back en modales.',
  'Naito Sutoka ajusta alcance a 2 y activa Oscilación parcial: barrido frontal con 100% al primer token y 50% a los siguientes.',
  'Agrega el Guardián de Luz usando el asset entregado por el usuario y lo asigna a los guardianes del jugador cuyo Kaster tenga dominio Luz.',
  'Pulido visual del retorno al Spellbook: arco continuo sin pausas, landing elemental y la carta reaparece solo después del splash final.',
  'Extracción equilibrada: se eliminan cartas x2/x3/x4 del mazo elemental, cada extracción roba 3 cartas x1 y la relación de dominios duales pasa a 60/40.',
  'Asegura que las animaciones de kasteo, extracción, retorno/restauración y destrucción queden por encima de la bomba de humo y la niebla sin mover el humo de sitio.',
  'La animación de retorno por muerte de invocación se hace más lenta y legible: destrucción en arena, subida en arco hacia el Spellbook y landing elemental al llegar.',
  'Aumenta el hitbox de invocaciones para que sea cómodo seleccionar fichas sin volver a tapar casillas/fichas detrás.',
  'Bloquea el botón de siguiente fase durante Extracción para evitar saltarse la animación y perder recursos.',
  'El icono central de la bomba de humo queda en una capa baja separada; la niebla y partículas se mantienen igual.',
  'Al clicar una casilla vacía o no válida de la arena se cierran los botones Info/Poder y se deselecciona la invocación.',
  'Reduce el collider/hitbox de fichas a un botón pequeño en la casilla base para que una ficha visualmente superpuesta no bloquee la selección de la ficha/casilla detrás.',
  'Agrega controles individuales para tokens de Kasters y cambia la muerte de invocaciones a brillo elemental + destrucción tipo estructura.',
  'Se separan los iconos planos de arena (arma, movimiento pendiente y Oculto) de la capa visual del token para que no reciban outline/glow/hover; queda una clase protegida para futuros iconos planos.',
  'La cortina de humo conserva sus nodos visuales al renderizar para que la animación no se reinicie con acciones del jugador o del rival.',
  'Las casillas de humo ahora tienen pulso desincronizado/aleatorio sin cambiar los valores de control de opacidad y escala calibrados por el usuario.',
  'Las animaciones de kasteo, extracción y viaje de cartas quedan por encima de la niebla/bomba de humo sin mover la niebla de su capa visual.',
  'El hitbox/collider de invocaciones queda limitado a la casilla base para evitar que una ficha bloquee otra 2 o 3 casillas arriba.',
  'Los grids de arena, líneas de riesgo y línea central ahora toman color del dominio visual del Kaster de cada jugador.',
  'Se separa dominio visual del Kaster del dominio real de las cartas: el Kaster controla ecosistema visual/extracción, pero costos, fondos, skins, respawn y unidades respetan su carta.',
  'Luz ajusta su paleta a dorado más oscuro tipo mantequilla/oro y Tokugawa mantiene Luz como base visual con Fuego como secundario de extracción.',
  'Corrige los fondos de dominio para cartas de Invocación/Kaster/Estructura: Luz usa el templo dorado indicado por el usuario y Fuego usa el paisaje volcánico rojo indicado por el usuario.',
  'Ieyasu Tokugawa queda coordinado con dominio primario Luz y elemento secundario Fuego para su deck elemental; la configuración ahora lee el dominio del Kaster.',
  'Caudillo usa el icono SVG correcto subido por el usuario y su descripción oficial del Excel de cualidades.',
  'Los Kasters ya no muestran chip de Elemento/Atributo debajo del tag KASTER; ahora muestran raza y cualidad como las invocaciones.',
  'Se registran Hattori Hanzo como Ninja/Asesino y Ieyasu Tokugawa como Samurai/Caudillo.',
  'Se actualiza el modal del elemento Luz - Revelación con su resumen, manejo elemental, tempo, invocaciones, fortalezas, debilidades y descripción final.',
  'Se elimina del panel ancho del Kaster el chip flotante de iconos Elemento/Atributo; los assets quedan registrados pero no se muestran ahí.',
  'Corrige Elemento Luz para usar las nubes doradas/blancas, no el skin; el panel del Kaster muestra solo iconos de Elemento/Atributo sin tag textual Luz · Revelación.',
  'El panel y la vista del Kaster ahora muestran los iconos de Elemento y Atributo según el dominio activo del Kaster.',
  'Se registra correctamente el asset de Elemento Luz como nubes doradas/blancas y el atributo Revelación como logo propio, separando ambos del icono de costo Luz.',
  'Tokugawa se asigna como Kaster activo del rival J2 con dominio principal Luz, usando su arte/token y extracción de Luz.',
  'Se integra el Kaster Tokugawa de Luz como carta/caster registrado, usando arte y token propios, sin asignarlo todavía como Kaster activo del rival.',
  'Base de dominios Luz/Oscuridad: se registran assets de Luz, costo Luz, frascos X1-X4, skin Luz y Tokugawa como caster visual preparado sin cambiar todavía el rival a Luz.',
  'Reconstrucción limpia desde v5.3.100: se conservan visuales estables y solo se reaplican cambios pedidos.',
  'Toyotomi Hideyoshi corrige el cruce de imagen carta/token.',
  'Se agrega regreso de Resolución a Kasteo solo si no hubo acciones.',
  'Se restaura el aviso correcto de movimiento obligatorio: la ficha vibra al intentar pasar fase con movimiento pendiente.',
  'Toyotomi Hideyoshi usa explícitamente su token de arena y recibe controles de tamaño reforzados para que no desaparezca por escala.',
  'El indicador de restauración de invocaciones ahora usa el mismo lenguaje de contenedor que ataque/vida, con controles propios de tamaño, posición e icono.',
  'Controles individuales de tamaño para cada ficha de invocación en arena, incluyendo Ojo de búho y Samurai Akari.',
  'Naito muestra solo botones Info y Poder cuando está seleccionada en tu resolución; el ataque vuelve al flujo normal de seleccionar objetivo.',
  'Sutoka hatsuen-dan solo puede lanzarse si no hay una cortina de humo activa; la reacción defensiva usa botón Poder con brillo breve.',
  'La cortina de humo ahora genera partículas de nube aleatorias sobre aproximadamente el 70% de las casillas del área, por encima de la arena y con transparencia suave.',
  'La bomba de humo de Naito ahora puede reaccionar contra ataques/selecciones rivales de invocaciones, Kaster, poderes y conjuros que apunten a una invocación aliada válida.',
  'Se refuerza el latido visible del icono central de la bomba de humo con controles propios de escala y opacidad.',
  'La bomba de humo ahora dura 6 fases completas desde su lanzamiento, no una ronda contada al cambio de jugador.',
  'Las invocaciones ocultas por humo ya no bloquean casillas para el rival; si el rival entra en esa casilla, la invocación oculta se desplaza a una casilla adyacente cercana al Kaster rival.',
  'Se corrige la sinergia Ninja: solo Naito Sutoka puede activar bombas; los demás Ninjas solo ganan Oculto dentro de la cortina.',
  'Se eliminan iconos repetidos de bomba en las casillas válidas; ahora el área de lanzamiento ilumina casillas y muestra el icono solo al hacer hover.',
  'Se agregan controles visuales superiores para humo, botón de poder, iconos, radio de cortina y calibración de grids.',
  'Se agrega botón directo de poder sobre los Ninjas aliados durante Resolución para que Sutoka hatsuen-dan pueda activarse sin depender del menú emergente anterior.',
  'Se refuerza el hitbox de invocaciones propias durante Resolución para recuperar movimiento, ataque y selección de objetivo.',
  'Naito sutoka puede activar Sutoka hatsuen-dan de forma voluntaria durante tu fase de Resolución, además de usarlo como reacción.',
  'Naito puede reaccionar con Sutoka hatsuen-dan cuando un Kaster o conjuro rival la selecciona como objetivo, antes de resolver el efecto.',
  'Se corrige la interacción de fichas con poder: se elimina el contador flotante de bombas sobre Naito, se restaura el click/movimiento de invocaciones normales y el menú de Naito queda con Atacar objetivo / Activar poder.',
  'Se integra el style.css subido por el usuario y se reaplican encima los estilos necesarios de humo/oculto sin el badge extra de contador en arena.',
  'Naito Sutoka ajusta alcance a 3, velocidad a 3 y recupera el factor funcional Ataque extra.',
  'El modal de Bomba de humo deja de usar la plantilla ofensiva: ahora muestra Arma / especial, aplicación táctica y sin daño base.',
  'Se corrigen los iconos invertidos de Bomba de humo y Oculto en todos los usos visuales, modales, badges y animaciones.',
  'Golpe crítico 2 baja a 3 PDA y mantiene multiplicador x2.',
  'Kagero y cualquier carta sin aplicación explícita real no renderizan chip de aplicación de daño; el overlay purga cualquier chip fantasma.',
  'Los factores ofensivos ahora usan un contenedor propio separado del alcance y la precisión.',
  'La PDA de precisión se ajusta para que precisión 6 sea acierto garantizado salvo reducción por evasión u otros efectos.',
  'Se agrega la carta aliada Ninja Naito sutoka con arte, ficha, stats base, cualidades y aplicación de daño explícita.',
  'Se agrega la carta enemiga Samurai Akari con arte, ficha, stats base de cualidades Tirador/Guerrero y costo fuego + aleatorio.',
  'Se agrega la carta aliada Ninja Ojo de búho con arte, ficha, stats base de arquero oscuro y sin activar todavía Probabilidad de letalidad ni Arma extra.',
  'Se agrega la carta enemiga Samurai Toyotomi hideyoshi con arte, ficha y stats base de héroe cuerpo a cuerpo, dejando aparte su poder y evasión para un parche posterior.',
  'Se corrige la inversión de imágenes carta/ficha en Ninja Naito sutoka y Samurai Akari, restaurando el mapeo correcto de artImage y tokenImage según los archivos originales subidos por el usuario.',
  'Se corrige el mapeo de arte/ficha de Ninja Ojo de búho: la carta usa ahora la imagen con borde y la ficha en arena usa la imagen sin borde.',
  'Se limpia el paquete eliminando archivos de respaldo y capturas sueltas no usadas por el juego.',
  'v352: aplica el color dinámico a Usuario, Objetivo, Kaster, Invocación y cualidades; añade un watchdog a Web Animations para impedir que la Extracción rival deje el turno bloqueado si animation.finished no responde.',
  'v355: aplica también en Kage no Michi la jerarquía visual Usuario → Kaster → Oscuridad/Asesino y Objetivo → Invocación → Oscuridad/Asesino/Bandido/Acechador, manteniendo agrupadas las restricciones del modal.',
  'v354: reconstruye Despliegue anticipado: exige Caudillo antes de pagar, selecciona objetivo antes del kasteo, permite dos copias sobre el mismo Caudillo, muestra disponibilidad en el Spellbook y monta los vínculos en la miniatura persistente correcta.',
  'v351: ajusta Despliegue anticipado a costo 2, reducción y bloqueo acumulables por dos instancias, separa Usuario → Kaster → cualidades y Objetivo → Invocación → Caudillo, y tematiza los modales por carta en Biblioteca o por Kaster durante la partida.',
  'v350: integra Despliegue anticipado, la cualidad Caballero, vínculo a Caudillo, reducción de costo para Guerreros y contador de uso de 3 fases.',
  'Se agrega la primera carta de tipo Hechizo: Kage no Michi, usando composición de fondo + skin y sin efecto funcional todavía.',
  'Se agrega el poder Sutoka hatsuen-dan a Ninja Naito sutoka, con modal clicable, contador de bombas y sinergia de familia Ninja.',
  'Se implementan las bombas de humo como arma arrojadiza funcional: alcance 3, cortina de humo de radio 3, duración de una ronda y consumo visual del contador.',
  'Se agrega el factor universal Oculto con icono en ficha, bloqueo de selección por la IA rival y reaplicación dinámica dentro de la cortina de humo.',
];

