const SMOKE_BOMB_ICON_ASSET = 'assets/weapons/smoke-bomb.svg';
const HIDDEN_FACTOR_ICON_ASSET = 'assets/factors/factor-oculto.png';
const KAGUYA_CHARGED_SHOT_IMAGE_ASSET = 'assets/powers/kaguya-disparo-energizado.webp';
const SUTOKA_SMOKE_BOMB_IMAGE_ASSET = 'assets/powers/sutoka-bomba-de-humo.webp';
const EXTRA_ATTACK_FACTOR_ICON_ASSET = 'assets/factors/factor-ataque-extra.png';
const ATTACK_SPEED_FACTOR_ICON_ASSET = 'assets/factors/factor-atacar-primero.svg';

const CATALYST_DOMAIN_ID = 'catalizadora';
const CATALYST_SKIN_ASSET = 'assets/card-skin-catalyst.png';

function isCatalystCard(card) {
  return !!(card && (card.isCatalyst === true || card.catalyst === true || card.domain?.elementId === CATALYST_DOMAIN_ID || card.domain?.universal === true));
}

function cardMatchesElementDomain(card, elementId) {
  if (!card || !elementId) return false;
  if (isCatalystCard(card)) return true;
  return getCardElementId(card) === elementId;
}

function getCatalystRandomCostTotal(card, controlledInvocationTotal = null) {
  if (!card) return 0;
  if (controlledInvocationTotal != null) return Math.max(0, Math.round(Number(controlledInvocationTotal) || 0));
  return Math.max(0, Math.round(totalCost(card.cost || {})));
}

