function getCasterDefinition(caster) {
  if (!caster) return null;
  if (caster.casterId && CASTER_LIBRARY[caster.casterId]) return CASTER_LIBRARY[caster.casterId];
  if (caster.cardId) {
    return Object.values(CASTER_LIBRARY).find(item => item.cardId === caster.cardId) || null;
  }
  return null;
}

function getCasterDisplayName(caster, fallback = 'Kaster') {
  return getCasterDefinition(caster)?.name || caster?.name || fallback;
}

function getCasterCompactDisplayName(caster, fallback = 'Kaster') {
  const def = getCasterDefinition(caster);
  const card = caster?.cardId ? CARD_LIBRARY[caster.cardId] : null;
  return def?.shortName || card?.shortName || caster?.shortName || def?.name || caster?.name || fallback;
}

function getCasterTokenImage(caster, fallback = 'assets/caster-hanzo.png') {
  return caster?.customAvatarUrl || getCasterDefinition(caster)?.tokenImage || caster?.tokenImage || fallback;
}

function getCasterArtImage(caster, fallback = 'assets/caster-hanzo.png') {
  return caster?.customAvatarUrl || getCasterDefinition(caster)?.artImage || caster?.artImage || fallback;
}

function applyLocalProfileCasterAvatar(url = '') {
  const caster = state?.players?.[LOCAL_PLAYER_ID]?.caster;
  if (!caster) return;
  const clean = String(url || '').trim();
  if (clean) caster.customAvatarUrl = clean;
  else delete caster.customAvatarUrl;
  try {
    renderUnits();
    renderCasterWidePanel();
  } catch (_) {}
}

function isHattoriCaster(playerId) {
  const caster = state?.players?.[playerId]?.caster;
  return Boolean(caster && (caster.casterId === 'hanzoDark' || caster.cardId === 'kasterHanzoDark'));
}

function isTokugawaCaster(playerId) {
  const caster = state?.players?.[playerId]?.caster;
  return Boolean(caster && (caster.casterId === 'tokugawaLight' || caster.cardId === 'kasterTokugawaLight'));
}

function getNativeCasterAbilityId(playerId) {
  const caster = state?.players?.[playerId]?.caster;
  const casterCard = caster?.cardId ? CARD_LIBRARY[caster.cardId] : null;
  const inferredLevel = casterCard ? (getCasterMatchProgress(casterCard)?.level || 1) : 1;
  const effectiveLevel = Math.max(1, Number(caster?.effectiveLevel || inferredLevel || 1));
  // La primera habilidad de Kaster se desbloquea globalmente en nivel 4.
  // En PvP/Bot el runtime ya se normaliza a nivel 10.
  if (effectiveLevel < 4) return null;
  if (isHattoriCaster(playerId)) return 'ansatsuNoKokuin';
  if (isTokugawaCaster(playerId)) return 'jinchiTenkan';
  const card = getCasterCardForPlayer(playerId);
  return card?.abilities?.find(entry => entry?.nativeCasterAbility)?.id || card?.abilities?.[0]?.id || null;
}

function ensureCasterRuntime(playerId) {
  const caster = state?.players?.[playerId]?.caster;
  if (!caster) return null;
  const def = getCasterDefinition(caster);
  const card = caster.cardId ? CARD_LIBRARY[caster.cardId] : null;
  const stats = def?.stats || card?.stats || {};
  caster.atk = Number.isFinite(Number(caster.atk)) ? Number(caster.atk) : Number(stats.atk ?? stats.damage ?? 0);
  caster.def = Number.isFinite(Number(caster.def)) ? Number(caster.def) : Number(stats.def ?? 0);
  caster.life = Number.isFinite(Number(caster.life)) ? Number(caster.life) : Number(stats.life ?? 0);
  caster.maxLife = Number.isFinite(Number(caster.maxLife)) ? Number(caster.maxLife) : Number(stats.maxLife ?? stats.life ?? caster.life ?? 0);
  caster.pureBase = Math.max(0, Number(caster.pureBase ?? stats.pureBase ?? 0));
  caster.pureCadence = Math.max(0, Number(caster.pureCadence ?? stats.pureCadence ?? 0));
  caster.pureMax = Math.max(caster.pureBase, Number(caster.pureMax ?? stats.pureMax ?? 0));
  caster.pureElement = Math.max(0, Math.min(caster.pureMax, Number(caster.pureElement ?? caster.pureBase)));
  caster.pureCastingVisitCount = Math.max(0, Number(caster.pureCastingVisitCount ?? 0));
  caster.pureCastingLastKey = String(caster.pureCastingLastKey || '');
  caster.pureExtractionLastKey = String(caster.pureExtractionLastKey || '');
  caster.specialCounterProgress = Math.max(0, Math.min(CASTER_SPECIAL_COUNTER_DAMAGE_THRESHOLD, Number(caster.specialCounterProgress ?? 0)));
  caster.specialCounters = Math.max(0, Number(caster.specialCounters ?? 0));
  return caster;
}

function getCasterPureElement(playerId) {
  return Number(ensureCasterRuntime(playerId)?.pureElement || 0);
}

function spendCasterPureElement(playerId, amount) {
  const caster = ensureCasterRuntime(playerId);
  const cost = Math.max(0, Math.floor(Number(amount) || 0));
  if (!caster || caster.pureElement < cost) return false;
  caster.pureElement -= cost;
  renderAll();
  return true;
}

function renderPureElementMeterHtml(caster, options = {}) {
  if (!caster) return '';
  const current = Math.max(0, Number(caster.pureElement || 0));
  const maximum = Math.max(0, Number(caster.pureMax || 0));
  const cadence = Math.max(1, Number(caster.pureCadence || 1));
  if (maximum <= 0) return '<span class="pure-element-meter-empty">Sin Elemento puro</span>';
  const compact = options.compact === true;
  const cells = [];
  for (let index = 0; index < maximum; index += 1) {
    if (index > 0 && index % cadence === 0) cells.push('<span class="pure-element-divider" aria-hidden="true">/</span>');
    const filled = index < current;
    cells.push(`<span class="pure-element-slot ${filled ? 'filled' : 'empty'}" title="${filled ? 'Elemento puro disponible' : 'Hueco de Elemento puro'}"><img src="${filled ? PURE_ELEMENT_ASSET : PURE_ELEMENT_EMPTY_ASSET}" alt=""></span>`);
  }
  return `<span class="pure-element-meter${compact ? ' compact' : ''}" data-current="${current}" data-max="${maximum}" data-cadence="${cadence}">${cells.join('')}</span>`;
}


function renderPureElementCostIcons(amount, options = {}) {
  const count = Math.max(0, Math.floor(Number(amount) || 0));
  const compact = options.compact === true;
  const icons = Array.from({ length: count }, () => `<img src="${PURE_ELEMENT_ASSET}" alt="Elemento puro">`).join('');
  return `<span class="caster-ability-pure-cost${compact ? ' compact' : ''}" title="Costo: ${count} Elementos puros">${icons}</span>`;
}

function getNativeCasterAbilityPureCost(playerId) {
  if (isHattoriCaster(playerId)) return HATTORI_ABILITY_PURE_COST_PER_TARGET;
  if (isTokugawaCaster(playerId)) return TOKUGAWA_ABILITY_PURE_COST;
  return 0;
}

function isCasterAbilityCard(card) {
  return Boolean(card && (card.type === 'casterAbility' || card.cardType === 'casterAbility'));
}

function getLoadedCasterAbilityCards(playerId) {
  const player = state?.players?.[playerId];
  if (!player) return [];
  return (player.handTabs || []).flat().map(cardId => CARD_LIBRARY[cardId]).filter(card => isCasterAbilityCard(card));
}

function recordCasterDamageForSpecialCounter(attackerPlayerId, amount) {
  if (!attackerPlayerId || amount <= 0) return;
  const caster = ensureCasterRuntime(attackerPlayerId);
  if (!caster || caster.specialCounters > 0) return;
  const accumulated = Number(caster.specialCounterProgress || 0) + Math.max(0, Number(amount) || 0);
  if (accumulated >= CASTER_SPECIAL_COUNTER_DAMAGE_THRESHOLD) {
    caster.specialCounterProgress = Math.max(0, accumulated - CASTER_SPECIAL_COUNTER_DAMAGE_THRESHOLD);
    caster.specialCounters = 1;
    showFloatingTextAt(caster.row, caster.col, 'COUNTER ESPECIAL');
    log(`Kaster J${attackerPlayerId} desbloquea Counter especial.`);
  } else {
    caster.specialCounterProgress = accumulated;
  }
}

function getDomainTheme(domainId, fallbackId = 'oscuridad') {
  return DOMAIN_THEME_DB[domainId] || DOMAIN_THEME_DB[fallbackId] || DOMAIN_THEME_DB.oscuridad;
}

function getCasterDomainId(caster) {
  return caster?.domainId || caster?.elementId || null;
}

function getPlayerDomainId(playerId) {
  const player = state?.players?.[playerId];
  return getCasterDomainId(player?.caster) || player?.domainId || player?.elementId || 'oscuridad';
}

function getPlayerDomainTheme(playerId) {
  return getDomainTheme(getPlayerDomainId(playerId));
}

