function getGuardianAssetForPlayer(playerId) {
  const domainId = getPlayerDomainId(playerId);
  return GUARDIAN_DOMAIN_ASSETS[domainId] || GUARDIAN_DOMAIN_ASSETS.oscuridad;
}

