function getWeaponProfile(card) {
  const weaponType = card?.weaponType || card?.attackProfile?.weaponType || 'golpe';
  const base = WEAPON_DB[weaponType] || WEAPON_DB.golpe;
  const condition = card?.weaponConditions?.[weaponType] || card?.attackProfile?.weaponCondition || {};
  return { ...base, condition, isConsumable: Boolean(condition.consumable), conditionNote: condition.note || '' };
}

function getWeaponInfoProfile(weaponId) {
  const weapon = WEAPON_DB[weaponId] || WEAPON_DB.golpe;
  return weapon;
}

function getWeaponSemanticContext(weapon, card = null, options = {}) {
  const categoryText = String(weapon?.category || '').toLocaleLowerCase('es');
  const isNativeAttack = categoryText.includes('ataque nativo') || weapon?.semanticKind === 'attack';
  const root = isNativeAttack ? 'Ataque' : 'Arma';
  const role = options.extra ? 'Extra' : (isNativeAttack ? 'Nativo' : 'Base');
  const mode = card ? getCombatModeProfile(card) : null;
  return {
    root,
    role,
    mode,
    levels: [root, role, ...(mode?.label ? [mode.label] : [])],
  };
}

function buildWeaponInfoHtml(weapon, card = null) {
  const condition = card ? (card.weaponConditions?.[weapon.id] || card.attackProfile?.weaponCondition || null) : null;
  const damageNature = card ? getDamageNatureProfile(card) : null;
  const semantic = getWeaponSemanticContext(weapon, card);
  const damageText = damageNature
    ? `<p><strong>Tipo de daño de esta carta:</strong> <button type="button" class="card-info-inline-chip" data-info-kind="damageNature" data-info-id="${damageNature.id}"><span class="card-info-letter-badge">${damageNature.letter}</span><span>${damageNature.label}</span></button></p>`
    : '';
  const extraWeapons = card ? getCardExtraWeapons(card) : [];
  const principalText = card && (card.weaponType === weapon.id || card.attackProfile?.weaponType === weapon.id)
    ? `<p><strong>${semantic.root === 'Arma' ? 'Arma' : 'Ataque'} principal de esta carta:</strong> <button type="button" class="card-info-inline-chip" data-info-kind="weaponDetail" data-info-id="${weapon.id}"><img src="${weapon.icon}" alt="${weapon.label}"><span>${weapon.label}</span></button></p>`
    : '';
  const extraWeaponText = extraWeapons.length ? `<p><strong>Factor:</strong> ${extraWeapons.map(extraWeapon => {
    const extraWeaponInfo = getWeaponInfoProfile(extraWeapon.weaponType);
    const sourceFactor = getFactorProfile(extraWeapon.sourceFactor || 'extraWeapon');
    const sourceId = getExtraWeaponSourceId(extraWeapon);
    return `<button type="button" class="card-info-inline-chip" data-info-kind="factor" data-info-id="${sourceFactor?.id || 'extraWeapon'}" data-factor-level="1" data-factor-source="${sourceId}"><img src="${sourceFactor?.icon || extraWeaponInfo.icon}" alt="${sourceFactor?.label || 'Arma extra'}"><span>${sourceFactor?.label || 'Arma extra'}</span></button>`;
  }).join('')}</p>` : '';
  const jointFactors = card ? getCardAttackFactors(card).filter(entry => (entry?.sourceWeapon || entry?.requiresWeaponType) === weapon.id) : [];
  const jointFactorsHtml = jointFactors.length ? `<p><strong>Factores habilitados conjuntamente con la cualidad compatible:</strong> ${jointFactors.map(entry => { const factor = getFactorProfile(entry.id); return `<button type="button" class="card-info-inline-chip" data-info-kind="factor" data-info-id="${entry.id}" data-factor-level="${entry.level || 1}" data-factor-source="${entry.source || ''}"><img src="${factor?.icon || ''}" alt="${factor?.label || entry.id}"><span>${factor?.label || entry.id} ${entry.level || 1}</span></button>`; }).join('')}</p><p>El arma no concede estos factores por sí sola: requiere también la cualidad indicada en la carta.</p>` : '';
  // Un arma/ataque base no necesita explicar que no se consume. Solo se documenta
  // el consumo cuando esta versión concreta sí tiene una condición consumible.
  const conditionText = condition?.consumable
    ? `<p><strong>Condición especial:</strong> Esta carta consume ${weapon.label} al utilizarlo. ${condition.note || ''}</p>`
    : '';
  return `<p><strong>Resumen:</strong> ${weapon.summary || 'Tipo de ofensiva disponible.'}</p>${buildSemanticTagChainHtml(semantic.levels)}${principalText}${damageText}${extraWeaponText}${jointFactorsHtml}${conditionText}`;
}

function buildWeaponDetailHtml(weapon, card = null) {
  const condition = card ? (card.weaponConditions?.[weapon.id] || card.attackProfile?.weaponCondition || null) : null;
  const semantic = getWeaponSemanticContext(weapon, card);
  const conditionText = condition?.consumable
    ? `<p><strong>Condición especial:</strong> Esta carta consume ${weapon.label} al utilizarlo. ${condition.note || ''}</p>`
    : '';
  return `<p><strong>Resumen:</strong> ${weapon.summary || 'Tipo de ofensiva disponible.'}</p>${buildSemanticTagChainHtml(semantic.levels)}<p>${weapon.description}</p>${conditionText}`;
}

function getBaseAttackCard(card) {
  if (!card) return null;
  const base = card.baseAttackProfile || {};
  const combatMode = base.combatMode || base.type || 'melee';
  const combatModeLabel = COMBAT_MODE_DB[combatMode]?.label || (combatMode === 'distance' ? 'Distancia' : combatMode === 'range' ? 'Rango' : 'Cuerpo a cuerpo');
  return {
    ...card,
    weaponType: base.weaponType || 'golpe',
    weaponConditions: {},
    attackProfile: {
      type: combatMode,
      combatMode,
      label: base.label || combatModeLabel,
      range: Number(base.range ?? 1),
      precision: Number(base.precision ?? 4),
      damage: Number(base.damage ?? 1),
      damageNature: base.damageNature || 'physical',
      applicationId: Object.prototype.hasOwnProperty.call(base, 'applicationId') ? base.applicationId : (Object.prototype.hasOwnProperty.call(base, 'damageApplication') ? base.damageApplication : null),
      modifiers: Array.isArray(base.modifiers) ? base.modifiers : [],
    },
  };
}


function getCardExtraWeapons(card) {
  return Array.isArray(card?.extraWeapons) ? card.extraWeapons : [];
}

function getExtraWeaponProfile(card, id = '') {
  const weapons = getCardExtraWeapons(card);
  if (!weapons.length) return null;
  return weapons.find(entry => String(entry.id) === String(id) || String(entry.weaponType) === String(id)) || weapons[0];
}


function buildAttackProfileFromWeaponEntry(entry = null, fallbackCard = null) {
  if (!entry) return fallbackCard?.attackProfile ? { ...(fallbackCard.attackProfile || {}) } : {};
  const combatMode = entry.combatMode || entry.type || 'melee';
  const combatModeLabel = COMBAT_MODE_DB[combatMode]?.label || (combatMode === 'distance' || combatMode === 'longRange' ? 'Distancia' : combatMode === 'range' || combatMode === 'tacticalRange' ? 'Rango' : 'Cuerpo a cuerpo');
  const hasExplicitApplication = Object.prototype.hasOwnProperty.call(entry, 'applicationId') || Object.prototype.hasOwnProperty.call(entry, 'damageApplication');
  const explicitApplication = Object.prototype.hasOwnProperty.call(entry, 'applicationId') ? entry.applicationId : entry.damageApplication;
  return {
    weaponType: entry.weaponType || fallbackCard?.weaponType || 'golpe',
    shirahadoriCompatible: entry.shirahadoriCompatible === true,
    type: combatMode,
    combatMode,
    label: entry.label || combatModeLabel,
    range: Number(entry.range ?? 1),
    precision: Number(entry.precision ?? 4),
    damage: Number(entry.damage ?? fallbackCard?.stats?.damage ?? fallbackCard?.stats?.atk ?? 1),
    damageNature: entry.damageNature || 'physical',
    applicationId: hasExplicitApplication ? explicitApplication : null,
    modifiers: Array.isArray(entry.modifiers) ? entry.modifiers : [],
    factors: Array.isArray(entry.factors) ? entry.factors : [],
  };
}

function getAttackProfileForWeapon(card, weaponType = null) {
  if (!card) return {};
  const normalized = String(weaponType || '').trim();
  const primaryWeaponType = String(card?.attackProfile?.weaponType || card?.weaponType || '').trim();
  const baseWeaponType = String(card?.baseAttackProfile?.weaponType || 'golpe').trim();
  if (!normalized || normalized === primaryWeaponType) return {
    ...(card.attackProfile || {}),
    weaponType: primaryWeaponType || card.weaponType || 'golpe',
    shirahadoriCompatible: card.attackProfile?.shirahadoriCompatible === true || card.shirahadoriCompatible === true,
  };
  if (normalized === baseWeaponType) return { ...(card.baseAttackProfile || {}) };
  const extra = getExtraWeaponProfile(card, normalized);
  if (extra && (String(extra.id) === normalized || String(extra.weaponType) === normalized)) {
    return buildAttackProfileFromWeaponEntry(extra, card);
  }
  return { ...(card.attackProfile || {}) };
}

function getFallbackWeaponTypeAfterDisarm(unit, droppedWeaponType = '') {
  const card = unit ? CARD_LIBRARY[unit.cardId] : null;
  if (!card) return card?.baseAttackProfile?.weaponType || 'golpe';
  const dropped = String(droppedWeaponType || '').trim();
  const extraWeapons = getCardExtraWeapons(card).filter(entry => entry && String(entry.weaponType || entry.id || '').trim());
  const fallbackExtra = extraWeapons.find(entry => String(entry.weaponType || entry.id || '').trim() !== dropped);
  if (fallbackExtra) return fallbackExtra.weaponType || fallbackExtra.id;
  return card?.baseAttackProfile?.weaponType || 'golpe';
}

function getUnitDroppedWeapons() {
  return Array.isArray(state.droppedWeapons) ? state.droppedWeapons : [];
}

function getUnitOwnerPlayerId(unit) {
  return Number(unit?.owner || unit?.playerId || 0);
}

function getDroppedWeaponMarkerAtForUnit(unit, row = null, col = null) {
  if (!unit) return null;
  const ownerPlayerId = getUnitOwnerPlayerId(unit);
  const targetRow = Number(row ?? unit.row ?? -1);
  const targetCol = Number(col ?? unit.col ?? -1);
  return getUnitDroppedWeapons().find(entry => Number(entry?.ownerPlayerId || 0) == ownerPlayerId
    && String(entry?.ownerUnitId || '') === String(unit.id || '')
    && Number(entry?.row) === targetRow
    && Number(entry?.col) === targetCol) || null;
}

function getRecoverableDroppedWeaponMarkerForUnit(unit) {
  if (!unit) return null;
  const ownerPlayerId = getUnitOwnerPlayerId(unit);
  return getUnitDroppedWeapons().find(entry => Number(entry?.ownerPlayerId || 0) === ownerPlayerId
    && String(entry?.ownerUnitId || '') === String(unit.id || '')) || null;
}

function cancelKaguyaChargedShotState(unit, reason = 'cancelación', options = {}) {
  if (!unit || !isKaguyaUnit(unit)) return false;
  const ownerPlayerId = getUnitOwnerPlayerId(unit);
  const hadPrimed = Boolean(unit.kaguyaChargedShotPrimed);
  const hadChanneling = Boolean(unit.kaguyaChanneling);
  const queue = Array.isArray(state.kaguyaChargedShots) ? state.kaguyaChargedShots : [];
  const remaining = queue.filter(shot => !(Number(shot?.playerId || 0) === ownerPlayerId && String(shot?.unitId || '') === String(unit.id || '')));
  const hadQueued = remaining.length !== queue.length;
  if (!hadPrimed && !hadChanneling && !hadQueued) return false;
  state.kaguyaChargedShots = remaining;
  unit.kaguyaChargedShotPrimed = false;
  unit.kaguyaChanneling = false;
  unit.kaguyaChannelRemaining = 0;
  const pending = state.pendingPowerAction;
  if (pending?.kind === 'kaguyaChargedShot'
    && Number(pending.playerId) === Number(ownerPlayerId)
    && String(pending.unitId || '') === String(unit.id || '')) {
    state.pendingPowerAction = null;
    if (typeof pending.reactionResolve === 'function') pending.reactionResolve('cancelled');
    else if (pending.fromQuickReactionWindow) forceReleaseQuickReactionManualPowerFlow('cancelled');
  }
  if (!options.suppressFloatingText) showFloatingTextAt(unit.row, unit.col, 'DISPARO CANCELADO', 'floating-combat debuff');
  log(`Disparo energizado de ${CARD_LIBRARY[unit.cardId]?.name || 'Kaguya'} se cancela por ${reason}.`);
  return true;
}

async function animateDroppedWeaponRecovery(playerId, unit, marker, weaponInfo = null) {
  if (!els.boardContent || !unit || !marker) return false;
  const info = weaponInfo || getWeaponInfoProfile(marker.weaponType || 'golpe');
  const localStart = getBoardLocalPointForCell(marker.row, marker.col);
  const start = viewportPointFromBoardLocal(localStart);
  const unitNode = getUnitDomNode(playerId, unit.id);
  const tokenNode = unitNode?.querySelector?.(':scope > .unit-token-img') || unitNode;
  const tokenRect = tokenNode?.getBoundingClientRect?.();
  const end = tokenRect
    ? { x: tokenRect.left + tokenRect.width * .5, y: tokenRect.top + tokenRect.height * .32 }
    : { x: start.x, y: start.y - 42 };
  const boardRect = els.boardContent.getBoundingClientRect();
  const iconSize = Math.max(27, Math.min(84, boardRect.width * 0.039));

  const fx = document.createElement('div');
  fx.className = 'weapon-recovery-fx';
  fx.style.left = `${start.x}px`;
  fx.style.top = `${start.y}px`;
  fx.style.width = `${iconSize}px`;
  fx.style.height = `${iconSize}px`;
  fx.innerHTML = `<span class="weapon-recovery-ring"></span><span class="weapon-recovery-inner"><img src="${info.icon}" alt="${info.label || marker.weaponType || 'Arma'}"></span>`;
  getGlobalFxLayer().appendChild(fx);

  const liftX = start.x + ((end.x - start.x) * .42);
  const liftY = Math.min(start.y, end.y) - Math.max(34, iconSize * .72);
  await animateCss(fx, [
    { left: `${start.x}px`, top: `${start.y + Math.max(5, iconSize * .12)}px`, transform: 'translate(-50%, -50%) scale(.72)', opacity: 0 },
    { left: `${start.x}px`, top: `${start.y}px`, transform: 'translate(-50%, -50%) scale(1)', opacity: 1, offset: .16 },
    { left: `${liftX}px`, top: `${liftY}px`, transform: 'translate(-50%, -50%) scale(1.08) rotate(-12deg)', opacity: 1, offset: .58 },
    { left: `${end.x}px`, top: `${end.y}px`, transform: 'translate(-50%, -50%) scale(.62) rotate(8deg)', opacity: 0 }
  ], 700, 'cubic-bezier(.2,.78,.2,1)').then(() => safeRemove(fx));
  showFloatingTextAt(unit.row, unit.col, String(info.label || marker.weaponType || 'ARMA').toUpperCase(), 'floating-combat buff weapon-recovery-label');
  return true;
}

function tryRecoverDroppedWeaponForUnit(unit) {
  if (!unit || unit.status === 'restoring') return false;
  const ownerPlayerId = getUnitOwnerPlayerId(unit);
  const marker = getDroppedWeaponMarkerAtForUnit(unit);
  if (!marker) return false;
  const weaponInfo = getWeaponInfoProfile(marker.weaponType || unit.disarmedWeaponType || 'golpe');
  const weaponLabel = weaponInfo?.label || 'arma';
  cancelKaguyaChargedShotState(unit, 'recoger el arma');
  restoreUnitBaseWeaponAvailability(unit);
  clearDroppedWeaponMarkersForUnit(ownerPlayerId, unit.id, marker.weaponType || null);
  renderDroppedWeaponsLayer();
  refreshUnitAttackPresentation(ownerPlayerId, unit);
  void animateDroppedWeaponRecovery(ownerPlayerId, unit, marker, weaponInfo)
    .catch(error => reportDebugError('animateDroppedWeaponRecovery', error));
  log(`${CARD_LIBRARY[unit.cardId]?.name || 'Invocación'} recupera ${weaponLabel} en ${coordLabel(unit.row, unit.col)}.`);
  return true;
}

function refreshUnitAttackPresentation(playerId, unit) {
  if (!unit) return;
  renderUnits();
  renderKaguyaChargeFxLayer();
  renderSelectedUnitCommandPanel();
  renderCombatHud();
  refreshOpenCardInfoForUnit(playerId, unit.id);
}

function clearDroppedWeaponMarkersForUnit(playerId, unitId, weaponType = null) {
  const normalized = weaponType ? String(weaponType).trim() : '';
  const numericPlayerId = Number(playerId || 0);
  state.droppedWeapons = getUnitDroppedWeapons().filter(entry => {
    const sameUnit = String(entry?.ownerUnitId || '') === String(unitId || '');
    const samePlayer = numericPlayerId > 0 ? Number(entry?.ownerPlayerId) === numericPlayerId : true;
    if (!sameUnit || !samePlayer) return true;
    if (!normalized) return false;
    return String(entry?.weaponType || '').trim() !== normalized;
  });
}

function registerDroppedWeaponMarker(playerId, unit, weaponType, cell) {
  if (!unit || !weaponType || !cell) return null;
  clearDroppedWeaponMarkersForUnit(playerId, unit.id, weaponType);
  const marker = {
    id: `drop_${Date.now()}_${Math.random().toString(16).slice(2)}`,
    ownerPlayerId: Number(playerId),
    ownerUnitId: String(unit.id),
    cardId: String(unit.cardId || ''),
    weaponType: String(weaponType),
    row: Number(cell.row),
    col: Number(cell.col),
    createdAt: Date.now(),
  };
  state.droppedWeapons = [...getUnitDroppedWeapons(), marker];
  return marker;
}

function getDisarmDropCandidates(unit) {
  if (!unit) return [];
  const candidates = [];
  for (let dr = -1; dr <= 1; dr += 1) {
    for (let dc = -1; dc <= 1; dc += 1) {
      if (dr === 0 && dc === 0) continue;
      const row = Number(unit.row) + dr;
      const col = Number(unit.col) + dc;
      if (row < 0 || row >= 18 || col < 0 || col >= 9) continue;
      candidates.push({ row, col });
    }
  }
  return candidates;
}

function chooseRandomDisarmDropCell(unit) {
  const candidates = getDisarmDropCandidates(unit);
  if (!candidates.length) return { row: Number(unit?.row || 0), col: Number(unit?.col || 0) };
  const open = candidates.filter(cell => !isOccupied(cell.row, cell.col)
    && !hasSpawnMarkerAtForPlayer(cell.row, cell.col)
    && !getUnitDroppedWeapons().some(entry => Number(entry?.row) === Number(cell.row) && Number(entry?.col) === Number(cell.col)));
  const pool = open.length ? open : candidates;
  return pool[Math.floor(Math.random() * pool.length)] || pool[0];
}

function chooseRandomDisarmDropCellWithReserved(unit, reservedKeys = new Set()) {
  const candidates = getDisarmDropCandidates(unit);
  if (!candidates.length) return { row: Number(unit?.row || 0), col: Number(unit?.col || 0) };
  const isReserved = cell => reservedKeys.has(`${cell.row}:${cell.col}`);
  const open = candidates.filter(cell => !isReserved(cell)
    && !isOccupied(cell.row, cell.col)
    && !hasSpawnMarkerAtForPlayer(cell.row, cell.col)
    && !getUnitDroppedWeapons().some(entry => Number(entry?.row) === Number(cell.row) && Number(entry?.col) === Number(cell.col)));
  const unreserved = candidates.filter(cell => !isReserved(cell));
  const pool = open.length ? open : (unreserved.length ? unreserved : candidates);
  const selected = pool[Math.floor(Math.random() * pool.length)] || pool[0];
  if (selected) reservedKeys.add(`${selected.row}:${selected.col}`);
  return selected || { row: Number(unit?.row || 0), col: Number(unit?.col || 0) };
}

async function animateDisarmWeaponDrop(playerId, unit, weaponType, dropCell, options = {}) {
  if (!els.boardContent || !unit || !weaponType || !dropCell) return false;
  const weaponInfo = getWeaponInfoProfile(weaponType);
  const startLocal = getBoardLocalPointForCell(unit.row, unit.col);
  const endLocal = getBoardLocalPointForCell(dropCell.row, dropCell.col);
  const start = viewportPointFromBoardLocal(startLocal);
  const end = viewportPointFromBoardLocal(endLocal);
  const boardRect = els.boardContent.getBoundingClientRect();
  // v280 · La caída y el marcador conservan la misma escala, reducida 25%
  // respecto de v279 para que el icono siga legible sin dominar la casilla.
  const markerSize = Math.max(27, Math.min(84, boardRect.width * 0.039));

  const burst = document.createElement('div');
  burst.className = 'disarm-chain-burst-fx';
  burst.style.left = `${start.x}px`;
  burst.style.top = `${start.y}px`;
  burst.innerHTML = '<i class="disarm-chain-ring"></i><i class="disarm-chain-ring second"></i><i class="disarm-chain-link link-a"></i><i class="disarm-chain-link link-b"></i><i class="disarm-chain-link link-c"></i>';
  getGlobalFxLayer().appendChild(burst);

  await animateCss(burst, [
    { transform: 'translate(-50%, -50%) scale(.28)', opacity: 0 },
    { transform: 'translate(-50%, -50%) scale(.82)', opacity: .96, offset: .28 },
    { transform: 'translate(-50%, -50%) scale(1.04)', opacity: .82, offset: .64 },
    { transform: 'translate(-50%, -50%) scale(1.18)', opacity: 0 }
  ], 760, 'cubic-bezier(.18,.72,.2,1)').then(() => safeRemove(burst));

  const token = document.createElement('div');
  token.className = 'disarm-weapon-drop-fx';
  token.style.left = `${start.x}px`;
  token.style.top = `${start.y}px`;
  token.style.setProperty('--disarm-weapon-size', `${markerSize}px`);
  token.innerHTML = `<span class="disarm-weapon-drop-inner"><img src="${weaponInfo.icon}" alt="${weaponInfo.label || weaponType}"></span>`;
  getGlobalFxLayer().appendChild(token);

  const midpointX = (start.x + end.x) / 2;
  const midpointY = Math.min(start.y, end.y) - Math.max(26, Math.min(54, Math.abs(end.x - start.x) * 0.18 + 28));
  await animateCss(token, [
    { transform: 'translate(-50%, -50%) scale(.92) rotate(0deg)', opacity: 0, left: `${start.x}px`, top: `${start.y}px` },
    { transform: 'translate(-50%, -50%) scale(1) rotate(-10deg)', opacity: 1, left: `${start.x + ((end.x - start.x) * 0.10)}px`, top: `${start.y - 16}px`, offset: .18 },
    { transform: 'translate(-50%, -50%) scale(1.02) rotate(18deg)', opacity: 1, left: `${midpointX}px`, top: `${midpointY}px`, offset: .52 },
    { transform: 'translate(-50%, -50%) scale(1) rotate(34deg)', opacity: 1, left: `${end.x}px`, top: `${end.y}px` }
  ], 720, 'cubic-bezier(.22,.72,.22,1)').then(() => safeRemove(token));
  options.onLand?.();

  const land = document.createElement('div');
  land.className = 'disarm-weapon-land-fx';
  land.style.left = `${end.x}px`;
  land.style.top = `${end.y}px`;
  land.style.setProperty('--disarm-weapon-size', `${markerSize}px`);
  land.innerHTML = '<i></i><i></i><i></i>';
  getGlobalFxLayer().appendChild(land);
  await animateCss(land, [
    { transform: 'translate(-50%, -50%) scale(.4)', opacity: 0 },
    { transform: 'translate(-50%, -50%) scale(1)', opacity: .95, offset: .38 },
    { transform: 'translate(-50%, -50%) scale(1.2)', opacity: 0 }
  ], 340, 'ease-out').then(() => safeRemove(land));
  return true;
}

function ensureDroppedWeaponsLayer() {
  if (els.droppedWeaponsLayer) return els.droppedWeaponsLayer;
  if (!els.boardContent) return null;
  els.droppedWeaponsLayer = document.createElement('div');
  els.droppedWeaponsLayer.id = 'droppedWeaponsLayer';
  els.droppedWeaponsLayer.className = 'dropped-weapons-layer';
  els.boardContent.insertBefore(els.droppedWeaponsLayer, els.unitsLayer || null);
  return els.droppedWeaponsLayer;
}

function renderDroppedWeaponsLayer() {
  const layer = ensureDroppedWeaponsLayer();
  if (!layer) return;
  const fragment = document.createDocumentFragment();
  const pickupPending = state.pendingPowerAction?.kind === 'kurokagiBukiPickup'
    ? state.pendingPowerAction
    : null;
  layer.classList.toggle('kurokagi-pickup-active', Boolean(pickupPending && Number(pickupPending.playerId) === Number(LOCAL_PLAYER_ID)));
  getUnitDroppedWeapons().forEach(entry => {
    if (!entry) return;
    const weapon = getWeaponInfoProfile(entry.weaponType || 'golpe');
    const node = document.createElement('div');
    node.className = 'dropped-weapon-marker';
    node.dataset.dropId = String(entry.id || '');
    const pos = cellCenter(entry.row, entry.col);
    node.style.left = `${pos.x}%`;
    node.style.top = `${pos.y}%`;
    node.style.zIndex = String(120 + Number(entry.row || 0));
    node.title = `${weapon.label || entry.weaponType} caída en ${coordLabel(entry.row, entry.col)}`;
    node.innerHTML = `<span class="dropped-weapon-ring"></span><span class="dropped-weapon-inner"><img src="${weapon.icon}" alt="${weapon.label || entry.weaponType}"></span>`;

    const pickupCandidate = pickupPending?.candidates?.find(candidate => String(candidate.dropId || '') === String(entry.id || '')) || null;
    if (pickupCandidate && Number(pickupPending.playerId) === Number(LOCAL_PLAYER_ID)) {
      node.classList.add('dropped-weapon-marker-selectable');
      node.title = `${weapon.label || entry.weaponType} · Daño ${pickupCandidate.capturedProfile?.damage ?? 0} · Toca para revisar`;
      node.setAttribute('role', 'button');
      node.setAttribute('tabindex', '0');
      const openChoice = event => {
        stopTargetMenuEvent(event);
        openKurokagiDroppedWeaponChoiceModal(pickupCandidate);
      };
      node.addEventListener('click', openChoice);
      node.addEventListener('keydown', event => {
        if (event.key === 'Enter' || event.key === ' ') openChoice(event);
      });
    }
    fragment.appendChild(node);
  });
  layer.replaceChildren(fragment);
}


function clearDroppedWeaponMarkerById(dropId) {
  const safeId = String(dropId || '');
  if (!safeId) return false;
  const before = getUnitDroppedWeapons().length;
  state.droppedWeapons = getUnitDroppedWeapons().filter(entry => String(entry?.id || '') !== safeId);
  return state.droppedWeapons.length !== before;
}

function closeKurokagiDroppedWeaponChoiceModal() {
  document.querySelectorAll('#kurokagiDropChoiceModal, .kurokagi-drop-choice-overlay').forEach(node => node.remove());
}

function getPendingKurokagiPickupCandidate(dropId) {
  const pending = state.pendingPowerAction;
  if (pending?.kind !== 'kurokagiBukiPickup') return null;
  return pending.candidates?.find(candidate => String(candidate.dropId || '') === String(dropId || '')) || null;
}

function getKurokagiBukiPickupCandidates(unit) {
  if (!isKurokagiButai3Unit(unit)) return [];
  const stored = Array.isArray(unit.kurokagiBukiPickupCandidates) ? unit.kurokagiBukiPickupCandidates : [];
  return stored.filter(candidate => candidate?.dropId
    && getUnitDroppedWeapons().some(entry => String(entry?.id || '') === String(candidate.dropId || '')));
}

function unitHasKurokagiBukiPickupReady(unit) {
  return getKurokagiBukiPickupCandidates(unit).length > 0;
}

function getKurokagiBukiStageBlocker(playerId = state.activePlayer) {
  const units = state.players?.[playerId]?.units || [];
  return units.find(unit => unit && unit.status !== 'restoring' && unitHasKurokagiBukiPickupReady(unit)) || null;
}

function beginKurokagiBukiPickup(playerId, unitId) {
  const unit = getUnitById(playerId, unitId);
  const candidates = getKurokagiBukiPickupCandidates(unit);
  if (!unit || unit.status === 'restoring' || !candidates.length) {
    log('Buki Utsushi no tiene armas desarmadas disponibles para recoger.');
    return false;
  }
  closeKurokagiWeaponModal({ preserveQuickReaction: true });
  closeKurokagiDroppedWeaponChoiceModal();
  clearCombatMenus();
  state.selectedTarget = null;
  state.pendingPowerAction = {
    kind: 'kurokagiBukiPickup',
    playerId: Number(playerId),
    unitId: unit.id,
    candidates,
  };
  showFloatingTextAt(unit.row, unit.col, 'BUKI UTSUSHI', 'floating-combat buff kurokagi-power-name');
  renderDroppedWeaponsLayer();
  log(`Buki Utsushi: toca una de las ${candidates.length} armas resaltadas, revisa su daño y confirma cuál recoger.`);
  return true;
}

async function resolveKurokagiDroppedWeaponChoice(dropId) {
  const pending = state.pendingPowerAction;
  if (pending?.kind !== 'kurokagiBukiPickup') return false;
  const candidate = getPendingKurokagiPickupCandidate(dropId);
  if (!candidate) return false;
  const playerId = Number(pending.playerId);
  const unitId = pending.unitId;
  const sourceUnit = getUnitById(playerId, unitId);
  if (!sourceUnit || sourceUnit.status === 'restoring') {
    resolveQuickReactionDeferredInvocationAction('cancelled', { actionId: 'kurokagiWeaponShift', unitId, playerId });
    return false;
  }

  state.pendingPowerAction = null;
  closeKurokagiDroppedWeaponChoiceModal();
  clearCombatMenus();
  renderDroppedWeaponsLayer();
  setActionExecutionLock(true, 'kurokagi-buki-pickup');

  try {
    showFloatingTextAt(sourceUnit.row, sourceUnit.col, 'BUKI UTSUSHI', 'floating-combat buff kurokagi-power-name');
    await sleep(180);
    const captured = await captureKurokagiDroppedWeapon({
      playerId,
      unit: sourceUnit,
      card: CARD_LIBRARY[sourceUnit.cardId],
    }, candidate);
    const liveSource = getUnitById(playerId, unitId);
    if (liveSource) {
      liveSource.kurokagiBukiPickupCandidates = [];
      liveSource.kurokagiBukiPickupReady = false;
      liveSource.kurokagiBukiResolutionPending = false;
      liveSource.movesLeft = 0;
      if (liveSource.status !== 'restoring') {
        await sleep(180);
        restoreInvocation(playerId, liveSource, captured ? 'Buki Utsushi' : 'Buki Utsushi sin captura');
      }
    }
    resolveQuickReactionDeferredInvocationAction(captured ? 'activated' : 'cancelled', { actionId: 'kurokagiWeaponShift', unitId, playerId });
    return captured;
  } finally {
    setActionExecutionLock(false, 'kurokagi-buki-pickup');
    renderDroppedWeaponsLayer();
    renderAll();
  }
}

function openKurokagiDroppedWeaponChoiceModal(candidate) {
  const pending = state.pendingPowerAction;
  if (pending?.kind !== 'kurokagiBukiPickup' || !candidate) return false;
  closeKurokagiDroppedWeaponChoiceModal();
  const weaponType = candidate.capturedProfile?.weaponType || 'golpe';
  const weapon = getWeaponInfoProfile(weaponType) || getWeaponInfoProfile('golpe');
  const damage = Math.max(0, Number(candidate.capturedProfile?.damage || 0));
  const overlay = document.createElement('div');
  overlay.id = 'kurokagiDropChoiceModal';
  overlay.className = 'kurokagi-drop-choice-overlay';
  overlay.innerHTML = `
    <section class="kurokagi-drop-choice-card">
      <button type="button" class="kurokagi-drop-choice-close" data-action="back" aria-label="Volver">×</button>
      <span class="kurokagi-drop-choice-kicker">BUKI UTSUSHI</span>
      <img class="kurokagi-drop-choice-icon" src="${weapon.icon}" alt="${candidate.capturedProfile?.label || weapon.label}">
      <h3>${candidate.capturedProfile?.label || weapon.label || 'Arma caída'}</h3>
      <p class="kurokagi-drop-choice-coordinate">Caída en ${coordLabel(candidate.dropCell.row, candidate.dropCell.col)}</p>
      <div class="kurokagi-drop-choice-damage"><span>DAÑO</span><strong>${damage}</strong></div>
      <p>Al recogerla, Kurokage copiará su tipo de ataque, alcance, precisión, daño y naturaleza. No copiará factores, aplicaciones especiales, habilidades ni poderes.</p>
      <button type="button" class="kurokagi-drop-choice-confirm" data-action="pick">RECOGER ESTA ARMA</button>
    </section>`;
  overlay.addEventListener('pointerdown', event => event.stopPropagation());
  overlay.addEventListener('click', event => {
    if (event.target === overlay) {
      event.stopPropagation();
      closeKurokagiDroppedWeaponChoiceModal();
    }
  });
  overlay.querySelector('[data-action="back"]')?.addEventListener('click', event => {
    stopTargetMenuEvent(event);
    closeKurokagiDroppedWeaponChoiceModal();
  });
  overlay.querySelector('[data-action="pick"]')?.addEventListener('click', event => {
    stopTargetMenuEvent(event);
    void resolveKurokagiDroppedWeaponChoice(candidate.dropId);
  });
  appendRokUiNode(overlay);
  return true;
}

function getMetaSourceProfile(sourceId) {
  if (!sourceId) return null;
  const domain = DOMAIN_ART_DB?.[sourceId] || null;
  if (domain) return { id: sourceId, label: `Dominio ${domain.elementLabel}`, icon: domain.elementArt, kind: 'domain', title: 'Dominio' };
  const quality = getQualityProfile(sourceId);
  if (quality) return { ...quality, kind: 'quality', title: 'Cualidad' };
  const race = getRaceProfile(sourceId);
  if (race) return { ...race, kind: 'race', title: 'Raza' };
  return null;
}

function getFactorEntrySourceId(factorEntry = {}) {
  return factorEntry?.source || factorEntry?.sourceId || factorEntry?.powerId || factorEntry?.sourceQuality || factorEntry?.sourceRace || factorEntry?.sourceType || '';
}

const POWER_SOURCE_OWNER_BY_ID = {
  sombraClanOda: { cardId: 'ninjaOdaNoKage', label: 'Oda no Kage' },
  confianzaTransmitida: { cardId: 'samuraiNobunagaOda', label: 'Oda Nobunaga' },
  integracionRapida: { cardId: 'miyamotoMusashi', label: 'Miyamoto Musashi' },
  legadoDelImbatible: { cardId: 'miyamotoMusashi', label: 'Miyamoto Musashi' },
  colegasDeGuerra: { cardId: 'samuraiToyotomiHideyoshi', label: 'Toyotomi Hideyoshi' },
  senjinNoKosei: { cardId: 'samuraiKarunobuTaicho', label: 'Karunobu Taichō' },
  elViejoAmigo: { cardId: 'samuraiTakedaShingen', label: 'Takeda Shingen' },
  mercanciaDeGuerra: { cardId: 'gioshoninMercaderErrante', label: 'Gioshonin' },
  genyutsuShinigamiKarasu: { cardId: 'ninjaYasuganaHattori', label: 'Yasugana Hattori' },
  sabotajeApresurado: { cardId: 'ninjaSaqueadorNovato', label: 'Saqueador novato' },
  bukiUtsushi: { cardId: 'ninjaKurokagiButai3', label: 'Kurokage' },
};

function getPowerGrantedSourceProfile(powerId = '') {
  const power = getPowerProfile(powerId);
  if (!power) return null;
  const owner = POWER_SOURCE_OWNER_BY_ID[powerId] || null;
  const ownerCard = owner?.cardId ? CARD_LIBRARY[owner.cardId] : null;
  const ownerLabel = owner?.label || ownerCard?.name || '';
  const label = ownerLabel ? `${power.label || power.name || powerId} - ${ownerLabel}` : (power.label || power.name || powerId);
  return {
    id: powerId,
    label,
    icon: ownerCard?.tokenImage || ownerCard?.artImage || power.icon || 'assets/card-types/card-type-ability.svg',
    kind: 'power',
    title: 'Poder',
  };
}

function getFactorSourceProfile(sourceId, factorEntry = {}, card = null) {
  const source = sourceId || getFactorEntrySourceId(factorEntry);
  const powerSource = getPowerGrantedSourceProfile(factorEntry?.powerId || (POWER_DB[source] ? source : ''));
  if (powerSource) return powerSource;
  if (source === 'domain' || source === 'element' || factorEntry?.sourceType === 'domain' || factorEntry?.source === 'domain') {
    const elementId = factorEntry?.elementId || getCardElementId(card);
    const domain = DOMAIN_ART_DB?.[elementId] || null;
    if (domain) return { id: elementId, label: `Dominio ${domain.elementLabel}`, icon: domain.elementArt, kind: 'domain', title: 'Dominio' };
  }
  return getMetaSourceProfile(source);
}

function getCardDomainGrantedFactors(card, elementId = null) {
  const domainId = elementId || getCardElementId(card);
  const direct = Array.isArray(card?.domainGrantedFactors) ? card.domainGrantedFactors : [];
  const attack = getCardAttackFactors(card).filter(factor => factor?.source === 'domain' || factor?.sourceType === 'domain');
  return [...direct, ...attack].filter((factor, index, list) => {
    if (factor?.elementId && factor.elementId !== domainId) return false;
    return list.findIndex(item => item?.id === factor?.id && Number(item?.level || 1) === Number(factor?.level || 1)) === index;
  });
}

function buildDomainGrantedFactorsHtml(card, elementId = null) {
  const granted = getCardDomainGrantedFactors(card, elementId);
  if (!granted.length) return '';
  const domain = DOMAIN_ART_DB?.[elementId || getCardElementId(card)] || null;
  return `<p><strong>Este dominio habilita en esta carta:</strong></p><div class="meta-source-factor-list">${granted.map(factorEntry => {
    const factor = getFactorProfile(factorEntry.id);
    const level = getFactorDisplayLevel(factorEntry);
    if (!factor) return '';
    return `<button type="button" class="card-info-inline-chip" data-info-kind="factor" data-info-id="${factor.id}" data-factor-level="${level}" data-factor-source="domain"><img src="${factor.icon}" alt="${factor.label}"><span>${factor.label} ${level}</span></button>`;
  }).join('')}</div>${domain ? `<p><strong>Origen:</strong> ${domain.elementLabel} es el dominio que habilita estos factores en esta carta.</p>` : ''}`;
}

function getExtraWeaponSourceId(extraWeapon = {}) {
  return extraWeapon.sourceRace || extraWeapon.sourceQuality || extraWeapon.source || 'human';
}

function buildExtraWeaponCard(card, id = '') {
  const extraWeapon = getExtraWeaponProfile(card, id);
  if (!card || !extraWeapon) return null;
  const combatMode = extraWeapon.combatMode || extraWeapon.type || 'melee';
  const combatModeLabel = COMBAT_MODE_DB[combatMode]?.label || (combatMode === 'distance' ? 'Distancia' : combatMode === 'range' ? 'Rango' : 'Cuerpo a cuerpo');
  return {
    ...card,
    weaponType: extraWeapon.weaponType || 'espada',
    weaponConditions: card.weaponConditions || {},
    attackProfile: {
      type: combatMode,
      combatMode,
      label: extraWeapon.label || combatModeLabel,
      range: Number(extraWeapon.range ?? 1),
      precision: Number(extraWeapon.precision ?? 6),
      damage: Number(extraWeapon.damage ?? 1),
      damageNature: extraWeapon.damageNature || 'physical',
      applicationId: Object.prototype.hasOwnProperty.call(extraWeapon, 'applicationId') ? extraWeapon.applicationId : null,
      modifiers: Array.isArray(extraWeapon.modifiers) ? extraWeapon.modifiers : [],
      factors: [],
    },
  };
}

function buildAttackPreviewHtml(cardLike) {
  if (!cardLike) return '';
  return `
    <div class="meta-info-attack-preview">
      <div class="card-info-stats card-info-stats-grouped card-info-stats-compact">
        <div class="stat-row stat-row-damage meta-info-stat-row-damage">
          <strong>DAÑO</strong>
          <span id="metaInfoBaseDamage">${renderWeaponDamageChip(cardLike)}</span>
          <span id="metaInfoBaseAttackType"><span class="card-info-chip-stack">${renderCombatModeChip(cardLike)}${renderDamageApplicationChip(cardLike)}</span></span>
          <span id="metaInfoBaseRange"><span class="card-info-chip-stack">${renderAttackRangeChip(cardLike)}${renderAttackPrecisionChip(cardLike)}</span></span>
        </div>
      </div>
    </div>`;
}


