function normalizeSpellbookTraitId(value) {
  return String(value || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '');
}

function getSpellbookCardTraits(cardOrId) {
  const card = typeof cardOrId === 'string' ? CARD_LIBRARY[cardOrId] : cardOrId;
  if (!card) return [];
  const rawTraits = [
    ...(Array.isArray(card.traits) ? card.traits : []),
    ...(Array.isArray(card.cardTraits) ? card.cardTraits : []),
    ...(Array.isArray(card.copyTraits) ? card.copyTraits : []),
    ...(Array.isArray(card.rasgos) ? card.rasgos : []),
  ];
  if (card.trait) rawTraits.push(card.trait);
  if (card.copyTrait) rawTraits.push(card.copyTrait);
  if (card.forcedLimits === true || card.limitesForzados === true) rawTraits.push(SPELLBOOK_FORCED_LIMITS_TRAIT_ID);
  if (card.adaptation === true || card.adaptacion === true) rawTraits.push(SPELLBOOK_LEGACY_ADAPTATION_TRAIT_ID);
  return [...new Set(rawTraits.map(normalizeSpellbookTraitId).filter(Boolean))];
}

function getCardTraitProfile(traitId) {
  const normalizedId = normalizeSpellbookTraitId(traitId);
  if (normalizedId === normalizeSpellbookTraitId(SPELLBOOK_LEGACY_ADAPTATION_TRAIT_ID)) {
    return CARD_TRAIT_DB.limitesforzados;
  }
  return CARD_TRAIT_DB[normalizedId] || null;
}

function getCardTraitProfiles(cardOrId) {
  const profiles = [];
  const seen = new Set();
  getSpellbookCardTraits(cardOrId).forEach(traitId => {
    const profile = getCardTraitProfile(traitId);
    if (!profile || seen.has(profile.id)) return;
    seen.add(profile.id);
    profiles.push(profile);
  });
  return profiles;
}

function cardHasForcedLimits(cardOrId) {
  return getCardTraitProfiles(cardOrId).some(profile => profile.id === SPELLBOOK_FORCED_LIMITS_TRAIT_ID);
}

function getSpellbookCardCopyLimit(cardOrId) {
  return cardHasForcedLimits(cardOrId)
    ? SPELLBOOK_FORCED_LIMITS_COPY_LIMIT
    : SPELLBOOK_BASE_COPY_LIMIT;
}

function getSpellbookCardCopyCount(cardOrId, cards = libraryBuilderState.spellbookCards) {
  const cardId = typeof cardOrId === 'string' ? cardOrId : cardOrId?.id;
  if (!cardId || !Array.isArray(cards)) return 0;
  return cards.reduce((total, value) => total + (value === cardId ? 1 : 0), 0);
}

function getSpellbookCardCopyStatusFor(cardOrId, cards = libraryBuilderState.spellbookCards) {
  const card = typeof cardOrId === 'string' ? CARD_LIBRARY[cardOrId] : cardOrId;
  const cardId = card?.id || (typeof cardOrId === 'string' ? cardOrId : null);
  const count = getSpellbookCardCopyCount(cardId, Array.isArray(cards) ? cards : []);
  const limit = getSpellbookCardCopyLimit(card);
  const hasForcedLimits = cardHasForcedLimits(card);
  const collectionLimited = Boolean(isRokUserModeActive() && card && getCardTypeId(card) !== 'kaster');
  const ownedCopies = collectionLimited ? getRokUserOwnedCopies(card) : Number.POSITIVE_INFINITY;
  const collectionRemaining = collectionLimited ? Math.max(0, ownedCopies - count) : Number.POSITIVE_INFINITY;
  const ruleRemaining = Math.max(0, limit - count);
  const remaining = Math.max(0, Math.min(ruleRemaining, collectionRemaining));
  const collectionBlocked = collectionLimited && collectionRemaining <= 0;
  return {
    cardId,
    count,
    limit,
    remaining,
    ruleRemaining,
    ownedCopies,
    collectionRemaining,
    collectionLimited,
    collectionBlocked,
    hasForcedLimits,
    canAdd: Boolean(cardId) && remaining > 0,
    reason: collectionBlocked
      ? (ownedCopies <= 0
        ? `No posees ninguna copia de ${card?.name || cardId} en tu colección.`
        : `Ya usaste las ${ownedCopies} copia${ownedCopies === 1 ? '' : 's'} que posees de ${card?.name || cardId}.`)
      : (hasForcedLimits
        ? `Límite de Límites forzados alcanzado: ${count}/${limit} copias.`
        : `Límite de copias alcanzado: ${count}/${limit}.`),
  };
}

function getBuilderCardCopyStatus(cardOrId) {
  return getSpellbookCardCopyStatusFor(cardOrId, libraryBuilderState.spellbookCards);
}


function getSpellbookCountedDomainId(cardOrId) {
  const card = typeof cardOrId === 'string' ? CARD_LIBRARY[cardOrId] : cardOrId;
  if (!card || card?.domain?.universal === true || isCatalystCard(card)) return null;
  const elementId = getCardElementId(card);
  return elementId && elementId !== CATALYST_DOMAIN_ID ? elementId : null;
}

function getSpellbookDomainEntries(casterCardId, cards = []) {
  const caster = CARD_LIBRARY[casterCardId];
  const baseDomainId = getSpellbookCountedDomainId(caster);
  const counts = new Map();
  if (baseDomainId) counts.set(baseDomainId, 0);
  (Array.isArray(cards) ? cards : []).filter(Boolean).forEach(cardId => {
    const domainId = getSpellbookCountedDomainId(cardId);
    if (!domainId) return;
    counts.set(domainId, (counts.get(domainId) || 0) + 1);
  });
  return [...counts.entries()]
    .map(([id, count]) => ({
      id,
      count,
      isBase: id === baseDomainId,
      profile: DOMAIN_ART_DB[id] || DOMAIN_ART_DB.oscuridad,
    }))
    .sort((a, b) => {
      if (a.isBase !== b.isBase) return a.isBase ? -1 : 1;
      if (a.count !== b.count) return b.count - a.count;
      return String(a.profile?.elementLabel || a.id).localeCompare(String(b.profile?.elementLabel || b.id), 'es');
    });
}

function getBuilderCardDomainStatus(cardOrId, casterCardId = libraryBuilderState.casterCardId, spellbookCards = libraryBuilderState.spellbookCards) {
  const card = typeof cardOrId === 'string' ? CARD_LIBRARY[cardOrId] : cardOrId;
  if (!card || getCardTypeId(card) === 'kaster') return { canAdd: true, domainId: null, domains: [] };
  const domainId = getSpellbookCountedDomainId(card);
  const domains = getSpellbookDomainEntries(casterCardId, spellbookCards);
  if (!domainId || domains.some(entry => entry.id === domainId) || domains.length < SPELLBOOK_MAX_DOMAINS) {
    return { canAdd: true, domainId, domains };
  }
  const profile = DOMAIN_ART_DB[domainId] || DOMAIN_ART_DB.oscuridad;
  const activeNames = domains.map(entry => entry.profile?.elementLabel || entry.id).join(', ');
  return {
    canAdd: false,
    domainId,
    domains,
    reason: `Este Spellbook ya utiliza el máximo de ${SPELLBOOK_MAX_DOMAINS} dominios (${activeNames}). No puedes agregar una carta de ${profile.elementLabel}.`,
  };
}

function normalizeSpellbookElementDistribution(raw, allowedElementIds = null) {
  const validIds = new Set(Object.keys(ELEMENT_EXTRACTION_ASSETS || {}));
  const allowedIds = Array.isArray(allowedElementIds) && allowedElementIds.length
    ? [...new Set(allowedElementIds.filter(id => validIds.has(id)))]
    : [...validIds];
  const source = raw && typeof raw === 'object' ? raw : {};
  const result = {};
  let remaining = SPELLBOOK_ELEMENT_MAX_TOTAL;
  allowedIds.forEach(elementId => {
    const amount = Math.max(0, Math.floor(Number(source[elementId]) || 0));
    const accepted = Math.min(amount, remaining);
    result[elementId] = accepted;
    remaining -= accepted;
  });
  return result;
}

function getSpellbookElementTotal(distribution) {
  return Object.values(distribution || {}).reduce((total, amount) => total + Math.max(0, Math.floor(Number(amount) || 0)), 0);
}

function getSpellbookElementOptionIds(casterCardId, cards = []) {
  const ids = [];
  const add = elementId => {
    if (!elementId || elementId === 'random' || elementId === CATALYST_DOMAIN_ID) return;
    if (!ELEMENT_EXTRACTION_ASSETS[elementId] || ids.includes(elementId)) return;
    ids.push(elementId);
  };
  add(getSpellbookCountedDomainId(casterCardId));
  getSpellbookDomainEntries(casterCardId, cards).forEach(entry => add(entry.id));
  (Array.isArray(cards) ? cards : []).filter(Boolean).forEach(cardId => {
    const card = CARD_LIBRARY[cardId];
    if (!card) return;
    Object.entries(getNormalizedCardCost(card)).forEach(([elementId, amount]) => {
      if (elementId !== 'random' && Number(amount) > 0) add(elementId);
    });
  });
  return ids.slice(0, SPELLBOOK_MAX_DOMAINS);
}

function getSpellbookMissingElementWarnings(cards, distribution) {
  const normalizedDistribution = normalizeSpellbookElementDistribution(distribution);
  return (Array.isArray(cards) ? cards : []).filter(Boolean).reduce((warnings, cardId, index) => {
    const card = CARD_LIBRARY[cardId];
    if (!card) return warnings;
    const missingElementIds = Object.entries(getNormalizedCardCost(card))
      .filter(([elementId, amount]) => elementId !== 'random' && Number(amount) > 0 && !(Number(normalizedDistribution[elementId]) > 0))
      .map(([elementId]) => elementId);
    if (!missingElementIds.length) return warnings;
    warnings.push({ cardId, index, name: card.name || cardId, missingElementIds });
    return warnings;
  }, []);
}

function getSpellbookElementWarningForCard(cardOrId, distribution = libraryBuilderState.elementDistribution) {
  const card = typeof cardOrId === 'string' ? CARD_LIBRARY[cardOrId] : cardOrId;
  if (!card || !libraryBuilderState.elementDistributionConfigured) return { incompatible: false, reason: '', missingElementIds: [] };
  const missingElementIds = Object.entries(getNormalizedCardCost(card))
    .filter(([elementId, amount]) => elementId !== 'random' && Number(amount) > 0 && !(Number(distribution?.[elementId]) > 0))
    .map(([elementId]) => elementId);
  if (!missingElementIds.length) return { incompatible: false, reason: '', missingElementIds: [] };
  const names = missingElementIds.map(elementId => getElementById(elementId)?.label || elementId).join(', ');
  return {
    incompatible: true,
    missingElementIds,
    reason: `${card.name || card.id} requiere ${names}, pero la Fuente elemental del Spellbook tiene 0 de ese elemento.`,
  };
}

function getSavedSpellbookElementEntries(spellbook) {
  if (!spellbook?.elementDistributionConfigured) return [];
  const allowedIds = getSpellbookElementOptionIds(spellbook.casterCardId, spellbook.cards);
  const distribution = normalizeSpellbookElementDistribution(spellbook.elementDistribution, allowedIds);
  return allowedIds
    .map(elementId => ({
      id: elementId,
      amount: Number(distribution[elementId]) || 0,
      label: getElementById(elementId)?.label || elementId,
      icon: getElementCostIcon(elementId),
    }))
    .filter(entry => entry.amount > 0);
}

function getSpellbookTypeCounts(spellbook) {
  const counts = { invocation: 0, spell: 0, ability: 0, artifact: 0, structure: 0, casterAbility: 0 };
  (spellbook?.cards || []).filter(Boolean).forEach(cardId => {
    const card = CARD_LIBRARY[cardId];
    if (!card) return;
    if (isCasterAbilityCard(card)) {
      counts.casterAbility += 1;
      return;
    }
    const rawType = getCardTypeId(card);
    const typeId = rawType === 'equipment' || rawType === 'equip' ? 'artifact' : rawType;
    if (Object.prototype.hasOwnProperty.call(counts, typeId)) counts[typeId] += 1;
  });
  return counts;
}

function getSpellbookBattlePointsTotal(spellbook) {
  return (spellbook?.cards || []).filter(Boolean).reduce((total, cardId) => {
    const points = getCardBattlePointsValue(CARD_LIBRARY[cardId]);
    return total + (Number.isFinite(points) ? points : 0);
  }, 0);
}

function getSpellbookFocusSummary(spellbook) {
  const scores = new Map();
  (spellbook?.cards || []).filter(Boolean).forEach(cardId => {
    const tags = getCardFocusTags(CARD_LIBRARY[cardId]);
    tags.forEach((tag, index) => scores.set(tag, (scores.get(tag) || 0) + Math.max(1, 3 - index)));
  });
  const ranked = [...scores.entries()]
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0], 'es'))
    .map(([tag]) => tag)
    .slice(0, 3);
  return ranked.length ? ranked : ['Equilibrio'];
}

