function normalizeRokUserCollection(raw = {}) {
  const normalized = {};
  if (!raw || typeof raw !== 'object') return normalized;
  Object.entries(raw).forEach(([cardId, amount]) => {
    if (!CARD_LIBRARY[cardId] || getCardTypeId(CARD_LIBRARY[cardId]) === 'kaster') return;
    const count = Math.max(0, Math.floor(Number(amount) || 0));
    if (count > 0) normalized[cardId] = count;
  });
  return normalized;
}

function normalizeRokUserBoosters(raw = {}) {
  const normalized = {};
  if (!raw || typeof raw !== 'object') return normalized;
  Object.entries(raw).forEach(([collectionId, amount]) => {
    const count = Math.max(0, Math.floor(Number(amount) || 0));
    if (count > 0) normalized[String(collectionId)] = count;
  });
  return normalized;
}


function normalizeRokUserResourceMap(raw = {}, allowedIds = []) {
  const normalized = {};
  const source = raw && typeof raw === 'object' ? raw : {};
  (allowedIds || []).forEach(id => {
    normalized[id] = Math.max(0, Math.floor(Number(source[id]) || 0));
  });
  return normalized;
}

function createEmptyRokUserElementResources() {
  return normalizeRokUserResourceMap({}, ROK_USER_RESOURCE_ELEMENT_IDS);
}

function createEmptyRokUserRarityResources() {
  return normalizeRokUserResourceMap({}, ROK_USER_RESOURCE_RARITY_IDS);
}

function getCasterXpRequirement(level = 1) {
  const safeLevel = Math.max(1, Math.min(CASTER_MAX_LEVEL, Math.floor(Number(level) || 1)));
  if (safeLevel >= CASTER_MAX_LEVEL) return 0;
  return CASTER_XP_BASE_REQUIREMENT + ((safeLevel - 1) * CASTER_XP_REQUIREMENT_STEP);
}

function normalizeCasterProgressEntry(raw = {}) {
  const level = Math.max(1, Math.min(CASTER_MAX_LEVEL, Math.floor(Number(raw?.level) || 1)));
  const requirement = getCasterXpRequirement(level);
  const xp = level >= CASTER_MAX_LEVEL ? 0 : Math.max(0, Math.min(Math.max(0, requirement - 1), Math.floor(Number(raw?.xp) || 0)));
  const totalXp = Math.max(xp, Math.floor(Number(raw?.totalXp) || 0));
  return { level, xp, totalXp, updatedAt: Number(raw?.updatedAt) || 0 };
}

function normalizeCasterProgressMap(raw = {}) {
  const normalized = {};
  if (!raw || typeof raw !== 'object') return normalized;
  Object.entries(raw).forEach(([cardId, entry]) => {
    if (!CARD_LIBRARY[cardId] || getCardTypeId(CARD_LIBRARY[cardId]) !== 'kaster') return;
    normalized[cardId] = normalizeCasterProgressEntry(entry);
  });
  return normalized;
}

function normalizeClonedCasterAbilityMap(raw = {}) {
  const normalized = {};
  if (!raw || typeof raw !== 'object') return normalized;
  Object.entries(raw).forEach(([abilityId, amount]) => {
    const count = Math.max(0, Math.floor(Number(amount) || 0));
    if (count > 0) normalized[String(abilityId)] = count;
  });
  return normalized;
}

function getCasterProgress(cardOrId) {
  const card = typeof cardOrId === 'string' ? CARD_LIBRARY[cardOrId] : cardOrId;
  if (!card || getCardTypeId(card) !== 'kaster') return normalizeCasterProgressEntry();
  rokUserProfile.casterProgress = normalizeCasterProgressMap(rokUserProfile.casterProgress);
  if (!rokUserProfile.casterProgress[card.id]) rokUserProfile.casterProgress[card.id] = normalizeCasterProgressEntry();
  return { ...rokUserProfile.casterProgress[card.id] };
}

function getCasterLevelBonuses(level = 1) {
  const safeLevel = Math.max(1, Math.min(CASTER_MAX_LEVEL, Math.floor(Number(level) || 1)));
  const bonuses = { life:0, attack:0, range:0, defense:0, precision:0, specialCounters:0, pureGeneration:0, pureMax:0, nativeAbilitySlots:0, addedAbilitySlots:0, pureUnlocked:false };
  for (let current = 2; current <= safeLevel; current += 1) {
    const milestone = CASTER_LEVEL_MILESTONES[current] || {};
    bonuses.life += Number(milestone.life || 0);
    bonuses.attack += Number(milestone.attack || 0);
    bonuses.range += Number(milestone.range || 0);
    bonuses.defense += Number(milestone.defense || 0);
    bonuses.precision += Number(milestone.precision || 0);
    bonuses.specialCounters += Number(milestone.specialCounters || 0);
    bonuses.pureGeneration += Number(milestone.pureGeneration || 0);
    bonuses.pureMax += Number(milestone.pureMax || 0);
    bonuses.nativeAbilitySlots += Number(milestone.nativeAbilitySlots || 0);
    bonuses.addedAbilitySlots += Number(milestone.addedAbilitySlots || 0);
    if (milestone.unlockPureElement) bonuses.pureUnlocked = true;
  }
  return bonuses;
}

function getCasterProgressedStats(cardOrId, progressOverride = null) {
  const card = typeof cardOrId === 'string' ? CARD_LIBRARY[cardOrId] : cardOrId;
  if (!card || getCardTypeId(card) !== 'kaster') return null;
  const progress = progressOverride ? normalizeCasterProgressEntry(progressOverride) : getCasterProgress(card);
  const bonuses = getCasterLevelBonuses(progress.level);
  const stats = card.stats || {};
  const attackProfile = card.attackProfile || {};
  const basePureGeneration = Math.max(0, Number(stats.pureCadence ?? 0));
  const basePureMax = Math.max(0, Number(stats.pureMax ?? 0));
  return {
    level: progress.level, xp: progress.xp, totalXp: progress.totalXp, xpRequired: getCasterXpRequirement(progress.level),
    life: Math.max(1, Number(stats.life ?? stats.maxLife ?? 1) + bonuses.life),
    attack: Math.max(0, Number(stats.atk ?? stats.damage ?? attackProfile.damage ?? 0) + bonuses.attack),
    defense: Math.max(0, Number(stats.def ?? 0) + bonuses.defense),
    range: Math.max(0, Number(attackProfile.range ?? 1) + bonuses.range),
    precision: Math.max(0, Number(attackProfile.precision ?? 0) + bonuses.precision),
    startingSpecialCounters: Math.max(0, Number(stats.startingSpecialCounters ?? stats.specialCounters ?? 0) + bonuses.specialCounters),
    pureUnlocked: bonuses.pureUnlocked,
    pureGenerationBase: basePureGeneration,
    pureGeneration: bonuses.pureUnlocked ? basePureGeneration + bonuses.pureGeneration : 0,
    pureMaxBase: basePureMax,
    pureMax: bonuses.pureUnlocked ? basePureMax + bonuses.pureMax : 0,
    abilitySlotsUnlocked: bonuses.nativeAbilitySlots + bonuses.addedAbilitySlots,
    bonuses,
  };
}

function grantCasterExperience(cardOrId, amount = 0, options = {}) {
  const card = typeof cardOrId === 'string' ? CARD_LIBRARY[cardOrId] : cardOrId;
  if (!card || getCardTypeId(card) !== 'kaster') return null;
  const gain = Math.max(0, Math.floor(Number(amount) || 0));
  const progress = getCasterProgress(card);
  if (!gain) return progress;
  progress.totalXp += gain;
  if (progress.level < CASTER_MAX_LEVEL) progress.xp += gain;
  const levelsGained = [];
  while (progress.level < CASTER_MAX_LEVEL) {
    const required = getCasterXpRequirement(progress.level);
    if (required <= 0 || progress.xp < required) break;
    progress.xp -= required;
    progress.level += 1;
    levelsGained.push(progress.level);
  }
  if (progress.level >= CASTER_MAX_LEVEL) progress.xp = 0;
  progress.updatedAt = Date.now();
  rokUserProfile.casterProgress[card.id] = normalizeCasterProgressEntry(progress);
  if (options.persist !== false) persistRokUserProfile();
  if (options.render !== false && state?.infoCard?.cardId === card.id && els.cardInfoOverlay?.classList.contains('open')) {
    if (levelsGained.length && (state.infoCard?.source === 'libraryBuilder' || state.infoCard?.source === 'cardCreator')) {
      openCardInfo(card.id, state.infoCard?.slotIndex ?? null, state.infoCard?.tab ?? null, { ...state.infoCard });
    } else {
      renderCasterLevelProgress(card);
    }
  }
  return { ...rokUserProfile.casterProgress[card.id], gained: gain, levelsGained };
}

function setCasterLevelForTesting(cardOrId, level = 1) {
  const card = typeof cardOrId === 'string' ? CARD_LIBRARY[cardOrId] : cardOrId;
  if (!card || getCardTypeId(card) !== 'kaster') return null;
  const safeLevel = Math.max(1, Math.min(CASTER_MAX_LEVEL, Math.floor(Number(level) || 1)));
  const previous = getCasterProgress(card);
  rokUserProfile.casterProgress[card.id] = normalizeCasterProgressEntry({ level:safeLevel, xp:0, totalXp:previous.totalXp, updatedAt:Date.now() });
  persistRokUserProfile();
  if (state?.infoCard?.cardId === card.id && els.cardInfoOverlay?.classList.contains('open')) openCardInfo(card.id, null, null, state.infoCard || {});
  return getCasterProgress(card);
}

function loadRokUserProfile() {
  const raw = safeLocalStorageGet(ROK_USER_PROFILE_STORAGE_KEY);
  if (raw) {
    try {
      const parsed = JSON.parse(raw);
      const parsedPureCrystal = Number(parsed?.pureCrystal);
      rokUserProfile = {
        schemaVersion: 4,
        profileId: typeof parsed?.profileId === 'string' && parsed.profileId ? parsed.profileId : 'local_guest',
        collection: normalizeRokUserCollection(parsed?.collection),
        boosters: normalizeRokUserBoosters(parsed?.boosters),
        pureCrystal: Number.isFinite(parsedPureCrystal) && parsedPureCrystal >= 0
          ? Math.floor(parsedPureCrystal)
          : ROK_USER_INITIAL_PURE_CRYSTAL,
        elements: normalizeRokUserResourceMap(parsed?.elements, ROK_USER_RESOURCE_ELEMENT_IDS),
        rarities: normalizeRokUserResourceMap(parsed?.rarities, ROK_USER_RESOURCE_RARITY_IDS),
        casterProgress: normalizeCasterProgressMap(parsed?.casterProgress),
        clonedCasterAbilities: normalizeClonedCasterAbilityMap(parsed?.clonedCasterAbilities),
        updatedAt: Number(parsed?.updatedAt) || 0,
      };
    } catch (_) {
      rokUserProfile = { schemaVersion: 4, profileId: 'local_guest', collection: {}, boosters: {}, pureCrystal: ROK_USER_INITIAL_PURE_CRYSTAL, elements: createEmptyRokUserElementResources(), rarities: createEmptyRokUserRarityResources(), casterProgress: {}, clonedCasterAbilities: {}, updatedAt: 0 };
    }
  } else {
    rokUserProfile = { schemaVersion: 4, profileId: 'local_guest', collection: {}, boosters: {}, pureCrystal: ROK_USER_INITIAL_PURE_CRYSTAL, elements: createEmptyRokUserElementResources(), rarities: createEmptyRokUserRarityResources(), casterProgress: {}, clonedCasterAbilities: {}, updatedAt: 0 };
    safeLocalStorageSet(ROK_USER_PROFILE_STORAGE_KEY, JSON.stringify(rokUserProfile));
  }
  rokUserModeActive = safeLocalStorageGet(ROK_USER_MODE_STORAGE_KEY) === '1';
  document.body?.classList.toggle('rok-user-mode', rokUserModeActive);
  return rokUserProfile;
}

function persistRokUserProfile() {
  rokUserProfile.updatedAt = Date.now();
  return safeLocalStorageSet(ROK_USER_PROFILE_STORAGE_KEY, JSON.stringify(rokUserProfile));
}

function formatRokPureCrystalAmount(value) {
  return Math.max(0, Math.floor(Number(value) || 0)).toLocaleString('en-US');
}

function getRokUserPureCrystal() {
  return Math.max(0, Math.floor(Number(rokUserProfile?.pureCrystal) || 0));
}

function getRokUserElementResource(elementId) {
  return Math.max(0, Math.floor(Number(rokUserProfile?.elements?.[elementId]) || 0));
}

function getRokUserRarityResource(rarityId) {
  return Math.max(0, Math.floor(Number(rokUserProfile?.rarities?.[rarityId]) || 0));
}

function updateRokUserResourceStrip(root) {
  if (!root) return;
  root.querySelectorAll('[data-user-element]').forEach(node => {
    const value = getRokUserElementResource(node.dataset.userElement);
    const target = node.querySelector('strong');
    if (target) target.textContent = formatRokPureCrystalAmount(value);
  });
  root.querySelectorAll('[data-user-rarity]').forEach(node => {
    const value = getRokUserRarityResource(node.dataset.userRarity);
    const target = node.querySelector('strong');
    if (target) target.textContent = formatRokPureCrystalAmount(value);
  });
}

function updateRokPureCrystalUi() {
  const formatted = formatRokPureCrystalAmount(getRokUserPureCrystal());
  [els.mainMenuPureCrystalValue, els.libraryPureCrystalValue, els.boosterStorePureCrystalValue].filter(Boolean).forEach(node => {
    node.textContent = formatted;
  });
  updateRokUserResourceStrip(els.mainMenuResourceStrip);
  updateRokUserResourceStrip(els.cardCreatorStockHud);
}

function grantRokUserElementResource(elementId, amount = 0, options = {}) {
  if (!ROK_USER_RESOURCE_ELEMENT_IDS.includes(elementId)) return 0;
  rokUserProfile.elements = normalizeRokUserResourceMap(rokUserProfile.elements, ROK_USER_RESOURCE_ELEMENT_IDS);
  rokUserProfile.elements[elementId] = Math.max(0, getRokUserElementResource(elementId) + Math.floor(Number(amount) || 0));
  if (options.persist !== false) persistRokUserProfile();
  updateRokPureCrystalUi();
  return rokUserProfile.elements[elementId];
}

function grantRokUserRarityResource(rarityId, amount = 0, options = {}) {
  if (!ROK_USER_RESOURCE_RARITY_IDS.includes(rarityId)) return 0;
  rokUserProfile.rarities = normalizeRokUserResourceMap(rokUserProfile.rarities, ROK_USER_RESOURCE_RARITY_IDS);
  rokUserProfile.rarities[rarityId] = Math.max(0, getRokUserRarityResource(rarityId) + Math.floor(Number(amount) || 0));
  if (options.persist !== false) persistRokUserProfile();
  updateRokPureCrystalUi();
  return rokUserProfile.rarities[rarityId];
}

function spendRokUserElementResource(elementId, amount = 0, options = {}) {
  const cost = Math.max(0, Math.floor(Number(amount) || 0));
  if (!ROK_USER_RESOURCE_ELEMENT_IDS.includes(elementId) || getRokUserElementResource(elementId) < cost) return false;
  rokUserProfile.elements[elementId] = getRokUserElementResource(elementId) - cost;
  if (options.persist !== false) persistRokUserProfile();
  updateRokPureCrystalUi();
  return true;
}

function spendRokUserRarityResource(rarityId, amount = 0, options = {}) {
  const cost = Math.max(0, Math.floor(Number(amount) || 0));
  if (!ROK_USER_RESOURCE_RARITY_IDS.includes(rarityId) || getRokUserRarityResource(rarityId) < cost) return false;
  rokUserProfile.rarities[rarityId] = getRokUserRarityResource(rarityId) - cost;
  if (options.persist !== false) persistRokUserProfile();
  updateRokPureCrystalUi();
  return true;
}

function setRokUserPureCrystal(amount, options = {}) {
  rokUserProfile.pureCrystal = Math.max(0, Math.floor(Number(amount) || 0));
  if (options.persist !== false) persistRokUserProfile();
  updateRokPureCrystalUi();
  return rokUserProfile.pureCrystal;
}

function grantRokUserPureCrystal(amount = 0) {
  const increment = Math.floor(Number(amount) || 0);
  return setRokUserPureCrystal(getRokUserPureCrystal() + increment);
}

function spendRokUserPureCrystal(amount = 0, options = {}) {
  const cost = Math.max(0, Math.floor(Number(amount) || 0));
  if (getRokUserPureCrystal() < cost) return false;
  rokUserProfile.pureCrystal = getRokUserPureCrystal() - cost;
  if (options.persist !== false) persistRokUserProfile();
  updateRokPureCrystalUi();
  return true;
}

function isRokUserModeActive() { return rokUserModeActive === true; }

function getRokCardOriginId(cardOrId) {
  const card = typeof cardOrId === 'string' ? CARD_LIBRARY[cardOrId] : cardOrId;
  const origin = String(card?.origin || '').trim().toLowerCase();
  return origin || 'neutral';
}

function getRokUserOwnedCopies(cardOrId) {
  const card = typeof cardOrId === 'string' ? CARD_LIBRARY[cardOrId] : cardOrId;
  if (!card) return 0;
  if (getCardTypeId(card) === 'kaster') return Number.POSITIVE_INFINITY;
  return Math.max(0, Math.floor(Number(rokUserProfile?.collection?.[card.id]) || 0));
}

function isRokUserCardUnlocked(cardOrId) {
  const card = typeof cardOrId === 'string' ? CARD_LIBRARY[cardOrId] : cardOrId;
  if (!card) return false;
  return getCardTypeId(card) === 'kaster' || getRokUserOwnedCopies(card) > 0;
}

function grantRokUserCollectionCard(cardId, amount = 1, options = {}) {
  const card = CARD_LIBRARY[cardId];
  if (!card || getCardTypeId(card) === 'kaster') return 0;
  const increment = Math.max(0, Math.floor(Number(amount) || 0));
  if (!increment) return getRokUserOwnedCopies(card);
  const current = getRokUserOwnedCopies(card);
  rokUserProfile.collection[cardId] = current + increment;
  if (options.persist !== false) persistRokUserProfile();
  if (document.body.classList.contains('rok-library-mode')) renderLibraryBuilder();
  return rokUserProfile.collection[cardId];
}

function spendRokUserCollectionCard(cardId, amount = 1, options = {}) {
  const card = CARD_LIBRARY[cardId];
  if (!card || getCardTypeId(card) === 'kaster') return false;
  const count = Math.max(0, Math.floor(Number(amount) || 0));
  const current = getRokUserOwnedCopies(card);
  if (current < count) return false;
  const next = current - count;
  if (next > 0) rokUserProfile.collection[cardId] = next;
  else delete rokUserProfile.collection[cardId];
  if (options.persist !== false) persistRokUserProfile();
  if (options.render !== false && document.body.classList.contains('rok-library-mode')) renderLibraryBuilder();
  return true;
}

function grantRokUserCollectionCards(cardIds = []) {
  const ids = Array.isArray(cardIds) ? cardIds : [];
  ids.forEach(cardId => grantRokUserCollectionCard(cardId, 1, { persist: false }));
  persistRokUserProfile();
  if (document.body.classList.contains('rok-library-mode')) renderLibraryBuilder();
  return { ...rokUserProfile.collection };
}

function resetRokUserCollection() {
  rokUserProfile.collection = {};
  persistRokUserProfile();
  if (document.body.classList.contains('rok-library-mode')) renderLibraryBuilder();
}

function setMainMenuUserHudMenuOpen(open) {
  const isOpen = Boolean(open);
  if (els.mainMenuUserHud) {
    els.mainMenuUserHud.classList.toggle('is-open', isOpen);
    els.mainMenuUserHud.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
  }
  if (els.mainMenuUserHudMenu) els.mainMenuUserHudMenu.setAttribute('aria-hidden', isOpen ? 'false' : 'true');
  return isOpen;
}

function toggleMainMenuUserHudMenu() {
  return setMainMenuUserHudMenuOpen(!els.mainMenuUserHud?.classList.contains('is-open'));
}

function resetRokUserProfileForTesting() {
  rokUserProfile = {
    schemaVersion: 4,
    profileId: 'local_guest',
    collection: {},
    boosters: {},
    pureCrystal: ROK_USER_INITIAL_PURE_CRYSTAL,
    elements: createEmptyRokUserElementResources(),
    rarities: createEmptyRokUserRarityResources(),
    casterProgress: {},
    clonedCasterAbilities: {},
    updatedAt: Date.now(),
  };
  if (typeof cardCreatorState !== 'undefined') {
    cardCreatorState.queue = [];
    cardCreatorState.decomposing = false;
    resetCardCreatorPendingCreationCost?.();
    resetCardCreatorModalQuantities?.();
  }
  persistRokUserProfile();
  updateRokPureCrystalUi();
  if (typeof boosterStoreState !== 'undefined') {
    boosterStoreState.step = 'collections';
    boosterStoreState.collectionId = null;
    boosterStoreState.purchaseMode = null;
    boosterStoreState.bundleCount = 1;
    boosterStoreState.lastAcquiredAmount = 0;
    boosterStoreState.openingTotal = 0;
    boosterStoreState.openingRemaining = 0;
    boosterStoreState.currentPackCards = [];
    boosterStoreState.openedCardsSession = [];
    boosterStoreState.openedPacksSession = 0;
    boosterStoreState.animationToken += 1;
  }
  if (document.body.classList.contains('rok-library-mode')) renderLibraryBuilder();
  if (els.mainMenuNotice) els.mainMenuNotice.textContent = 'Usuario reiniciado · colección, recursos y boosters eliminados; 9,000 Cristales Puros restaurados.';
  setMainMenuUserHudMenuOpen(false);
  return true;
}

function updateRokUserModeUi() {
  document.body?.classList.toggle('rok-user-mode', rokUserModeActive);
  updateRokPureCrystalUi();
  if (els.mainMenuUserModeBtn) {
    els.mainMenuUserModeBtn.classList.toggle('active', rokUserModeActive);
    els.mainMenuUserModeBtn.setAttribute('aria-pressed', rokUserModeActive ? 'true' : 'false');
  }
  if (els.mainMenuUserModeState) els.mainMenuUserModeState.textContent = rokUserModeActive ? 'Activo · colección local' : 'Desactivado';
}

function setRokUserModeActive(active, options = {}) {
  rokUserModeActive = Boolean(active);
  safeLocalStorageSet(ROK_USER_MODE_STORAGE_KEY, rokUserModeActive ? '1' : '0');
  updateRokUserModeUi();
  if (options.render !== false && document.body.classList.contains('rok-library-mode')) renderLibraryBuilder();
  return rokUserModeActive;
}

function toggleRokUserMode() {
  const active = setRokUserModeActive(!rokUserModeActive);
  if (els.mainMenuNotice) {
    els.mainMenuNotice.textContent = active
      ? 'Modo Usuario activo · la Biblioteca usa tu colección local.'
      : 'Modo Usuario desactivado · Biblioteca de desarrollo habilitada.';
  }
}


// ROK Lite v461 · Etapa 5 · Creador de Cartas / descomposición.
const CARD_CREATOR_MAX_QUEUE = 50;
const CARD_CREATOR_SUPPORTED_TYPES = new Set(['invocation', 'spell', 'ability', 'artifact', 'equipment', 'structure']);
const CARD_CREATOR_ELEMENT_COLORS = Object.freeze({
  ...Object.fromEntries(Object.keys(DOMINION_COLOR_PALETTE).map(id => [id, getDominionPrimaryColor(id)])),
  catalizadora: '#f3eaff',
});
const CARD_CREATOR_RARITY_ASSETS = Object.freeze({
  // Los nueve sprites conservan su secuencia visual histórica; lo que cambia es
  // qué rareza lógica ocupa cada escalón de esa secuencia.
  ordinary:'assets/rarities/rarity-ordinary.png',
  uncommon:'assets/rarities/rarity-uncommon.png',
  infrequent:'assets/rarities/rarity-extraordinary.png',
  unusual:'assets/rarities/rarity-singular.png',
  extraordinary:'assets/rarities/rarity-infrequent.png',
  strange:'assets/rarities/rarity-unusual.png',
  singular:'assets/rarities/rarity-strange.png',
  legendary:'assets/rarities/rarity-mythic.png',
  mythic:'assets/rarities/rarity-legendary.png',
});

const cardCreatorState = {
  active: false,
  queue: [],
  sequence: 0,
  decomposing: false,
  pendingCreationCardId: null,
  pendingCreationCost: null,
  modalQuantityCardId: null,
  decomposeQuantity: 1,
  createQuantity: 1,
};

function isCardCreatorModeActive() {
  return cardCreatorState.active === true || document.body?.classList.contains('rok-card-creator-mode');
}

function getCardCreatorQueuedCount(cardId) {
  return cardCreatorState.queue.reduce((total, entry) => total + (entry.cardId === cardId ? 1 : 0), 0);
}

function getCardCreatorAvailableOwnedCopies(cardOrId) {
  const card = typeof cardOrId === 'string' ? CARD_LIBRARY[cardOrId] : cardOrId;
  if (!card || getCardTypeId(card) === 'kaster') return 0;
  return Math.max(0, getRokUserOwnedCopies(card) - getCardCreatorQueuedCount(card.id));
}

function pickRandomCreatorElementId() {
  return ROK_USER_RESOURCE_ELEMENT_IDS[Math.floor(Math.random() * ROK_USER_RESOURCE_ELEMENT_IDS.length)] || 'oscuridad';
}

function addCreatorElementAmount(target, elementId, amount = 1) {
  if (!ROK_USER_RESOURCE_ELEMENT_IDS.includes(elementId)) return target;
  const value = Math.max(0, Math.floor(Number(amount) || 0));
  if (!value) return target;
  target[elementId] = (target[elementId] || 0) + value;
  return target;
}

function allocateRandomCreatorElements(unitCount = 0) {
  const result = {};
  const count = Math.max(0, Math.floor(Number(unitCount) || 0));
  for (let index = 0; index < count; index += 1) addCreatorElementAmount(result, pickRandomCreatorElementId(), 1);
  return result;
}

function getCardCreatorRarityId(card) {
  try { return getBoosterCardRarityId(card) || 'ordinary'; }
  catch (_) {
    try { return getCardVisualRarity(card)?.id || 'ordinary'; }
    catch (_) { return normalizeCardRarityId(card?.rarity); }
  }
}

function getCardCreatorDominantElementId(card) {
  if (!card) return 'oscuridad';
  if (isCatalystCard(card)) return 'catalizadora';
  const cardElement = getCardElementId(card);
  if (ROK_USER_RESOURCE_ELEMENT_IDS.includes(cardElement)) return cardElement;
  const entries = getCardCostEntries(card)
    .filter(([id, amount]) => ROK_USER_RESOURCE_ELEMENT_IDS.includes(id) && Number(amount) > 0)
    .sort((a, b) => Number(b[1]) - Number(a[1]));
  return entries[0]?.[0] || 'oscuridad';
}

function getCardCreatorElementalCostTotal(card) {
  // Usa el mismo costo TOTAL que presenta la carta para kastearse. Esto incluye
  // la porción aleatoria y también costos dinámicos con una cantidad base definida.
  return Math.max(0, Math.floor(Number(getCardTotalCost(card)) || 0));
}

function getCardCreatorDecomposeReward(card) {
  // Regla v465: por cada copia se calcula primero y SIEMPRE se redondea hacia abajo.
  // Cristal Puro devuelto = floor(PB total × 20%).
  const pureCrystal = Math.max(0, Math.floor((Number(getCardBattlePointsValue(card)) || 0) * 0.20));
  const rarityId = getCardCreatorRarityId(card);
  const elements = {};
  const totalElementalCost = getCardCreatorElementalCostTotal(card);
  const returnedElementUnits = Math.max(0, Math.floor(totalElementalCost / 2));
  const baseElementId = getCardCreatorDominantElementId(card);

  // Las cartas con dominio elemental normal convierten TODO su costo (incluido el aleatorio)
  // al elemento base antes de calcular la devolución. Catalizadora no tiene recurso base propio,
  // por lo que conserva su reparto universal entre los elementos de recurso existentes.
  if (returnedElementUnits > 0) {
    if (ROK_USER_RESOURCE_ELEMENT_IDS.includes(baseElementId)) {
      addCreatorElementAmount(elements, baseElementId, returnedElementUnits);
    } else {
      const universalElements = allocateRandomCreatorElements(returnedElementUnits);
      Object.entries(universalElements).forEach(([elementId, amount]) => addCreatorElementAmount(elements, elementId, amount));
    }
  }

  return { pureCrystal, rarityId, elements };
}

function buildCardCreatorCreationCost(card) {
  const elements = {};
  const totalElementalCost = getCardCreatorElementalCostTotal(card);
  const baseElementId = getCardCreatorDominantElementId(card);

  // Regla v463: el costo elemental de creación usa el COSTO TOTAL de kasteo.
  // Todo costo aleatorio se convierte al elemento base de la carta.
  if (totalElementalCost > 0) {
    if (ROK_USER_RESOURCE_ELEMENT_IDS.includes(baseElementId)) {
      addCreatorElementAmount(elements, baseElementId, totalElementalCost);
    } else {
      const universalElements = allocateRandomCreatorElements(totalElementalCost);
      Object.entries(universalElements).forEach(([elementId, amount]) => addCreatorElementAmount(elements, elementId, amount));
    }
  }

  return {
    cardId: card.id,
    pureCrystal: Math.max(0, Math.floor(Number(getCardBattlePointsValue(card)) || 0)),
    rarityId: getCardCreatorRarityId(card),
    rarityAmount: 1,
    elements,
  };
}

function ensureCardCreatorPendingCreationCost(card) {
  if (!card) return null;
  if (cardCreatorState.pendingCreationCardId !== card.id || !cardCreatorState.pendingCreationCost) {
    cardCreatorState.pendingCreationCardId = card.id;
    cardCreatorState.pendingCreationCost = buildCardCreatorCreationCost(card);
  }
  return cardCreatorState.pendingCreationCost;
}

function resetCardCreatorPendingCreationCost() {
  cardCreatorState.pendingCreationCardId = null;
  cardCreatorState.pendingCreationCost = null;
}

function ensureCardCreatorModalQuantities(card) {
  if (!card) return;
  if (cardCreatorState.modalQuantityCardId === card.id) return;
  cardCreatorState.modalQuantityCardId = card.id;
  cardCreatorState.decomposeQuantity = getCardCreatorAvailableOwnedCopies(card) > 0 ? 1 : 0;
  cardCreatorState.createQuantity = 1;
}

function resetCardCreatorModalQuantities() {
  cardCreatorState.modalQuantityCardId = null;
  cardCreatorState.decomposeQuantity = 1;
  cardCreatorState.createQuantity = 1;
}

function multiplyCardCreatorCost(cost, quantity = 1) {
  const count = Math.max(0, Math.floor(Number(quantity) || 0));
  const elements = {};
  Object.entries(cost?.elements || {}).forEach(([elementId, amount]) => {
    elements[elementId] = Math.max(0, Math.floor(Number(amount) || 0)) * count;
  });
  return {
    cardId: cost?.cardId || null,
    pureCrystal: Math.max(0, Math.floor(Number(cost?.pureCrystal) || 0)) * count,
    rarityId: cost?.rarityId || 'ordinary',
    rarityAmount: Math.max(0, Math.floor(Number(cost?.rarityAmount) || 1)) * count,
    elements,
    quantity: count,
  };
}

function getCardCreatorMaxCreatableCopies(card) {
  const unitCost = ensureCardCreatorPendingCreationCost(card);
  if (!card || !unitCost) return 0;
  if (card.upcoming || card.spellbookLocked || !CARD_CREATOR_SUPPORTED_TYPES.has(getCardTypeId(card))) return 0;
  const limits = [];
  if (unitCost.pureCrystal > 0) limits.push(Math.floor(getRokUserPureCrystal() / unitCost.pureCrystal));
  Object.entries(unitCost.elements || {}).forEach(([elementId, amount]) => {
    const needed = Math.max(0, Math.floor(Number(amount) || 0));
    if (needed > 0) limits.push(Math.floor(getRokUserElementResource(elementId) / needed));
  });
  const rarityNeeded = Math.max(0, Math.floor(Number(unitCost.rarityAmount) || 1));
  if (rarityNeeded > 0) limits.push(Math.floor(getRokUserRarityResource(unitCost.rarityId) / rarityNeeded));
  if (!limits.length) return 0;
  return Math.max(0, Math.min(...limits));
}

function getCardCreatorCreationAffordability(card, quantity = 1) {
  const unitCost = ensureCardCreatorPendingCreationCost(card);
  const count = Math.max(1, Math.floor(Number(quantity) || 1));
  const cost = multiplyCardCreatorCost(unitCost, count);
  if (!card || !unitCost) return { canCreate:false, reason:'No se pudo calcular el costo de creación.', cost, unitCost, quantity:count };
  if (card.upcoming || card.spellbookLocked) return { canCreate:false, reason:'Esta carta todavía no está habilitada para creación.', cost, unitCost, quantity:count };
  if (!CARD_CREATOR_SUPPORTED_TYPES.has(getCardTypeId(card))) return { canCreate:false, reason:'Este tipo de carta todavía no puede crearse.', cost, unitCost, quantity:count };
  if (getRokUserPureCrystal() < cost.pureCrystal) return { canCreate:false, reason:`Faltan ${formatRokPureCrystalAmount(cost.pureCrystal - getRokUserPureCrystal())} Cristales Puros.`, cost, unitCost, quantity:count };
  for (const [elementId, amount] of Object.entries(cost.elements || {})) {
    if (getRokUserElementResource(elementId) < amount) {
      return { canCreate:false, reason:`Falta ${ROK_USER_RESOURCE_ELEMENT_LABELS[elementId] || elementId}: necesitas ${amount}.`, cost, unitCost, quantity:count };
    }
  }
  if (getRokUserRarityResource(cost.rarityId) < cost.rarityAmount) {
    return { canCreate:false, reason:`Necesitas ${ROK_USER_RESOURCE_RARITY_LABELS[cost.rarityId] || cost.rarityId} ×${cost.rarityAmount}.`, cost, unitCost, quantity:count };
  }
  return { canCreate:true, reason:'', cost, unitCost, quantity:count };
}

function setCardCreatorQuantityControlValue(control, value) {
  if (!control) return;
  const text = String(Math.max(0, Math.floor(Number(value) || 0)));
  if ('value' in control) control.value = text;
  else control.textContent = text;
}

function setCardCreatorModalQuantityFromInput(kind, rawValue) {
  if (!state.infoCard || state.infoCard.source !== 'cardCreator') return;
  const card = CARD_LIBRARY[state.infoCard.cardId];
  if (!card) return;
  ensureCardCreatorModalQuantities(card);
  const requested = Math.max(0, Math.floor(Number(rawValue) || 0));

  if (kind === 'decompose') {
    const max = Math.max(0, Math.min(
      getCardCreatorAvailableOwnedCopies(card),
      CARD_CREATOR_MAX_QUEUE - cardCreatorState.queue.length
    ));
    cardCreatorState.decomposeQuantity = max > 0 ? Math.max(1, Math.min(max, requested || 1)) : 0;
  } else if (kind === 'create') {
    const max = getCardCreatorMaxCreatableCopies(card);
    const normalized = Math.max(1, requested || 1);
    cardCreatorState.createQuantity = max > 0 ? Math.min(max, normalized) : 1;
  }

  hideCardInfoSpellbookFeedback();
  updateCardInfoAction();
}

function adjustCardCreatorModalQuantity(kind, delta) {
  if (!state.infoCard || state.infoCard.source !== 'cardCreator') return;
  const card = CARD_LIBRARY[state.infoCard.cardId];
  if (!card) return;
  ensureCardCreatorModalQuantities(card);
  const step = delta < 0 ? -1 : 1;
  if (kind === 'decompose') {
    const max = Math.max(0, Math.min(
      getCardCreatorAvailableOwnedCopies(card),
      CARD_CREATOR_MAX_QUEUE - cardCreatorState.queue.length
    ));
    if (max <= 0) cardCreatorState.decomposeQuantity = 0;
    else cardCreatorState.decomposeQuantity = Math.max(1, Math.min(max, cardCreatorState.decomposeQuantity + step));
  } else if (kind === 'create') {
    const max = getCardCreatorMaxCreatableCopies(card);
    if (step < 0) cardCreatorState.createQuantity = Math.max(1, cardCreatorState.createQuantity - 1);
    else if (max > 0) cardCreatorState.createQuantity = Math.min(max, cardCreatorState.createQuantity + 1);
  }
  hideCardInfoSpellbookFeedback();
  updateCardInfoAction();
}

function renderRokUserResourceStripMarkup({ includeLabels = false } = {}) {
  const crystal = `<span class="rok-resource-chip pure" title="Cristal Puro"><img src="${ROK_PURE_CRYSTAL_ASSET}" alt="Cristal Puro"><strong>${formatRokPureCrystalAmount(getRokUserPureCrystal())}</strong>${includeLabels ? '<small>Cristal</small>' : ''}</span>`;
  const elements = ROK_USER_RESOURCE_ELEMENT_IDS.map(elementId => `<span class="rok-resource-chip element" data-user-element="${elementId}" title="${ROK_USER_RESOURCE_ELEMENT_LABELS[elementId]}"><img src="${getElementCostIcon(elementId)}" alt="${ROK_USER_RESOURCE_ELEMENT_LABELS[elementId]}"><strong>${formatRokPureCrystalAmount(getRokUserElementResource(elementId))}</strong>${includeLabels ? `<small>${ROK_USER_RESOURCE_ELEMENT_LABELS[elementId]}</small>` : ''}</span>`).join('');
  const rarities = ROK_USER_RESOURCE_RARITY_IDS.map(rarityId => `<span class="rok-resource-chip rarity" data-user-rarity="${rarityId}" title="${ROK_USER_RESOURCE_RARITY_LABELS[rarityId]}"><img src="${CARD_CREATOR_RARITY_ASSETS[rarityId]}" alt="${ROK_USER_RESOURCE_RARITY_LABELS[rarityId]}"><strong>${formatRokPureCrystalAmount(getRokUserRarityResource(rarityId))}</strong>${includeLabels ? `<small>${ROK_USER_RESOURCE_RARITY_LABELS[rarityId]}</small>` : ''}</span>`).join('');
  return `${crystal}${elements}<span class="rok-resource-divider" aria-hidden="true"></span>${rarities}`;
}

function getCardCreatorQueueTotals() {
  const totals = { pureCrystal:0, elements:{}, rarities:{} };
  cardCreatorState.queue.forEach(entry => {
    totals.pureCrystal += Math.max(0, Math.floor(Number(entry?.reward?.pureCrystal) || 0));
    Object.entries(entry?.reward?.elements || {}).forEach(([elementId, amount]) => addCreatorElementAmount(totals.elements, elementId, amount));
    const rarityId = entry?.reward?.rarityId;
    if (rarityId) totals.rarities[rarityId] = (totals.rarities[rarityId] || 0) + 1;
  });
  return totals;
}

function showCardCreatorNotice(message = '') {
  if (els.cardCreatorNotice) {
    els.cardCreatorNotice.textContent = String(message || '');
    els.cardCreatorNotice.classList.remove('pulse');
    void els.cardCreatorNotice.offsetWidth;
    if (message) els.cardCreatorNotice.classList.add('pulse');
  }
  if (els.libraryBuilderNotice) els.libraryBuilderNotice.textContent = String(message || '');
}

function renderCardCreatorWorkshop() {
  if (!isCardCreatorModeActive()) return;
  if (els.cardCreatorWorkshopPanel) els.cardCreatorWorkshopPanel.hidden = false;
  if (els.libraryBuilderSpellbookPanel) els.libraryBuilderSpellbookPanel.hidden = true;
  if (els.cardCreatorStockHud) {
    els.cardCreatorStockHud.innerHTML = renderRokUserResourceStripMarkup({ includeLabels:false });
    updateRokUserResourceStrip(els.cardCreatorStockHud);
  }
  if (els.cardCreatorQueueCount) els.cardCreatorQueueCount.textContent = `${cardCreatorState.queue.length} / ${CARD_CREATOR_MAX_QUEUE}`;
  if (els.cardCreatorOrbEmpty) els.cardCreatorOrbEmpty.hidden = cardCreatorState.queue.length > 0;
  if (els.cardCreatorOrbItems) {
    els.cardCreatorOrbItems.innerHTML = '';
    cardCreatorState.queue.forEach((entry, index) => {
      const card = CARD_LIBRARY[entry.cardId];
      const orb = document.createElement('button');
      orb.type = 'button';
      orb.className = `card-creator-floating-orb element-${entry.elementId || 'oscuridad'}`;
      orb.dataset.queueId = entry.queueId;
      orb.title = `${card?.name || entry.cardId} · clic para retirar del mezclador`;
      const angle = ((index * 137.508) + (entry.seed % 37)) * Math.PI / 180;
      const ring = 20 + ((entry.seed * 17 + index * 11) % 66);
      const x = 50 + Math.cos(angle) * ring * .58;
      const y = 50 + Math.sin(angle) * ring * .42;
      orb.style.setProperty('--orb-x', `${Math.max(8, Math.min(92, x)).toFixed(2)}%`);
      orb.style.setProperty('--orb-y', `${Math.max(10, Math.min(90, y)).toFixed(2)}%`);
      orb.style.setProperty('--orb-delay', `${-((entry.seed % 31) / 10).toFixed(1)}s`);
      orb.style.setProperty('--orb-duration', `${(4.2 + ((entry.seed % 23) / 10)).toFixed(1)}s`);
      orb.style.setProperty('--orb-size', `${18 + (entry.seed % 13)}px`);
      orb.style.setProperty('--orb-color', CARD_CREATOR_ELEMENT_COLORS[entry.elementId] || CARD_CREATOR_ELEMENT_COLORS.oscuridad);
      orb.innerHTML = '<i></i>';
      els.cardCreatorOrbItems.appendChild(orb);
    });
  }
  const totals = getCardCreatorQueueTotals();
  if (els.cardCreatorReturnCrystal) {
    els.cardCreatorReturnCrystal.innerHTML = totals.pureCrystal > 0
      ? `<span class="creator-return-chip"><img src="${ROK_PURE_CRYSTAL_ASSET}" alt="Cristal Puro"><strong>${formatRokPureCrystalAmount(totals.pureCrystal)}</strong></span>`
      : '<span class="creator-return-empty">—</span>';
  }
  if (els.cardCreatorReturnElements) {
    const html = ROK_USER_RESOURCE_ELEMENT_IDS.filter(id => totals.elements[id] > 0).map(elementId => `<span class="creator-return-chip"><img src="${getElementCostIcon(elementId)}" alt="${ROK_USER_RESOURCE_ELEMENT_LABELS[elementId]}"><strong>${totals.elements[elementId]}</strong></span>`).join('');
    els.cardCreatorReturnElements.innerHTML = html || '<span class="creator-return-empty">—</span>';
  }
  if (els.cardCreatorReturnRarities) {
    const nodes = [];
    ROK_USER_RESOURCE_RARITY_IDS.forEach(rarityId => {
      const count = Math.max(0, Number(totals.rarities[rarityId]) || 0);
      for (let index = 0; index < count; index += 1) nodes.push(`<img class="creator-return-rarity-icon" src="${CARD_CREATOR_RARITY_ASSETS[rarityId]}" alt="${ROK_USER_RESOURCE_RARITY_LABELS[rarityId]}" title="${ROK_USER_RESOURCE_RARITY_LABELS[rarityId]}">`);
    });
    els.cardCreatorReturnRarities.innerHTML = nodes.join('') || '<span class="creator-return-empty">—</span>';
  }
  if (els.cardCreatorDecomposeBtn) els.cardCreatorDecomposeBtn.disabled = cardCreatorState.decomposing || cardCreatorState.queue.length === 0;
  if (els.cardCreatorClearBtn) els.cardCreatorClearBtn.disabled = cardCreatorState.decomposing || cardCreatorState.queue.length === 0;
  updateRokPureCrystalUi();
}

function addCardToCreatorQueue(cardId, requestedQuantity = 1) {
  const card = CARD_LIBRARY[cardId];
  if (!card || !CARD_CREATOR_SUPPORTED_TYPES.has(getCardTypeId(card))) return { ok:false, added:0, reason:'Este tipo de carta no puede descomponerse todavía.' };
  if (card.upcoming || card.spellbookLocked) return { ok:false, added:0, reason:'Esta carta todavía no está habilitada para descomposición.' };
  if (cardCreatorState.decomposing) return { ok:false, added:0, reason:'Espera a que termine la descomposición actual.' };
  const quantity = Math.max(1, Math.floor(Number(requestedQuantity) || 1));
  const freeSlots = Math.max(0, CARD_CREATOR_MAX_QUEUE - cardCreatorState.queue.length);
  const availableOwned = getCardCreatorAvailableOwnedCopies(card);
  if (freeSlots <= 0) return { ok:false, added:0, reason:`El mezclador alcanzó su límite de ${CARD_CREATOR_MAX_QUEUE} cartas.` };
  if (availableOwned <= 0) return { ok:false, added:0, reason:`No posees otra copia disponible de ${card.name || card.id} para descomponer.` };
  const maxQuantity = Math.min(freeSlots, availableOwned);
  if (quantity > maxQuantity) {
    const reason = freeSlots < availableOwned
      ? `Solo caben ${freeSlots} carta${freeSlots === 1 ? '' : 's'} más en el mezclador.`
      : `Solo tienes ${availableOwned} copia${availableOwned === 1 ? '' : 's'} disponible${availableOwned === 1 ? '' : 's'} para descomponer.`;
    return { ok:false, added:0, reason };
  }
  const dominant = getCardCreatorDominantElementId(card);
  const entries = [];
  for (let copy = 0; copy < quantity; copy += 1) {
    const entry = {
      queueId: `creator-${Date.now()}-${++cardCreatorState.sequence}`,
      cardId: card.id,
      reward: getCardCreatorDecomposeReward(card),
      elementId: dominant,
      seed: Math.floor(Math.random() * 100000),
    };
    cardCreatorState.queue.push(entry);
    entries.push(entry);
  }
  renderLibraryBuilder();
  renderCardCreatorWorkshop();
  if (state.infoCard?.source === 'cardCreator') updateCardInfoAction();
  showCardCreatorNotice(`${quantity} copia${quantity === 1 ? '' : 's'} de ${card.name || card.id} agregada${quantity === 1 ? '' : 's'} al mezclador · ${cardCreatorState.queue.length}/${CARD_CREATOR_MAX_QUEUE}.`);
  return { ok:true, added:quantity, entries };
}

function removeCardCreatorQueueEntry(queueId) {
  if (cardCreatorState.decomposing) return false;
  const index = cardCreatorState.queue.findIndex(entry => entry.queueId === queueId);
  if (index < 0) return false;
  const [entry] = cardCreatorState.queue.splice(index, 1);
  renderLibraryBuilder();
  renderCardCreatorWorkshop();
  if (state.infoCard?.source === 'cardCreator') updateCardInfoAction();
  showCardCreatorNotice(`${CARD_LIBRARY[entry.cardId]?.name || entry.cardId} retirada del mezclador.`);
  return true;
}

function clearCardCreatorQueue() {
  if (cardCreatorState.decomposing || !cardCreatorState.queue.length) return false;
  cardCreatorState.queue = [];
  renderLibraryBuilder();
  renderCardCreatorWorkshop();
  if (state.infoCard?.source === 'cardCreator') updateCardInfoAction();
  showCardCreatorNotice('Mezclador vacío. No se consumió ninguna carta.');
  return true;
}

async function decomposeCardCreatorQueue() {
  if (cardCreatorState.decomposing || !cardCreatorState.queue.length) return false;
  const counts = {};
  cardCreatorState.queue.forEach(entry => { counts[entry.cardId] = (counts[entry.cardId] || 0) + 1; });
  for (const [cardId, amount] of Object.entries(counts)) {
    if (getRokUserOwnedCopies(cardId) < amount) {
      showCardCreatorNotice(`No se puede descomponer: faltan copias de ${CARD_LIBRARY[cardId]?.name || cardId}.`);
      return false;
    }
  }
  cardCreatorState.decomposing = true;
  if (els.cardCreatorOrb) els.cardCreatorOrb.classList.add('is-decomposing');
  if (els.cardCreatorDecomposeBtn) els.cardCreatorDecomposeBtn.disabled = true;
  if (els.cardCreatorClearBtn) els.cardCreatorClearBtn.disabled = true;
  showCardCreatorNotice(`Descomponiendo ${cardCreatorState.queue.length} carta${cardCreatorState.queue.length === 1 ? '' : 's'}…`);
  await sleep(1250);

  const totals = getCardCreatorQueueTotals();
  Object.entries(counts).forEach(([cardId, amount]) => spendRokUserCollectionCard(cardId, amount, { persist:false, render:false }));
  rokUserProfile.pureCrystal = getRokUserPureCrystal() + totals.pureCrystal;
  rokUserProfile.elements = normalizeRokUserResourceMap(rokUserProfile.elements, ROK_USER_RESOURCE_ELEMENT_IDS);
  Object.entries(totals.elements).forEach(([elementId, amount]) => { rokUserProfile.elements[elementId] = getRokUserElementResource(elementId) + amount; });
  rokUserProfile.rarities = normalizeRokUserResourceMap(rokUserProfile.rarities, ROK_USER_RESOURCE_RARITY_IDS);
  Object.entries(totals.rarities).forEach(([rarityId, amount]) => { rokUserProfile.rarities[rarityId] = getRokUserRarityResource(rarityId) + amount; });
  persistRokUserProfile();

  cardCreatorState.queue = [];
  cardCreatorState.decomposing = false;
  if (els.cardCreatorOrb) els.cardCreatorOrb.classList.remove('is-decomposing');
  renderLibraryBuilder();
  renderCardCreatorWorkshop();
  if (state.infoCard?.source === 'cardCreator') updateCardInfoAction();
  showCardCreatorNotice(`Descomposición completada · +${formatRokPureCrystalAmount(totals.pureCrystal)} Cristal Puro y recursos transferidos.`);
  return true;
}

function renderCardCreatorCreationCost(card, quantity = cardCreatorState.createQuantity) {
  if (!els.cardInfoCooldownTray || !card) return;
  ensureCardCreatorModalQuantities(card);
  const count = Math.max(1, Math.floor(Number(quantity) || 1));
  const unitCost = ensureCardCreatorPendingCreationCost(card);
  const cost = multiplyCardCreatorCost(unitCost, count);
  const row = els.cardInfoCooldownTray.closest('.stat-row-cooldowns');
  if (row) row.removeAttribute('hidden');
  const owned = getRokUserOwnedCopies(card);
  const queued = getCardCreatorQueuedCount(card.id);
  const availableOwned = getCardCreatorAvailableOwnedCopies(card);
  const resourceChip = (asset, label, needed, available, extraClass = '') => {
    const missing = Math.max(0, needed - available);
    const missingClass = missing > 0 ? ' is-missing' : '';
    const detail = missing > 0 ? `<small>${formatRokPureCrystalAmount(available)} disp. · faltan ${formatRokPureCrystalAmount(missing)}</small>` : '';
    return `<span class="creator-modal-cost-chip ${extraClass}${missingClass}" title="${label}: necesitas ${formatRokPureCrystalAmount(needed)} · tienes ${formatRokPureCrystalAmount(available)}"><img src="${asset}" alt="${label}"><strong>${formatRokPureCrystalAmount(needed)}</strong>${detail}</span>`;
  };
  const elementChips = Object.entries(cost?.elements || {}).filter(([, amount]) => amount > 0).map(([elementId, amount]) => resourceChip(
    getElementCostIcon(elementId),
    ROK_USER_RESOURCE_ELEMENT_LABELS[elementId],
    amount,
    getRokUserElementResource(elementId)
  )).join('');
  const rarityAsset = CARD_CREATOR_RARITY_ASSETS[cost?.rarityId] || CARD_CREATOR_RARITY_ASSETS.ordinary;
  const rarityLabel = ROK_USER_RESOURCE_RARITY_LABELS[cost?.rarityId] || 'Ordinaria';
  const rarityChip = resourceChip(rarityAsset, rarityLabel, cost?.rarityAmount || count, getRokUserRarityResource(cost?.rarityId), 'rarity');
  const pureChip = resourceChip(ROK_PURE_CRYSTAL_ASSET, 'Cristal Puro', cost?.pureCrystal || 0, getRokUserPureCrystal(), 'pure');
  els.cardInfoCooldownTray.innerHTML = `<div class="card-creator-modal-cost"><div class="card-creator-modal-cost-main"><span class="card-creator-modal-cost-title">COSTO DE CREACIÓN <b>×${count}</b></span><div class="card-creator-modal-cost-values">${pureChip}${elementChips}${rarityChip}</div></div><div class="card-creator-owned-copies" title="Copias reales en tu colección y copias reservadas en el mezclador"><span>COPIAS EN COLECCIÓN</span><strong>${owned}</strong><small>${queued > 0 ? `${queued} en mezclador · ` : ''}${availableOwned} disp. para descomponer</small></div></div>`;
}

function spendCardCreatorCreationResources(cost) {
  if (!cost) return false;
  if (getRokUserPureCrystal() < cost.pureCrystal) return false;
  for (const [elementId, amount] of Object.entries(cost.elements || {})) if (getRokUserElementResource(elementId) < amount) return false;
  if (getRokUserRarityResource(cost.rarityId) < (cost.rarityAmount || 1)) return false;
  rokUserProfile.pureCrystal = getRokUserPureCrystal() - cost.pureCrystal;
  rokUserProfile.elements = normalizeRokUserResourceMap(rokUserProfile.elements, ROK_USER_RESOURCE_ELEMENT_IDS);
  Object.entries(cost.elements || {}).forEach(([elementId, amount]) => { rokUserProfile.elements[elementId] = getRokUserElementResource(elementId) - amount; });
  rokUserProfile.rarities = normalizeRokUserResourceMap(rokUserProfile.rarities, ROK_USER_RESOURCE_RARITY_IDS);
  rokUserProfile.rarities[cost.rarityId] = getRokUserRarityResource(cost.rarityId) - (cost.rarityAmount || 1);
  return true;
}

function createCardFromCreatorModal() {
  if (!state.infoCard || state.infoCard.source !== 'cardCreator') return false;
  const card = CARD_LIBRARY[state.infoCard.cardId];
  if (!card) return false;
  ensureCardCreatorModalQuantities(card);
  const quantity = Math.max(1, Math.floor(Number(cardCreatorState.createQuantity) || 1));
  const affordability = getCardCreatorCreationAffordability(card, quantity);
  if (!affordability.canCreate) {
    showCardInfoSpellbookFeedback(affordability.reason.toUpperCase(), 'warning');
    updateCardInfoAction();
    return false;
  }
  if (!spendCardCreatorCreationResources(affordability.cost)) {
    showCardInfoSpellbookFeedback('LOS RECURSOS CAMBIARON. REVISA EL COSTO DE CREACIÓN.', 'warning');
    updateCardInfoAction();
    return false;
  }
  grantRokUserCollectionCard(card.id, quantity, { persist:false });
  persistRokUserProfile();
  resetCardCreatorPendingCreationCost();
  cardCreatorState.pendingCreationCardId = card.id;
  cardCreatorState.pendingCreationCost = buildCardCreatorCreationCost(card);
  const maxAfter = getCardCreatorMaxCreatableCopies(card);
  cardCreatorState.createQuantity = maxAfter > 0 ? Math.min(quantity, maxAfter) : 1;
  renderLibraryBuilder();
  renderCardCreatorWorkshop();
  updateCardInfoAction();
  showCardInfoSpellbookFeedback(quantity === 1 ? 'CARTA CREADA.' : `${quantity} CARTAS CREADAS.`, 'success', 3000);
  const totalOwned = getRokUserOwnedCopies(card);
  showCardCreatorNotice(`${quantity} copia${quantity === 1 ? '' : 's'} creada${quantity === 1 ? '' : 's'} · ${card.name || card.id} ahora tiene ${totalOwned} copia${totalOwned === 1 ? '' : 's'} en tu colección.`);
  return true;
}

function mountCardCreatorUi() {
  const screen = els.libraryBuilderScreen || document.getElementById('libraryBuilderScreen');
  const layout = screen?.querySelector('.library-builder-layout');
  const summaryHud = screen?.querySelector('.library-builder-summary-hud');
  const topHud = els.cardCreatorTopHud || document.getElementById('cardCreatorTopHud');
  const workshop = els.cardCreatorWorkshopPanel || document.getElementById('cardCreatorWorkshopPanel');
  if (summaryHud && topHud && topHud.parentElement !== summaryHud) summaryHud.appendChild(topHud);
  if (layout && workshop && workshop.parentElement !== layout) layout.appendChild(workshop);
}

function unmountCardCreatorUi() {
  const host = els.cardCreatorDetachedHost || document.getElementById('cardCreatorDetachedHost');
  const topHud = els.cardCreatorTopHud || document.getElementById('cardCreatorTopHud');
  const workshop = els.cardCreatorWorkshopPanel || document.getElementById('cardCreatorWorkshopPanel');
  if (!host) return;
  if (topHud && topHud.parentElement !== host) host.appendChild(topHud);
  if (workshop && workshop.parentElement !== host) host.appendChild(workshop);
}

function openCardCreatorScreen() {
  cardCreatorState.active = true;
  cardCreatorState.decomposing = false;
  resetCardCreatorPendingCreationCost();
  resetCardCreatorModalQuantities();
  setLibraryBuilderIdle();
  document.body.classList.remove('rok-menu-mode', 'rok-battle-mode', 'rok-spellbooks-mode');
  document.body.classList.add('rok-library-mode', 'rok-card-creator-mode');
  clearBattleHudForInactiveScreen();
  if (els.mainMenuScreen) els.mainMenuScreen.setAttribute('aria-hidden', 'true');
  if (els.spellbooksCollectionScreen) els.spellbooksCollectionScreen.setAttribute('aria-hidden', 'true');
  if (els.libraryBuilderScreen) els.libraryBuilderScreen.setAttribute('aria-hidden', 'false');
  mountCardCreatorUi();
  renderLibraryBuilder();
  renderCardCreatorWorkshop();
  showCardCreatorNotice('Selecciona una carta: puedes agregar una copia poseída al mezclador o crearla si tienes recursos.');
}

function closeCardCreatorMode() {
  cardCreatorState.active = false;
  resetCardCreatorPendingCreationCost();
  resetCardCreatorModalQuantities();
  unmountCardCreatorUi();
  document.body.classList.remove('rok-card-creator-mode');
}

