function getNextBoosterDebugSampleCard(collection, avoidIds = []) {
  if (!ROK_BOOSTER_DEBUG_SAMPLE_MODE) return null;
  const avoid = new Set((avoidIds || []).map(String));
  const pool = ROK_BOOSTER_DEBUG_SAMPLE_IDS
    .map(cardId => CARD_LIBRARY[cardId])
    .filter(card => card && getCardTypeId(card) === ROK_BOOSTER_DEBUG_SAMPLE_TYPE)
    .filter(card => {
      const origin = getRokCardOriginId(card);
      return origin === 'neutral' || origin === collection?.originId;
    });
  if (!pool.length) return null;
  for (let offset = 0; offset < pool.length; offset += 1) {
    const index = (rokBoosterDebugSampleCursor + offset) % pool.length;
    const card = pool[index];
    if (!card || avoid.has(String(card.id))) continue;
    rokBoosterDebugSampleCursor = (index + 1) % pool.length;
    return card;
  }
  const fallback = pool[rokBoosterDebugSampleCursor % pool.length] || pool[0];
  rokBoosterDebugSampleCursor = (rokBoosterDebugSampleCursor + 1) % pool.length;
  return fallback || null;
}

const boosterStoreState = {
  step: 'collections',
  collectionId: null,
  purchaseMode: '',
  bundleCount: 1,
  lastAcquiredAmount: 0,
  returnContext: 'main',
  openingRemaining: 0,
  openingTotal: 0,
  currentPackCards: [],
  openedCardsSession: [],
  openedPacksSession: 0,
  animationToken: 0,
};

function getRokUserBoosterCount(collectionId) {
  return Math.max(0, Math.floor(Number(rokUserProfile?.boosters?.[collectionId]) || 0));
}

function grantRokUserBoosters(collectionId, amount = 1) {
  if (!ROK_BOOSTER_COLLECTIONS[collectionId]) return 0;
  const increment = Math.max(0, Math.floor(Number(amount) || 0));
  if (!increment) return getRokUserBoosterCount(collectionId);
  rokUserProfile.boosters = normalizeRokUserBoosters(rokUserProfile.boosters);
  rokUserProfile.boosters[collectionId] = getRokUserBoosterCount(collectionId) + increment;
  persistRokUserProfile();
  return rokUserProfile.boosters[collectionId];
}

function getTotalRokUserBoosters() {
  return Object.keys(ROK_BOOSTER_COLLECTIONS).reduce((total, id) => total + getRokUserBoosterCount(id), 0);
}

function consumeRokUserBoosters(collectionId, amount = 1) {
  const current = getRokUserBoosterCount(collectionId);
  const decrement = Math.max(0, Math.min(current, Math.floor(Number(amount) || 0)));
  if (!decrement) return current;
  rokUserProfile.boosters = normalizeRokUserBoosters(rokUserProfile.boosters);
  const next = current - decrement;
  if (next > 0) rokUserProfile.boosters[collectionId] = next;
  else delete rokUserProfile.boosters[collectionId];
  persistRokUserProfile();
  return next;
}

function getBoosterCardRarityId(card) {
  const allowForcedRarity = card?.boosterDebugSample === true || card?.allowForcedRarity === true || card?.rarityOverrideMode === 'debug';
  if (allowForcedRarity && card?.forceRarityId) return normalizeCardRarityId(card.forceRarityId);
  try { return getLibraryBuilderCardRarityId(card) || 'ordinary'; }
  catch (_) {
    try { return getCardVisualRarity(card)?.id || 'ordinary'; }
    catch (_) { return normalizeCardRarityId(card?.rarity) || 'ordinary'; }
  }
}

function getBoosterRarityRank(cardOrId) {
  const card = typeof cardOrId === 'string' ? CARD_LIBRARY[cardOrId] : cardOrId;
  const index = ROK_BOOSTER_RARITY_ORDER.indexOf(getBoosterCardRarityId(card));
  return index >= 0 ? index + 1 : 1;
}

function getBoosterEligibleCards(collection, typeId) {
  if (!collection) return [];
  return Object.values(CARD_LIBRARY).filter(card => {
    if (!card || card.upcoming || card.spellbookLocked) return false;
    if (getCardTypeId(card) !== typeId) return false;
    if (typeId === 'kaster' && !ROK_BOOSTER_INCLUDE_KASTERS) return false;
    const origin = getRokCardOriginId(card);
    return origin === 'neutral' || origin === collection.originId;
  });
}

function weightedPick(items, weightGetter) {
  const prepared = (items || []).map(item => ({ item, weight: Math.max(0, Number(weightGetter(item)) || 0) })).filter(entry => entry.weight > 0);
  if (!prepared.length) return null;
  const total = prepared.reduce((sum, entry) => sum + entry.weight, 0);
  let roll = Math.random() * total;
  for (const entry of prepared) {
    roll -= entry.weight;
    if (roll <= 0) return entry.item;
  }
  return prepared[prepared.length - 1].item;
}

function pickBoosterRarityId(cards, avoidIds = []) {
  const avoid = new Set((avoidIds || []).map(String));
  const source = (cards || []).filter(Boolean);
  const available = source.filter(card => !avoid.has(String(card.id)));
  const pool = available.length ? available : source;
  if (!pool.length) return null;

  // v452: la rareza se tira primero. La cantidad de cartas existentes en una
  // rareza ya no multiplica su probabilidad de aparecer. Solo participan las
  // rarezas que realmente tienen al menos una carta válida para este slot.
  const rarityIds = ROK_BOOSTER_RARITY_ORDER.filter(rarityId =>
    pool.some(card => getBoosterCardRarityId(card) === rarityId)
  );
  if (!rarityIds.length) return null;
  return weightedPick(rarityIds, rarityId => ROK_BOOSTER_RARITY_WEIGHTS[rarityId] || 0) || rarityIds[0];
}

function pickBoosterCardByRarity(cards, avoidIds = []) {
  const avoid = new Set((avoidIds || []).map(String));
  const source = (cards || []).filter(Boolean);
  const available = source.filter(card => !avoid.has(String(card.id)));
  const pool = available.length ? available : source;
  if (!pool.length) return null;

  // Primera tirada: rareza. Segunda tirada: una carta uniforme dentro de esa
  // rareza. Así 20 cartas Ordinarias no hacen que Ordinaria sea 20 veces más
  // probable que si solo hubiese una carta Ordinaria.
  const rarityId = pickBoosterRarityId(pool);
  if (!rarityId) return null;
  const rarityPool = pool.filter(card => getBoosterCardRarityId(card) === rarityId);
  if (!rarityPool.length) return null;
  return rarityPool[Math.floor(Math.random() * rarityPool.length)] || rarityPool[0];
}

function pickBoosterTokenType(collection) {
  const types = ['invocation', 'structure', ...(ROK_BOOSTER_INCLUDE_KASTERS ? ['kaster'] : [])]
    .filter(typeId => getBoosterEligibleCards(collection, typeId).length > 0);
  if (!types.length) return 'invocation';
  return weightedPick(types, typeId => ROK_BOOSTER_TOKEN_CATEGORY_WEIGHTS[typeId] || 1) || types[0];
}

function pickBoosterComplementaryType(collection) {
  const types = ROK_BOOSTER_COMPLEMENTARY_TYPES.filter(typeId => getBoosterEligibleCards(collection, typeId).length > 0);
  if (!types.length) return 'spell';
  return types[Math.floor(Math.random() * types.length)] || types[0];
}

function generateRokBoosterPack(collection) {
  const chosen = [];
  for (let i = 0; i < 2; i += 1) {
    const typeId = pickBoosterTokenType(collection);
    const card = pickBoosterCardByRarity(getBoosterEligibleCards(collection, typeId), chosen);
    if (card) chosen.push(card.id);
  }
  for (let i = 0; i < 3; i += 1) {
    const typeId = pickBoosterComplementaryType(collection);
    const card = pickBoosterCardByRarity(getBoosterEligibleCards(collection, typeId), chosen);
    if (card) chosen.push(card.id);
  }
  while (chosen.length < 5) {
    const fallback = Object.values(CARD_LIBRARY).filter(card => card && !card.upcoming && !card.spellbookLocked && getCardTypeId(card) !== 'kaster' && ['neutral', collection.originId].includes(getRokCardOriginId(card)));
    const card = pickBoosterCardByRarity(fallback, chosen);
    if (!card) break;
    chosen.push(card.id);
  }
  const debugSample = getNextBoosterDebugSampleCard(collection, chosen);
  if (debugSample?.id) {
    const replaceIndex = Math.max(0, Math.min(ROK_BOOSTER_DEBUG_SAMPLE_SLOT_INDEX, chosen.length - 1));
    if (chosen.length) chosen[replaceIndex] = debugSample.id;
    else chosen.push(debugSample.id);
  }
  return chosen.slice(0, 5);
}

function createBoosterRevealCardNode(cardId, options = {}) {
  const card = CARD_LIBRARY[cardId];
  if (!card) return document.createElement('span');
  const rarityId = getBoosterCardRarityId(card);
  const rank = getBoosterRarityRank(card);
  const rarity = (() => { try { return getCardVisualRarity(card); } catch (_) { return { id: rarityId, label: CARD_RARITY_LABELS?.[rarityId] || rarityId }; } })();
  const wrap = document.createElement('article');
  wrap.className = `booster-reveal-card rarity-${rarityId} rarity-rank-${rank}${options.compact ? ' compact' : ''}`;
  wrap.dataset.cardId = cardId;
  wrap.dataset.rarity = rarityId;
  wrap.dataset.rarityRank = String(rank);
  const visual = document.createElement('div');
  visual.className = 'booster-reveal-card-visual';
  const cardNode = createCardElement(card);
  cardNode.classList.add('booster-reveal-card-art');
  visual.appendChild(cardNode);

  // v460 · El foil principal se dibuja clonando el skin real de la carta.
  // Como el PNG del skin es transparente fuera de su marco/zona inferior,
  // el reflejo queda recortado exactamente a esa geometría y no al arte.
  const skinSource = cardNode.querySelector('.card-skin');
  const addSkinFoil = (kind) => {
    if (!skinSource) return null;
    const skinFoil = skinSource.cloneNode(true);
    skinFoil.className = `booster-rarity-skin-foil booster-rarity-skin-foil-${kind}`;
    skinFoil.alt = '';
    skinFoil.setAttribute('aria-hidden', 'true');
    skinFoil.removeAttribute('onerror');
    visual.appendChild(skinFoil);
    return skinFoil;
  };

  if (rarityId !== 'ordinary') addSkinFoil('basic');
  if (['singular','infrequent','unusual','strange','mythic','legendary'].includes(rarityId)) addSkinFoil('spark');

  // Extraña en adelante añade destellos de color que recorren la carta completa,
  // pero de forma translúcida. Legendaria además irradia partículas hacia fuera.
  if (['strange','mythic','legendary'].includes(rarityId)) {
    const streaks = document.createElement('i');
    streaks.className = 'booster-rarity-high-streaks';
    streaks.setAttribute('aria-hidden', 'true');
    visual.appendChild(streaks);
  }

  // Se conservan estos nodos por compatibilidad, pero v460 los anula visualmente.
  const pattern = document.createElement('i');
  pattern.className = 'booster-card-rarity-pattern';
  pattern.setAttribute('aria-hidden', 'true');
  visual.appendChild(pattern);
  const aura = document.createElement('i');
  aura.className = 'booster-card-rarity-aura';
  aura.setAttribute('aria-hidden', 'true');
  visual.appendChild(aura);
  const particles = document.createElement('i');
  particles.className = 'booster-card-rarity-particles';
  particles.setAttribute('aria-hidden', 'true');
  visual.appendChild(particles);
  const flare = document.createElement('i');
  flare.className = 'booster-card-rarity-flare';
  flare.setAttribute('aria-hidden', 'true');
  visual.appendChild(flare);
  wrap.appendChild(visual);

  if (['strange','mythic','legendary'].includes(rarityId)) {
    const outerGlow = document.createElement('i');
    outerGlow.className = 'booster-rarity-outer-glow';
    outerGlow.setAttribute('aria-hidden', 'true');
    wrap.appendChild(outerGlow);
  }
  if (rarityId === 'legendary') {
    const outerBorder = document.createElement('i');
    outerBorder.className = 'booster-rarity-legendary-border';
    outerBorder.setAttribute('aria-hidden', 'true');
    wrap.appendChild(outerBorder);
    const outerParticles = document.createElement('i');
    outerParticles.className = 'booster-rarity-legendary-particles';
    outerParticles.setAttribute('aria-hidden', 'true');
    wrap.appendChild(outerParticles);
  }
  if (card.boosterDebugSample) wrap.classList.add('booster-debug-sample-card');
  const copy = document.createElement('div');
  copy.className = 'booster-reveal-card-copy';
  copy.innerHTML = `<strong>${escapeHtml(card.name || cardId)}</strong><span>${escapeHtml(rarity?.label || CARD_RARITY_LABELS?.[rarityId] || rarityId)}</span>`;
  wrap.appendChild(copy);
  return wrap;
}

function getBoosterRevealTier(cardIds = []) {
  const highest = Math.max(1, ...(cardIds || []).map(getBoosterRarityRank));
  if (highest >= 9) return 'legendary';
  if (highest >= 7) return 'high';
  if (highest >= 4) return 'mid';
  return 'basic';
}

function getBoosterPurchaseCost(mode = boosterStoreState.purchaseMode, bundleCount = boosterStoreState.bundleCount) {
  if (mode === 'single') return ROK_BOOSTER_SINGLE_COST;
  if (mode === 'bundle5') return Math.max(1, Math.floor(Number(bundleCount) || 1)) * ROK_BOOSTER_BUNDLE5_COST;
  return 0;
}

function purchaseRokUserBoosters(collectionId, mode, bundleCount = 1) {
  if (!ROK_BOOSTER_COLLECTIONS[collectionId]) return { ok: false, reason: 'Colección no disponible.', amount: 0, cost: 0 };
  const normalizedMode = mode === 'bundle5' ? 'bundle5' : 'single';
  const bundles = Math.max(1, Math.floor(Number(bundleCount) || 1));
  const amount = normalizedMode === 'bundle5' ? bundles * 5 : 1;
  const cost = normalizedMode === 'bundle5' ? bundles * ROK_BOOSTER_BUNDLE5_COST : ROK_BOOSTER_SINGLE_COST;
  const balance = getRokUserPureCrystal();
  if (balance < cost) return { ok: false, reason: `Cristal Puro insuficiente: necesitas ${formatRokPureCrystalAmount(cost)} y tienes ${formatRokPureCrystalAmount(balance)}.`, amount, cost };
  rokUserProfile.pureCrystal = balance - cost;
  rokUserProfile.boosters = normalizeRokUserBoosters(rokUserProfile.boosters);
  rokUserProfile.boosters[collectionId] = getRokUserBoosterCount(collectionId) + amount;
  persistRokUserProfile();
  updateRokPureCrystalUi();
  return { ok: true, amount, cost, balance: getRokUserPureCrystal(), boosterCount: getRokUserBoosterCount(collectionId) };
}

function buildBoosterFoilPackMarkup(collection, className = '') {
  const maskUrl = `url('${collection.packImage}')`;
  return `<span class="booster-pack-visual ${className}" style="--booster-pack-mask:${maskUrl}"><img src="${collection.packImage}" alt="Booster pack ${collection.name}"><i class="booster-pack-foil" aria-hidden="true"></i><i class="booster-pack-foil-soft" aria-hidden="true"></i></span>`;
}

function buildBoosterFanMarkup(collection) {
  const rotations = [-18, -9, 0, 9, 18];
  return `<span class="booster-pack-fan" aria-hidden="true">${rotations.map((angle, index) => `<span class="booster-pack-fan-card" style="--fan-index:${index};--fan-angle:${angle}deg;--fan-x:${(index - 2) * 15}px">${buildBoosterFoilPackMarkup(collection, 'booster-pack-visual-small')}</span>`).join('')}</span>`;
}

function buildBoosterBoxParticlesMarkup(count = 28) {
  return Array.from({ length: count }, (_, index) => {
    const angle = (index / Math.max(1, count)) * Math.PI * 2;
    const radius = 36 + ((index * 17) % 48);
    const x = 50 + Math.cos(angle) * radius;
    const y = 52 + Math.sin(angle) * (radius * .52);
    const delay = (index % 9) * .13;
    const duration = 1.8 + ((index % 7) * .18);
    return `<i class="booster-box-particle" style="--particle-left:${x.toFixed(2)}%;--particle-top:${y.toFixed(2)}%;--particle-delay:${delay.toFixed(2)}s;--particle-duration:${duration.toFixed(2)}s"></i>`;
  }).join('');
}

function updateBoosterStoreHeader(collection = null) {
  updateRokPureCrystalUi();
  if (els.boosterStoreScreen) els.boosterStoreScreen.dataset.storeStep = boosterStoreState.step;
  if (els.boosterStoreInventory) {
    const total = getTotalRokUserBoosters();
    els.boosterStoreInventory.textContent = collection
      ? `${collection.name}: ${getRokUserBoosterCount(collection.id)} pack${getRokUserBoosterCount(collection.id) === 1 ? '' : 's'} sin abrir`
      : `Packs sin abrir: ${total}`;
  }
  if (els.boosterStoreTitle) {
    const titles = {
      collections: 'Adquirir booster packs',
      acquired: 'Booster packs adquiridos',
      opening: 'Apertura de booster',
      reveal: 'Cartas obtenidas',
      results: 'Apertura completada',
    };
    els.boosterStoreTitle.textContent = titles[boosterStoreState.step] || collection?.label || 'Booster box';
  }
  if (els.boosterStoreSubtitle) {
    const subtitles = {
      collections: 'Selecciona una booster box para entrar a su colección.',
      acquired: 'Tus packs están listos. Puedes abrirlos ahora o guardarlos para después.',
      opening: 'El sobre se abrirá y las cinco cartas saldrán desde su interior.',
      reveal: 'Revisa las cinco cartas. Después abre el siguiente booster o todos los restantes.',
      results: 'Todas las cartas abiertas en esta sesión ya forman parte de tu colección.',
    };
    els.boosterStoreSubtitle.textContent = subtitles[boosterStoreState.step] || 'Selecciona si quieres adquirir un pack o grupos de cinco.';
  }
}

function renderBoosterStoreCollections() {
  const collections = Object.values(ROK_BOOSTER_COLLECTIONS);
  els.boosterStoreContent?.classList.add('collections-compact');
  updateBoosterStoreHeader(null);
  els.boosterStoreContent.innerHTML = `
    <section class="booster-store-collection-view">
      <div class="booster-store-section-title"><span>COLECCIONES DISPONIBLES</span><strong>Selecciona una booster box</strong></div>
      <div class="booster-store-collection-grid">
        ${collections.map(collection => `
          <button class="booster-store-box-choice" type="button" data-booster-action="select-collection" data-collection-id="${collection.id}">
            <span class="booster-store-box-choice-glow" aria-hidden="true"></span>
            <img src="${collection.boxImage}" alt="${collection.label}">
            <span class="booster-store-box-choice-copy"><strong>${collection.label}</strong><small>${collection.description}</small><em>${getRokUserBoosterCount(collection.id)} sin abrir</em></span>
          </button>`).join('')}
      </div>
    </section>`;
  if (els.boosterStoreNotice) els.boosterStoreNotice.textContent = 'Elige una caja. Al seleccionarla, las demás desaparecerán y entrarás a esa colección.';
}

function renderBoosterStoreFocus(collection) {
  els.boosterStoreContent?.classList.remove('collections-compact');
  updateBoosterStoreHeader(collection);
  const singleSelected = boosterStoreState.purchaseMode === 'single';
  const bundleSelected = boosterStoreState.purchaseMode === 'bundle5';
  const bundles = Math.max(1, Math.min(20, Number(boosterStoreState.bundleCount) || 1));
  const total = bundleSelected ? bundles * 5 : 1;
  const purchaseCost = getBoosterPurchaseCost(boosterStoreState.purchaseMode, bundles);
  const balance = getRokUserPureCrystal();
  const canAfford = Boolean(boosterStoreState.purchaseMode) && balance >= purchaseCost;
  els.boosterStoreContent.innerHTML = `
    <section class="booster-store-focus-view">
      <div class="booster-store-selected-box-stage">
        <div class="booster-store-selected-box-aura" aria-hidden="true"></div>
        <div class="booster-store-selected-box-particles" aria-hidden="true">${buildBoosterBoxParticlesMarkup()}</div>
        <img class="booster-store-selected-box-img" src="${collection.boxImage}" alt="${collection.label}">
        <div class="booster-store-selected-box-caption"><img src="${collection.originIcon}" alt=""><span><strong>${collection.label}</strong><small>Origen exclusivo · Japón</small></span></div>
      </div>
      <div class="booster-store-purchase-panel">
        <div class="booster-store-section-title"><span>ELIGE CANTIDAD</span><strong>¿Qué quieres adquirir?</strong></div>
        <div class="booster-store-purchase-options">
          <button class="booster-purchase-option${singleSelected ? ' selected' : ''}" type="button" data-booster-action="purchase-mode" data-mode="single">
            <span class="booster-purchase-art booster-purchase-art-single">${buildBoosterFoilPackMarkup(collection)}</span>
            <strong>1 booster pack</strong><small>Un sobre de 5 cartas</small>
            <span class="booster-purchase-price"><img src="${ROK_PURE_CRYSTAL_ASSET}" alt=""><b>${formatRokPureCrystalAmount(ROK_BOOSTER_SINGLE_COST)}</b><em>Cristal Puro</em></span>
          </button>
          <button class="booster-purchase-option${bundleSelected ? ' selected' : ''}" type="button" data-booster-action="purchase-mode" data-mode="bundle5">
            <span class="booster-purchase-art booster-purchase-art-fan">${buildBoosterFanMarkup(collection)}</span>
            <strong>5 booster packs</strong><small>Adquiere grupos de cinco</small>
            <span class="booster-purchase-price"><img src="${ROK_PURE_CRYSTAL_ASSET}" alt=""><b>${formatRokPureCrystalAmount(ROK_BOOSTER_BUNDLE5_COST)}</b><em>Cristal Puro</em></span>
          </button>
        </div>
        ${bundleSelected ? `
          <div class="booster-bundle-counter-wrap">
            <span>¿Cuántos packs de 5 quieres?</span>
            <div class="booster-bundle-counter">
              <button type="button" data-booster-action="bundle-minus" aria-label="Restar un grupo de cinco">−</button>
              <strong>${bundles}</strong>
              <button type="button" data-booster-action="bundle-plus" aria-label="Agregar un grupo de cinco">+</button>
            </div>
            <em>Total: ${bundles * 5} booster packs · ${formatRokPureCrystalAmount(bundles * ROK_BOOSTER_BUNDLE5_COST)} Cristal Puro</em>
          </div>` : ''}
        <div class="booster-store-balance-line"><span>Disponible</span><span><img src="${ROK_PURE_CRYSTAL_ASSET}" alt=""><strong>${formatRokPureCrystalAmount(balance)}</strong> Cristal Puro</span></div>
        ${getRokUserBoosterCount(collection.id) > 0 ? `<button class="booster-store-open-owned-btn" type="button" data-booster-action="open-owned">Abrir ${getRokUserBoosterCount(collection.id)} booster${getRokUserBoosterCount(collection.id) === 1 ? '' : 's'} sin abrir</button>` : ''}
        <button class="booster-store-acquire-btn${boosterStoreState.purchaseMode && !canAfford ? ' insufficient' : ''}" type="button" data-booster-action="acquire" ${canAfford ? '' : 'disabled'}>
          ${boosterStoreState.purchaseMode ? (canAfford ? `Adquirir ${total} booster pack${total === 1 ? '' : 's'} · ${formatRokPureCrystalAmount(purchaseCost)} Cristal Puro` : `Cristal Puro insuficiente · necesitas ${formatRokPureCrystalAmount(purchaseCost)}`) : 'Selecciona una opción'}
        </button>
      </div>
    </section>`;
  if (els.boosterStoreNotice) els.boosterStoreNotice.textContent = boosterStoreState.purchaseMode
    ? (canAfford
      ? `Selección actual: ${total} booster pack${total === 1 ? '' : 's'} de ${collection.label} por ${formatRokPureCrystalAmount(purchaseCost)} Cristal Puro.`
      : `No tienes suficiente Cristal Puro. Saldo actual: ${formatRokPureCrystalAmount(balance)}.`)
    : 'Selecciona 1 booster pack o un grupo de 5 para continuar.';
}

function renderBoosterStoreAcquired(collection) {
  updateBoosterStoreHeader(collection);
  const amount = Math.max(1, Number(boosterStoreState.lastAcquiredAmount) || 1);
  const packs = Array.from({ length: amount }, (_, index) => `<span class="booster-acquired-pack" style="--acquired-delay:${Math.min(index, 14) * 45}ms">${buildBoosterFoilPackMarkup(collection, 'booster-pack-visual-acquired')}</span>`).join('');
  els.boosterStoreContent.innerHTML = `
    <section class="booster-store-acquired-view">
      <div class="booster-store-acquired-copy"><span>ADQUISICIÓN COMPLETADA</span><strong>Adquiriste ${amount} booster pack${amount === 1 ? '' : 's'}</strong><small>Se guardaron en tu perfil de Modo Usuario.</small></div>
      <div class="booster-acquired-row">${packs}</div>
      <div class="booster-store-acquired-actions">
        <button class="booster-store-secondary-btn" type="button" data-booster-action="acquire-more">Adquirir más</button>
        <button class="booster-store-primary-btn booster-store-open-now-btn" type="button" data-booster-action="open-acquired">Abrir boosters</button>
      </div>
    </section>`;
  if (els.boosterStoreNotice) els.boosterStoreNotice.textContent = `${getRokUserBoosterCount(collection.id)} booster pack${getRokUserBoosterCount(collection.id) === 1 ? '' : 's'} de ${collection.name} sin abrir en tu perfil.`;
}


function renderBoosterCardList(container, cardIds, options = {}) {
  if (!container) return;
  container.innerHTML = '';
  (cardIds || []).forEach((cardId, index) => {
    const node = createBoosterRevealCardNode(cardId, { compact: options.compact === true });
    node.style.setProperty('--booster-card-index', String(index));
    container.appendChild(node);
  });
}

function beginBoosterOpeningSession(collection, amount) {
  const available = getRokUserBoosterCount(collection.id);
  const total = Math.max(0, Math.min(available, Math.floor(Number(amount) || 0)));
  if (!total) {
    boosterStoreState.step = 'focus';
    renderBoosterStore();
    if (els.boosterStoreNotice) els.boosterStoreNotice.textContent = 'No tienes boosters sin abrir en esta colección.';
    return;
  }
  boosterStoreState.openingTotal = total;
  boosterStoreState.openingRemaining = total;
  boosterStoreState.currentPackCards = [];
  boosterStoreState.openedCardsSession = [];
  boosterStoreState.openedPacksSession = 0;
  beginNextBoosterOpening(collection);
}

function renderBoosterOpeningStage(collection, cardIds) {
  els.boosterStoreContent?.classList.remove('collections-compact');
  updateBoosterStoreHeader(collection);
  const tier = getBoosterRevealTier(cardIds);
  els.boosterStoreContent.innerHTML = `
    <section class="booster-opening-view booster-reveal-tier-${tier}">
      <div class="booster-opening-effects" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i></div>
      <div class="booster-opening-counter">Booster ${boosterStoreState.openedPacksSession} de ${boosterStoreState.openingTotal}</div>
      <div class="booster-opening-stage" data-opening-stage>
        <div class="booster-opening-closed" data-opening-closed>${buildBoosterFoilPackMarkup(collection, 'booster-pack-visual-opening')}</div>
        <div class="booster-opening-open" data-opening-open aria-hidden="true">
          <img class="booster-opening-back" src="${collection.openBackImage}" alt="">
          <div class="booster-opening-card-stack" data-opening-card-stack></div>
          <img class="booster-opening-front" src="${collection.openFrontImage}" alt="">
        </div>
      </div>
      <div class="booster-opening-status" data-opening-status>Preparando apertura…</div>
    </section>`;
}

async function playBoosterOpeningAnimation(collection, cardIds, animationToken) {
  const content = els.boosterStoreContent;
  const closed = content?.querySelector('[data-opening-closed]');
  const opened = content?.querySelector('[data-opening-open]');
  const stack = content?.querySelector('[data-opening-card-stack]');
  const status = content?.querySelector('[data-opening-status]');
  if (!closed || !opened || !stack) return;

  await sleep(460);
  if (animationToken !== boosterStoreState.animationToken) return;
  closed.classList.add('is-tearing');
  if (status) status.textContent = 'Abriendo booster…';

  await sleep(360);
  if (animationToken !== boosterStoreState.animationToken) return;
  closed.classList.add('is-hidden');
  opened.setAttribute('aria-hidden', 'false');
  opened.classList.add('is-visible');

  renderBoosterCardList(stack, cardIds, { compact: true });
  const extractionCards = [...stack.querySelectorAll('.booster-reveal-card')];
  extractionCards.forEach((node, index) => {
    node.classList.add('inside-pack', 'booster-extraction-card');
    node.style.setProperty('--opening-card-index', String(index));
    node.style.setProperty('--booster-extract-delay', `${index * 150}ms`);
  });

  await sleep(220);
  if (animationToken !== boosterStoreState.animationToken) return;
  opened.classList.add('cards-extracting');
  if (status) status.textContent = 'Extrayendo cartas…';

  // Cinco cartas: salen desde el centro del sobre, una tras otra, y abandonan
  // completamente la parte superior de la escena antes de retirar el pack.
  const extractionMs = ((Math.max(0, extractionCards.length - 1)) * 150) + 700;
  await sleep(extractionMs);
  if (animationToken !== boosterStoreState.animationToken) return;

  opened.classList.add('is-clearing');
  if (status) status.textContent = 'Ordenando cartas…';
  await sleep(360);
  if (animationToken !== boosterStoreState.animationToken) return;

  boosterStoreState.step = 'reveal';
  renderBoosterStore();
}

function beginNextBoosterOpening(collection) {
  if (!collection || boosterStoreState.openingRemaining <= 0 || getRokUserBoosterCount(collection.id) <= 0) {
    boosterStoreState.step = 'results';
    renderBoosterStore();
    return;
  }
  const cardIds = generateRokBoosterPack(collection);
  consumeRokUserBoosters(collection.id, 1);
  grantRokUserCollectionCards(cardIds);
  boosterStoreState.currentPackCards = cardIds;
  boosterStoreState.openedCardsSession.push(...cardIds);
  boosterStoreState.openingRemaining -= 1;
  boosterStoreState.openedPacksSession += 1;
  boosterStoreState.step = 'opening';
  const token = ++boosterStoreState.animationToken;
  renderBoosterOpeningStage(collection, cardIds);
  playBoosterOpeningAnimation(collection, cardIds, token);
}

function renderBoosterStoreReveal(collection) {
  els.boosterStoreContent?.classList.remove('collections-compact');
  updateBoosterStoreHeader(collection);
  const cards = boosterStoreState.currentPackCards || [];
  const tier = getBoosterRevealTier(cards);
  els.boosterStoreContent.innerHTML = `
    <section class="booster-reveal-view booster-reveal-tier-${tier}">
      <div class="booster-reveal-burst" aria-hidden="true"><i></i><i></i><i></i><i></i></div>
      <div class="booster-reveal-heading"><span>BOOSTER ABIERTO</span><strong>Estas son tus 5 cartas</strong><small>${boosterStoreState.openingRemaining > 0 ? `${boosterStoreState.openingRemaining} booster${boosterStoreState.openingRemaining === 1 ? '' : 's'} pendiente${boosterStoreState.openingRemaining === 1 ? '' : 's'}` : 'Último booster de la sesión'}</small></div>
      <div class="booster-reveal-row" data-booster-reveal-row></div>
      <div class="booster-reveal-actions">
        ${boosterStoreState.openingRemaining > 0 ? `<button class="booster-store-primary-btn" type="button" data-booster-action="open-next">Abrir el siguiente</button><button class="booster-store-secondary-btn" type="button" data-booster-action="open-all">Abrir todos</button>` : `<button class="booster-store-primary-btn" type="button" data-booster-action="show-results">Ver todas las cartas</button>`}
      </div>
    </section>`;
  renderBoosterCardList(els.boosterStoreContent.querySelector('[data-booster-reveal-row]'), cards);
}

function openAllRemainingBoosters(collection) {
  const count = Math.max(0, Math.min(boosterStoreState.openingRemaining, getRokUserBoosterCount(collection.id)));
  for (let index = 0; index < count; index += 1) {
    const cards = generateRokBoosterPack(collection);
    consumeRokUserBoosters(collection.id, 1);
    grantRokUserCollectionCards(cards);
    boosterStoreState.openedCardsSession.push(...cards);
    boosterStoreState.openedPacksSession += 1;
  }
  boosterStoreState.openingRemaining = 0;
  boosterStoreState.currentPackCards = [];
  boosterStoreState.step = 'results';
  boosterStoreState.animationToken += 1;
  renderBoosterStore();
}

function renderBoosterStoreResults(collection) {
  els.boosterStoreContent?.classList.remove('collections-compact');
  updateBoosterStoreHeader(collection);
  const cards = boosterStoreState.openedCardsSession || [];
  const tier = getBoosterRevealTier(cards);
  els.boosterStoreContent.innerHTML = `
    <section class="booster-results-view booster-reveal-tier-${tier}">
      <div class="booster-results-heading"><span>APERTURA COMPLETADA</span><strong>${boosterStoreState.openedPacksSession} booster${boosterStoreState.openedPacksSession === 1 ? '' : 's'} · ${cards.length} cartas</strong><small>Todas las copias ya fueron agregadas a tu colección.</small></div>
      <div class="booster-results-row" data-booster-results-row></div>
      <div class="booster-results-actions"><button class="booster-store-secondary-btn" type="button" data-booster-action="focus-store">Volver a la caja</button><button class="booster-store-primary-btn" type="button" data-booster-action="close-store">Listo</button></div>
    </section>`;
  const resultsRow = els.boosterStoreContent.querySelector('[data-booster-results-row]');
  if (resultsRow) {
    resultsRow.style.setProperty('--booster-results-columns', String(Math.max(1, Math.min(10, cards.length))));
  }
  // En la vista de resultados todas las cartas usan una única escala visual.
  // El grid es quien decide cuántas caben por fila (máximo 10).
  renderBoosterCardList(resultsRow, cards, { compact: true });
}

function renderBoosterStore() {
  if (!els.boosterStoreContent) return;
  const collection = boosterStoreState.collectionId ? ROK_BOOSTER_COLLECTIONS[boosterStoreState.collectionId] : null;
  if (boosterStoreState.step === 'collections' || !collection) {
    boosterStoreState.step = 'collections';
    boosterStoreState.collectionId = null;
    renderBoosterStoreCollections();
    return;
  }
  if (boosterStoreState.step === 'acquired') return renderBoosterStoreAcquired(collection);
  if (boosterStoreState.step === 'reveal') return renderBoosterStoreReveal(collection);
  if (boosterStoreState.step === 'results') return renderBoosterStoreResults(collection);
  if (boosterStoreState.step === 'opening') return renderBoosterOpeningStage(collection, boosterStoreState.currentPackCards || []);
  renderBoosterStoreFocus(collection);
}

function openBoosterStoreScreen(context = 'main') {
  boosterStoreState.returnContext = String(context || 'main');
  boosterStoreState.step = 'collections';
  boosterStoreState.collectionId = null;
  boosterStoreState.purchaseMode = '';
  boosterStoreState.bundleCount = 1;
  boosterStoreState.lastAcquiredAmount = 0;
  boosterStoreState.openingRemaining = 0;
  boosterStoreState.openingTotal = 0;
  boosterStoreState.currentPackCards = [];
  boosterStoreState.openedCardsSession = [];
  boosterStoreState.openedPacksSession = 0;
  boosterStoreState.animationToken += 1;
  els.boosterStoreScreen?.setAttribute('aria-hidden', 'false');
  document.body.classList.add('rok-booster-store-mode');
  renderBoosterStore();
}

function closeBoosterStoreScreen() {
  boosterStoreState.animationToken += 1;
  els.boosterStoreScreen?.setAttribute('aria-hidden', 'true');
  document.body.classList.remove('rok-booster-store-mode');
  boosterStoreState.step = 'collections';
  boosterStoreState.collectionId = null;
  boosterStoreState.purchaseMode = '';
  boosterStoreState.bundleCount = 1;
}

function goBackInBoosterStore() {
  if (['opening', 'reveal', 'results'].includes(boosterStoreState.step)) {
    boosterStoreState.animationToken += 1;
    boosterStoreState.step = 'focus';
    boosterStoreState.currentPackCards = [];
    boosterStoreState.openingRemaining = 0;
    renderBoosterStore();
    return;
  }
  if (boosterStoreState.step === 'acquired') {
    boosterStoreState.step = 'focus';
    boosterStoreState.purchaseMode = '';
    renderBoosterStore();
    return;
  }
  if (boosterStoreState.step === 'focus') {
    boosterStoreState.step = 'collections';
    boosterStoreState.collectionId = null;
    boosterStoreState.purchaseMode = '';
    renderBoosterStore();
    return;
  }
  closeBoosterStoreScreen();
}

function handleBoosterStoreContentClick(event) {
  const actionNode = event.target.closest('[data-booster-action]');
  if (!actionNode) return;
  event.preventDefault();
  const action = actionNode.dataset.boosterAction;
  if (action === 'select-collection') {
    const collectionId = actionNode.dataset.collectionId;
    if (!ROK_BOOSTER_COLLECTIONS[collectionId]) return;
    boosterStoreState.collectionId = collectionId;
    boosterStoreState.step = 'focus';
    boosterStoreState.purchaseMode = '';
    boosterStoreState.bundleCount = 1;
    renderBoosterStore();
    return;
  }
  const collection = ROK_BOOSTER_COLLECTIONS[boosterStoreState.collectionId];
  if (!collection) return;
  if (action === 'open-acquired') {
    beginBoosterOpeningSession(collection, Math.max(1, Number(boosterStoreState.lastAcquiredAmount) || 1));
    return;
  }
  if (action === 'open-owned') {
    beginBoosterOpeningSession(collection, getRokUserBoosterCount(collection.id));
    return;
  }
  if (action === 'open-next') {
    beginNextBoosterOpening(collection);
    return;
  }
  if (action === 'open-all') {
    openAllRemainingBoosters(collection);
    return;
  }
  if (action === 'show-results') {
    boosterStoreState.step = 'results';
    renderBoosterStore();
    return;
  }
  if (action === 'focus-store') {
    boosterStoreState.step = 'focus';
    boosterStoreState.purchaseMode = '';
    boosterStoreState.openingRemaining = 0;
    renderBoosterStore();
    return;
  }
  if (action === 'purchase-mode') {
    boosterStoreState.purchaseMode = actionNode.dataset.mode === 'bundle5' ? 'bundle5' : 'single';
    if (boosterStoreState.purchaseMode !== 'bundle5') boosterStoreState.bundleCount = 1;
    renderBoosterStore();
    return;
  }
  if (action === 'bundle-minus') {
    boosterStoreState.bundleCount = Math.max(1, (Number(boosterStoreState.bundleCount) || 1) - 1);
    renderBoosterStore();
    return;
  }
  if (action === 'bundle-plus') {
    boosterStoreState.bundleCount = Math.min(20, (Number(boosterStoreState.bundleCount) || 1) + 1);
    renderBoosterStore();
    return;
  }
  if (action === 'acquire') {
    if (!boosterStoreState.purchaseMode) return;
    if (!isRokUserModeActive()) setRokUserModeActive(true, { render: false });
    const purchase = purchaseRokUserBoosters(collection.id, boosterStoreState.purchaseMode, boosterStoreState.bundleCount);
    if (!purchase.ok) {
      if (els.boosterStoreNotice) els.boosterStoreNotice.textContent = purchase.reason || 'No se pudo completar la compra.';
      renderBoosterStore();
      return;
    }
    boosterStoreState.lastAcquiredAmount = purchase.amount;
    boosterStoreState.step = 'acquired';
    renderBoosterStore();
    return;
  }
  if (action === 'acquire-more') {
    boosterStoreState.step = 'focus';
    boosterStoreState.purchaseMode = '';
    boosterStoreState.bundleCount = 1;
    renderBoosterStore();
    return;
  }
  if (action === 'close-store') closeBoosterStoreScreen();
}

function getRokUserSpellbookCollectionIssue(spellbook) {
  if (spellbook?.builtIn === true) return '';
  if (!isRokUserModeActive()) return '';
  const counts = new Map();
  (spellbook?.cards || []).filter(Boolean).forEach(cardId => counts.set(cardId, (counts.get(cardId) || 0) + 1));
  for (const [cardId, required] of counts.entries()) {
    const card = CARD_LIBRARY[cardId];
    if (!card || getCardTypeId(card) === 'kaster') continue;
    const owned = getRokUserOwnedCopies(card);
    if (required > owned) return `Modo Usuario: necesitas ${required} copia${required === 1 ? '' : 's'} de ${card.name || cardId}, pero posees ${owned}.`;
  }
  return '';
}

