function getQualityProfileByIdOrLabel(value = '') {
  const key = String(value || '').trim();
  if (!key) return null;
  const direct = getQualityProfile(key);
  if (direct) return direct;
  const normalized = key.toLocaleLowerCase('es');
  return Object.values(QUALITY_DB).find(profile => String(profile?.label || '').trim().toLocaleLowerCase('es') === normalized) || null;
}

function getAdventureQualityMeta(name = '') {
  const label = String(name || '').trim();
  if (ADVENTURE_QUALITY_META[label]) return ADVENTURE_QUALITY_META[label];
  const profile = getQualityProfileByIdOrLabel(label);
  if (profile) return { icon: profile.icon || '', tint: '#8fb7c4', qualityId: profile.id };
  return { icon: '', tint: '#8fb7c4' };
}

function renderAdventureQualityIcon(name = '') {
  const meta = getAdventureQualityMeta(name);
  const fallback = String(name || '?').trim().charAt(0).toUpperCase() || '?';
  return `<span class="adventure-quality-icon" style="--quality-tint:${meta.tint}">${meta.icon ? `<img src="${meta.icon}" alt="">` : `<span>${fallback}</span>`}</span>`;
}

function renderAdventureQualityTag(name = '') {
  return `<button type="button" class="adventure-quality-tag" data-adventure-quality="${name}">${renderAdventureQualityIcon(name)}<span>${name}</span></button>`;
}

function renderAdventureRolePill(role = {}) {
  return `<button type="button" class="adventure-role-pill" data-adventure-quality="${role.name || ''}"><div class="adventure-role-pill-head">${renderAdventureQualityIcon(role.name)}<b>${role.name || 'Rol'}</b></div><span>${role.text || ''}</span></button>`;
}

const ADVENTURE_DOMAIN_ID_BY_LABEL = {
  Agua: 'agua',
  Tierra: 'tierra',
  Viento: 'viento',
  Luz: 'luz',
  Oscuridad: 'oscuridad',
  Fuego: 'fuego',
  Muerte: 'muerte',
  Sonido: 'sonido',
  Rayo: 'rayo'
};

function getAdventureDomainProfile(entry = {}) {
  const id = ADVENTURE_DOMAIN_ID_BY_LABEL[String(entry.element || '').trim()] || '';
  if (id && DOMAIN_ART_DB[id]) return DOMAIN_ART_DB[id];
  if (id === 'rayo') {
    return {
      elementLabel: 'Rayo',
      attributeLabel: 'Energía',
      elementArt: 'assets/domain/domain-element-lightning-adventure.png',
      attributeArt: 'assets/domain/domain-attribute-energy-adventure.png'
    };
  }
  return DOMAIN_ART_DB.agua;
}

function renderAdventureDomainEmblem(entry = {}, primary = false) {
  const profile = getAdventureDomainProfile(entry);
  const sizeClass = primary ? 'primary' : 'secondary';
  return `<button type="button" class="adventure-domain-emblem ${sizeClass}" data-adventure-domain="${ADVENTURE_DOMAIN_ID_BY_LABEL[String(entry.element || '').trim()] || ''}" title="Dominio: ${profile.elementLabel} · Atributo: ${profile.attributeLabel}" aria-label="Abrir dominio ${profile.elementLabel}, ${profile.attributeLabel}">
    <span class="adventure-domain-layer adventure-domain-bg" aria-hidden="true"></span>
    <img class="adventure-domain-layer adventure-domain-element" src="${profile.elementArt}" alt="Elemento ${profile.elementLabel}">
    <img class="adventure-domain-layer adventure-domain-attribute" src="${profile.attributeArt}" alt="Atributo ${profile.attributeLabel}">
  </button>`;
}

function renderAdventureCasterDomainPanel(encounter, ready) {
  if (!els.adventureCasterDomainPanel) return;
  if (!ready || !encounter || !Array.isArray(encounter.domains) || !encounter.domains.length) {
    els.adventureCasterDomainPanel.innerHTML = '';
    return;
  }
  els.adventureCasterDomainPanel.innerHTML = encounter.domains
    .map((entry, index) => renderAdventureDomainEmblem(entry, index === 0))
    .join('');
}

function getAdventurePlayerCaster(id = adventureState.playerCasterId) {
  return ADVENTURE_PLAYER_CASTERS.find(caster => caster.id === id) || ADVENTURE_PLAYER_CASTERS[0];
}

function getAdventureRaceIcon(entity = {}) {
  if (entity.raceId === 'human') {
    return entity.gender === 'female' ? 'assets/races/race-human-female.svg' : 'assets/races/race-human-male.svg';
  }
  return '';
}

function renderAdventureIdentityTag({ label = '', icon = '', quality = '', muted = false } = {}) {
  const attrs = quality ? ` data-adventure-quality="${quality}"` : '';
  const tag = quality ? 'button' : 'span';
  return `<${tag}${quality ? ' type="button"' : ''} class="adventure-identity-tag${muted ? ' muted' : ''}"${attrs}>${icon ? `<img src="${icon}" alt="">` : `<span class="adventure-identity-fallback">?</span>`}<span>${label}</span></${tag}>`;
}

function renderAdventureCasterIdentity(entity = {}) {
  const parts = [
    renderAdventureIdentityTag({ label: 'Kaster', icon: 'assets/card-types/card-type-kaster.svg' }),
    renderAdventureIdentityTag({ label: entity.raceLabel || 'Raza por definir', icon: getAdventureRaceIcon(entity), muted: !getAdventureRaceIcon(entity) }),
  ];
  (entity.casterQualities || []).forEach(name => {
    const meta = getAdventureQualityMeta(name);
    parts.push(renderAdventureIdentityTag({ label: name, icon: meta.icon, quality: name }));
  });
  return parts.join('');
}

function synchronizeAdventureQualityTextWithCanonicalSource() {
  Object.entries(ADVENTURE_QUALITY_META).forEach(([label, meta]) => {
    const existing = getQualityProfileByIdOrLabel(label);
    if (!existing) return;
    // El archivo de cualidades es la fuente canónica de resumen/descripción.
    if (meta.summary) existing.summary = meta.summary;
    if (meta.description) existing.description = meta.description;
  });
}
synchronizeAdventureQualityTextWithCanonicalSource();

function getAdventureQualityModalProfile(name = '') {
  const label = String(name || '').trim();
  if (!label) return null;
  const meta = getAdventureQualityMeta(label);
  const existing = getQualityProfileByIdOrLabel(label);
  if (existing) {
    if (meta.summary) existing.summary = meta.summary;
    if (meta.description) existing.description = meta.description;
    return existing;
  }
  const id = `adventure_${label.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '')}`;
  if (!QUALITY_DB[id]) {
    QUALITY_DB[id] = {
      id,
      label,
      icon: meta.icon || '',
      focus: meta.summary || label,
      classification: { applicationModes: [], applicationTags: [], natures: [], functionalCategories: [] },
      tags: [],
      summary: meta.summary || 'Cualidad de R.O.K.',
      description: meta.description || '',
      adventureSupplemental: true,
    };
  }
  return QUALITY_DB[id];
}

function getAdventurePrimaryDomainId(encounter = getAdventureWaterEncounter(adventureState.encounterId)) {
  const primary = Array.isArray(encounter?.domains) ? encounter.domains[0] : null;
  return ADVENTURE_DOMAIN_ID_BY_LABEL[String(primary?.element || '').trim()] || 'agua';
}

function applyAdventureMetaInfoColor(domainId = getAdventurePrimaryDomainId()) {
  const overlay = els.cardMetaInfoOverlay || document.getElementById('cardMetaInfoOverlay');
  if (!overlay) return;
  const normalized = normalizeDominionId(domainId) || 'agua';
  overlay.classList.add('card-element-meta-theme');
  overlay.dataset.metaTheme = normalized;
  overlay.dataset.elementTheme = normalized;
  overlay.style.setProperty('--meta-theme-color', getDominionPrimaryColor(normalized, 'agua'));
  overlay.style.setProperty('--meta-theme-secondary-color', getDominionSecondaryColor(normalized, 'agua'));
}

function ensureAdventureSharedMetaInfoOverlay() {
  const overlay = els.cardMetaInfoOverlay || document.getElementById('cardMetaInfoOverlay');
  if (!overlay) return null;
  // Aventura oculta .game-shell completa. El modal real de metainformación
  // vive originalmente dentro de ese árbol, así que lo montamos en body para
  // poder reutilizar EXACTAMENTE el mismo modal de las cartas sin duplicarlo.
  if (overlay.parentElement !== document.body) document.body.appendChild(overlay);
  overlay.style.removeProperty('visibility');
  overlay.style.removeProperty('pointer-events');
  return overlay;
}

function openAdventureQualityInfo(name = '') {
  const profile = getAdventureQualityModalProfile(name);
  if (!profile) return;
  if (!ensureAdventureSharedMetaInfoOverlay()) return;
  // Reutiliza el modal real de las cartas, pero su color pertenece al dominio
  // principal del Kaster que está siendo previsualizado en Aventura.
  openCardMetaInfo('quality', profile.id, null);
  applyAdventureMetaInfoColor(getAdventurePrimaryDomainId());
}

function openAdventureDomainInfo(domainId = '') {
  if (!domainId) return;
  if (!ensureAdventureSharedMetaInfoOverlay()) return;
  openCardMetaInfo('domain', domainId, null);
  applyAdventureMetaInfoColor(domainId);
}

function loadAdventureProgress() {
  try {
    const raw = safeLocalStorageGet(ADVENTURE_PROGRESS_STORAGE_KEY);
    const parsed = raw ? JSON.parse(raw) : {};
    const encounterWinCounts = {};
    if (parsed?.encounterWinCounts && typeof parsed.encounterWinCounts === 'object') {
      Object.entries(parsed.encounterWinCounts).forEach(([encounterId, amount]) => {
        const count = Math.max(0, Math.floor(Number(amount) || 0));
        if (count > 0) encounterWinCounts[String(encounterId)] = count;
      });
    }
    const elementBoosterRewards = {};
    if (parsed?.elementBoosterRewards && typeof parsed.elementBoosterRewards === 'object') {
      Object.entries(parsed.elementBoosterRewards).forEach(([elementId, amount]) => {
        const count = Math.max(0, Math.floor(Number(amount) || 0));
        if (count > 0) elementBoosterRewards[String(elementId)] = count;
      });
    }
    const firstVictoryRewards = {};
    if (parsed?.firstVictoryRewards && typeof parsed.firstVictoryRewards === 'object') {
      Object.entries(parsed.firstVictoryRewards).forEach(([encounterId, reward]) => {
        if (!reward || typeof reward !== 'object') return;
        firstVictoryRewards[String(encounterId)] = {
          boosterElementId: String(reward.boosterElementId || ''),
          boosterTier: Math.max(1, Math.floor(Number(reward.boosterTier) || 1)),
          cardId: CARD_LIBRARY[reward.cardId] && getCardTypeId(CARD_LIBRARY[reward.cardId]) !== 'kaster' ? String(reward.cardId) : '',
          cardPending: Boolean(reward.cardPending),
          awardedAt: Math.max(0, Number(reward.awardedAt) || 0),
        };
      });
    }
    return {
      defeatedEncounterIds: Array.isArray(parsed.defeatedEncounterIds) ? parsed.defeatedEncounterIds : [],
      unlockedCardIds: Array.isArray(parsed.unlockedCardIds) ? parsed.unlockedCardIds : [],
      spellbookCardIds: Array.isArray(parsed.spellbookCardIds) ? parsed.spellbookCardIds : [],
      encounterWinCounts,
      elementBoosterRewards,
      firstVictoryRewards,
    };
  } catch (_) {
    return { defeatedEncounterIds: [], unlockedCardIds: [], spellbookCardIds: [], encounterWinCounts: {}, elementBoosterRewards: {}, firstVictoryRewards: {} };
  }
}

function saveAdventureProgress(progress) {
  safeLocalStorageSet(ADVENTURE_PROGRESS_STORAGE_KEY, JSON.stringify(progress || {}));
}

function isAdventureSpellbookEditingUnlocked() {
  return loadAdventureProgress().defeatedEncounterIds.includes('enigma-apprentice');
}

function getAdventureCasterVictoryXp(encounterId, previousWins = 0) {
  const encounter = getAdventureWaterEncounter(encounterId);
  const firstVictory = Math.max(0, Number(previousWins) || 0) <= 0;
  if (encounter?.isBoss) return firstVictory ? 10 : 2;
  return firstVictory ? 5 : 1;
}

function getAdventurePrimaryElementId(entity = null) {
  const domains = Array.isArray(entity?.domains) ? entity.domains : [];
  const label = String(domains[0]?.element || '').trim();
  const mapped = ADVENTURE_DOMAIN_ID_BY_LABEL[label] || label.toLocaleLowerCase('es');
  return ROK_USER_RESOURCE_ELEMENT_IDS.includes(mapped) ? mapped : '';
}

function getAdventurePlayerRewardElementId(options = {}) {
  const explicit = String(options?.playerElementId || '').trim().toLocaleLowerCase('es');
  if (ROK_USER_RESOURCE_ELEMENT_IDS.includes(explicit)) return explicit;
  return getAdventurePrimaryElementId(getAdventurePlayerCaster());
}

function getAdventureEncounterRewardElementId(encounterId = '') {
  return getAdventurePrimaryElementId(getAdventureWaterEncounter(encounterId));
}

function getAdventureEncounterSpellbookRewardPool(encounterId = '') {
  const ids = Array.isArray(adventureState?.encounterSpellbooks?.[encounterId]) ? adventureState.encounterSpellbooks[encounterId] : [];
  return [...new Set(ids.map(String))].filter(cardId => {
    const card = CARD_LIBRARY[cardId];
    return card && getCardTypeId(card) !== 'kaster';
  });
}

function pickAdventureRivalRewardCardId(encounterId = '') {
  const pool = getAdventureEncounterSpellbookRewardPool(encounterId);
  if (!pool.length) return '';
  return pool[Math.floor(Math.random() * pool.length)] || pool[0] || '';
}

function pickAdventureRandomRarityRewards(count = 2) {
  const amount = Math.max(0, Math.floor(Number(count) || 0));
  const rewards = [];
  for (let index = 0; index < amount; index += 1) {
    const rarityId = ROK_USER_RESOURCE_RARITY_IDS[Math.floor(Math.random() * ROK_USER_RESOURCE_RARITY_IDS.length)] || ROK_USER_RESOURCE_RARITY_IDS[0];
    if (rarityId) rewards.push(rarityId);
  }
  return rewards;
}

function getAdventureVictoryRewardPreview(encounterId, previousWins = 0, options = {}) {
  const firstVictory = Math.max(0, Number(previousWins) || 0) <= 0;
  if (firstVictory) {
    return {
      kind: 'firstVictory',
      xp: getAdventureCasterVictoryXp(encounterId, previousWins),
      booster: { elementId: getAdventurePlayerRewardElementId(options), tier: 1, amount: 1, reserved: true },
      rivalCard: { source: 'encounterSpellbook', random: true },
    };
  }
  return {
    kind: 'repeatVictory',
    xp: getAdventureCasterVictoryXp(encounterId, previousWins),
    elementResource: { elementId: getAdventureEncounterRewardElementId(encounterId), amount: 10 },
    rarityResources: { amount: 2, random: true },
  };
}

function resolvePendingAdventureFirstVictoryCardReward(encounterId = '') {
  const progress = loadAdventureProgress();
  const record = progress.firstVictoryRewards?.[encounterId];
  if (!record?.cardPending || record.cardId) return record || null;
  const cardId = pickAdventureRivalRewardCardId(encounterId);
  if (!cardId) return record;
  grantRokUserCollectionCard(cardId, 1, { persist: false, render: false });
  record.cardId = cardId;
  record.cardPending = false;
  progress.firstVictoryRewards[encounterId] = record;
  saveAdventureProgress(progress);
  persistRokUserProfile();
  if (document.body.classList.contains('rok-library-mode')) renderLibraryBuilder();
  return { ...record };
}

function grantAdventureVictoryRewards(encounterId, previousWins = 0, options = {}) {
  const firstVictory = Math.max(0, Number(previousWins) || 0) <= 0;
  if (firstVictory) {
    const progress = loadAdventureProgress();
    const existing = progress.firstVictoryRewards?.[encounterId];
    if (existing?.awardedAt) return { kind: 'firstVictory', duplicateProtected: true, ...existing };
    const boosterElementId = getAdventurePlayerRewardElementId(options);
    if (boosterElementId) {
      progress.elementBoosterRewards = { ...(progress.elementBoosterRewards || {}) };
      progress.elementBoosterRewards[boosterElementId] = Math.max(0, Number(progress.elementBoosterRewards[boosterElementId]) || 0) + 1;
    }
    const cardId = pickAdventureRivalRewardCardId(encounterId);
    if (cardId) grantRokUserCollectionCard(cardId, 1, { persist: false, render: false });
    const rewardRecord = {
      boosterElementId,
      boosterTier: 1,
      cardId,
      cardPending: !cardId,
      awardedAt: Date.now(),
    };
    progress.firstVictoryRewards = { ...(progress.firstVictoryRewards || {}), [encounterId]: rewardRecord };
    saveAdventureProgress(progress);
    persistRokUserProfile();
    if (document.body.classList.contains('rok-library-mode')) renderLibraryBuilder();
    return {
      kind: 'firstVictory',
      booster: boosterElementId ? { elementId: boosterElementId, tier: 1, amount: 1, reserved: true } : null,
      cardId,
      cardPending: !cardId,
    };
  }

  const enemyElementId = getAdventureEncounterRewardElementId(encounterId);
  const rarityIds = pickAdventureRandomRarityRewards(2);
  if (enemyElementId) grantRokUserElementResource(enemyElementId, 10, { persist: false });
  rarityIds.forEach(rarityId => grantRokUserRarityResource(rarityId, 1, { persist: false }));
  persistRokUserProfile();
  return {
    kind: 'repeatVictory',
    elementResource: enemyElementId ? { elementId: enemyElementId, amount: 10 } : null,
    rarityIds,
  };
}

function awardAdventureCasterExperience(casterCardId, encounterId, previousWins = null, options = {}) {
  const casterCard = CARD_LIBRARY[casterCardId];
  if (!casterCard || getCardTypeId(casterCard) !== 'kaster') return null;
  const progress = loadAdventureProgress();
  const winsBefore = previousWins == null
    ? Math.max(0, Number(progress.encounterWinCounts?.[encounterId]) || 0)
    : Math.max(0, Number(previousWins) || 0);
  const xp = getAdventureCasterVictoryXp(encounterId, winsBefore);
  return grantCasterExperience(casterCard, xp, { persist: options.persist !== false, render: options.render !== false });
}

function markAdventureEncounterDefeated(encounterId, rewardCardIds = [], options = {}) {
  const progress = loadAdventureProgress();
  const previousWins = Math.max(0, Number(progress.encounterWinCounts?.[encounterId]) || 0);
  progress.encounterWinCounts = { ...(progress.encounterWinCounts || {}), [encounterId]: previousWins + 1 };
  if (!progress.defeatedEncounterIds.includes(encounterId)) progress.defeatedEncounterIds.push(encounterId);
  rewardCardIds.forEach(cardId => {
    if (CARD_LIBRARY[cardId] && !progress.unlockedCardIds.includes(cardId)) progress.unlockedCardIds.push(cardId);
  });
  saveAdventureProgress(progress);
  const casterCardId = String(options?.playerCasterCardId || '');
  const casterXpResult = casterCardId ? awardAdventureCasterExperience(casterCardId, encounterId, previousWins) : null;
  const adventureRewardResult = grantAdventureVictoryRewards(encounterId, previousWins, options);
  renderAdventurePreparation();
  return { encounterId, previousWins, currentWins: previousWins + 1, casterXpResult, adventureRewardResult };
}

function getAdventureSpellbookCardIds() {
  const progress = loadAdventureProgress();
  if (progress.spellbookCardIds.length) return progress.spellbookCardIds.filter(id => CARD_LIBRARY[id]);
  return adventureState.playerSpellbookCardIds.filter(id => CARD_LIBRARY[id]);
}

function getSpellbookDominantQualityStatsFromCardIds(cardIds = [], fallback = []) {
  const statsByQuality = new Map();
  for (const cardId of Array.isArray(cardIds) ? cardIds : []) {
    const card = CARD_LIBRARY[cardId];
    if (!card || card.type !== 'invocation') continue;
    const battlePoints = Math.max(0, Number(getCardBattlePointsValue(card) || 0));
    const qualityIds = [...new Set(Array.isArray(card.qualities) ? card.qualities.filter(Boolean) : [])];
    qualityIds.forEach(qualityId => {
      const profile = getQualityProfileByIdOrLabel(qualityId);
      const id = profile?.id || String(qualityId);
      const current = statsByQuality.get(id) || {
        id,
        label: profile?.label || String(qualityId),
        count: 0,
        pbSum: 0,
      };
      current.count += 1;
      current.pbSum += battlePoints;
      statsByQuality.set(id, current);
    });
  }
  const ranked = [...statsByQuality.values()].sort((a, b) =>
    Number(b.count || 0) - Number(a.count || 0)
    || Number(b.pbSum || 0) - Number(a.pbSum || 0)
    || String(a.label || '').localeCompare(String(b.label || ''), 'es')
  );
  if (ranked.length) return ranked.slice(0, 3);
  return (Array.isArray(fallback) ? fallback : []).slice(0, 3).map(value => {
    const profile = getQualityProfileByIdOrLabel(value);
    return { id: profile?.id || String(value), label: profile?.label || String(value), count: 0, pbSum: 0, preview: true };
  });
}

function getAdventureDominantQualitiesFromCardIds(cardIds = [], fallback = []) {
  return getSpellbookDominantQualityStatsFromCardIds(cardIds, fallback).map(entry => entry.label);
}

function getAdventureIntroTokenImage(card) {
  return card?.tokenImage || '';
}

function getAdventureRepresentativeInvocationArt(qualityLabel, cardIds = [], fallbackIndex = 0) {
  for (const cardId of cardIds) {
    const card = CARD_LIBRARY[cardId];
    if (!card || card.type !== 'invocation') continue;
    const matches = (card.qualities || []).some(qualityId => {
      const profile = getQualityProfile(qualityId);
      return (profile?.label || qualityId) === qualityLabel;
    });
    if (!matches) continue;
    const tokenImage = getAdventureIntroTokenImage(card);
    if (tokenImage) return tokenImage;
  }
  return ADVENTURE_PREVIEW_INVOCATION_ART[fallbackIndex % ADVENTURE_PREVIEW_INVOCATION_ART.length];
}

function getAdventureDominantEntries(entity, cardIds = []) {
  const fallback = entity?.previewDominants || entity?.qualities || [];
  const ranked = getSpellbookDominantQualityStatsFromCardIds(cardIds, fallback);
  return ranked.slice(0, 3).map((entry, index) => ({
    quality: entry.label,
    qualityId: entry.id,
    count: Number(entry.count || 0),
    pbSum: Number(entry.pbSum || 0),
    image: getAdventureRepresentativeInvocationArt(entry.label, cardIds, index),
    preview: !cardIds.length || entry.preview === true,
  }));
}

function renderAdventureDominantChips(entries = [], compact = false, interactive = false) {
  return entries.map(entry => {
    const className = `adventure-dominant-chip${compact ? ' compact' : ''}${interactive ? ' interactive' : ''}`;
    const content = `${renderAdventureQualityIcon(entry.quality)}<span>${entry.quality}</span>`;
    return interactive
      ? `<button type="button" class="${className}" data-adventure-quality="${entry.quality}" aria-label="Abrir información de la cualidad ${entry.quality}">${content}</button>`
      : `<span class="${className}">${content}</span>`;
  }).join('');
}

function renderAdventureDominantFigures(entries = [], side = 'left') {
  return entries.slice(0, 3).map((entry, index) => {
    const meta = getAdventureQualityMeta(entry.quality);
    const diagnostic = entry.count ? `${entry.quality} · ${entry.count} invocaciones · ${entry.pbSum} PB acumulados` : entry.quality;
    return `<div class="adventure-intro-dominant-emblem adventure-intro-dominant-${side}" style="--intro-index:${index};--quality-tint:${meta.tint || '#8fb7c4'}" title="${diagnostic}" aria-label="${entry.quality}"><span class="adventure-intro-dominant-foil" aria-hidden="true"></span>${renderAdventureQualityIcon(entry.quality)}</div>`;
  }).join('');
}

function getAdventureStrongestInvocationCard(cardIds = []) {
  let best = null;
  let bestScore = -Infinity;
  for (const cardId of Array.isArray(cardIds) ? cardIds : []) {
    const card = CARD_LIBRARY[cardId];
    if (!card || card.type !== 'invocation') continue;
    const score = Number(getCardBattlePointsValue(card) || 0);
    if (!best || score > bestScore) {
      best = card;
      bestScore = score;
    }
  }
  return best;
}

function getAdventureStrongestInvocationPreview(cardIds = [], options = {}) {
  const card = getAdventureStrongestInvocationCard(cardIds);
  const tokenImage = getAdventureIntroTokenImage(card);
  if (tokenImage) {
    return {
      card,
      image: tokenImage,
      name: card.shortName || card.name || 'Invocación'
    };
  }
  if (card) return null;
  const fallbackImages = Array.isArray(options?.fallbackImages)
    ? options.fallbackImages.filter(Boolean)
    : [];
  const image = fallbackImages[0] || ADVENTURE_PREVIEW_INVOCATION_ART[0] || '';
  if (!image) return null;
  return {
    card: null,
    image,
    name: options?.fallbackName || 'Invocación destacada',
    placeholder: true,
  };
}

function normalizeIntroPalette(colors = []) {
  const unique = [];
  (Array.isArray(colors) ? colors : []).forEach(color => {
    const value = String(color || '').trim();
    if (value && !unique.includes(value)) unique.push(value);
  });
  while (unique.length < 3) unique.push(unique[unique.length - 1] || getDominionPrimaryColor('agua'));
  return unique.slice(0, 3);
}

function getEntityDominionIds(entity = {}) {
  const ids = [];
  const pushId = value => {
    const id = normalizeDominionId(value);
    if (id && !ids.includes(id)) ids.push(id);
  };
  if (Array.isArray(entity?.domains)) {
    entity.domains.forEach(entry => pushId(entry?.id || entry?.elementId || entry?.element));
  }
  pushId(entity?.domainId || entity?.elementId || entity?.element);
  if (entity?.domain?.elementId) pushId(entity.domain.elementId);
  return ids;
}

function getAdventureIntroPalette(entity = {}) {
  const ids = getEntityDominionIds(entity);
  if (!ids.length) return normalizeIntroPalette([getDominionPrimaryColor('oscuridad'), getDominionSecondaryColor('oscuridad')]);
  const colors = ids.map(id => getDominionPrimaryColor(id));
  colors.push(getDominionSecondaryColor(ids[0]));
  return normalizeIntroPalette(colors);
}

function applyAdventureIntroPalette(sideEl, colors = []) {
  if (!sideEl) return;
  const palette = Array.isArray(colors) ? colors : [];
  sideEl.style.setProperty('--intro-color-1', palette[0] || getDominionPrimaryColor('agua'));
  sideEl.style.setProperty('--intro-color-2', palette[1] || palette[0] || getDominionSecondaryColor('agua'));
  sideEl.style.setProperty('--intro-color-3', palette[2] || palette[1] || palette[0] || getDominionSecondaryColor('agua'));
}

function syncVersusLetterColors(introRoot, rivalSideEl, playerSideEl) {
  if (!introRoot || typeof window === 'undefined' || typeof window.getComputedStyle !== 'function') return;
  const readPrimary = (sideEl, fallback) => {
    if (!sideEl) return fallback;
    return window.getComputedStyle(sideEl).getPropertyValue('--intro-color-1').trim() || fallback;
  };
  introRoot.style.setProperty('--vs-rival-color', readPrimary(rivalSideEl, getDominionPrimaryColor('agua')));
  introRoot.style.setProperty('--vs-player-color', readPrimary(playerSideEl, getDominionPrimaryColor('tierra')));
}

function getAdventureArenaConfig(encounter) {
  const custom = encounter?.arena && typeof encounter.arena === 'object' ? encounter.arena : {};
  const registryId = String(encounter?.arenaId || custom.id || '').trim();
  const registered = ROK_ARENA_REGISTRY[registryId] || null;
  const fallbackLabel = `Arena de ${encounter?.label || 'Agua'}`;
  return {
    id: registered?.id || registryId || '',
    label: custom.label || registered?.label || fallbackLabel,
    previewImage: custom.previewImage || registered?.previewImage || 'assets/adventure/water-region-map.webp',
    battleImage: custom.battleImage || registered?.battleImage || 'assets/arena.webp',
    previewFocusX: Number.isFinite(Number(custom.previewFocusX)) ? Number(custom.previewFocusX) : 50,
    previewFocusY: Number.isFinite(Number(custom.previewFocusY)) ? Number(custom.previewFocusY) : 50,
    battleFocusX: Number.isFinite(Number(custom.battleFocusX)) ? Number(custom.battleFocusX) : 50,
    battleFocusY: Number.isFinite(Number(custom.battleFocusY)) ? Number(custom.battleFocusY) : 50,
    custom: Boolean(registered || custom.previewImage || custom.battleImage),
  };
}

function getAdventureArenaPreview(encounter) {
  const arena = getAdventureArenaConfig(encounter);
  return {
    id: arena.id,
    label: arena.label,
    image: arena.previewImage,
    focusX: arena.previewFocusX,
    focusY: arena.previewFocusY,
    preview: true,
    custom: arena.custom,
  };
}

function getAdventureBattleArena(encounter) {
  const arena = getAdventureArenaConfig(encounter);
  return {
    id: arena.id,
    label: arena.label,
    image: arena.battleImage,
    focusX: arena.battleFocusX,
    focusY: arena.battleFocusY,
    preview: false,
    custom: arena.custom,
  };
}

function renderAdventurePreparation() {
  if (!els.adventurePrepareView) return;
  const encounter = getAdventureWaterEncounter(adventureState.encounterId);
  const playerCaster = getAdventurePlayerCaster();
  const playerCardIds = getAdventureSpellbookCardIds();
  const arena = getAdventureArenaPreview(encounter);

  const rivalPrepPalette = getAdventureIntroPalette(encounter);
  const playerPrepPalette = getAdventureIntroPalette(playerCaster);
  if (els.adventurePrepRivalCard) {
    els.adventurePrepRivalCard.style.setProperty('--prep-domain-primary', rivalPrepPalette[0]);
    els.adventurePrepRivalCard.style.setProperty('--prep-domain-secondary', rivalPrepPalette[1] || rivalPrepPalette[0]);
  }
  if (els.adventurePrepPlayerCard) {
    els.adventurePrepPlayerCard.style.setProperty('--prep-domain-primary', playerPrepPalette[0]);
    els.adventurePrepPlayerCard.style.setProperty('--prep-domain-secondary', playerPrepPalette[1] || playerPrepPalette[0]);
  }

  if (els.adventurePrepRivalImage) els.adventurePrepRivalImage.src = encounter.image;
  if (els.adventurePrepRivalName) els.adventurePrepRivalName.textContent = encounter.label;
  if (els.adventurePrepRivalLevel) els.adventurePrepRivalLevel.textContent = `NIVEL ${Math.max(1, Number(encounter.level) || 1)}`;
  if (els.adventurePrepPlayerImage) els.adventurePrepPlayerImage.src = playerCaster.image;
  if (els.adventurePrepPlayerName) els.adventurePrepPlayerName.textContent = playerCaster.label;
  if (els.adventurePrepArenaImage) {
    els.adventurePrepArenaImage.src = arena.image;
    els.adventurePrepArenaImage.alt = `Previsualización de ${arena.label}`;
    els.adventurePrepArenaImage.style.objectPosition = `${arena.focusX}% ${arena.focusY}%`;
    els.adventurePrepArenaImage.dataset.customArena = arena.custom ? 'true' : 'false';
  }
  if (els.adventurePrepArenaName) els.adventurePrepArenaName.textContent = arena.label;
  if (els.adventurePrepArenaBadge) els.adventurePrepArenaBadge.textContent = arena.preview ? 'PREVISUALIZACIÓN' : 'ARENA';

  const unlocked = isAdventureSpellbookEditingUnlocked();
  if (els.adventurePrepSpellbookStatus) {
    els.adventurePrepSpellbookStatus.textContent = unlocked
      ? `${playerCardIds.length} cartas configuradas · edición disponible`
      : 'Edición bloqueada hasta derrotar a Kiara.';
  }
  if (els.adventurePrepEditSpellbookBtn) {
    els.adventurePrepEditSpellbookBtn.disabled = !unlocked;
    els.adventurePrepEditSpellbookBtn.textContent = unlocked ? 'Editar Spellbook' : 'Spellbook bloqueado';
  }
  if (els.adventurePlayerCasterList) {
    els.adventurePlayerCasterList.innerHTML = ADVENTURE_PLAYER_CASTERS.map(caster => `<button type="button" class="adventure-player-caster-option${caster.id === adventureState.playerCasterId ? ' selected' : ''}" data-adventure-player-caster="${caster.id}"><img src="${caster.image}" alt=""><span><b>${caster.label}</b><small>${caster.subtitle}</small></span></button>`).join('');
  }
}

function renderAdventureCasterDetail(entity, side = 'player') {
  if (!els.adventureCasterDetailOverlay || !entity) return;
  if (els.adventureCasterDetailKicker) els.adventureCasterDetailKicker.textContent = side === 'rival' ? 'KASTER RIVAL' : 'TU KASTER';
  if (els.adventureCasterDetailName) els.adventureCasterDetailName.textContent = entity.label || 'Kaster';
  if (els.adventureCasterDetailImage) els.adventureCasterDetailImage.src = entity.image || '';
  if (els.adventureCasterDetailIdentity) els.adventureCasterDetailIdentity.innerHTML = renderAdventureCasterIdentity(entity);
  if (els.adventureCasterDetailStats) {
    const stats = entity.stats || {};
    const sections = stats.sections || [];
    const profile = stats.profile || [];
    els.adventureCasterDetailStats.innerHTML = sections.map(section => `<div class="adventure-detail-stat-section"><b>${section.title}</b>${(section.items || []).map(item => `<span><em>${item.label}</em><strong>${item.display ?? item.value ?? '-'}</strong></span>`).join('')}</div>`).join('') + (profile.length ? `<div class="adventure-detail-profile">${profile.map(line => `<span><b>${line.label}</b>${line.value}</span>`).join('')}</div>` : '');
  }
  const dominantSource = side === 'rival'
    ? getAdventureDominantEntries(entity, adventureState.encounterSpellbooks[entity.id] || [])
    : getAdventureDominantEntries({ previewDominants: entity.previewDominants }, getAdventureSpellbookCardIds());
  if (els.adventureCasterDetailDominants) els.adventureCasterDetailDominants.innerHTML = renderAdventureDominantChips(dominantSource);
  els.adventureCasterDetailOverlay.classList.add('open');
  els.adventureCasterDetailOverlay.setAttribute('aria-hidden', 'false');
}

function closeAdventureCasterDetail() {
  els.adventureCasterDetailOverlay?.classList.remove('open');
  els.adventureCasterDetailOverlay?.setAttribute('aria-hidden', 'true');
}

function openAdventureSpellbookEditor() {
  if (!isAdventureSpellbookEditingUnlocked()) {
    showAdventureNotice('El Spellbook se desbloquea al derrotar a Kiara.');
    return;
  }
  const progress = loadAdventureProgress();
  const current = new Set(progress.spellbookCardIds || []);
  const unlocked = new Set([...(progress.unlockedCardIds || []), ...current]);
  if (els.adventureSpellbookGrid) {
    const cards = Object.values(CARD_LIBRARY).filter(card => card && card.type !== 'kaster' && card.type !== 'element');
    els.adventureSpellbookGrid.innerHTML = cards.map(card => {
      const available = unlocked.has(card.id);
      const selected = current.has(card.id);
      const art = card.artImage || card.tokenImage || card.bgImage || '';
      return `<button type="button" class="adventure-spellbook-card${available ? ' unlocked' : ' locked'}${selected ? ' selected' : ''}" data-adventure-spellbook-card="${card.id}" ${available ? '' : 'disabled'}><span class="adventure-spellbook-card-art">${art ? `<img src="${art}" alt="">` : ''}</span><b>${card.shortName || card.name || card.id}</b><small>${available ? (selected ? 'EN SPELLBOOK' : 'DESBLOQUEADA') : 'BLOQUEADA'}</small></button>`;
    }).join('');
  }
  if (els.adventureSpellbookOverlay) {
    els.adventureSpellbookOverlay.classList.add('open');
    els.adventureSpellbookOverlay.setAttribute('aria-hidden', 'false');
  }
  updateAdventureSpellbookEditorCounter();
}

function updateAdventureSpellbookEditorCounter() {
  const progress = loadAdventureProgress();
  if (els.adventureSpellbookCounter) els.adventureSpellbookCounter.textContent = `${(progress.spellbookCardIds || []).length}/30`;
}

function toggleAdventureSpellbookCard(cardId) {
  const progress = loadAdventureProgress();
  const unlocked = new Set(progress.unlockedCardIds || []);
  const current = progress.spellbookCardIds || [];
  if (!unlocked.has(cardId) && !current.includes(cardId)) return;
  const index = current.indexOf(cardId);
  if (index >= 0) current.splice(index, 1);
  else if (current.length < 30) current.push(cardId);
  progress.spellbookCardIds = current;
  saveAdventureProgress(progress);
  openAdventureSpellbookEditor();
  renderAdventurePreparation();
}

function closeAdventureSpellbookEditor() {
  els.adventureSpellbookOverlay?.classList.remove('open');
  els.adventureSpellbookOverlay?.setAttribute('aria-hidden', 'true');
}

function startAdventureBattleIntro() {
  const encounter = getAdventureWaterEncounter(adventureState.encounterId);
  const playerCaster = getAdventurePlayerCaster();
  if (!els.adventureBattleIntro) return;
  const rivalCardIds = adventureState.encounterSpellbooks[encounter.id] || [];
  const playerCardIds = getAdventureSpellbookCardIds();
  els.adventureIntroRivalChampion = ensureVersusIntroChampionElement(
    els.adventureIntroRivalSide, els.adventureIntroRivalChampion, 'adventureIntroRivalChampion', 'Invocación rival destacada'
  );
  els.adventureIntroPlayerChampion = ensureVersusIntroChampionElement(
    els.adventureIntroPlayerSide, els.adventureIntroPlayerChampion, 'adventureIntroPlayerChampion', 'Invocación destacada del jugador'
  );
  const rivalEntries = getAdventureDominantEntries(encounter, rivalCardIds);
  const playerEntries = getAdventureDominantEntries({ previewDominants: playerCaster.previewDominants }, playerCardIds);
  if (els.adventureIntroRivalImage) {
    els.adventureIntroRivalImage.src = encounter.image;
    applyVsLayoutCalibrationToElement(els.adventureIntroRivalImage, `kaster:adventure:${encounter.id}`);
  }
  if (els.adventureIntroRivalName) els.adventureIntroRivalName.textContent = encounter.label;
  if (els.adventureIntroRivalDominants) els.adventureIntroRivalDominants.innerHTML = renderAdventureDominantFigures(rivalEntries, 'left');
  if (els.adventureIntroPlayerImage) {
    els.adventureIntroPlayerImage.src = playerCaster.image;
    applyVsLayoutCalibrationToElement(els.adventureIntroPlayerImage, `kaster:adventure-player:${playerCaster.id}`);
  }
  if (els.adventureIntroPlayerName) els.adventureIntroPlayerName.textContent = playerCaster.label;
  if (els.adventureIntroPlayerDominants) els.adventureIntroPlayerDominants.innerHTML = renderAdventureDominantFigures(playerEntries, 'right');
  setVersusIntroChampion(els.adventureIntroRivalChampion, rivalCardIds, 'Invocación rival destacada', {
    fallbackImages: [...rivalEntries.map(entry => entry.image).filter(Boolean), ...ADVENTURE_PREVIEW_INVOCATION_ART],
    fallbackName: `Invocación de ${encounter.label || 'rival'}`,
  });
  setVersusIntroChampion(els.adventureIntroPlayerChampion, playerCardIds, 'Invocación destacada del jugador', {
    fallbackImages: [...playerEntries.map(entry => entry.image).filter(Boolean), ...ADVENTURE_PREVIEW_INVOCATION_ART],
    fallbackName: `Invocación de ${playerCaster.label || 'jugador'}`,
  });
  applyAdventureIntroPalette(els.adventureIntroRivalSide, getAdventureIntroPalette(encounter, rivalEntries));
  applyAdventureIntroPalette(els.adventureIntroPlayerSide, getAdventureIntroPalette(playerCaster, playerEntries));
  syncVersusLetterColors(els.adventureBattleIntro, els.adventureIntroRivalSide, els.adventureIntroPlayerSide);
  startVersusIntroEnergy(els.adventureBattleIntro);
  els.adventureBattleIntro.setAttribute('aria-hidden', 'false');
  els.adventureBattleIntro.classList.remove('active', 'counting', 'combat-ready');
  void els.adventureBattleIntro.offsetWidth;
  els.adventureBattleIntro.classList.add('active');

  if (adventureState.battleIntroTimer) clearTimeout(adventureState.battleIntroTimer);
  adventureState.battleIntroTimer = setTimeout(() => {
    els.adventureBattleIntro?.classList.add('counting');
    let count = 3;
    if (els.adventureIntroCountdown) {
      els.adventureIntroCountdown.textContent = String(count);
      triggerVersusIntroCountdownPulse(els.adventureIntroCountdown);
    }
    const interval = setInterval(() => {
      count -= 1;
      if (count >= 1) {
        if (els.adventureIntroCountdown) {
          els.adventureIntroCountdown.textContent = String(count);
          triggerVersusIntroCountdownPulse(els.adventureIntroCountdown);
        }
        return;
      }
      clearInterval(interval);
      if (els.adventureIntroCountdown) {
        els.adventureIntroCountdown.textContent = '';
        resetVersusIntroCountdownPulse(els.adventureIntroCountdown);
      }
      els.adventureBattleIntro?.classList.add('combat-ready');
      setTimeout(() => launchPreparedAdventureBattle(), 1050);
    }, 1000);
  }, 2600);
}

let onlineVersusIntroTimer = null;
let onlineVersusIntroStartAt = 0;

const versusIntroEnergyState = new WeakMap();

function ensureVersusIntroEnergyLayer(sideEl, variant = 'streaks') {
  if (!sideEl) return null;
  const safeVariant = variant === 'particles' ? 'particles' : 'streaks';
  const className = `adventure-intro-energy-layer adventure-intro-${safeVariant}-layer`;
  let layer = sideEl.querySelector(`:scope > .adventure-intro-${safeVariant}-layer`);
  if (!layer) {
    layer = document.createElement('div');
    layer.className = className;
    sideEl.insertBefore(layer, sideEl.firstChild || null);
  }
  return layer;
}

function parseIntroCssColor(color) {
  const value = String(color || '').trim();
  if (!value) return null;
  if (value.startsWith('#')) {
    const hex = value.slice(1);
    if (hex.length === 3) {
      return {
        r: parseInt(hex[0] + hex[0], 16),
        g: parseInt(hex[1] + hex[1], 16),
        b: parseInt(hex[2] + hex[2], 16),
      };
    }
    if (hex.length >= 6) {
      return {
        r: parseInt(hex.slice(0, 2), 16),
        g: parseInt(hex.slice(2, 4), 16),
        b: parseInt(hex.slice(4, 6), 16),
      };
    }
  }
  const match = value.match(/rgba?\(([^)]+)\)/i);
  if (match) {
    const parts = match[1].split(',').map(part => Number(part.trim()));
    if (parts.length >= 3 && parts.every(num => Number.isFinite(num))) {
      return { r: parts[0], g: parts[1], b: parts[2] };
    }
  }
  return null;
}

function mixIntroColors(a, b, amount = 0.5) {
  const alpha = Math.max(0, Math.min(1, Number(amount) || 0));
  return {
    r: Math.round(a.r + (b.r - a.r) * alpha),
    g: Math.round(a.g + (b.g - a.g) * alpha),
    b: Math.round(a.b + (b.b - a.b) * alpha),
  };
}

function introColorToCss(colorObj) {
  if (!colorObj) return getDominionPrimaryColor('agua');
  return `rgb(${Math.max(0, Math.min(255, colorObj.r || 0))}, ${Math.max(0, Math.min(255, colorObj.g || 0))}, ${Math.max(0, Math.min(255, colorObj.b || 0))})`;
}

function getVersusIntroEnergyPalette(sideEl) {
  if (!sideEl) return [getDominionPrimaryColor('agua'), getDominionSecondaryColor('agua')];
  const computed = getComputedStyle(sideEl);
  const raw = [1, 2, 3].map(index => computed.getPropertyValue(`--intro-color-${index}`).trim()).filter(Boolean);
  const parsed = raw.map(parseIntroCssColor).filter(Boolean);
  if (!parsed.length) return [getDominionPrimaryColor('agua'), getDominionSecondaryColor('agua')];
  const colors = parsed.map(color => introColorToCss(color));
  if (parsed.length === 1) {
    const base = parsed[0];
    const aqua = mixIntroColors(base, { r: 82, g: 255, b: 208 }, 0.28);
    const light = mixIntroColors(base, { r: 214, g: 255, b: 248 }, 0.42);
    return [introColorToCss(base), introColorToCss(aqua), introColorToCss(light)];
  }
  if (parsed.length === 2) {
    const bridge = mixIntroColors(parsed[0], parsed[1], 0.5);
    colors.push(introColorToCss(bridge));
  }
  return colors.slice(0, 3);
}

function getVersusIntroEnergyConfig(sideEl) {
  return {
    direction: sideEl?.classList.contains('adventure-intro-rival') ? 'left' : 'right',
    palette: getVersusIntroEnergyPalette(sideEl),
  };
}

function createVersusIntroStreak(layer, config = {}) {
  if (!layer) return;
  const streak = document.createElement('div');
  const direction = config.direction === 'right' ? 'right' : 'left';
  streak.className = `adventure-intro-streak ${direction}`;

  const palette = Array.isArray(config.palette) && config.palette.length ? config.palette : [getDominionPrimaryColor('agua'), getDominionSecondaryColor('agua')];
  const baseColor = palette[Math.floor(Math.random() * palette.length)] || getDominionPrimaryColor('agua');
  const parsedBase = parseIntroCssColor(baseColor) || { r: 127, g: 200, b: 255 };
  const mixed = Math.random() < 0.58
    ? mixIntroColors(parsedBase, { r: 255, g: 255, b: 255 }, 0.08 + Math.random() * 0.24)
    : parsedBase;
  const width = 18 + Math.random() * 34;
  const height = 2 + Math.random() * 6.5;
  const top = 10 + Math.random() * 74;
  const duration = 900 + Math.random() * 1100;
  const peakOpacity = 0.7 + Math.random() * 0.3;
  const blur = Math.random() * 1.4;

  streak.style.top = `${top}%`;
  streak.style.width = `${width}%`;
  streak.style.height = `${height}px`;
  streak.style.setProperty('--streak-color', introColorToCss(mixed));
  streak.style.setProperty('--streak-duration', `${Math.round(duration)}ms`);
  streak.style.setProperty('--peak-opacity', peakOpacity.toFixed(3));
  streak.style.filter = `blur(${blur.toFixed(2)}px)`;

  streak.addEventListener('animationend', () => streak.remove(), { once: true });
  layer.appendChild(streak);
}

function createVersusIntroComet(layer, config = {}) {
  if (!layer) return;
  const particle = document.createElement('div');
  const direction = config.direction === 'right' ? 'right' : 'left';
  const isOrb = Math.random() < 0.34;
  particle.className = `adventure-intro-comet ${direction}${isOrb ? ' is-orb' : ''}`;

  const palette = Array.isArray(config.palette) && config.palette.length
    ? config.palette
    : [getDominionPrimaryColor('agua'), getDominionSecondaryColor('agua')];
  const baseColor = palette[Math.floor(Math.random() * palette.length)] || getDominionPrimaryColor('agua');
  const parsedBase = parseIntroCssColor(baseColor) || { r: 127, g: 200, b: 255 };
  const mixed = Math.random() < 0.64
    ? mixIntroColors(parsedBase, { r: 255, g: 255, b: 255 }, 0.05 + Math.random() * 0.22)
    : parsedBase;

  // Los orbes deben verse notablemente más pequeños que en v582 y con
  // tamaños realmente variados. Además, evitamos usar la clase global
  // `.orb` para que no hereden el tamaño fijo del sistema general.
  const coreSize = isOrb ? 1.575 + Math.random() * 4.2 : 1.7 + Math.random() * 4.1;
  const tailLength = isOrb ? 5.25 + Math.random() * 15.75 : 15 + Math.random() * 42;
  const top = 7 + Math.random() * 84;
  const opacity = isOrb ? 0.22 + Math.random() * 0.44 : 0.28 + Math.random() * 0.62;

  // Lines run at ~900–2000 ms. Intentionally mix particles that are
  // somewhat faster with others that are substantially slower.
  const speedRoll = Math.random();
  let duration;
  if (speedRoll < 0.43) duration = 620 + Math.random() * 560;       // faster
  else if (speedRoll < 0.70) duration = 1350 + Math.random() * 900; // around/just slower
  else duration = 2800 + Math.random() * 2600;                     // much slower

  particle.style.top = `${top}%`;
  particle.style.width = `${tailLength.toFixed(1)}px`;
  particle.style.height = `${coreSize.toFixed(1)}px`;
  particle.style.setProperty('--comet-color', introColorToCss(mixed));
  particle.style.setProperty('--comet-duration', `${Math.round(duration)}ms`);
  particle.style.setProperty('--comet-opacity', opacity.toFixed(3));
  particle.style.setProperty('--comet-core', `${coreSize.toFixed(1)}px`);
  particle.style.setProperty('--comet-tail', `${tailLength.toFixed(1)}px`);

  particle.addEventListener('animationend', () => particle.remove(), { once: true });
  layer.appendChild(particle);
}

function triggerVersusIntroCountdownPulse(countdownEl) {
  if (!countdownEl) return;
  countdownEl.style.animation = 'none';
  void countdownEl.offsetWidth;
  countdownEl.style.animation = 'adventureCountPulse 1000ms ease forwards';
}

function resetVersusIntroCountdownPulse(countdownEl) {
  if (!countdownEl) return;
  countdownEl.style.animation = 'none';
}

function stopVersusIntroEnergy(introRoot) {
  if (!introRoot) return;
  const state = versusIntroEnergyState.get(introRoot);
  if (state) {
    state.active = false;
    (state.timeouts || []).forEach(id => window.clearTimeout(id));
    state.timeouts = [];
  }
  Array.from(introRoot.querySelectorAll('.adventure-intro-energy-layer')).forEach(layer => { layer.textContent = ''; });
}

function startVersusIntroEnergy(introRoot) {
  if (!introRoot) return;
  stopVersusIntroEnergy(introRoot);
  const sideLayers = Array.from(introRoot.querySelectorAll('.adventure-intro-side')).map(sideEl => ({
    sideEl,
    streakLayer: ensureVersusIntroEnergyLayer(sideEl, 'streaks'),
    particleLayer: ensureVersusIntroEnergyLayer(sideEl, 'particles'),
    config: getVersusIntroEnergyConfig(sideEl),
  })).filter(entry => entry.streakLayer && entry.particleLayer);
  const state = { active: true, timeouts: [] };
  versusIntroEnergyState.set(introRoot, state);

  sideLayers.forEach(({ streakLayer, particleLayer, config }) => {
    for (let i = 0; i < 4; i += 1) createVersusIntroStreak(streakLayer, config);
    for (let i = 0; i < 5; i += 1) createVersusIntroComet(particleLayer, config);

    const streakLoop = () => {
      if (!state.active) return;
      createVersusIntroStreak(streakLayer, config);
      const delay = 85 + Math.random() * 190;
      const timeoutId = window.setTimeout(streakLoop, delay);
      state.timeouts.push(timeoutId);
    };

    const cometLoop = () => {
      if (!state.active) return;
      createVersusIntroComet(particleLayer, config);
      const delay = 95 + Math.random() * 230;
      const timeoutId = window.setTimeout(cometLoop, delay);
      state.timeouts.push(timeoutId);
    };

    state.timeouts.push(window.setTimeout(streakLoop, 40 + Math.random() * 110));
    state.timeouts.push(window.setTimeout(cometLoop, 55 + Math.random() * 160));
  });
}

function getLoadoutSpellbookCardIds(loadout = null) {
  if (!loadout || typeof loadout !== 'object') return [];
  return normalizeSpellbookCardSlots(loadout.cards).filter(cardId => typeof cardId === 'string' && CARD_LIBRARY[cardId]);
}

function getLoadoutCasterIntroData(loadout = null, fallbackName = 'Kaster') {
  const casterCard = CARD_LIBRARY[loadout?.casterCardId] || null;
  const casterDef = casterCard ? getCasterRuntimeDefinitionFromCard(casterCard) : null;
  const domains = [];
  const pushDomainTint = domainId => {
    const id = normalizeDominionId(domainId);
    if (!id) return;
    const tint = getDominionPrimaryColor(id);
    if (tint && !domains.includes(tint)) domains.push(tint);
  };
  if (Array.isArray(casterDef?.domains)) {
    casterDef.domains.forEach(entry => pushDomainTint(entry?.id || entry?.elementId));
  }
  if (Array.isArray(casterCard?.domains)) {
    casterCard.domains.forEach(entry => pushDomainTint(entry?.id || entry?.elementId));
  }
  pushDomainTint(casterDef?.domainId || casterDef?.elementId || null);
  pushDomainTint(casterCard?.domain?.elementId || casterCard?.elementId || null);
  return {
    card: casterCard,
    name: casterCard?.name || casterDef?.name || fallbackName,
    image: casterDef?.tokenImage || casterCard?.tokenImage || casterDef?.artImage || casterCard?.artImage || 'assets/caster-hanzo.png',
    elementId: getCardElementId(casterCard),
    domainColors: domains,
    layoutKey: casterCard?.id ? `kaster:${casterCard.id}` : (casterDef?.cardId ? `kaster:${casterDef.cardId}` : ''),
  };
}

function getOnlineIntroPalette(loadout = null) {
  const caster = getLoadoutCasterIntroData(loadout);
  const colors = Array.isArray(caster.domainColors) ? [...caster.domainColors] : [];
  const primaryId = normalizeDominionId(caster.elementId);
  if (primaryId) colors.push(getDominionSecondaryColor(primaryId));
  return normalizeIntroPalette(colors);
}

function ensureVersusIntroChampionElement(sideEl, element, id, alt = 'Invocación destacada') {
  if (element && element.isConnected) return element;
  if (!sideEl) return null;
  let resolved = id ? document.getElementById(id) : null;
  if (resolved) return resolved;
  resolved = document.createElement('img');
  if (id) resolved.id = id;
  resolved.className = 'adventure-intro-champion';
  resolved.alt = alt;
  resolved.draggable = false;
  const caster = sideEl.querySelector('.adventure-intro-caster');
  if (caster) sideEl.insertBefore(resolved, caster);
  else sideEl.prepend(resolved);
  return resolved;
}

function setVersusIntroChampion(element, cardIds = [], fallbackAlt = 'Invocación destacada', options = {}) {
  if (!element) return null;
  const champion = getAdventureStrongestInvocationPreview(cardIds, options);
  if (!champion?.image) {
    element.removeAttribute('src');
    element.removeAttribute('title');
    element.classList.remove('visible');
    applyVsLayoutCalibrationToElement(element, '');
    return null;
  }
  element.src = champion.image;
  element.alt = champion.name || fallbackAlt;
  const pb = champion.card ? Number(getCardBattlePointsValue(champion.card) || 0) : null;
  element.title = champion.card
    ? `${champion.name || fallbackAlt} · ${pb} PB`
    : (champion.name || fallbackAlt);
  element.classList.add('visible');
  applyVsLayoutCalibrationToElement(element, champion.card ? getVsLayoutInvocationKey(champion.card) : '');
  return champion;
}

function resetOnlineVersusIntroCountdown() {
  if (onlineVersusIntroTimer) window.clearInterval(onlineVersusIntroTimer);
  onlineVersusIntroTimer = null;
}

function hideOnlineVersusIntro() {
  resetOnlineVersusIntroCountdown();
  onlineVersusIntroStartAt = 0;
  stopVersusIntroEnergy(els.onlineVersusIntro);
  if (!els.onlineVersusIntro) return;
  els.onlineVersusIntro.classList.remove('active', 'counting', 'combat-ready');
  els.onlineVersusIntro.setAttribute('aria-hidden', 'true');
  if (els.onlineIntroCountdown) { els.onlineIntroCountdown.textContent = ''; resetVersusIntroCountdownPulse(els.onlineIntroCountdown); }
}

function showOnlineVersusIntro(config = {}) {
  if (!els.onlineVersusIntro) return false;
  const room = config.room && typeof config.room === 'object' ? config.room : {};
  const localSlot = Number(config.localPlayerSlot) === 2 ? 2 : 1;
  const rivalSlot = localSlot === 1 ? 2 : 1;
  const players = room.players || {};
  const localRecord = players[localSlot] || players[String(localSlot)] || {};
  const rivalRecord = players[rivalSlot] || players[String(rivalSlot)] || {};
  const localLoadout = localRecord.loadout || null;
  const rivalLoadout = rivalRecord.loadout || null;
  const localCardIds = getLoadoutSpellbookCardIds(localLoadout);
  const rivalCardIds = getLoadoutSpellbookCardIds(rivalLoadout);
  const localEntries = getAdventureDominantEntries({}, localCardIds);
  const rivalEntries = getAdventureDominantEntries({}, rivalCardIds);
  const localCaster = getLoadoutCasterIntroData(localLoadout, 'Tu Kaster');
  const rivalCaster = getLoadoutCasterIntroData(rivalLoadout, 'Kaster rival');

  els.onlineIntroRivalChampion = ensureVersusIntroChampionElement(
    els.onlineIntroRivalSide, els.onlineIntroRivalChampion, 'onlineIntroRivalChampion', 'Invocación rival destacada'
  );
  els.onlineIntroPlayerChampion = ensureVersusIntroChampionElement(
    els.onlineIntroPlayerSide, els.onlineIntroPlayerChampion, 'onlineIntroPlayerChampion', 'Invocación destacada del jugador'
  );

  if (els.onlineIntroRivalImage) {
    els.onlineIntroRivalImage.src = rivalCaster.image;
    applyVsLayoutCalibrationToElement(els.onlineIntroRivalImage, rivalCaster.layoutKey);
  }
  if (els.onlineIntroPlayerImage) {
    els.onlineIntroPlayerImage.src = localCaster.image;
    applyVsLayoutCalibrationToElement(els.onlineIntroPlayerImage, localCaster.layoutKey);
  }
  if (els.onlineIntroRivalName) els.onlineIntroRivalName.textContent = config.rivalDisplayName || rivalRecord.displayName || 'Jugador rival';
  if (els.onlineIntroPlayerName) els.onlineIntroPlayerName.textContent = config.localDisplayName || localRecord.displayName || 'Jugador';
  if (els.onlineIntroRivalKicker) els.onlineIntroRivalKicker.textContent = config.rivalKicker || rivalCaster.name;
  if (els.onlineIntroPlayerKicker) els.onlineIntroPlayerKicker.textContent = config.localKicker || localCaster.name;
  if (els.onlineIntroRivalDominants) els.onlineIntroRivalDominants.innerHTML = renderAdventureDominantFigures(rivalEntries, 'left');
  if (els.onlineIntroPlayerDominants) els.onlineIntroPlayerDominants.innerHTML = renderAdventureDominantFigures(localEntries, 'right');
  setVersusIntroChampion(els.onlineIntroRivalChampion, rivalCardIds, 'Invocación rival destacada', {
    fallbackImages: [...rivalEntries.map(entry => entry.image).filter(Boolean), ...ADVENTURE_PREVIEW_INVOCATION_ART],
    fallbackName: 'Invocación rival destacada',
  });
  setVersusIntroChampion(els.onlineIntroPlayerChampion, localCardIds, 'Invocación destacada del jugador', {
    fallbackImages: [...localEntries.map(entry => entry.image).filter(Boolean), ...ADVENTURE_PREVIEW_INVOCATION_ART],
    fallbackName: 'Invocación destacada del jugador',
  });
  applyAdventureIntroPalette(els.onlineIntroRivalSide, getOnlineIntroPalette(rivalLoadout, rivalEntries));
  applyAdventureIntroPalette(els.onlineIntroPlayerSide, getOnlineIntroPalette(localLoadout, localEntries));
  syncVersusLetterColors(els.onlineVersusIntro, els.onlineIntroRivalSide, els.onlineIntroPlayerSide);

  const arenaPreview = String(config.arena?.previewImage || config.arenaPreview || '').trim();
  if (els.onlineIntroBackground) {
    els.onlineIntroBackground.style.backgroundImage = arenaPreview
      ? `linear-gradient(90deg, rgba(2,8,13,.72), rgba(4,5,9,.82) 49%, rgba(4,5,9,.82) 51%, rgba(12,8,4,.72)), url("${arenaPreview.replace(/"/g, '%22')}")`
      : '';
    els.onlineIntroBackground.style.backgroundSize = arenaPreview ? 'cover' : '';
    els.onlineIntroBackground.style.backgroundPosition = arenaPreview ? 'center' : '';
  }

  const startAt = Math.max(1, Number(config.startAt || (Date.now() + 1000)));
  const restartScene = onlineVersusIntroStartAt !== startAt || els.onlineVersusIntro.getAttribute('aria-hidden') !== 'false';
  onlineVersusIntroStartAt = startAt;
  if (restartScene) {
    startVersusIntroEnergy(els.onlineVersusIntro);
    els.onlineVersusIntro.setAttribute('aria-hidden', 'false');
    els.onlineVersusIntro.classList.remove('active', 'counting', 'combat-ready');
    void els.onlineVersusIntro.offsetWidth;
    els.onlineVersusIntro.classList.add('active');
  }

  resetOnlineVersusIntroCountdown();
  const paint = () => {
    const remaining = startAt - Date.now();
    let countText = '';
    if (remaining <= 3200 && remaining > 2200) countText = '3';
    else if (remaining <= 2200 && remaining > 1200) countText = '2';
    else if (remaining <= 1200 && remaining > 200) countText = '1';
    if (els.onlineIntroCountdown && els.onlineIntroCountdown.textContent !== countText) {
      els.onlineIntroCountdown.textContent = countText;
      if (countText) triggerVersusIntroCountdownPulse(els.onlineIntroCountdown);
      else resetVersusIntroCountdownPulse(els.onlineIntroCountdown);
    }
    els.onlineVersusIntro.classList.toggle('counting', Boolean(countText));
    if (remaining <= 200) els.onlineVersusIntro.classList.add('combat-ready');
    if (remaining < -1500) resetOnlineVersusIntroCountdown();
  };
  paint();
  onlineVersusIntroTimer = window.setInterval(paint, 100);
  return true;
}


let localVersusIntroCompletionTimer = null;

function getPlayerTemplateIntroLoadout(playerTemplate = null, options = {}) {
  const player = playerTemplate && typeof playerTemplate === 'object' ? playerTemplate : {};
  const cards = [];
  const handTabs = Array.isArray(player.handTabs) ? player.handTabs : [];
  handTabs.forEach(tab => {
    if (!Array.isArray(tab)) return;
    tab.forEach(cardId => {
      if (typeof cardId === 'string' && CARD_LIBRARY[cardId]) cards.push(cardId);
    });
  });
  if (Array.isArray(options.cards)) {
    cards.length = 0;
    options.cards.forEach(cardId => {
      if (typeof cardId === 'string' && CARD_LIBRARY[cardId]) cards.push(cardId);
    });
  }
  return {
    id: options.id || player.selectedSpellbookId || 'versus-intro-loadout',
    name: options.name || player.spellbookName || 'Spellbook',
    casterCardId: options.casterCardId || player.caster?.cardId || '',
    cards,
    elementDistribution: {},
    elementDistributionConfigured: false,
    schemaVersion: SPELLBOOK_SCHEMA_VERSION,
  };
}

function getBotVersusIntroLoadout(matchMode = 'normal') {
  const template = cloneMatchData(INITIAL_BATTLE_STATE.players?.[2] || {});
  if (matchMode === TEST_MATCH_MODE_ID) {
    return getPlayerTemplateIntroLoadout(template, {
      id: 'rok-test-bot-shirahadori',
      name: 'Bot de prueba · Shirahadori',
      cards: [
        TEST_BOT_KAGERO_CARD_ID,
        TEST_BOT_KAGERO_CARD_ID,
        TEST_BOT_KAGERO_CARD_ID,
        TEST_BOT_SHIRAHADORI_CARD_ID,
        TEST_BOT_SHIRAHADORI_CARD_ID,
        TEST_BOT_SHIRAHADORI_CARD_ID,
      ],
    });
  }
  return getPlayerTemplateIntroLoadout(template, {
    id: 'rok-default-bot-tokugawa',
    name: 'Bot · Tokugawa',
  });
}

function getVersusIntroCasterName(loadout = null, fallback = 'Kaster') {
  return getLoadoutCasterIntroData(loadout, fallback).name || fallback;
}

function cancelLocalVersusIntroCompletion() {
  if (localVersusIntroCompletionTimer) window.clearTimeout(localVersusIntroCompletionTimer);
  localVersusIntroCompletionTimer = null;
}

function showLocalVersusIntro(config = {}) {
  const localLoadout = config.localLoadout || null;
  const rivalLoadout = config.rivalLoadout || null;
  if (!localLoadout || !rivalLoadout) return false;
  cancelLocalVersusIntroCompletion();
  try { hideOnlineVersusIntro(); } catch (_) {}

  const duration = Math.max(3600, Number(config.duration || 6200));
  const startAt = Date.now() + duration;
  const localCasterName = getVersusIntroCasterName(localLoadout, 'Tu Kaster');
  const rivalCasterName = getVersusIntroCasterName(rivalLoadout, 'Kaster rival');
  const room = {
    players: {
      1: { displayName: localCasterName, loadout: cloneMatchData(localLoadout) },
      2: { displayName: rivalCasterName, loadout: cloneMatchData(rivalLoadout) },
    },
  };
  const shown = showOnlineVersusIntro({
    room,
    localPlayerSlot: 1,
    startAt,
    localDisplayName: config.localDisplayName || localCasterName,
    rivalDisplayName: config.rivalDisplayName || rivalCasterName,
    localKicker: config.localKicker || 'JUGADOR',
    rivalKicker: config.rivalKicker || 'RIVAL',
    arena: config.arena || null,
    arenaPreview: config.arenaPreview || '',
  });
  if (!shown) return false;

  localVersusIntroCompletionTimer = window.setTimeout(() => {
    localVersusIntroCompletionTimer = null;
    hideOnlineVersusIntro();
    try { config.onComplete?.(); }
    catch (error) { reportGameException(error, 'Presentación VS local · finalizar'); }
  }, duration + 80);
  return true;
}

window.ROK_VERSUS_INTRO = {
  showOnline: showOnlineVersusIntro,
  hideOnline: hideOnlineVersusIntro,
  showLocal: showLocalVersusIntro,
  hideLocal() { cancelLocalVersusIntroCompletion(); hideOnlineVersusIntro(); },
  getDominants(loadout = null) {
    const cardIds = getLoadoutSpellbookCardIds(loadout);
    return getSpellbookDominantQualityStatsFromCardIds(cardIds, []);
  },
  getStrongestInvocation(loadout = null) {
    const card = getAdventureStrongestInvocationCard(getLoadoutSpellbookCardIds(loadout));
    return card ? { id: card.id, name: card.name, battlePoints: Number(getCardBattlePointsValue(card) || 0) } : null;
  },
};


/* =========================================================
   Iniciativa de combate · Piedra / Papel / Tijera
   Se ejecuta después de la presentación VS y antes del flujo
   normal de fases / extracción inicial.
   ========================================================= */
const RPS_INITIATIVE_CHOICES = Object.freeze({
  rock: Object.freeze({ id: 'rock', label: 'Piedra', image: 'assets/rps/rock.webp' }),
  paper: Object.freeze({ id: 'paper', label: 'Papel', image: 'assets/rps/paper.webp' }),
  scissors: Object.freeze({ id: 'scissors', label: 'Tijera', image: 'assets/rps/scissors.webp' }),
});

const rpsInitiativeRuntime = {
  generation: 0,
  active: false,
  round: 1,
  matchSerial: 1,
  resolver: null,
  pollTimer: null,
  onlineUpdateHandler: null,
};

const RPS_INITIATIVE_GAMEPLAY_PAUSE_TOKEN = 'online-initiative-rps';

function getRpsChoice(id) {
  return RPS_INITIATIVE_CHOICES[String(id || '')] || null;
}

function resolveRpsInitiativeChoice(player1Choice, player2Choice) {
  const p1 = String(player1Choice || '');
  const p2 = String(player2Choice || '');
  if (!getRpsChoice(p1) || !getRpsChoice(p2)) return 0;
  if (p1 === p2) return 0;
  if (
    (p1 === 'rock' && p2 === 'scissors')
    || (p1 === 'scissors' && p2 === 'paper')
    || (p1 === 'paper' && p2 === 'rock')
  ) return 1;
  return 2;
}

function getRpsPlayerPalette(playerId) {
  const domainId = getPlayerDomainId(playerId) || state.players?.[playerId]?.elementId || 'oscuridad';
  return getDominionPalette(domainId, 'oscuridad');
}

function ensureRpsInitiativeOverlay() {
  let root = document.getElementById('rpsInitiativeOverlay');
  if (root) return root;
  root = document.createElement('div');
  root.id = 'rpsInitiativeOverlay';
  root.className = 'rps-initiative-overlay';
  root.setAttribute('aria-hidden', 'true');
  root.innerHTML = `
    <div class="rps-initiative-flyer" id="rpsInitiativeFlyer">¿QUIÉN INICIA?</div>
    <div class="rps-initiative-stage">
      <div class="rps-locked-card rps-locked-card-rival" id="rpsRivalLockedCard" aria-hidden="true"><span>?</span></div>
      <div class="rps-locked-card rps-locked-card-local" id="rpsLocalLockedCard" aria-hidden="true"><span>?</span></div>
      <div class="rps-duel" id="rpsInitiativeDuel" aria-hidden="true">
        <div class="rps-duel-card rps-duel-card-rival" id="rpsDuelRival"></div>
        <div class="rps-duel-card rps-duel-card-local" id="rpsDuelLocal"></div>
      </div>
      <div class="rps-initiative-result" id="rpsInitiativeResult"></div>
    </div>
    <div class="rps-choice-tray" id="rpsChoiceTray" aria-label="Selecciona Piedra, Papel o Tijera"></div>
  `;
  document.body.appendChild(root);
  return root;
}

function setRpsCardTheme(element, playerId) {
  if (!element) return;
  const palette = getRpsPlayerPalette(playerId);
  element.style.setProperty('--rps-primary', palette.dominant || '#5400FF');
  element.style.setProperty('--rps-secondary', palette.secondary || '#000000');
}

function getRpsCardDomainAssets(playerId) {
  const elementId = getPlayerDomainId(playerId) || state.players?.[playerId]?.elementId || 'oscuridad';
  const cardLike = {
    type: 'invocation',
    elementId,
    skinImage: getElementSkinForCard(null, elementId),
    bgImage: getElementBackgroundForCard({ type: 'invocation' }, elementId),
  };
  return {
    elementId,
    skinImage: getElementSkinForCard(cardLike, elementId),
    bgImage: getElementBackgroundForCard(cardLike, elementId),
  };
}

function renderRpsChoiceCardMarkup(choice, playerId, options = {}) {
  const item = getRpsChoice(choice);
  if (!item) return '';
  const palette = getRpsPlayerPalette(playerId);
  const hidden = options.hidden === true;
  const assets = getRpsCardDomainAssets(playerId);
  const cardLabel = String(item.label || '').toUpperCase();
  return `<div class="rps-card rps-card-domain${hidden ? ' is-hidden' : ''}" style="--rps-primary:${palette.dominant};--rps-secondary:${palette.secondary}" data-rps-domain="${assets.elementId}">
    <div class="rps-card-core">
      <img class="rps-card-layer rps-card-bgimg" src="${assets.bgImage}" alt="fondo ${assets.elementId}" onerror="this.onerror=null;this.src='assets/card-bg-darkness.jpg';">
      <div class="rps-card-art-shell">
        ${hidden ? '<div class="rps-card-question">?</div>' : `<img class="rps-card-layer rps-card-artimg" src="${item.image}" alt="${item.label}">`}
      </div>
      <img class="rps-card-layer rps-card-skinimg" src="${assets.skinImage}" alt="skin ${assets.elementId}" onerror="this.onerror=null;this.src='assets/card-skin-darkness.png';">
      <div class="rps-card-titlebar">${cardLabel}</div>
    </div>
  </div>`;
}

function stopRpsInitiativeRuntime(reason = 'cancelled') {
  rpsInitiativeRuntime.generation += 1;
  rpsInitiativeRuntime.active = false;
  if (rpsInitiativeRuntime.pollTimer) clearInterval(rpsInitiativeRuntime.pollTimer);
  rpsInitiativeRuntime.pollTimer = null;
  if (rpsInitiativeRuntime.onlineUpdateHandler) {
    window.removeEventListener('rok-online-initiative-update', rpsInitiativeRuntime.onlineUpdateHandler);
    rpsInitiativeRuntime.onlineUpdateHandler = null;
  }
  const resolver = rpsInitiativeRuntime.resolver;
  rpsInitiativeRuntime.resolver = null;
  const root = document.getElementById('rpsInitiativeOverlay');
  root?.classList.remove('open', 'resolving', 'revealed');
  root?.setAttribute('aria-hidden', 'true');
  try { releaseGlobalGameplayPause(RPS_INITIATIVE_GAMEPLAY_PAUSE_TOKEN); } catch (_) {}
  try { hideBattleInactivityPrompt(`initiative-rps:${reason}`); } catch (_) {}
  if (typeof resolver === 'function' && reason !== 'completed') {
    try { resolver(0); } catch (_) {}
  }
}

function delayRps(ms, generation) {
  return new Promise(resolve => {
    const started = Date.now();
    const tick = async () => {
      if (generation !== rpsInitiativeRuntime.generation) return resolve(false);
      if (!isOnlineMatchActive()) await waitForGlobalGameplayResume();
      const elapsed = Date.now() - started;
      if (elapsed >= ms) return resolve(true);
      window.setTimeout(tick, Math.min(80, ms - elapsed));
    };
    tick();
  });
}

function setRpsLockedCard(element, playerId, visible) {
  if (!element) return;
  setRpsCardTheme(element, playerId);
  element.setAttribute('aria-hidden', visible ? 'false' : 'true');
  element.classList.toggle('visible', Boolean(visible));
}

function renderRpsChoiceTray(root, localPlayerId, onSelect) {
  const tray = root.querySelector('#rpsChoiceTray');
  if (!tray) return;
  tray.innerHTML = '';
  Object.values(RPS_INITIATIVE_CHOICES).forEach((choice, index) => {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'rps-choice-card';
    button.style.setProperty('--rps-index', String(index));
    setRpsCardTheme(button, localPlayerId);
    button.innerHTML = renderRpsChoiceCardMarkup(choice.id, localPlayerId);
    button.setAttribute('aria-label', choice.label);
    button.addEventListener('click', () => onSelect(choice.id));
    tray.appendChild(button);
  });
}

async function animateRpsReveal(root, p1Choice, p2Choice, localPlayerId, generation) {
  if (generation !== rpsInitiativeRuntime.generation) return false;
  const rivalPlayerId = localPlayerId === 1 ? 2 : 1;
  const localChoice = localPlayerId === 1 ? p1Choice : p2Choice;
  const rivalChoice = localPlayerId === 1 ? p2Choice : p1Choice;
  const rivalLocked = root.querySelector('#rpsRivalLockedCard');
  const localLocked = root.querySelector('#rpsLocalLockedCard');
  const duel = root.querySelector('#rpsInitiativeDuel');
  const duelRival = root.querySelector('#rpsDuelRival');
  const duelLocal = root.querySelector('#rpsDuelLocal');
  const tray = root.querySelector('#rpsChoiceTray');
  tray?.classList.add('locked');
  root.classList.add('resolving');
  await delayRps(420, generation);
  if (generation !== rpsInitiativeRuntime.generation) return false;
  setRpsLockedCard(rivalLocked, rivalPlayerId, false);
  setRpsLockedCard(localLocked, localPlayerId, false);
  if (duelRival) duelRival.innerHTML = renderRpsChoiceCardMarkup(rivalChoice, rivalPlayerId, { hidden: true });
  if (duelLocal) duelLocal.innerHTML = renderRpsChoiceCardMarkup(localChoice, localPlayerId, { hidden: true });
  duel?.setAttribute('aria-hidden', 'false');
  duel?.classList.add('visible');
  await delayRps(560, generation);
  if (generation !== rpsInitiativeRuntime.generation) return false;
  if (duelRival) duelRival.innerHTML = renderRpsChoiceCardMarkup(rivalChoice, rivalPlayerId);
  if (duelLocal) duelLocal.innerHTML = renderRpsChoiceCardMarkup(localChoice, localPlayerId);
  root.classList.add('revealed');
  return true;
}

async function runInitiativeSelection(options = {}) {
  stopRpsInitiativeRuntime('replace');
  const generation = rpsInitiativeRuntime.generation;
  rpsInitiativeRuntime.active = true;
  rpsInitiativeRuntime.round = 1;
  rpsInitiativeRuntime.matchSerial = Math.max(1, Number(options.matchSerial || state.matchSerial || 1));
  const mode = options.mode === 'online' ? 'online' : 'bot';
  const localPlayerId = Math.max(1, Math.min(2, Number(options.localPlayerId || (mode === 'online' ? window.ROK_ONLINE_PVP?.getSession?.().playerSlot : 1) || 1)));
  const rivalPlayerId = localPlayerId === 1 ? 2 : 1;
  if (mode === 'online') {
    try { acquireGlobalGameplayPause(RPS_INITIATIVE_GAMEPLAY_PAUSE_TOKEN); } catch (_) {}
    try { hideBattleInactivityPrompt('initiative-rps-open'); } catch (_) {}
    try { markBattleActivity('initiative-rps-open'); } catch (_) {}
  }
  const root = ensureRpsInitiativeOverlay();
  const flyer = root.querySelector('#rpsInitiativeFlyer');
  const result = root.querySelector('#rpsInitiativeResult');
  const rivalLocked = root.querySelector('#rpsRivalLockedCard');
  const localLocked = root.querySelector('#rpsLocalLockedCard');
  const duel = root.querySelector('#rpsInitiativeDuel');
  root.classList.remove('resolving', 'revealed');
  root.classList.add('open');
  root.setAttribute('aria-hidden', 'false');
  if (flyer) flyer.textContent = '¿QUIÉN INICIA?';
  if (result) result.textContent = '';
  setRpsLockedCard(rivalLocked, rivalPlayerId, false);
  setRpsLockedCard(localLocked, localPlayerId, false);
  duel?.classList.remove('visible');
  duel?.setAttribute('aria-hidden', 'true');
  await delayRps(680, generation);

  return new Promise(resolve => {
    rpsInitiativeRuntime.resolver = resolve;
    let localChoice = '';
    let botChoice = '';
    let resolving = false;

    const resetRoundVisuals = () => {
      if (generation !== rpsInitiativeRuntime.generation) return;
      localChoice = '';
      botChoice = '';
      resolving = false;
      root.classList.remove('resolving', 'revealed');
      const tray = root.querySelector('#rpsChoiceTray');
      tray?.classList.remove('locked');
      duel?.classList.remove('visible');
      duel?.setAttribute('aria-hidden', 'true');
      setRpsLockedCard(rivalLocked, rivalPlayerId, false);
      setRpsLockedCard(localLocked, localPlayerId, false);
      if (result) result.textContent = '';
      renderRpsChoiceTray(root, localPlayerId, handleLocalSelect);
      if (mode === 'bot') {
        window.setTimeout(() => {
          if (generation !== rpsInitiativeRuntime.generation || botChoice) return;
          const ids = Object.keys(RPS_INITIATIVE_CHOICES);
          botChoice = ids[Math.floor(Math.random() * ids.length)];
          setRpsLockedCard(rivalLocked, rivalPlayerId, true);
          void maybeResolveBotRound();
        }, 520 + Math.floor(Math.random() * 650));
      }
    };

    const finishWinner = async winner => {
      if (generation !== rpsInitiativeRuntime.generation) return;
      if (result) result.textContent = `JUGADOR ${winner} INICIA`;
      await delayRps(1280, generation);
      if (generation !== rpsInitiativeRuntime.generation) return;
      const resolver = rpsInitiativeRuntime.resolver;
      rpsInitiativeRuntime.resolver = null;
      rpsInitiativeRuntime.active = false;
      root.classList.remove('open', 'resolving', 'revealed');
      root.setAttribute('aria-hidden', 'true');
      if (rpsInitiativeRuntime.pollTimer) clearInterval(rpsInitiativeRuntime.pollTimer);
      rpsInitiativeRuntime.pollTimer = null;
      if (mode === 'online') {
        try { releaseGlobalGameplayPause(RPS_INITIATIVE_GAMEPLAY_PAUSE_TOKEN); } catch (_) {}
        try { markBattleActivity('initiative-rps-complete'); } catch (_) {}
      }
      try { resolver?.(winner); } catch (_) {}
    };

    const processRound = async (p1Choice, p2Choice) => {
      if (resolving || generation !== rpsInitiativeRuntime.generation) return;
      if (!getRpsChoice(p1Choice) || !getRpsChoice(p2Choice)) return;
      resolving = true;
      await animateRpsReveal(root, p1Choice, p2Choice, localPlayerId, generation);
      if (generation !== rpsInitiativeRuntime.generation) return;
      const winner = resolveRpsInitiativeChoice(p1Choice, p2Choice);
      if (!winner) {
        if (result) result.textContent = 'EMPATE';
        await delayRps(1050, generation);
        if (generation !== rpsInitiativeRuntime.generation) return;
        rpsInitiativeRuntime.round += 1;
        if (mode === 'online') {
          try { await window.ROK_ONLINE_PVP?.prepareInitiativeRound?.(rpsInitiativeRuntime.round, rpsInitiativeRuntime.matchSerial); } catch (_) {}
        }
        resetRoundVisuals();
        return;
      }
      await finishWinner(winner);
    };

    const maybeResolveBotRound = async () => {
      if (!localChoice || !botChoice || resolving) return;
      const p1 = localPlayerId === 1 ? localChoice : botChoice;
      const p2 = localPlayerId === 1 ? botChoice : localChoice;
      await processRound(p1, p2);
    };

    const pollOnline = async () => {
      if (mode !== 'online' || resolving || generation !== rpsInitiativeRuntime.generation) return;
      const info = window.ROK_ONLINE_PVP?.getInitiativeState?.(rpsInitiativeRuntime.round, rpsInitiativeRuntime.matchSerial);
      if (!info) return;
      const rivalChoice = localPlayerId === 1 ? info.player2Choice : info.player1Choice;
      const ownChoice = localPlayerId === 1 ? info.player1Choice : info.player2Choice;
      if (ownChoice) setRpsLockedCard(localLocked, localPlayerId, true);
      if (rivalChoice) setRpsLockedCard(rivalLocked, rivalPlayerId, true);
      if (info.player1Choice && info.player2Choice) await processRound(info.player1Choice, info.player2Choice);
    };

    async function handleLocalSelect(choiceId) {
      if (resolving || localChoice || generation !== rpsInitiativeRuntime.generation) return;
      if (!getRpsChoice(choiceId)) return;
      localChoice = choiceId;
      root.querySelector('#rpsChoiceTray')?.classList.add('locked');
      setRpsLockedCard(localLocked, localPlayerId, true);
      if (mode === 'online') {
        const ok = await window.ROK_ONLINE_PVP?.submitInitiativeChoice?.(choiceId, rpsInitiativeRuntime.round, rpsInitiativeRuntime.matchSerial);
        if (!ok) {
          localChoice = '';
          root.querySelector('#rpsChoiceTray')?.classList.remove('locked');
          setRpsLockedCard(localLocked, localPlayerId, false);
          if (result) result.textContent = 'No se pudo registrar la elección';
          return;
        }
        void pollOnline();
      } else {
        void maybeResolveBotRound();
      }
    }

    renderRpsChoiceTray(root, localPlayerId, handleLocalSelect);
    if (mode === 'online') {
      void window.ROK_ONLINE_PVP?.prepareInitiativeRound?.(1, rpsInitiativeRuntime.matchSerial).catch?.(() => {});
      rpsInitiativeRuntime.pollTimer = window.setInterval(() => { void pollOnline(); }, 140);
      void pollOnline();
    } else {
      window.setTimeout(() => {
        if (generation !== rpsInitiativeRuntime.generation || botChoice) return;
        const ids = Object.keys(RPS_INITIATIVE_CHOICES);
        botChoice = ids[Math.floor(Math.random() * ids.length)];
        setRpsLockedCard(rivalLocked, rivalPlayerId, true);
        void maybeResolveBotRound();
      }, 520 + Math.floor(Math.random() * 650));
    }
  });
}

window.ROK_INITIATIVE_RPS = {
  play: runInitiativeSelection,
  cancel: stopRpsInitiativeRuntime,
  resolve: resolveRpsInitiativeChoice,
  getState: () => ({ ...rpsInitiativeRuntime }),
};

function launchPreparedAdventureBattle() {
  const encounter = getAdventureWaterEncounter(adventureState.encounterId);
  const playerCaster = getAdventurePlayerCaster();
  const playerCasterCardId = CARD_LIBRARY[playerCaster?.cardId] && getCardTypeId(CARD_LIBRARY[playerCaster.cardId]) === 'kaster'
    ? String(playerCaster.cardId)
    : (CARD_LIBRARY[playerCaster?.id] && getCardTypeId(CARD_LIBRARY[playerCaster.id]) === 'kaster' ? String(playerCaster.id) : '');
  const payload = {
    mode: 'adventure',
    encounterId: encounter.id,
    rivalCaster: encounter,
    playerCaster,
    playerCasterCardId,
    playerSpellbookCardIds: getAdventureSpellbookCardIds(),
    arena: getAdventureBattleArena(encounter),
    arenaPreview: getAdventureArenaPreview(encounter),
  };
  window.ROK_ADVENTURE_PENDING_BATTLE = payload;
  stopVersusIntroEnergy(els.adventureBattleIntro);
  if (typeof window.ROK_ADVENTURE_START_BATTLE === 'function') {
    window.ROK_ADVENTURE_START_BATTLE(payload);
    return;
  }
  els.adventureBattleIntro?.classList.remove('active', 'counting', 'combat-ready');
  els.adventureBattleIntro?.setAttribute('aria-hidden', 'true');
  setAdventureView('prepare');
  showAdventureNotice('Presentación VS lista. El inicio real se conectará al definir el Kaster y los Spellbooks de Aventura.');
}

window.ROK_ADVENTURE = {
  markEncounterDefeated: markAdventureEncounterDefeated,
  getCasterVictoryXp: (encounterId, previousWins = 0) => getAdventureCasterVictoryXp(encounterId, previousWins),
  awardCasterExperience: (casterCardId, encounterId, previousWins = null) => awardAdventureCasterExperience(casterCardId, encounterId, previousWins),
  getVictoryRewardPreview: (encounterId, previousWins = 0, options = {}) => getAdventureVictoryRewardPreview(encounterId, previousWins, options),
  grantVictoryRewards: (encounterId, previousWins = 0, options = {}) => grantAdventureVictoryRewards(encounterId, previousWins, options),
  resolvePendingFirstVictoryCard: encounterId => resolvePendingAdventureFirstVictoryCardReward(encounterId),
  setPlayerSpellbook(cardIds = []) { adventureState.playerSpellbookCardIds = Array.isArray(cardIds) ? cardIds.filter(id => CARD_LIBRARY[id]) : []; renderAdventurePreparation(); },
  setEncounterSpellbook(encounterId, cardIds = []) {
    adventureState.encounterSpellbooks[encounterId] = Array.isArray(cardIds) ? cardIds.filter(id => CARD_LIBRARY[id]) : [];
    resolvePendingAdventureFirstVictoryCardReward(encounterId);
    renderAdventurePreparation();
  },
  getProgress: () => loadAdventureProgress(),
  getArenaForEncounter(encounterId = adventureState.encounterId) { return getAdventureBattleArena(getAdventureWaterEncounter(encounterId)); },
  getArenaPreviewForEncounter(encounterId = adventureState.encounterId) { return getAdventureArenaPreview(getAdventureWaterEncounter(encounterId)); },
};

function renderAdventureCasterStats(encounter, ready) {
  if (!els.adventureCasterStats) return;
  if (!ready || !encounter || !encounter.stats) {
    els.adventureCasterStats.innerHTML = `<div class="adventure-stats-kicker">Estadísticas</div><div class="adventure-caster-profile"><div class="adventure-caster-profile-line"><b>En desarrollo</b><span>Las estadísticas del Kaster aparecerán aquí cuando el encuentro quede definido.</span></div></div>`;
    return;
  }
  const stats = encounter.stats || {};
  const sections = Array.isArray(stats.sections) ? stats.sections : [];
  const profile = Array.isArray(stats.profile) ? stats.profile : [];
  const sectionsHtml = sections.map(section => {
    const itemsHtml = (section.items || []).map(item => {
      const max = Math.max(1, Number(item.max) || 1);
      const value = Math.max(0, Number(item.value) || 0);
      const ratio = Math.max(0, Math.min(100, (value / max) * 100));
      const display = item.display != null ? item.display : String(value);
      return `<div class="adventure-stat-row"><div class="adventure-stat-line"><span>${item.label || ''}</span><span class="adventure-stat-value">${display}</span></div><div class="adventure-stat-bar"><div class="adventure-stat-fill" style="--stat-ratio:${ratio}%;--stat-fill-from:${item.fillFrom || '#55d7ff'};--stat-fill-to:${item.fillTo || '#8cf7ff'}"></div></div></div>`;
    }).join('');
    return `<div class="adventure-stats-section"><div class="adventure-stats-section-title">${section.title || ''}</div>${itemsHtml}</div>`;
  }).join('');
  const profileHtml = profile.length ? `<div class="adventure-caster-profile">${profile.map(line => `<div class="adventure-caster-profile-line"><b>${line.label || ''}</b><span>${line.value || ''}</span></div>`).join('')}</div>` : '';
  els.adventureCasterStats.innerHTML = `<div class="adventure-stats-kicker">Ficha del Kaster</div>${sectionsHtml}${profileHtml}`;
}

function updateAdventureWaterMapFocus(point) {
  if (!els.adventureWaterMapCanvas) {
    setAdventureMarkerPosition(els.adventureWaterMarker, point);
    return;
  }
  const px = Math.max(0, Math.min(1, (Number(point && point.x) || 50) / 100));
  const py = Math.max(0, Math.min(1, (Number(point && point.y) || 50) / 100));
  const canvasW = Math.max(1, els.adventureWaterMapCanvas.clientWidth || 1);
  const canvasH = Math.max(1, els.adventureWaterMapCanvas.clientHeight || 1);
  const sourceW = 916;
  const sourceH = 1717;
  const sourceRatio = sourceW / sourceH;
  const canvasRatio = canvasW / canvasH;

  // Primero cubrimos por completo el recuadro (sin bandas negras), conservando
  // la proporción natural del mapa. Después ampliamos y desplazamos el lienzo
  // hasta que el marcador seleccionado quede dentro de la zona de enfoque.
  let coverW, coverH;
  if (canvasRatio >= sourceRatio) {
    coverW = canvasW;
    coverH = coverW / sourceRatio;
  } else {
    coverH = canvasH;
    coverW = coverH * sourceRatio;
  }
  const zoom = 1.46;
  const renderW = coverW * zoom;
  const renderH = coverH * zoom;
  const focusX = .52 * canvasW;
  const focusY = .50 * canvasH;
  let left = focusX - (px * renderW);
  let top = focusY - (py * renderH);
  left = Math.min(0, Math.max(canvasW - renderW, left));
  top = Math.min(0, Math.max(canvasH - renderH, top));

  els.adventureWaterMapCanvas.style.setProperty('--water-map-width', `${renderW}px`);
  els.adventureWaterMapCanvas.style.setProperty('--water-map-height', `${renderH}px`);
  els.adventureWaterMapCanvas.style.setProperty('--water-map-left', `${left}px`);
  els.adventureWaterMapCanvas.style.setProperty('--water-map-top', `${top}px`);
  setAdventureMarkerPosition(els.adventureWaterMarker, { x: `${left + px * renderW}px`, y: `${top + py * renderH}px` }, true);
}

function setAdventureMarkerPosition(markerEl, point, rawUnits = false) {
  if (!markerEl || !point) return;
  if (rawUnits) {
    markerEl.style.setProperty('--marker-x', String(point.x || '50%'));
    markerEl.style.setProperty('--marker-y', String(point.y || '50%'));
    return;
  }
  markerEl.style.setProperty('--marker-x', `${Number(point.x) || 50}%`);
  markerEl.style.setProperty('--marker-y', `${Number(point.y) || 50}%`);
}

function showAdventureNotice(message = '') {
  if (!els.adventureNotice) return;
  if (adventureState.noticeTimer) clearTimeout(adventureState.noticeTimer);
  els.adventureNotice.textContent = String(message || '');
  els.adventureNotice.classList.toggle('show', Boolean(message));
  if (message) {
    adventureState.noticeTimer = setTimeout(() => {
      els.adventureNotice?.classList.remove('show');
      adventureState.noticeTimer = null;
    }, 2600);
  }
}

function renderAdventureZoneList() {
  if (!els.adventureZoneList) return;
  els.adventureZoneList.innerHTML = ADVENTURE_WORLD_ZONES.map(zone => {
    const selected = zone.id === adventureState.worldZoneId;
    return `<button class="adventure-option ${zone.available ? 'available' : 'locked'}${selected ? ' selected' : ''}" type="button" role="option" aria-selected="${selected ? 'true' : 'false'}" data-adventure-zone="${zone.id}" style="--option-accent:${zone.accent};--option-accent-from:${zone.accentFrom || zone.accent};--option-accent-to:${zone.accentTo || zone.accent}">
      <span class="adventure-option-main"><span class="adventure-option-name">${zone.element}</span><span class="adventure-option-badge">${zone.available ? 'DISPONIBLE' : 'BLOQUEADA'}</span></span>
      <small>${zone.domain}</small>
    </button>`;
  }).join('');
}

function selectAdventureWorldZone(zoneId, options = {}) {
  const zone = getAdventureWorldZone(zoneId);
  adventureState.worldZoneId = zone.id;
  if (!options.skipListRender) renderAdventureZoneList();
  setAdventureMarkerPosition(els.adventureWorldMarker, zone.marker);
  if (els.adventureZoneElement) els.adventureZoneElement.textContent = String(zone.element || '').toUpperCase();
  if (els.adventureZoneName) els.adventureZoneName.textContent = zone.domain || '';
  if (els.adventureZoneDomain) els.adventureZoneDomain.textContent = `${zone.element} · ${zone.domain}`;
  if (els.adventureZoneDescription) els.adventureZoneDescription.textContent = zone.description || '';
  if (els.adventureZoneStatus) {
    els.adventureZoneStatus.textContent = zone.available ? 'DISPONIBLE' : 'BLOQUEADA';
    els.adventureZoneStatus.classList.toggle('available', zone.available);
    els.adventureZoneStatus.classList.toggle('locked', !zone.available);
  }
  if (options.notifyLocked && !zone.available) showAdventureNotice(`${zone.element} · esta región todavía no está disponible.`);
}

function renderAdventureCasterList() {
  if (!els.adventureCasterList) return;
  els.adventureCasterList.innerHTML = ADVENTURE_WATER_ENCOUNTERS.map((encounter, index) => {
    const selected = encounter.id === adventureState.encounterId;
    return `<button class="adventure-option adventure-caster-option ${encounter.available ? 'available' : 'locked'}${selected ? ' selected' : ''}" type="button" role="option" aria-selected="${selected ? 'true' : 'false'}" data-adventure-encounter="${encounter.id}" style="--option-accent:${encounter.available ? getAdventureIntroPalette(encounter)[0] : '#64727a'}">
      <span class="adventure-option-main"><span class="adventure-option-name">${index + 1}. ${encounter.label}</span><span class="adventure-option-meta"><span class="adventure-option-level">NIVEL ${Math.max(1, Number(encounter.level) || 1)}</span><span class="adventure-option-badge">${encounter.available ? 'ACTIVO' : 'PENDIENTE'}</span></span></span>
      <small>${encounter.subtitle}</small>
    </button>`;
  }).join('');
}

function selectAdventureWaterEncounter(encounterId, options = {}) {
  const encounter = getAdventureWaterEncounter(encounterId);
  adventureState.encounterId = encounter.id;
  if (!options.skipListRender) renderAdventureCasterList();
  updateAdventureWaterMapFocus(encounter.marker);

  const ready = encounter.available === true;
  if (els.adventureCasterImage) {
    els.adventureCasterImage.hidden = !ready;
    if (ready && encounter.image) els.adventureCasterImage.src = encounter.image;
    els.adventureCasterImage.alt = ready ? encounter.label : '';
    const visual = els.adventureCasterImage.parentElement;
    if (visual) {
      visual.style.setProperty('--caster-art-scale', String(encounter.imageScale || 1.72));
      visual.style.setProperty('--caster-art-shift-x', encounter.imageShiftX || '-8%');
      visual.style.setProperty('--caster-art-shift-y', encounter.imageShiftY || '14%');
    }
  }
  if (els.adventureCasterPlaceholder) els.adventureCasterPlaceholder.hidden = ready;
  renderAdventureCasterDomainPanel(encounter, ready);
  if (els.adventureCasterDomain) els.adventureCasterDomain.textContent = ready ? encounter.domain : 'AGUA · CONOCIMIENTO';
  if (els.adventureCasterName) els.adventureCasterName.textContent = encounter.label;
  if (els.adventureCasterLevel) els.adventureCasterLevel.textContent = `NIVEL ${Math.max(1, Number(encounter.level) || 1)}`;
  if (els.adventureCasterQualities) {
    // Este bloque pertenece a la FICHA DEL KASTER: aquí NO se muestran las
    // dominantes del Spellbook. Solo las cualidades propias del Kaster rival.
    els.adventureCasterQualities.innerHTML = ready
      ? (encounter.casterQualities || []).map(name => renderAdventureQualityTag(name)).join('')
      : renderAdventureIdentityTag({ label: 'Por definir', muted: true });
  }
  renderAdventureCasterStats(encounter, ready);
  if (els.adventureCasterDeckTitle) els.adventureCasterDeckTitle.textContent = ready ? encounter.deckTitle : 'Encuentro en desarrollo';
  if (els.adventureCasterDescription) els.adventureCasterDescription.textContent = ready
    ? encounter.description
    : 'Este punto de combate queda reservado para uno de los próximos Kasters de la región de Agua. Su identidad, Spellbook y arena temática se añadirán cuando queden definidos.';
  if (els.adventureCasterRoles) {
    els.adventureCasterRoles.innerHTML = ready
      ? (encounter.roles || []).map(role => renderAdventureRolePill(role)).join('')
      : '';
  }
  if (els.adventureCasterStatus) {
    els.adventureCasterStatus.textContent = ready ? 'DISPONIBLE' : 'PENDIENTE';
    els.adventureCasterStatus.classList.toggle('available', ready);
    els.adventureCasterStatus.classList.toggle('locked', !ready);
  }
  if (options.notifyLocked && !ready) showAdventureNotice('Este encuentro todavía no ha sido definido.');
}

function setAdventureView(view = 'world') {
  adventureState.view = ['water', 'prepare'].includes(view) ? view : 'world';
  const water = adventureState.view === 'water';
  const prepare = adventureState.view === 'prepare';
  const world = adventureState.view === 'world';
  if (els.adventureWorldView) els.adventureWorldView.hidden = !world;
  if (els.adventureWaterView) els.adventureWaterView.hidden = !water;
  if (els.adventurePrepareView) els.adventurePrepareView.hidden = !prepare;
  if (els.adventureTitle) els.adventureTitle.textContent = prepare ? 'Preparar combate' : (water ? 'Área de Agua' : 'Regiones elementales');
  if (els.adventureSubtitle) els.adventureSubtitle.textContent = prepare
    ? 'Confirma tu Kaster, revisa el Spellbook y conoce la arena antes del enfrentamiento.'
    : (water ? 'Selecciona un enfrentamiento para conocer al Kaster rival y localizar su arena.' : 'Explora el continente y elige la región donde comenzará tu travesía.');
  if (els.adventureProgressChip) els.adventureProgressChip.textContent = prepare ? 'ETAPA 3 · PREPARACIÓN' : (water ? 'ETAPA 2 · AGUA' : 'ETAPA 1 · REGIONES');
  if (els.adventureBackBtn) {
    els.adventureBackBtn.textContent = prepare ? 'Enfrentamientos' : 'Regiones';
    els.adventureBackBtn.hidden = world;
  }
  if (els.adventureHomeBtn) els.adventureHomeBtn.hidden = false;
  if (prepare) renderAdventurePreparation();
  else if (water) selectAdventureWaterEncounter(adventureState.encounterId);
  else selectAdventureWorldZone(adventureState.worldZoneId);
}

function openAdventureScreen() {
  document.body.classList.remove('rok-menu-mode', 'rok-battle-mode', 'rok-library-mode', 'rok-spellbooks-mode', 'rok-card-creator-mode');
  document.body.classList.add('rok-adventure-mode');
  clearBattleHudForInactiveScreen();
  closeBotMatchModeSelector();
  closeMatchSpellbookSelector();
  if (els.mainMenuScreen) els.mainMenuScreen.setAttribute('aria-hidden', 'true');
  if (els.libraryBuilderScreen) els.libraryBuilderScreen.setAttribute('aria-hidden', 'true');
  if (els.spellbooksCollectionScreen) els.spellbooksCollectionScreen.setAttribute('aria-hidden', 'true');
  if (els.adventureScreen) els.adventureScreen.setAttribute('aria-hidden', 'false');
  adventureState.worldZoneId = 'water';
  adventureState.encounterId = 'enigma-apprentice';
  setAdventureView('world');
  renderAdventureZoneList();
  renderAdventureCasterList();
  showAdventureNotice('');
}

function closeAdventureScreen() {
  if (els.adventureScreen) els.adventureScreen.setAttribute('aria-hidden', 'true');
  showMainMenu();
}

function handleAdventureBack() {
  if (adventureState.view === 'prepare') {
    setAdventureView('water');
    return;
  }
  if (adventureState.view === 'water') {
    setAdventureView('world');
    return;
  }
  closeAdventureScreen();
}

function enterSelectedAdventureZone() {
  const zone = getAdventureWorldZone(adventureState.worldZoneId);
  if (!zone.available || zone.id !== 'water') {
    showAdventureNotice(`${zone.element} · esta región todavía no está disponible.`);
    return;
  }
  setAdventureView('water');
}

function prepareSelectedAdventureEncounter() {
  const encounter = getAdventureWaterEncounter(adventureState.encounterId);
  if (!encounter.available) {
    showAdventureNotice('Este encuentro todavía no ha sido definido.');
    return;
  }
  setAdventureView('prepare');
}

function showMainMenu() {
  if (typeof closeCardCreatorMode === 'function') closeCardCreatorMode();
  document.body.classList.add('rok-menu-mode');
  document.body.classList.remove('rok-battle-mode', 'rok-library-mode', 'rok-spellbooks-mode', 'rok-card-creator-mode', 'rok-adventure-mode');
  clearBattleHudForInactiveScreen();
  closeSpellbookNameModal();
  closeSpellbookElementModal();
  closeSpellbookElementWarningModal();
  closeCasterChangeModal();
  closeBotMatchModeSelector();
  closeMatchSpellbookSelector();
  if (els.mainMenuScreen) els.mainMenuScreen.setAttribute('aria-hidden', 'false');
  if (els.adventureScreen) els.adventureScreen.setAttribute('aria-hidden', 'true');
  if (els.libraryBuilderScreen) els.libraryBuilderScreen.setAttribute('aria-hidden', 'true');
  if (els.spellbooksCollectionScreen) els.spellbooksCollectionScreen.setAttribute('aria-hidden', 'true');
  updateRokUserModeUi();
  updateRokPureCrystalUi();
  if (els.mainMenuNotice) els.mainMenuNotice.textContent = isRokUserModeActive()
    ? 'Modo Usuario activo · colección local habilitada.'
    : '';
}

function reportGameException(error, label = 'Juego') {
  try { window.ROK_DEBUG_RIBBON?.showException?.(error, label); } catch (_) {}
  try { console.error('[ROK GAME ERROR]', label, error); } catch (_) {}
}

function reportDebugError(label = 'Juego', error = null) {
  // Compatibilidad con los catch históricos: el reporter recibe (label, error),
  // mientras reportGameException utiliza (error, label). Nunca debe lanzar otro
  // error desde un catch ni ocultar la excepción original.
  reportGameException(error, `DEBUG · ${label || 'Juego'}`);
  return error;
}

function runGameStep(label, fn) {
  try { return fn(); }
  catch (error) {
    reportGameException(error, label);
    throw error;
  }
}

function safeRenderStep(label, fn) {
  try { return fn(); }
  catch (error) {
    reportGameException(error, 'renderAll · ' + label);
    return null;
  }
}

function openBotMatchModeSelector() {
  if (!els.botMatchModeModal) {
    openMatchSpellbookSelector('bot');
    return;
  }
  els.botMatchModeModal.classList.add('open');
  els.botMatchModeModal.setAttribute('aria-hidden', 'false');
}

function closeBotMatchModeSelector() {
  if (!els.botMatchModeModal) return;
  els.botMatchModeModal.classList.remove('open');
  els.botMatchModeModal.setAttribute('aria-hidden', 'true');
}

function chooseBotMatchMode(mode = 'normal') {
  closeBotMatchModeSelector();
  openMatchSpellbookSelector(mode === TEST_MATCH_MODE_ID ? 'bot-test' : 'bot');
}

function isTestMatchActive() {
  return state.matchMode === TEST_MATCH_MODE_ID;
}

function configureTestBotPlayer(playerId = 2) {
  const player = state.players?.[playerId];
  if (!player) return false;
  player.selectedSpellbookId = 'rok-test-bot-shirahadori';
  player.spellbookName = 'Bot de prueba · Shirahadori';
  player.handTabs = [
    [
      TEST_BOT_KAGERO_CARD_ID,
      TEST_BOT_KAGERO_CARD_ID,
      TEST_BOT_KAGERO_CARD_ID,
      TEST_BOT_SHIRAHADORI_CARD_ID,
      TEST_BOT_SHIRAHADORI_CARD_ID,
      TEST_BOT_SHIRAHADORI_CARD_ID,
      ...Array(6).fill(null),
    ],
    Array(12).fill(null),
    Array(12).fill(null),
  ];
  player.castQueue = [];
  player.units = [];
  player.spawnMarkers = [];
  player.spellbookUseCooldowns = {};
  player.spellbookCardStates = {};
  player.spellbookCardInstances = {};
  player.testBotShirahadoriPlan = {
    openingStarted: false,
    openingComplete: false,
    kageroCastCount: 0,
    shirahadoriAppliedCount: 0,
  };
  // Limpia el escenario antiguo por si el estado se reutiliza durante desarrollo.
  delete player.testBotInterceptarPlan;
  return true;
}

function grantTestMatchResources(playerId) {
  const player = state.players?.[playerId];
  if (!player) return;
  const resourceElements = ELEMENTS.filter(element => element.id !== CATALYST_DOMAIN_ID);
  player.resources = [];
  resourceElements.forEach((element, elementIndex) => {
    for (let copy = 0; copy < TEST_MATCH_RESOURCE_COPIES_PER_ELEMENT; copy += 1) {
      player.resources.push({
        ...element,
        icon: getElementCostIcon(element.id),
        uid: `test_${playerId}_${element.id}_${copy}_${Date.now()}`,
        createdAt: Date.now() + (elementIndex * 1000) + copy,
      });
    }
  });
}

function prepareTestMatchRuntime() {
  configureTestBotPlayer(2);
  grantTestMatchResources(1);
  grantTestMatchResources(2);
}

function startBotBattleFromMainMenu(selectedLoadout = null, options = {}) {
  try {
    if (!selectedLoadout) {
      openMatchSpellbookSelector('bot');
      return;
    }
    const issue = getSpellbookMatchIssue(selectedLoadout);
    if (issue) throw new Error(issue);

    const resolvedMatchMode = options.matchMode === TEST_MATCH_MODE_ID ? TEST_MATCH_MODE_ID : 'normal';
    if (options.skipVersusIntro !== true) {
      const rivalLoadout = getBotVersusIntroLoadout(resolvedMatchMode);
      const localCasterName = getVersusIntroCasterName(selectedLoadout, 'Tu Kaster');
      const rivalCasterName = getVersusIntroCasterName(rivalLoadout, 'Kaster rival');
      const shown = showLocalVersusIntro({
        localLoadout: selectedLoadout,
        rivalLoadout,
        localDisplayName: localCasterName,
        rivalDisplayName: rivalCasterName,
        localKicker: resolvedMatchMode === TEST_MATCH_MODE_ID ? 'PRÁCTICA · JUGADOR' : 'JUGADOR',
        rivalKicker: resolvedMatchMode === TEST_MATCH_MODE_ID ? 'BOT DE PRÁCTICA' : 'BOT',
        arena: ROK_ARENA_REGISTRY.classic,
        duration: 6200,
        onComplete: () => startBotBattleFromMainMenu(selectedLoadout, {
          ...options,
          matchMode: resolvedMatchMode,
          skipVersusIntro: true,
        }),
      });
      if (shown) return;
    }

    window.ROK_ONLINE_PVP?.leaveRoom?.({ silent: true, keepMenu: true });
    ROK_ONLINE_MATCH_ACTIVE = false;
    LOCAL_PLAYER_ID = 1;
    resetBattleStateForSelectedMatch(true);
    state.matchMode = resolvedMatchMode;
    applySpellbookLoadoutToPlayer(1, selectedLoadout);
    applyEffectiveCasterStatsToRuntimePlayer(2);
    if (isTestMatchActive()) configureTestBotPlayer(2);
    document.body.classList.remove('rok-menu-mode', 'rok-library-mode', 'rok-spellbooks-mode');
    document.body.classList.add('rok-battle-mode');
    if (els.mainMenuScreen) els.mainMenuScreen.setAttribute('aria-hidden', 'true');
    if (els.libraryBuilderScreen) els.libraryBuilderScreen.setAttribute('aria-hidden', 'true');
    if (els.spellbooksCollectionScreen) els.spellbooksCollectionScreen.setAttribute('aria-hidden', 'true');
    mainMenuBattleStarted = true;
    resetBattleInactivityRuntime('bot-battle-start');
    runGameStep('startBotBattle · updateHudModeUi', updateHudModeUi);
    runGameStep('startBotBattle · initializeElementDecks', initializeElementDecks);
    runGameStep('startBotBattle · renderAll pre-iniciativa', renderAll);
    void runInitiativeSelection({ mode: 'bot', localPlayerId: 1, matchSerial: state.matchSerial }).then(async winner => {
      if (!winner || !mainMenuBattleStarted) return;
      state.activePlayer = winner;
      if (isTestMatchActive()) {
        runGameStep('startBotBattle · prepareTestMatchRuntime', prepareTestMatchRuntime);
      } else {
        runGameStep('startBotBattle · prepareStartingElementStocks', prepareStartingElementStocks);
      }
      runGameStep('startBotBattle · enterPhase inicial', () => enterPhase(true, true));
      runGameStep('startBotBattle · renderAll inicial', renderAll);
      if (isTestMatchActive()) {
        const introTransitions = [{ text: 'EXTRACCIÓN', playerId: winner, duration: 900 }];
        runGameStep('startBotBattle · queueTransitions', () => queueTransitions(introTransitions));
        runGameStep('startBotBattle · schedulePhaseStartActions', () => schedulePhaseStartActions(sumTransitionDurations(introTransitions) - 120));
      } else {
        await playOpeningElementIntro();
        schedulePhaseStartActions(0);
      }
    });
  } catch (error) {
    reportGameException(error, 'Iniciar batalla con Spellbook');
    showMainMenu();
    if (els.mainMenuNotice) els.mainMenuNotice.textContent = error?.message || 'No se pudo cargar el Spellbook seleccionado.';
  }
}

function showMainMenuComingSoon(label) {
  if (!els.mainMenuNotice) return;
  els.mainMenuNotice.textContent = `${label} · próximamente`;
  els.mainMenuNotice.classList.remove('pulse');
  void els.mainMenuNotice.offsetWidth;
  els.mainMenuNotice.classList.add('pulse');
}


function openLibraryBuilderScreen(options = {}) {
  closeCardCreatorMode();
  updateRokPureCrystalUi();
  const mode = options.mode || 'idle';
  if (mode === 'new') beginNewSpellbook();
  else if (mode === 'edit' && options.spellbook) loadSpellbookIntoBuilder(options.spellbook);
  else if (mode === 'draft') restoreLibraryBuilderDraft();
  else if (mode === 'idle') setLibraryBuilderIdle();

  document.body.classList.remove('rok-menu-mode', 'rok-battle-mode', 'rok-spellbooks-mode');
  document.body.classList.add('rok-library-mode');
  clearBattleHudForInactiveScreen();
  if (els.mainMenuScreen) els.mainMenuScreen.setAttribute('aria-hidden', 'true');
  if (els.spellbooksCollectionScreen) els.spellbooksCollectionScreen.setAttribute('aria-hidden', 'true');
  if (els.libraryBuilderScreen) els.libraryBuilderScreen.setAttribute('aria-hidden', 'false');
  renderLibraryBuilder();
}

function getLibraryBuilderComparableSnapshot() {
  return JSON.stringify({
    casterCardId: libraryBuilderState.casterCardId || null,
    spellbookName: String(libraryBuilderState.spellbookName || '').trim(),
    spellbookCards: normalizeSpellbookCardSlots(libraryBuilderState.spellbookCards),
    elementDistribution: normalizeSpellbookElementDistribution(libraryBuilderState.elementDistribution),
    elementDistributionConfigured: libraryBuilderState.elementDistributionConfigured === true,
  });
}

function getSavedSpellbookComparableSnapshot(spellbook) {
  const normalized = normalizeSavedSpellbook(spellbook);
  if (!normalized) return null;
  return JSON.stringify({
    casterCardId: normalized.casterCardId || null,
    spellbookName: String(normalized.name || '').trim(),
    spellbookCards: normalizeSpellbookCardSlots(normalized.cards),
    elementDistribution: normalizeSpellbookElementDistribution(normalized.elementDistribution),
    elementDistributionConfigured: normalized.elementDistributionConfigured === true,
  });
}

function hasUnsavedLibraryBuilderChanges() {
  if (isCardCreatorModeActive()) return false;
  if (libraryBuilderState.mode !== 'build' && libraryBuilderState.mode !== 'selectCaster') return false;
  if (!libraryBuilderState.currentSpellbookId) return true;
  const saved = getSavedSpellbookById(libraryBuilderState.currentSpellbookId);
  if (!saved) return true;
  if (libraryBuilderState.changingCaster) return true;
  return getLibraryBuilderComparableSnapshot() !== getSavedSpellbookComparableSnapshot(saved);
}

function closeLibraryBuilderExitModal() {
  libraryBuilderExitDestination = null;
  if (els.libraryBuilderExitModal) els.libraryBuilderExitModal.setAttribute('aria-hidden', 'true');
  if (els.libraryBuilderExitNotice) els.libraryBuilderExitNotice.textContent = '';
}

function leaveLibraryBuilderImmediately(destination = 'menu') {
  const target = destination || 'menu';
  libraryBuilderExitDestination = null;
  libraryBuilderExitAfterSave = null;
  if (els.libraryBuilderExitModal) els.libraryBuilderExitModal.setAttribute('aria-hidden', 'true');
  closeCardInfoSpellbookTargetModal?.();
  closeCardInfo?.();
  closeSpellbookNameModal?.();
  closeSpellbookElementModal?.();
  closeSpellbookElementWarningModal?.();
  closeCasterChangeModal?.();
  clearLibraryBuilderDraft();
  setLibraryBuilderIdle();
  hideBattleScoreDebugToggleButton();
  if (target === 'spellbooks') openSpellbooksCollectionScreen();
  else showMainMenu();
}

function requestLeaveLibraryBuilder(destination = 'menu') {
  if (!hasUnsavedLibraryBuilderChanges()) {
    leaveLibraryBuilderImmediately(destination);
    return;
  }
  libraryBuilderExitDestination = destination || 'menu';
  const canSave = libraryBuilderState.mode === 'build' && Boolean(getCurrentBuilderCaster());
  if (els.libraryBuilderExitCopy) {
    const verb = libraryBuilderState.currentSpellbookId ? 'editando' : 'creando';
    els.libraryBuilderExitCopy.textContent = `Estás ${verb} “${libraryBuilderState.spellbookName || 'Nuevo Spellbook'}”. ¿Deseas guardar los cambios antes de salir?`;
  }
  if (els.libraryBuilderExitSaveBtn) {
    els.libraryBuilderExitSaveBtn.disabled = !canSave;
    els.libraryBuilderExitSaveBtn.title = canSave ? 'Guardar el Spellbook y salir.' : 'Selecciona primero un Kaster para poder guardar.';
  }
  if (els.libraryBuilderExitNotice) {
    els.libraryBuilderExitNotice.textContent = canSave ? '' : 'Todavía no hay un Kaster seleccionado. Puedes cancelar o salir sin guardar.';
  }
  if (els.libraryBuilderExitModal) els.libraryBuilderExitModal.setAttribute('aria-hidden', 'false');
}

function confirmLibraryBuilderExitWithoutSaving() {
  const destination = libraryBuilderExitDestination || 'menu';
  leaveLibraryBuilderImmediately(destination);
}

function saveLibraryBuilderAndExit() {
  const destination = libraryBuilderExitDestination || 'menu';
  if (libraryBuilderState.mode !== 'build' || !getCurrentBuilderCaster()) {
    if (els.libraryBuilderExitNotice) els.libraryBuilderExitNotice.textContent = 'Selecciona primero un Kaster para poder guardar.';
    return;
  }
  libraryBuilderExitAfterSave = destination;
  if (els.libraryBuilderExitModal) els.libraryBuilderExitModal.setAttribute('aria-hidden', 'true');
  libraryBuilderExitDestination = null;
  if (!requestSaveCurrentSpellbook()) {
    libraryBuilderExitAfterSave = null;
    libraryBuilderExitDestination = destination;
    if (els.libraryBuilderExitModal) els.libraryBuilderExitModal.setAttribute('aria-hidden', 'false');
    if (els.libraryBuilderExitNotice) els.libraryBuilderExitNotice.textContent = 'No se pudo iniciar el guardado. Revisa el aviso del constructor.';
  }
}

function closeLibraryBuilderScreen() {
  requestLeaveLibraryBuilder('menu');
}

function openSpellbooksCollectionScreen(message = '') {
  updateRokPureCrystalUi();
  document.body.classList.remove('rok-menu-mode', 'rok-battle-mode', 'rok-library-mode');
  document.body.classList.add('rok-spellbooks-mode');
  clearBattleHudForInactiveScreen();
  closeSpellbookNameModal();
  closeSpellbookElementModal();
  closeSpellbookElementWarningModal();
  closeCasterChangeModal();
  if (els.mainMenuScreen) els.mainMenuScreen.setAttribute('aria-hidden', 'true');
  if (els.libraryBuilderScreen) els.libraryBuilderScreen.setAttribute('aria-hidden', 'true');
  if (els.spellbooksCollectionScreen) els.spellbooksCollectionScreen.setAttribute('aria-hidden', 'false');
  renderSpellbooksCollection();
  showSpellbooksCollectionNotice(message);
}

function closeSpellbooksCollectionScreen() {
  showMainMenu();
}


function isBattleHudScreenActive() {
  return document.body.classList.contains('rok-battle-mode')
    && !document.body.classList.contains('rok-menu-mode')
    && !document.body.classList.contains('rok-library-mode');
}

function clearBattleHudForInactiveScreen() {
  try { resetBattleInactivityRuntime?.('screen-change'); } catch (_) {}
  try { clearCombatMenus?.(); } catch (_) {}
  try { closeGioshoninSupplyPrompt?.('screen-change', { silent: true }); } catch (_) {}
  try { closeQuickReactionModal?.('screen-change'); } catch (_) {}
  try { hideQuickReactionWindow?.(); } catch (_) {}
  if (els.targetAccessPanel) els.targetAccessPanel.classList.remove('visible');
  if (els.opponentThinkingNotice) {
    els.opponentThinkingNotice.classList.remove('visible', 'thinking-calibration-pinned');
    els.opponentThinkingNotice.setAttribute('aria-hidden', 'true');
  }
  if (els.hudOverlayLayer) els.hudOverlayLayer.classList.remove('active');
}

function startLibraryBuilderTestBattle() {
  try {
    if (libraryBuilderState.mode !== 'build' || !libraryBuilderState.casterCardId) {
      showLibraryBuilderNotice('Primero crea o abre un Spellbook.');
      return;
    }
    const testLoadout = {
      id: libraryBuilderState.currentSpellbookId || 'spellbook_builder_test',
      name: libraryBuilderState.spellbookName || 'Spellbook de prueba',
      casterCardId: libraryBuilderState.casterCardId,
      cards: normalizeSpellbookCardSlots(libraryBuilderState.spellbookCards),
      elementDistribution: normalizeSpellbookElementDistribution(libraryBuilderState.elementDistribution),
      elementDistributionConfigured: libraryBuilderState.elementDistributionConfigured === true,
      schemaVersion: SPELLBOOK_SCHEMA_VERSION,
    };
    const issue = getSpellbookMatchIssue(testLoadout);
    if (issue) {
      showLibraryBuilderNotice(issue);
      return;
    }
    if (els.libraryBuilderScreen) els.libraryBuilderScreen.setAttribute('aria-hidden', 'true');
    closeCardMetaInfo?.();
    closeCardInfo?.();
    startBotBattleFromMainMenu(testLoadout);
  } catch (error) {
    reportGameException(error, 'Botón Probar');
  }
}

function showLibraryBuilderNotice(message) {
  if (!els.libraryBuilderNotice) return;
  els.libraryBuilderNotice.textContent = message || '';
  els.libraryBuilderNotice.classList.remove('pulse');
  void els.libraryBuilderNotice.offsetWidth;
  els.libraryBuilderNotice.classList.add('pulse');
}

function safeLocalStorageGet(key) {
  try { return window.localStorage.getItem(key); }
  catch (error) {
    console.warn('[ROK Spellbooks] No se pudo leer localStorage.', error);
    return null;
  }
}

function safeLocalStorageSet(key, value) {
  try {
    window.localStorage.setItem(key, value);
    return true;
  } catch (error) {
    reportGameException(error, 'Guardar Spellbook en navegador');
    return false;
  }
}

function safeLocalStorageRemove(key) {
  try { window.localStorage.removeItem(key); }
  catch (error) { console.warn('[ROK Spellbooks] No se pudo borrar localStorage.', error); }
}


const VS_LAYOUT_CALIBRATION_STORAGE_KEY = 'rokLite.vsLayoutCalibration.v1';
const VS_LAYOUT_CSS_START = '/* ROK VS LAYOUT CALIBRATION START */';
const VS_LAYOUT_CSS_END = '/* ROK VS LAYOUT CALIBRATION END */';
const VS_LAYOUT_UNIVERSAL_STORAGE_KEY = 'rokLite.vsLayoutUniversal.v2';
const VS_LAYOUT_UNIVERSAL_LEGACY_STORAGE_KEY = 'rokLite.vsLayoutUniversal.v1';
const VS_LAYOUT_UNIVERSAL_CSS_START = '/* ROK VS LAYOUT UNIVERSAL START */';
const VS_LAYOUT_UNIVERSAL_CSS_END = '/* ROK VS LAYOUT UNIVERSAL END */';
const VS_LAYOUT_GRID_CSS_START = '/* ROK VS GUIDE GRID START */';
const VS_LAYOUT_GRID_CSS_END = '/* ROK VS GUIDE GRID END */';
const vsLayoutEditorState = {
  activeKind: '',
  activeKey: '',
  activeEntity: null,
  casterKey: '',
  invocationKey: '',
  cssFileHandle: null,
  catalog: { kasters: [], invocations: [] },
};

const VS_LAYOUT_GRID_STORAGE_KEY = 'rokLite.vsLayoutGuideGrid.v1';
const VS_LAYOUT_GRID_COLS = 16;
const VS_LAYOUT_GRID_ROWS = 18;
const VS_LAYOUT_GRID_COLOR_NAMES = new Set(['cyan', 'gold', 'magenta', 'green']);
const vsLayoutGridState = {
  visible: false,
  paintEnabled: false,
  color: 'cyan',
  painting: false,
  dirty: false,
  cells: {},
};

const vsLayoutUniversalState = {
  kaster: { scale: 1, x: 0, y: 0 },
  invocation: { scale: 1, x: 0, y: 0 },
};
let vsLayoutUniversalLoaded = false;

function loadVsLayoutCalibrationMap() {
  try {
    const raw = safeLocalStorageGet(VS_LAYOUT_CALIBRATION_STORAGE_KEY);
    const parsed = raw ? JSON.parse(raw) : {};
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
  } catch (_) {
    return {};
  }
}

function saveVsLayoutCalibrationMap(map) {
  return safeLocalStorageSet(VS_LAYOUT_CALIBRATION_STORAGE_KEY, JSON.stringify(map || {}));
}

function normalizeVsLayoutCalibration(value = null) {
  const source = value && typeof value === 'object' ? value : {};
  return {
    scale: Math.max(0.35, Math.min(1.8, Number(source.scale || 1))),
    x: Math.max(-320, Math.min(320, Math.round(Number(source.x || 0)))),
    y: Math.max(-260, Math.min(260, Math.round(Number(source.y || 0)))),
  };
}

function normalizeVsLayoutUniversal(value = null) {
  const source = value && typeof value === 'object' ? value : {};
  return {
    scale: Math.max(0.6, Math.min(1.4, Number(source.scale || 1))),
    x: Math.max(-320, Math.min(320, Math.round(Number(source.x || 0)))),
    y: Math.max(-260, Math.min(260, Math.round(Number(source.y || 0)))),
  };
}

function normalizeVsLayoutUniversalBundle(value = null) {
  const source = value && typeof value === 'object' ? value : {};
  const legacyFlat = ('scale' in source || 'x' in source || 'y' in source) ? normalizeVsLayoutUniversal(source) : null;
  return {
    kaster: normalizeVsLayoutUniversal(source.kaster || legacyFlat),
    invocation: normalizeVsLayoutUniversal(source.invocation || legacyFlat),
  };
}

function getVsLayoutUniversalKindFromKey(key = '') {
  return String(key || '').startsWith('invocation:') ? 'invocation' : 'kaster';
}

function readVsLayoutUniversalFromComputedCss() {
  try {
    const computed = window.getComputedStyle(document.documentElement);
    const legacy = normalizeVsLayoutUniversal({
      scale: Number.parseFloat(computed.getPropertyValue('--vs-layout-universal-scale')) || 1,
      x: Number.parseFloat(computed.getPropertyValue('--vs-layout-universal-x')) || 0,
      y: Number.parseFloat(computed.getPropertyValue('--vs-layout-universal-y')) || 0,
    });
    const readKind = kind => normalizeVsLayoutUniversal({
      scale: Number.parseFloat(computed.getPropertyValue(`--vs-layout-universal-${kind}-scale`)) || legacy.scale,
      x: Number.parseFloat(computed.getPropertyValue(`--vs-layout-universal-${kind}-x`)) || legacy.x,
      y: Number.parseFloat(computed.getPropertyValue(`--vs-layout-universal-${kind}-y`)) || legacy.y,
    });
    return { kaster: readKind('kaster'), invocation: readKind('invocation') };
  } catch (_) {
    return normalizeVsLayoutUniversalBundle(null);
  }
}

function loadVsLayoutUniversalState() {
  let value = null;
  try {
    const raw = safeLocalStorageGet(VS_LAYOUT_UNIVERSAL_STORAGE_KEY);
    value = raw ? JSON.parse(raw) : null;
    if (!value) {
      const legacyRaw = safeLocalStorageGet(VS_LAYOUT_UNIVERSAL_LEGACY_STORAGE_KEY);
      value = legacyRaw ? JSON.parse(legacyRaw) : null;
    }
  } catch (_) { value = null; }
  const normalized = normalizeVsLayoutUniversalBundle(value || readVsLayoutUniversalFromComputedCss());
  vsLayoutUniversalState.kaster = normalized.kaster;
  vsLayoutUniversalState.invocation = normalized.invocation;
  vsLayoutUniversalLoaded = true;
  return normalizeVsLayoutUniversalBundle(vsLayoutUniversalState);
}

function saveVsLayoutUniversalState(value = vsLayoutUniversalState) {
  const normalized = normalizeVsLayoutUniversalBundle(value);
  vsLayoutUniversalState.kaster = normalized.kaster;
  vsLayoutUniversalState.invocation = normalized.invocation;
  vsLayoutUniversalLoaded = true;
  return safeLocalStorageSet(VS_LAYOUT_UNIVERSAL_STORAGE_KEY, JSON.stringify(normalized));
}

function getVsLayoutUniversalBundle() {
  if (!vsLayoutUniversalLoaded) loadVsLayoutUniversalState();
  return normalizeVsLayoutUniversalBundle(vsLayoutUniversalState);
}

function getVsLayoutUniversalState(kind = 'kaster') {
  const bundle = getVsLayoutUniversalBundle();
  return normalizeVsLayoutUniversal(kind === 'invocation' ? bundle.invocation : bundle.kaster);
}

function applyVsLayoutUniversalToRoot(value = vsLayoutUniversalState) {
  const normalized = normalizeVsLayoutUniversalBundle(value);
  vsLayoutUniversalState.kaster = normalized.kaster;
  vsLayoutUniversalState.invocation = normalized.invocation;
  vsLayoutUniversalLoaded = true;
  const root = document.documentElement;
  if (!root) return normalized;
  ['kaster', 'invocation'].forEach(kind => {
    const entry = normalized[kind];
    root.style.setProperty(`--vs-layout-universal-${kind}-scale`, String(entry.scale));
    root.style.setProperty(`--vs-layout-universal-${kind}-x`, `${entry.x}px`);
    root.style.setProperty(`--vs-layout-universal-${kind}-y`, `${entry.y}px`);
  });
  return normalized;
}

function combineVsLayoutCalibration(individualValue = null, universalValue = null) {
  const individual = normalizeVsLayoutCalibration(individualValue);
  const universal = normalizeVsLayoutUniversal(universalValue);
  return {
    scale: Math.max(0.2, Math.min(2.4, individual.scale * universal.scale)),
    x: individual.x + universal.x,
    xMirror: -(individual.x + universal.x),
    y: individual.y + universal.y,
  };
}

function hasStoredVsLayoutCalibration(key = '') {
  const map = loadVsLayoutCalibrationMap();
  return Object.prototype.hasOwnProperty.call(map, String(key || ''));
}

function readVsLayoutCalibrationFromElement(element, key = '') {
  if (!element || !key) return normalizeVsLayoutCalibration(null);
  const map = loadVsLayoutCalibrationMap();
  if (Object.prototype.hasOwnProperty.call(map, key)) return normalizeVsLayoutCalibration(map[key]);

  element.dataset.vsLayoutKey = key;
  element.style.removeProperty('--vs-layout-scale');
  element.style.removeProperty('--vs-layout-x');
  element.style.removeProperty('--vs-layout-x-mirror');
  element.style.removeProperty('--vs-layout-y');
  const computed = window.getComputedStyle(element);
  const scale = Number.parseFloat(computed.getPropertyValue('--vs-layout-scale')) || 1;
  const x = Number.parseFloat(computed.getPropertyValue('--vs-layout-x')) || 0;
  const y = Number.parseFloat(computed.getPropertyValue('--vs-layout-y')) || 0;
  return normalizeVsLayoutCalibration({ scale, x, y });
}

function loadVsLayoutGuideGridState() {
  try {
    const raw = safeLocalStorageGet(VS_LAYOUT_GRID_STORAGE_KEY);
    const parsed = raw ? JSON.parse(raw) : {};
    vsLayoutGridState.visible = parsed?.visible === true;
    vsLayoutGridState.paintEnabled = false;
    vsLayoutGridState.color = VS_LAYOUT_GRID_COLOR_NAMES.has(parsed?.color) ? parsed.color : 'cyan';
    vsLayoutGridState.cells = parsed?.cells && typeof parsed.cells === 'object' && !Array.isArray(parsed.cells) ? { ...parsed.cells } : {};
  } catch (_) {
    vsLayoutGridState.visible = false;
    vsLayoutGridState.paintEnabled = false;
    vsLayoutGridState.color = 'cyan';
    vsLayoutGridState.cells = {};
  }
  vsLayoutGridState.dirty = false;
}

function saveVsLayoutGuideGridState() {
  safeLocalStorageSet(VS_LAYOUT_GRID_STORAGE_KEY, JSON.stringify({
    visible: vsLayoutGridState.visible,
    color: vsLayoutGridState.color,
    cells: vsLayoutGridState.cells,
  }));
}

function renderVsLayoutGuideGrid() {
  const grid = els.vsLayoutGuideGrid;
  if (!grid) return;
  if (grid.children.length !== VS_LAYOUT_GRID_COLS * VS_LAYOUT_GRID_ROWS) {
    const fragment = document.createDocumentFragment();
    for (let index = 0; index < VS_LAYOUT_GRID_COLS * VS_LAYOUT_GRID_ROWS; index += 1) {
      const cell = document.createElement('span');
      cell.className = 'vs-layout-guide-cell';
      cell.dataset.vsGridIndex = String(index);
      fragment.appendChild(cell);
    }
    grid.replaceChildren(fragment);
  }
  grid.querySelectorAll('.vs-layout-guide-cell').forEach(cell => {
    const index = cell.dataset.vsGridIndex;
    const color = vsLayoutGridState.cells[index];
    cell.dataset.paint = VS_LAYOUT_GRID_COLOR_NAMES.has(color) ? color : '';
  });
}

function syncVsLayoutGuideGridUi() {
  const grid = els.vsLayoutGuideGrid;
  const paintMode = vsLayoutGridState.visible && vsLayoutGridState.paintEnabled;
  if (grid) {
    grid.classList.toggle('is-visible', vsLayoutGridState.visible);
    grid.classList.toggle('is-painting', paintMode);
    grid.setAttribute('aria-hidden', vsLayoutGridState.visible ? 'false' : 'true');
  }
  els.vsLayoutEditorIntro?.classList.toggle('vs-layout-paint-mode', paintMode);
  if (els.vsLayoutGridToggle) els.vsLayoutGridToggle.checked = vsLayoutGridState.visible;
  if (els.vsLayoutGridPaintBtn) {
    els.vsLayoutGridPaintBtn.setAttribute('aria-pressed', vsLayoutGridState.paintEnabled ? 'true' : 'false');
    els.vsLayoutGridPaintBtn.textContent = vsLayoutGridState.paintEnabled ? 'Pintar: activado' : 'Pintar: desactivado';
    els.vsLayoutGridPaintBtn.classList.toggle('active', vsLayoutGridState.paintEnabled);
  }
  els.vsLayoutGridPalette?.querySelectorAll('[data-vs-grid-color]').forEach(button => {
    button.classList.toggle('is-selected', button.dataset.vsGridColor === vsLayoutGridState.color);
  });
}

function setVsLayoutGuideGridVisible(visible) {
  vsLayoutGridState.visible = visible === true;
  if (!vsLayoutGridState.visible) {
    vsLayoutGridState.paintEnabled = false;
    vsLayoutGridState.painting = false;
  }
  saveVsLayoutGuideGridState();
  syncVsLayoutGuideGridUi();
}

function setVsLayoutGuidePaintEnabled(enabled) {
  if (enabled === true && !vsLayoutGridState.visible) vsLayoutGridState.visible = true;
  vsLayoutGridState.paintEnabled = enabled === true && vsLayoutGridState.visible;
  vsLayoutGridState.painting = false;
  saveVsLayoutGuideGridState();
  syncVsLayoutGuideGridUi();
  if (vsLayoutGridState.paintEnabled) {
    setVsLayoutEditorStatus('Modo Pintar activo: Kaster e invocación se ocultan temporalmente para liberar toda la cuadrícula.');
  } else {
    setVsLayoutEditorStatus('Modo Pintar desactivado: los sprites vuelven a mostrarse.');
  }
}

function paintVsLayoutGuideCell(cell) {
  const index = cell?.dataset?.vsGridIndex;
  if (index == null || !vsLayoutGridState.paintEnabled) return;
  if (vsLayoutGridState.color === 'erase') delete vsLayoutGridState.cells[index];
  else if (VS_LAYOUT_GRID_COLOR_NAMES.has(vsLayoutGridState.color)) vsLayoutGridState.cells[index] = vsLayoutGridState.color;
  vsLayoutGridState.dirty = true;
  cell.dataset.paint = VS_LAYOUT_GRID_COLOR_NAMES.has(vsLayoutGridState.cells[index]) ? vsLayoutGridState.cells[index] : '';
  saveVsLayoutGuideGridState();
}

function clearVsLayoutGuideGrid() {
  vsLayoutGridState.cells = {};
  vsLayoutGridState.dirty = true;
  renderVsLayoutGuideGrid();
  saveVsLayoutGuideGridState();
  setVsLayoutEditorStatus('Pintura de la cuadrícula eliminada.');
}

function getVsLayoutCalibration(key = '') {
  const map = loadVsLayoutCalibrationMap();
  return normalizeVsLayoutCalibration(map[String(key || '')]);
}

function setVsLayoutCalibration(key, calibration, meta = {}) {
  if (!key) return false;
  const map = loadVsLayoutCalibrationMap();
  const normalized = normalizeVsLayoutCalibration(calibration);
  map[key] = {
    ...normalized,
    kind: meta.kind || map[key]?.kind || '',
    name: meta.name || map[key]?.name || '',
    updatedAt: Date.now(),
  };
  return saveVsLayoutCalibrationMap(map);
}

function escapeVsLayoutCssAttr(value = '') {
  return String(value).replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}

function parseVsLayoutCalibrationCssBlock(cssText = '') {
  const source = String(cssText || '');
  const start = source.indexOf(VS_LAYOUT_CSS_START);
  const end = source.indexOf(VS_LAYOUT_CSS_END);
  if (start < 0 || end < start) return {};
  const body = source.slice(start + VS_LAYOUT_CSS_START.length, end);
  const parsed = {};
  const rulePattern = /\[data-vs-layout-key="((?:\\.|[^"\\])*)"\]\s*\{([^}]*)\}/g;
  let match;
  while ((match = rulePattern.exec(body))) {
    const key = String(match[1] || '').replace(/\\"/g, '"').replace(/\\\\/g, '\\');
    const declarations = match[2] || '';
    const readNumber = property => {
      const propertyPattern = new RegExp(`${property}\\s*:\\s*(-?\\d+(?:\\.\\d+)?)`, 'i');
      const valueMatch = declarations.match(propertyPattern);
      return valueMatch ? Number(valueMatch[1]) : null;
    };
    const scale = readNumber('--vs-layout-scale');
    const x = readNumber('--vs-layout-x');
    const y = readNumber('--vs-layout-y');
    if (!key || scale == null || x == null || y == null) continue;
    parsed[key] = { ...normalizeVsLayoutCalibration({ scale, x, y }), updatedAt: 0 };
  }
  return parsed;
}

function buildVsLayoutCalibrationCssBlock(sourceMap = null) {
  const map = sourceMap && typeof sourceMap === 'object' ? sourceMap : loadVsLayoutCalibrationMap();
  const rules = Object.entries(map)
    .sort((a, b) => Number(b[1]?.updatedAt || 0) - Number(a[1]?.updatedAt || 0) || String(a[0]).localeCompare(String(b[0])))
    .map(([key, raw]) => {
      const value = normalizeVsLayoutCalibration(raw);
      const mirrorX = value.x === 0 ? 0 : -value.x;
      return `[data-vs-layout-key="${escapeVsLayoutCssAttr(key)}"] { --vs-layout-scale:${value.scale.toFixed(2)}; --vs-layout-x:${value.x}px; --vs-layout-x-mirror:${mirrorX}px; --vs-layout-y:${value.y}px; }`;
    });
  return `${VS_LAYOUT_CSS_START}\n${rules.join('\n')}\n${VS_LAYOUT_CSS_END}`;
}

function parseVsLayoutUniversalCssBlock(cssText = '') {
  const source = String(cssText || '');
  const start = source.indexOf(VS_LAYOUT_UNIVERSAL_CSS_START);
  const end = source.indexOf(VS_LAYOUT_UNIVERSAL_CSS_END);
  if (start < 0 || end < start) return null;
  const body = source.slice(start + VS_LAYOUT_UNIVERSAL_CSS_START.length, end);
  const read = property => {
    const match = body.match(new RegExp(`${property}\\s*:\\s*(-?\\d+(?:\\.\\d+)?)`, 'i'));
    return match ? Number(match[1]) : null;
  };
  const legacy = {
    scale: read('--vs-layout-universal-scale'),
    x: read('--vs-layout-universal-x'),
    y: read('--vs-layout-universal-y'),
  };
  const readKind = kind => {
    const value = {
      scale: read(`--vs-layout-universal-${kind}-scale`),
      x: read(`--vs-layout-universal-${kind}-x`),
      y: read(`--vs-layout-universal-${kind}-y`),
    };
    const complete = value.scale != null && value.x != null && value.y != null;
    if (complete) return normalizeVsLayoutUniversal(value);
    if (legacy.scale != null && legacy.x != null && legacy.y != null) return normalizeVsLayoutUniversal(legacy);
    return normalizeVsLayoutUniversal(null);
  };
  return { kaster: readKind('kaster'), invocation: readKind('invocation') };
}

function buildVsLayoutUniversalCssBlock(value = null) {
  const universal = normalizeVsLayoutUniversalBundle(value || vsLayoutUniversalState);
  return `${VS_LAYOUT_UNIVERSAL_CSS_START}\n:root {\n  --vs-layout-universal-kaster-scale:${universal.kaster.scale.toFixed(2)};\n  --vs-layout-universal-kaster-x:${universal.kaster.x}px;\n  --vs-layout-universal-kaster-y:${universal.kaster.y}px;\n  --vs-layout-universal-invocation-scale:${universal.invocation.scale.toFixed(2)};\n  --vs-layout-universal-invocation-x:${universal.invocation.x}px;\n  --vs-layout-universal-invocation-y:${universal.invocation.y}px;\n}\n${VS_LAYOUT_UNIVERSAL_CSS_END}`;
}

function parseVsLayoutGridCssBlock(cssText = '') {
  const source = String(cssText || '');
  const start = source.indexOf(VS_LAYOUT_GRID_CSS_START);
  const end = source.indexOf(VS_LAYOUT_GRID_CSS_END);
  if (start < 0 || end < start) return {};
  const body = source.slice(start + VS_LAYOUT_GRID_CSS_START.length, end);
  const result = {};
  const pattern = /data-vs-grid-index="(\d+)"\][^{]*\{[^}]*--vs-layout-guide-css-color\s*:\s*(cyan|gold|magenta|green)\s*;?[^}]*\}/gi;
  let match;
  while ((match = pattern.exec(body))) {
    const index = Number(match[1]);
    const color = String(match[2] || '').toLowerCase();
    if (Number.isInteger(index) && index >= 0 && index < VS_LAYOUT_GRID_COLS * VS_LAYOUT_GRID_ROWS && VS_LAYOUT_GRID_COLOR_NAMES.has(color)) {
      result[String(index)] = color;
    }
  }
  return result;
}

function buildVsLayoutGridCssBlock(sourceCells = null) {
  const cells = sourceCells && typeof sourceCells === 'object' ? sourceCells : vsLayoutGridState.cells;
  const paint = {
    cyan: 'rgba(25,217,255,.27)',
    gold: 'rgba(255,213,74,.28)',
    magenta: 'rgba(255,67,189,.26)',
    green: 'rgba(94,227,108,.25)',
  };
  const rules = Object.entries(cells)
    .filter(([index, color]) => /^\d+$/.test(String(index)) && VS_LAYOUT_GRID_COLOR_NAMES.has(color))
    .sort((a, b) => Number(a[0]) - Number(b[0]))
    .map(([index, color]) => `.vs-layout-guide-cell[data-vs-grid-index="${index}"] { --vs-layout-guide-css-color:${color}; --vs-layout-guide-css-paint:${paint[color]}; }`);
  return `${VS_LAYOUT_GRID_CSS_START}\n${rules.join('\n')}\n${VS_LAYOUT_GRID_CSS_END}`;
}

function replaceDelimitedCssBlock(cssText, startMarker, endMarker, block) {
  const source = String(cssText || '');
  const start = source.indexOf(startMarker);
  const end = source.indexOf(endMarker);
  if (start >= 0 && end >= start) {
    return source.slice(0, start) + block + source.slice(end + endMarker.length);
  }
  return `${source.replace(/\s*$/, '')}\n\n${block}\n`;
}

function replaceVsLayoutCssBlock(cssText = '') {
  let source = String(cssText || '');
  const cssMap = parseVsLayoutCalibrationCssBlock(source);
  const browserMap = loadVsLayoutCalibrationMap();
  const mergedMap = { ...cssMap, ...browserMap };
  const cssUniversal = parseVsLayoutUniversalCssBlock(source);
  const browserUniversal = getVsLayoutUniversalBundle();
  const mergedUniversal = normalizeVsLayoutUniversalBundle(browserUniversal || cssUniversal);
  const cssGrid = parseVsLayoutGridCssBlock(source);
  const mergedGrid = vsLayoutGridState.dirty
    ? { ...(vsLayoutGridState.cells || {}) }
    : { ...cssGrid, ...(vsLayoutGridState.cells || {}) };

  source = replaceDelimitedCssBlock(source, VS_LAYOUT_CSS_START, VS_LAYOUT_CSS_END, buildVsLayoutCalibrationCssBlock(mergedMap));
  source = replaceDelimitedCssBlock(source, VS_LAYOUT_UNIVERSAL_CSS_START, VS_LAYOUT_UNIVERSAL_CSS_END, buildVsLayoutUniversalCssBlock(mergedUniversal));
  source = replaceDelimitedCssBlock(source, VS_LAYOUT_GRID_CSS_START, VS_LAYOUT_GRID_CSS_END, buildVsLayoutGridCssBlock(mergedGrid));
  return source;
}

function applyVsLayoutCalibrationToElement(element, key = '') {
  if (!element) return;
  if (!key) {
    delete element.dataset.vsLayoutKey;
    ['--vs-layout-scale','--vs-layout-x','--vs-layout-x-mirror','--vs-layout-y','--vs-layout-effective-scale','--vs-layout-effective-x','--vs-layout-effective-x-mirror','--vs-layout-effective-y']
      .forEach(property => element.style.removeProperty(property));
    return;
  }

  element.dataset.vsLayoutKey = key;
  let individual = null;
  if (hasStoredVsLayoutCalibration(key)) {
    individual = getVsLayoutCalibration(key);
    element.style.setProperty('--vs-layout-scale', String(individual.scale));
    element.style.setProperty('--vs-layout-x', `${individual.x}px`);
    element.style.setProperty('--vs-layout-x-mirror', `${individual.x === 0 ? 0 : -individual.x}px`);
    element.style.setProperty('--vs-layout-y', `${individual.y}px`);
  } else {
    element.style.removeProperty('--vs-layout-scale');
    element.style.removeProperty('--vs-layout-x');
    element.style.removeProperty('--vs-layout-x-mirror');
    element.style.removeProperty('--vs-layout-y');
    const computed = window.getComputedStyle(element);
    individual = normalizeVsLayoutCalibration({
      scale: Number.parseFloat(computed.getPropertyValue('--vs-layout-scale')) || 1,
      x: Number.parseFloat(computed.getPropertyValue('--vs-layout-x')) || 0,
      y: Number.parseFloat(computed.getPropertyValue('--vs-layout-y')) || 0,
    });
  }

  const universalKind = getVsLayoutUniversalKindFromKey(key);
  const effective = combineVsLayoutCalibration(individual, getVsLayoutUniversalState(universalKind));
  element.style.setProperty('--vs-layout-effective-scale', String(effective.scale));
  element.style.setProperty('--vs-layout-effective-x', `${effective.x}px`);
  element.style.setProperty('--vs-layout-effective-x-mirror', `${effective.xMirror}px`);
  element.style.setProperty('--vs-layout-effective-y', `${effective.y}px`);
}

function refreshVsLayoutUniversalOnVisibleSprites() {
  [
    els.vsLayoutEditorCaster, els.vsLayoutEditorChampion,
    els.onlineIntroRivalImage, els.onlineIntroPlayerImage,
    els.onlineIntroRivalChampion, els.onlineIntroPlayerChampion,
    els.adventureIntroRivalImage, els.adventureIntroPlayerImage,
    els.adventureIntroRivalChampion, els.adventureIntroPlayerChampion,
  ].forEach(element => {
    const key = element?.dataset?.vsLayoutKey;
    if (element && key) applyVsLayoutCalibrationToElement(element, key);
  });
}

function getVsLayoutKasterKey(entity = null) {
  if (!entity) return '';
  const id = entity.cardId || entity.id || entity.casterId || entity.name || entity.label || '';
  return id ? `kaster:${id}` : '';
}

function getVsLayoutInvocationKey(card = null) {
  const id = card?.id || card?.cardId || '';
  return id ? `invocation:${id}` : '';
}

function getVsLayoutKasterCatalog() {
  const result = [];
  const seen = new Set();
  const push = entry => {
    if (!entry?.key || !entry?.image || seen.has(entry.key)) return;
    seen.add(entry.key);
    result.push(entry);
  };

  Object.values(CARD_LIBRARY).slice().reverse().forEach(card => {
    if (!card || card.type !== 'kaster') return;
    const def = getCasterRuntimeDefinitionFromCard(card);
    push({
      kind: 'kaster',
      key: `kaster:${card.id}`,
      id: card.id,
      name: card.name || def?.name || card.id,
      image: def?.tokenImage || card.tokenImage || def?.artImage || card.artImage || '',
      source: 'CARD_LIBRARY',
    });
  });

  Object.values(CASTER_LIBRARY).slice().reverse().forEach(caster => {
    const id = caster.cardId || caster.id;
    push({
      kind: 'kaster',
      key: `kaster:${id}`,
      id,
      name: caster.name || id,
      image: caster.tokenImage || caster.artImage || '',
      source: 'CASTER_LIBRARY',
    });
  });

  [...ADVENTURE_PLAYER_CASTERS].reverse().forEach(caster => {
    push({
      kind: 'kaster',
      key: `kaster:adventure-player:${caster.id}`,
      id: caster.id,
      name: caster.label || caster.id,
      image: caster.tokenImage || caster.image || '',
      source: 'ADVENTURE_PLAYER',
    });
  });

  [...ADVENTURE_WATER_ENCOUNTERS].reverse().forEach(caster => {
    push({
      kind: 'kaster',
      key: `kaster:adventure:${caster.id}`,
      id: caster.id,
      name: caster.label || caster.id,
      image: caster.tokenImage || caster.image || '',
      source: 'ADVENTURE_RIVAL',
    });
  });

  return result;
}

function getVsLayoutInvocationCatalog() {
  return Object.values(CARD_LIBRARY).slice().reverse()
    .filter(card => card && getCardTypeId(card) === 'invocation' && (card.tokenImage || card.artImage || card.thumbnailImage))
    .map(card => ({
      kind: 'invocation',
      key: getVsLayoutInvocationKey(card),
      id: card.id,
      name: card.name || card.shortName || card.id,
      image: card.tokenImage || card.artImage || card.thumbnailImage || '',
      source: 'CARD_LIBRARY',
      card,
    }));
}

function populateVsLayoutEditorSelectors() {
  vsLayoutEditorState.catalog.kasters = getVsLayoutKasterCatalog();
  vsLayoutEditorState.catalog.invocations = getVsLayoutInvocationCatalog();
  if (els.vsLayoutCasterSelect) {
    els.vsLayoutCasterSelect.innerHTML = '<option value="">— Ningún Kaster —</option>' + vsLayoutEditorState.catalog.kasters
      .map(entry => `<option value="${escapeAttribute(entry.key)}">${escapeHtml(entry.name)}</option>`).join('');
  }
  if (els.vsLayoutInvocationSelect) {
    els.vsLayoutInvocationSelect.innerHTML = '<option value="">— Ninguna invocación —</option>' + vsLayoutEditorState.catalog.invocations
      .map(entry => `<option value="${escapeAttribute(entry.key)}">${escapeHtml(entry.name)}</option>`).join('');
  }
}

function findVsLayoutEditorEntry(kind, key) {
  const list = kind === 'invocation' ? vsLayoutEditorState.catalog.invocations : vsLayoutEditorState.catalog.kasters;
  return list.find(entry => entry.key === key) || null;
}

function setVsLayoutEditorStatus(message = '') {
  if (els.vsLayoutSaveStatus) els.vsLayoutSaveStatus.textContent = message || '';
}

function setVsLayoutEditorControlsEnabled(enabled) {
  [els.vsLayoutScaleRange, els.vsLayoutXRange, els.vsLayoutYRange, els.vsLayoutSaveBtn, els.vsLayoutResetBtn, els.vsLayoutReplayBtn]
    .forEach(control => { if (control) control.disabled = !enabled; });
}

function syncVsLayoutEditorOutputs(value = null) {
  const calibration = normalizeVsLayoutCalibration(value);
  if (els.vsLayoutScaleRange) els.vsLayoutScaleRange.value = String(calibration.scale);
  if (els.vsLayoutXRange) els.vsLayoutXRange.value = String(calibration.x);
  if (els.vsLayoutYRange) els.vsLayoutYRange.value = String(calibration.y);
  if (els.vsLayoutScaleValue) els.vsLayoutScaleValue.textContent = `${Math.round(calibration.scale * 100)}%`;
  if (els.vsLayoutXValue) els.vsLayoutXValue.textContent = `${calibration.x} px`;
  if (els.vsLayoutYValue) els.vsLayoutYValue.textContent = `${calibration.y} px`;
}

function getVsLayoutEditorLiveCalibration() {
  return normalizeVsLayoutCalibration({
    scale: Number(els.vsLayoutScaleRange?.value || 1),
    x: Number(els.vsLayoutXRange?.value || 0),
    y: Number(els.vsLayoutYRange?.value || 0),
  });
}

function getVsLayoutUniversalControls(kind = 'kaster') {
  if (kind === 'invocation') {
    return {
      scaleRange: els.vsLayoutInvocationUniversalScaleRange,
      xRange: els.vsLayoutInvocationUniversalXRange,
      yRange: els.vsLayoutInvocationUniversalYRange,
      scaleValue: els.vsLayoutInvocationUniversalScaleValue,
      xValue: els.vsLayoutInvocationUniversalXValue,
      yValue: els.vsLayoutInvocationUniversalYValue,
    };
  }
  return {
    scaleRange: els.vsLayoutCasterUniversalScaleRange,
    xRange: els.vsLayoutCasterUniversalXRange,
    yRange: els.vsLayoutCasterUniversalYRange,
    scaleValue: els.vsLayoutCasterUniversalScaleValue,
    xValue: els.vsLayoutCasterUniversalXValue,
    yValue: els.vsLayoutCasterUniversalYValue,
  };
}

function syncVsLayoutUniversalOutputs(kind = 'kaster', value = null) {
  const calibration = normalizeVsLayoutUniversal(value || getVsLayoutUniversalState(kind));
  const controls = getVsLayoutUniversalControls(kind);
  if (controls.scaleRange) controls.scaleRange.value = String(calibration.scale);
  if (controls.xRange) controls.xRange.value = String(calibration.x);
  if (controls.yRange) controls.yRange.value = String(calibration.y);
  if (controls.scaleValue) controls.scaleValue.textContent = `${Math.round(calibration.scale * 100)}%`;
  if (controls.xValue) controls.xValue.textContent = `${calibration.x} px`;
  if (controls.yValue) controls.yValue.textContent = `${calibration.y} px`;
}

function getVsLayoutUniversalLiveCalibration(kind = 'kaster') {
  const controls = getVsLayoutUniversalControls(kind);
  return normalizeVsLayoutUniversal({
    scale: Number(controls.scaleRange?.value || 1),
    x: Number(controls.xRange?.value || 0),
    y: Number(controls.yRange?.value || 0),
  });
}

function applyVsLayoutUniversalLiveCalibration(kind = 'kaster') {
  const value = getVsLayoutUniversalLiveCalibration(kind);
  const bundle = getVsLayoutUniversalBundle();
  bundle[kind] = value;
  applyVsLayoutUniversalToRoot(bundle);
  refreshVsLayoutUniversalOnVisibleSprites();

  // v567 · Si el usuario está editando una pieza individual del mismo tipo,
  // el universal debe verse sobre ESA MISMA previsualización sin esperar a
  // guardar ni a volver a seleccionarla. Se conserva el ajuste individual
  // actualmente escrito en los sliders aunque todavía no esté persistido.
  if (vsLayoutEditorState.activeKind === kind && vsLayoutEditorState.activeKey) {
    const target = kind === 'invocation' ? els.vsLayoutEditorChampion : els.vsLayoutEditorCaster;
    if (target) {
      const individual = getVsLayoutEditorLiveCalibration();
      const effective = combineVsLayoutCalibration(individual, value);
      target.dataset.vsLayoutKey = vsLayoutEditorState.activeKey;
      target.style.setProperty('--vs-layout-scale', String(individual.scale));
      target.style.setProperty('--vs-layout-x', `${individual.x}px`);
      target.style.setProperty('--vs-layout-x-mirror', `${individual.x === 0 ? 0 : -individual.x}px`);
      target.style.setProperty('--vs-layout-y', `${individual.y}px`);
      target.style.setProperty('--vs-layout-effective-scale', String(effective.scale));
      target.style.setProperty('--vs-layout-effective-x', `${effective.x}px`);
      target.style.setProperty('--vs-layout-effective-x-mirror', `${effective.xMirror}px`);
      target.style.setProperty('--vs-layout-effective-y', `${effective.y}px`);
    }
  }

  syncVsLayoutUniversalOutputs(kind, value);
  setVsLayoutEditorStatus(`Cambio universal de ${kind === 'invocation' ? 'invocaciones' : 'Kasters'} sin guardar.`);
}

async function saveVsLayoutUniversalCurrent(kind = 'kaster') {
  const value = getVsLayoutUniversalLiveCalibration(kind);
  const bundle = getVsLayoutUniversalBundle();
  bundle[kind] = value;
  saveVsLayoutUniversalState(bundle);
  applyVsLayoutUniversalToRoot(bundle);
  refreshVsLayoutUniversalOnVisibleSprites();
  if (vsLayoutEditorState.activeKind === kind && vsLayoutEditorState.activeKey) {
    const target = kind === 'invocation' ? els.vsLayoutEditorChampion : els.vsLayoutEditorCaster;
    if (target) {
      const individual = getVsLayoutEditorLiveCalibration();
      const effective = combineVsLayoutCalibration(individual, value);
      target.style.setProperty('--vs-layout-effective-scale', String(effective.scale));
      target.style.setProperty('--vs-layout-effective-x', `${effective.x}px`);
      target.style.setProperty('--vs-layout-effective-x-mirror', `${effective.xMirror}px`);
      target.style.setProperty('--vs-layout-effective-y', `${effective.y}px`);
    }
  }
  if (vsLayoutEditorState.cssFileHandle) {
    const written = await writeVsLayoutCalibrationToLinkedCss();
    if (written) setVsLayoutEditorStatus(`Ajuste universal de ${kind === 'invocation' ? 'invocaciones' : 'Kasters'} guardado en navegador + style.css.`);
  } else {
    setVsLayoutEditorStatus(`Ajuste universal de ${kind === 'invocation' ? 'invocaciones' : 'Kasters'} guardado en este navegador.`);
  }
}

function resetVsLayoutUniversalCurrent(kind = 'kaster') {
  syncVsLayoutUniversalOutputs(kind, { scale: 1, x: 0, y: 0 });
  applyVsLayoutUniversalLiveCalibration(kind);
}

function applyVsLayoutEditorLiveCalibration() {
  const key = vsLayoutEditorState.activeKey;
  const kind = vsLayoutEditorState.activeKind;
  if (!key || !kind) return;
  const target = kind === 'invocation' ? els.vsLayoutEditorChampion : els.vsLayoutEditorCaster;
  if (!target) return;
  const value = getVsLayoutEditorLiveCalibration();
  const universalKind = kind === 'invocation' ? 'invocation' : 'kaster';
  const effective = combineVsLayoutCalibration(value, getVsLayoutUniversalState(universalKind));
  target.dataset.vsLayoutKey = key;
  target.style.setProperty('--vs-layout-scale', String(value.scale));
  target.style.setProperty('--vs-layout-x', `${value.x}px`);
  target.style.setProperty('--vs-layout-x-mirror', `${value.x === 0 ? 0 : -value.x}px`);
  target.style.setProperty('--vs-layout-y', `${value.y}px`);
  target.style.setProperty('--vs-layout-effective-scale', String(effective.scale));
  target.style.setProperty('--vs-layout-effective-x', `${effective.x}px`);
  target.style.setProperty('--vs-layout-effective-x-mirror', `${effective.xMirror}px`);
  target.style.setProperty('--vs-layout-effective-y', `${effective.y}px`);
  syncVsLayoutEditorOutputs(value);
  setVsLayoutEditorStatus('Cambio individual sin guardar.');
}

function replayVsLayoutEditorPreview() {
  const intro = els.vsLayoutEditorIntro;
  if (!intro) return;
  try { stopVersusIntroEnergy(intro); } catch (_) {}
  intro.classList.remove('active', 'counting', 'combat-ready');
  void intro.offsetWidth;
  try { startVersusIntroEnergy(intro); } catch (_) {}
  intro.classList.add('active');
}

function queueVsLayoutEditorReplay() {
  const images = [els.vsLayoutEditorCaster, els.vsLayoutEditorChampion].filter(image => image?.getAttribute?.('src'));
  if (!images.length) {
    replayVsLayoutEditorPreview();
    return;
  }
  const waiters = images.map(image => {
    if (image.complete && Number(image.naturalWidth || 0) > 0) return Promise.resolve();
    return new Promise(resolve => {
      const done = () => {
        image.removeEventListener('load', done);
        image.removeEventListener('error', done);
        resolve();
      };
      image.addEventListener('load', done, { once: true });
      image.addEventListener('error', done, { once: true });
      window.setTimeout(done, 900);
    });
  });
  Promise.all(waiters).then(() => window.requestAnimationFrame(replayVsLayoutEditorPreview));
}

function updateVsLayoutEditorSelectedVisual() {
  els.vsLayoutEditorCaster?.classList.toggle('vs-layout-editor-selected', vsLayoutEditorState.activeKind === 'kaster');
  els.vsLayoutEditorChampion?.classList.toggle('vs-layout-editor-selected', vsLayoutEditorState.activeKind === 'invocation');
}

function selectVsLayoutEditorEntity(kind, key = '') {
  const entry = key ? findVsLayoutEditorEntry(kind, key) : null;
  if (kind === 'kaster') {
    vsLayoutEditorState.casterKey = key || '';
    if (els.vsLayoutEditorCaster) {
      if (entry?.image) {
        els.vsLayoutEditorCaster.src = entry.image;
        els.vsLayoutEditorCaster.alt = entry.name || 'Kaster';
        applyVsLayoutCalibrationToElement(els.vsLayoutEditorCaster, entry.key);
      } else {
        els.vsLayoutEditorCaster.removeAttribute('src');
        applyVsLayoutCalibrationToElement(els.vsLayoutEditorCaster, '');
      }
    }
  } else {
    vsLayoutEditorState.invocationKey = key || '';
    if (els.vsLayoutEditorChampion) {
      if (entry?.image) {
        els.vsLayoutEditorChampion.src = entry.image;
        els.vsLayoutEditorChampion.alt = entry.name || 'Invocación';
        els.vsLayoutEditorChampion.classList.add('visible');
        applyVsLayoutCalibrationToElement(els.vsLayoutEditorChampion, entry.key);
      } else {
        els.vsLayoutEditorChampion.removeAttribute('src');
        els.vsLayoutEditorChampion.classList.remove('visible');
        applyVsLayoutCalibrationToElement(els.vsLayoutEditorChampion, '');
      }
    }
  }

  if (entry) {
    vsLayoutEditorState.activeKind = kind;
    vsLayoutEditorState.activeKey = entry.key;
    vsLayoutEditorState.activeEntity = entry;
    if (els.vsLayoutCurrentName) els.vsLayoutCurrentName.textContent = entry.name;
    if (els.vsLayoutCurrentKind) els.vsLayoutCurrentKind.textContent = kind === 'invocation' ? 'Invocación destacada' : 'Kaster';
    if (els.vsLayoutEditorPreviewName) els.vsLayoutEditorPreviewName.textContent = entry.name;
    const target = kind === 'invocation' ? els.vsLayoutEditorChampion : els.vsLayoutEditorCaster;
    syncVsLayoutEditorOutputs(readVsLayoutCalibrationFromElement(target, entry.key));
    setVsLayoutEditorControlsEnabled(true);
    setVsLayoutEditorStatus('Ajuste cargado. Modifica los controles y guarda cuando esté listo.');
  } else if (vsLayoutEditorState.activeKind === kind) {
    vsLayoutEditorState.activeKind = '';
    vsLayoutEditorState.activeKey = '';
    vsLayoutEditorState.activeEntity = null;
    if (els.vsLayoutCurrentName) els.vsLayoutCurrentName.textContent = 'Selecciona un elemento';
    if (els.vsLayoutCurrentKind) els.vsLayoutCurrentKind.textContent = '—';
    if (els.vsLayoutEditorPreviewName) els.vsLayoutEditorPreviewName.textContent = 'Selecciona un elemento';
    syncVsLayoutEditorOutputs({ scale: 1, x: 0, y: 0 });
    setVsLayoutEditorControlsEnabled(false);
  }
  updateVsLayoutEditorSelectedVisual();
  queueVsLayoutEditorReplay();
}

async function writeVsLayoutCalibrationToLinkedCss() {
  const handle = vsLayoutEditorState.cssFileHandle;
  if (!handle) return false;
  try {
    if (handle.queryPermission && handle.requestPermission) {
      let permission = await handle.queryPermission({ mode: 'readwrite' });
      if (permission !== 'granted') permission = await handle.requestPermission({ mode: 'readwrite' });
      if (permission !== 'granted') throw new Error('Permiso de escritura denegado.');
    }
    const file = await handle.getFile();
    const source = await file.text();
    const updated = replaceVsLayoutCssBlock(source);
    const writable = await handle.createWritable();
    await writable.write(updated);
    await writable.close();
    return true;
  } catch (error) {
    reportGameException(error, 'Editor VS · guardar style.css');
    setVsLayoutEditorStatus(`No se pudo escribir style.css: ${error?.message || error}`);
    return false;
  }
}

async function bindVsLayoutEditorCssFile() {
  if (typeof window.showOpenFilePicker !== 'function') {
    setVsLayoutEditorStatus('Este navegador no permite vincular archivos. Usa “Exportar CSS”.');
    return;
  }
  try {
    const [handle] = await window.showOpenFilePicker({
      multiple: false,
      types: [{ description: 'Hoja de estilos R.O.K', accept: { 'text/css': ['.css'] } }],
    });
    if (!handle) return;
    vsLayoutEditorState.cssFileHandle = handle;
    try {
      const file = await handle.getFile();
      const cssText = await file.text();
      const cssMap = parseVsLayoutCalibrationCssBlock(cssText);
      const browserMap = loadVsLayoutCalibrationMap();
      const imported = { ...cssMap, ...browserMap };
      saveVsLayoutCalibrationMap(imported);

      const cssUniversal = parseVsLayoutUniversalCssBlock(cssText);
      if (cssUniversal) {
        saveVsLayoutUniversalState(cssUniversal);
        applyVsLayoutUniversalToRoot(cssUniversal);
        syncVsLayoutUniversalOutputs('kaster', cssUniversal.kaster);
        syncVsLayoutUniversalOutputs('invocation', cssUniversal.invocation);
      }

      const cssGrid = parseVsLayoutGridCssBlock(cssText);
      if (Object.keys(cssGrid).length) {
        vsLayoutGridState.cells = { ...cssGrid, ...(vsLayoutGridState.cells || {}) };
        vsLayoutGridState.dirty = false;
        saveVsLayoutGuideGridState();
        renderVsLayoutGuideGrid();
      }

      refreshVsLayoutUniversalOnVisibleSprites();
      const importedCount = Object.keys(cssMap).length;
      const guideCount = Object.keys(cssGrid).length;
      setVsLayoutEditorStatus(`style.css vinculado: ${handle.name}. ${importedCount} calibraciones + ${guideCount} marcas de guía reconocidas.`);
    } catch (_) {
      setVsLayoutEditorStatus(`style.css vinculado: ${handle.name}. Al guardar, se actualizará el bloque de calibración.`);
    }
  } catch (error) {
    if (error?.name !== 'AbortError') reportGameException(error, 'Editor VS · vincular style.css');
  }
}

function pickVsLayoutCssFileFallback() {
  return new Promise((resolve, reject) => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.css,text/css';
    input.style.display = 'none';
    const cleanup = () => input.remove();
    input.addEventListener('change', () => {
      const file = input.files?.[0] || null;
      cleanup();
      if (!file) { reject(new DOMException('Selección cancelada.', 'AbortError')); return; }
      resolve(file);
    }, { once: true });
    document.body.appendChild(input);
    input.click();
  });
}

async function getVsLayoutCssSourceForExport() {
  if (vsLayoutEditorState.cssFileHandle) {
    const file = await vsLayoutEditorState.cssFileHandle.getFile();
    return await file.text();
  }

  if (window.location?.protocol === 'file:') {
    setVsLayoutEditorStatus('Selecciona el style.css actual para exportarlo sin el bloqueo CORS de file://.');
    if (typeof window.showOpenFilePicker === 'function') {
      const [handle] = await window.showOpenFilePicker({
        multiple: false,
        types: [{ description: 'Hoja de estilos R.O.K', accept: { 'text/css': ['.css'] } }],
      });
      if (!handle) throw new DOMException('Selección cancelada.', 'AbortError');
      vsLayoutEditorState.cssFileHandle = handle;
      const file = await handle.getFile();
      return await file.text();
    }
    const file = await pickVsLayoutCssFileFallback();
    return await file.text();
  }

  const response = await fetch('style.css', { cache: 'no-store' });
  if (!response.ok) throw new Error(`No se pudo leer style.css (${response.status}).`);
  return await response.text();
}

async function exportVsLayoutEditorCss() {
  try {
    const source = await getVsLayoutCssSourceForExport();
    const updated = replaceVsLayoutCssBlock(source);
    const blob = new Blob([updated], { type: 'text/css;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = 'style.css';
    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1200);
    setVsLayoutEditorStatus('style.css exportado: ajustes individuales, ajuste universal y guía incluidos.');
  } catch (error) {
    if (error?.name === 'AbortError') {
      setVsLayoutEditorStatus('Exportación cancelada.');
      return;
    }
    reportGameException(error, 'Editor VS · exportar CSS');
    setVsLayoutEditorStatus(`No se pudo exportar el CSS: ${error?.message || error}`);
  }
}

async function saveVsLayoutGuideGridToCss() {
  saveVsLayoutGuideGridState();
  if (!vsLayoutEditorState.cssFileHandle) {
    setVsLayoutEditorStatus('La guía ya quedó guardada en el navegador. Vincula style.css o usa Exportar CSS para llevar las marcas al archivo.');
    return;
  }
  const written = await writeVsLayoutCalibrationToLinkedCss();
  if (written) {
    vsLayoutGridState.dirty = false;
    setVsLayoutEditorStatus(`Guía guardada en style.css · ${Object.keys(vsLayoutGridState.cells || {}).length} celdas marcadas.`);
  }
}

async function saveVsLayoutEditorCurrent() {
  const key = vsLayoutEditorState.activeKey;
  const entry = vsLayoutEditorState.activeEntity;
  if (!key || !entry) return;
  const value = getVsLayoutEditorLiveCalibration();
  const saved = setVsLayoutCalibration(key, value, { kind: entry.kind, name: entry.name });
  if (!saved) {
    setVsLayoutEditorStatus('No se pudo guardar la calibración en el navegador.');
    return;
  }
  applyVsLayoutCalibrationToElement(entry.kind === 'invocation' ? els.vsLayoutEditorChampion : els.vsLayoutEditorCaster, key);
  if (vsLayoutEditorState.cssFileHandle) {
    const written = await writeVsLayoutCalibrationToLinkedCss();
    if (written) setVsLayoutEditorStatus(`Guardado: ${entry.name}. Navegador + style.css actualizados.`);
  } else {
    setVsLayoutEditorStatus(`Guardado: ${entry.name}. Persistido en este navegador.`);
  }
}

function resetVsLayoutEditorCurrent() {
  if (!vsLayoutEditorState.activeKey) return;
  syncVsLayoutEditorOutputs({ scale: 1, x: 0, y: 0 });
  applyVsLayoutEditorLiveCalibration();
}

function openVsLayoutEditor() {
  if (!els.vsLayoutEditorScreen) return;
  setMainMenuUserHudMenuOpen(false);
  if (els.mainMenuScreen) els.mainMenuScreen.setAttribute('aria-hidden', 'true');
  document.body.classList.remove('rok-battle-mode', 'rok-library-mode', 'rok-spellbooks-mode', 'rok-card-creator-mode', 'rok-adventure-mode');
  document.body.classList.add('rok-vs-layout-editor-mode');
  populateVsLayoutEditorSelectors();
  loadVsLayoutGuideGridState();
  renderVsLayoutGuideGrid();
  syncVsLayoutGuideGridUi();
  const universal = loadVsLayoutUniversalState();
  applyVsLayoutUniversalToRoot(universal);
  syncVsLayoutUniversalOutputs('kaster', universal.kaster);
  syncVsLayoutUniversalOutputs('invocation', universal.invocation);
  vsLayoutEditorState.activeKind = '';
  vsLayoutEditorState.activeKey = '';
  vsLayoutEditorState.activeEntity = null;
  vsLayoutEditorState.casterKey = '';
  vsLayoutEditorState.invocationKey = '';
  if (els.vsLayoutCasterSelect) els.vsLayoutCasterSelect.value = '';
  if (els.vsLayoutInvocationSelect) els.vsLayoutInvocationSelect.value = '';
  if (els.vsLayoutEditorCaster) els.vsLayoutEditorCaster.removeAttribute('src');
  if (els.vsLayoutEditorChampion) {
    els.vsLayoutEditorChampion.removeAttribute('src');
    els.vsLayoutEditorChampion.classList.remove('visible');
  }
  if (els.vsLayoutCurrentName) els.vsLayoutCurrentName.textContent = 'Selecciona un elemento';
  if (els.vsLayoutCurrentKind) els.vsLayoutCurrentKind.textContent = '—';
  if (els.vsLayoutEditorPreviewName) els.vsLayoutEditorPreviewName.textContent = 'Selecciona un elemento';
  syncVsLayoutEditorOutputs({ scale: 1, x: 0, y: 0 });
  setVsLayoutEditorControlsEnabled(false);
  els.vsLayoutEditorScreen.setAttribute('aria-hidden', 'false');
  setVsLayoutEditorStatus(`Selecciona un Kaster o una invocación para comenzar. ${vsLayoutEditorState.catalog.kasters.length} Kasters · ${vsLayoutEditorState.catalog.invocations.length} invocaciones detectadas.`);
  replayVsLayoutEditorPreview();
}

function closeVsLayoutEditor() {
  try { stopVersusIntroEnergy(els.vsLayoutEditorIntro); } catch (_) {}
  vsLayoutGridState.paintEnabled = false;
  vsLayoutGridState.painting = false;
  els.vsLayoutEditorIntro?.classList.remove('active', 'counting', 'combat-ready', 'vs-layout-paint-mode');
  els.vsLayoutEditorScreen?.setAttribute('aria-hidden', 'true');
  document.body.classList.remove('rok-vs-layout-editor-mode');
  showMainMenu();
}

window.ROK_VS_LAYOUT_EDITOR = {
  open: openVsLayoutEditor,
  close: closeVsLayoutEditor,
  getSaved: () => loadVsLayoutCalibrationMap(),
  getKasters: () => getVsLayoutKasterCatalog(),
  getInvocations: () => getVsLayoutInvocationCatalog(),
  getGrid: () => ({ ...vsLayoutGridState, cells: { ...vsLayoutGridState.cells } }),
  getUniversal: () => getVsLayoutUniversalBundle(),
  buildCss: buildVsLayoutCalibrationCssBlock,
  buildUniversalCss: buildVsLayoutUniversalCssBlock,
  buildGridCss: buildVsLayoutGridCssBlock,
};

function normalizeSpellbookCardSlots(cards) {
  const source = Array.isArray(cards)
    ? cards
    : (cards && typeof cards === 'object' ? cards : {});
  return Array.from({ length: SPELLBOOK_MAX_CARDS }, (_, index) => {
    const cardId = source[index] ?? source[String(index)];
    return typeof cardId === 'string' && CARD_LIBRARY[cardId] ? cardId : null;
  });
}

function normalizeSavedSpellbook(raw) {
  if (!raw || typeof raw !== 'object') return null;
  const casterCardId = typeof raw.casterCardId === 'string' && getCardTypeId(CARD_LIBRARY[raw.casterCardId]) === 'kaster'
    ? raw.casterCardId
    : null;
  if (!casterCardId) return null;
  return {
    id: typeof raw.id === 'string' && raw.id ? raw.id : createSpellbookId(),
    name: typeof raw.name === 'string' && raw.name.trim() ? raw.name.trim().slice(0, 48) : 'Spellbook sin nombre',
    casterCardId,
    cards: normalizeSpellbookCardSlots(raw.cards),
    elementDistribution: normalizeSpellbookElementDistribution(raw.elementDistribution),
    elementDistributionConfigured: raw.elementDistributionConfigured === true || getSpellbookElementTotal(raw.elementDistribution) > 0,
    createdAt: Number(raw.createdAt) || Date.now(),
    updatedAt: Number(raw.updatedAt) || Date.now(),
    schemaVersion: SPELLBOOK_SCHEMA_VERSION,
    builtIn: raw.builtIn === true,
    readOnly: raw.readOnly === true || raw.builtIn === true,
  };
}

function getBuiltInSpellbooks() {
  const baseTimestamp = 1;
  return BUILT_IN_SPELLBOOK_DEFINITIONS
    .map((definition, index) => normalizeSavedSpellbook({
      ...definition,
      cards: [...definition.cards],
      elementDistribution: { ...definition.elementDistribution },
      elementDistributionConfigured: true,
      createdAt: baseTimestamp + index,
      updatedAt: baseTimestamp + index,
      builtIn: true,
      readOnly: true,
    }))
    .filter(Boolean);
}

function sortSpellbookCollection(entries = []) {
  return [...entries].sort((a, b) => {
    const builtInDelta = Number(Boolean(b?.builtIn)) - Number(Boolean(a?.builtIn));
    if (builtInDelta) return builtInDelta;
    return Number(b?.updatedAt || 0) - Number(a?.updatedAt || 0);
  });
}

function mergeBuiltInSpellbooks(userEntries = []) {
  const builtIns = getBuiltInSpellbooks();
  const builtInIds = new Set(builtIns.map(entry => entry.id));
  const builtInNames = new Set(builtIns.map(entry => String(entry.name || '').trim().toLocaleLowerCase('es')));
  const user = (userEntries || []).filter(entry => {
    if (!entry || builtInIds.has(entry.id)) return false;
    return !builtInNames.has(String(entry.name || '').trim().toLocaleLowerCase('es'));
  });
  return sortSpellbookCollection([...builtIns, ...user]);
}


function cloneMatchData(value) {
  return value == null ? value : JSON.parse(JSON.stringify(value));
}

function getSpellbookMatchCardCount(spellbook) {
  return (spellbook?.cards || []).filter(cardId => typeof cardId === 'string' && CARD_LIBRARY[cardId]).length;
}

function getSpellbookMatchIssue(spellbook) {
  const normalized = normalizeSavedSpellbook(spellbook);
  if (!normalized) return 'El Spellbook no tiene un Kaster válido.';
  const cardCount = getSpellbookMatchCardCount(normalized);
  if (cardCount <= 0) return 'El Spellbook no contiene cartas.';
  const elementTotal = getSpellbookElementTotal(normalized.elementDistribution);
  if (!normalized.elementDistributionConfigured || elementTotal <= 0) return 'Configura y guarda su distribución elemental antes de jugar.';
  if (elementTotal > SPELLBOOK_ELEMENT_MAX_TOTAL) return `La Fuente supera el máximo de ${SPELLBOOK_ELEMENT_MAX_TOTAL} elementos.`;
  const collectionIssue = getRokUserSpellbookCollectionIssue(normalized);
  if (collectionIssue) return collectionIssue;
  return '';
}

function serializeSpellbookMatchLoadout(spellbook) {
  const normalized = normalizeSavedSpellbook(spellbook);
  if (!normalized) return null;
  return {
    id: normalized.id,
    spellbookId: normalized.id,
    name: normalized.name,
    casterCardId: normalized.casterCardId,
    cards: normalizeSpellbookCardSlots(normalized.cards),
    elementDistribution: normalizeSpellbookElementDistribution(normalized.elementDistribution),
    elementDistributionConfigured: normalized.elementDistributionConfigured === true,
    schemaVersion: SPELLBOOK_SCHEMA_VERSION,
    builtIn: normalized.builtIn === true,
  };
}

function spellbookCardsToHandTabs(cards) {
  const normalized = normalizeSpellbookCardSlots(cards);
  return [
    normalized.slice(0, 12),
    normalized.slice(12, 24),
    [...normalized.slice(24, 30), ...Array(6).fill(null)],
  ];
}

function getCasterRuntimeDefinitionFromCard(casterCard) {
  if (!casterCard) return null;
  return Object.values(CASTER_LIBRARY).find(entry => entry.cardId === casterCard.id) || null;
}

function shouldNormalizeCasterLevelForCurrentMatch() {
  // Aventura conserva el nivel persistente real. PvP Online y Player vs Bot
  // normalizan temporalmente ambos Kasters a nivel 10 para evitar ventajas
  // competitivas provenientes del progreso externo.
  if (String(state?.matchMode || '').toLowerCase() === 'adventure') return false;
  if (isOnlineMatchActive()) return true;
  return Boolean(state?.aiEnabled) && ['normal', TEST_MATCH_MODE_ID].includes(String(state?.matchMode || 'normal'));
}

function getCasterMatchProgress(cardOrId) {
  const card = typeof cardOrId === 'string' ? CARD_LIBRARY[cardOrId] : cardOrId;
  if (!card || getCardTypeId(card) !== 'kaster') return normalizeCasterProgressEntry();
  const persistent = getCasterProgress(card);
  if (!shouldNormalizeCasterLevelForCurrentMatch()) return persistent;
  return normalizeCasterProgressEntry({ level: CASTER_MAX_LEVEL, xp: 0, totalXp: persistent.totalXp, updatedAt: persistent.updatedAt });
}

function getCasterMatchProgressedStats(cardOrId) {
  const card = typeof cardOrId === 'string' ? CARD_LIBRARY[cardOrId] : cardOrId;
  if (!card || getCardTypeId(card) !== 'kaster') return null;
  return getCasterProgressedStats(card, getCasterMatchProgress(card));
}

function applyEffectiveCasterStatsToRuntimePlayer(playerId) {
  const player = state?.players?.[playerId];
  const caster = player?.caster;
  const card = caster?.cardId ? CARD_LIBRARY[caster.cardId] : null;
  if (!player || !caster || !card || getCardTypeId(card) !== 'kaster') return null;
  const persistent = getCasterProgress(card);
  const effective = getCasterMatchProgressedStats(card);
  if (!effective) return null;
  caster.atk = effective.attack;
  caster.def = effective.defense;
  caster.life = effective.life;
  caster.maxLife = effective.life;
  caster.pureBase = Math.max(0, Number(card.stats?.pureBase ?? 0));
  caster.pureCadence = effective.pureGeneration;
  caster.pureMax = effective.pureMax;
  caster.pureElement = Math.max(0, Math.min(caster.pureMax, caster.pureBase));
  caster.specialCounterProgress = 0;
  caster.specialCounters = effective.startingSpecialCounters;
  caster.persistentLevel = persistent.level;
  caster.effectiveLevel = effective.level;
  caster.levelNormalized = effective.level !== persistent.level;
  return effective;
}

function applySpellbookLoadoutToPlayer(playerId, rawLoadout) {
  const loadout = normalizeSavedSpellbook(rawLoadout);
  if (!loadout) throw new Error(`No se pudo cargar el Spellbook del Jugador ${playerId}.`);
  const issue = getSpellbookMatchIssue(loadout);
  if (issue) throw new Error(issue);
  const player = state.players?.[playerId];
  const casterCard = CARD_LIBRARY[loadout.casterCardId];
  if (!player || !casterCard) throw new Error(`No existe el Jugador ${playerId} o su Kaster.`);

  const casterDef = getCasterRuntimeDefinitionFromCard(casterCard);
  const stats = casterDef?.stats || casterCard.stats || {};
  const persistentProgress = getCasterProgress(casterCard);
  const effectiveProgression = getCasterMatchProgressedStats(casterCard) || getCasterProgressedStats(casterCard, persistentProgress);
  const domainId = getCardElementId(casterCard);
  const existingCaster = player.caster || {};
  const pureBase = Math.max(0, Number(stats.pureBase ?? 0));
  const maxLife = Math.max(1, Number(effectiveProgression?.life ?? stats.maxLife ?? stats.life ?? existingCaster.maxLife ?? 1));

  player.selectedSpellbookId = loadout.id;
  player.spellbookName = loadout.name;
  player.elementId = domainId;
  player.domainId = domainId;
  player.elementDistribution = normalizeSpellbookElementDistribution(loadout.elementDistribution);
  player.elementDistributionConfigured = true;
  player.resources = [];
  player.elementDeck = [];
  player.elementDiscard = [];
  player.handTabs = spellbookCardsToHandTabs(loadout.cards);
  player.spellbookUseCooldowns = {};
  player.spellbookCardStates = {};
  player.spellbookCardInstances = {};
  player.castQueue = [];
  player.units = [];
  player.spawnMarkers = [];
  player.caster = {
    ...existingCaster,
    id: `p${playerId}Caster`,
    casterId: casterDef?.id || casterCard.id,
    cardId: casterCard.id,
    name: casterCard.name,
    domainId,
    elementId: domainId,
    atk: Number(effectiveProgression?.attack ?? stats.atk ?? stats.damage ?? 0),
    def: Number(effectiveProgression?.defense ?? stats.def ?? CASTER_DEFENSE_VALUE),
    life: maxLife,
    maxLife,
    movesLeft: 0,
    state: 'ready',
    pureElement: pureBase,
    pureBase,
    pureCadence: Math.max(0, Number(effectiveProgression?.pureGeneration ?? stats.pureCadence ?? 0)),
    pureMax: Math.max(pureBase, Number(effectiveProgression?.pureMax ?? stats.pureMax ?? pureBase)),
    pureCastingVisitCount: 0,
    pureCastingLastKey: '',
    pureExtractionLastKey: '',
    specialCounterProgress: 0,
    specialCounters: Math.max(0, Number(effectiveProgression?.startingSpecialCounters ?? stats.startingSpecialCounters ?? 0)),
    persistentLevel: persistentProgress.level,
    effectiveLevel: effectiveProgression?.level ?? persistentProgress.level,
    levelNormalized: Number(effectiveProgression?.level ?? persistentProgress.level) !== Number(persistentProgress.level),
  };
  return loadout;
}

function resetBattleStateForSelectedMatch(aiEnabled) {
  resetBattleInactivityRuntime('match-state-reset');
  clearTimeout(schedulePhaseStartActions.timer);
  clearTimeout(scheduleSustainedCombatResolution.timer);
  clearTimeout(scheduleSustainedStructureAttacks.timer);
  try { clearTransientBattleUiForRestart(); } catch (_) {}
  const localHudMode = state.hudMode;
  const localSemiAutoMovement = state.semiAutoMovement;
  const fresh = cloneMatchData(INITIAL_BATTLE_STATE);
  Object.keys(state).forEach(key => delete state[key]);
  Object.assign(state, fresh);
  state.hudMode = localHudMode;
  state.semiAutoMovement = localSemiAutoMovement;
  state.aiEnabled = Boolean(aiEnabled);
  state.matchMode = 'normal';
  state.gameOver = false;
  state.activeTab = 0;
}

function closeMatchSpellbookSelector() {
  matchSpellbookSelectMode = null;
  matchSpellbookSelectedId = null;
  if (els.matchSpellbookSelectModal) {
    els.matchSpellbookSelectModal.classList.remove('open');
    els.matchSpellbookSelectModal.setAttribute('aria-hidden', 'true');
  }
}

function selectMatchSpellbook(id) {
  const spellbook = getSavedSpellbookById(id);
  const issue = getSpellbookMatchIssue(spellbook);
  if (!spellbook || issue) return;
  matchSpellbookSelectedId = id;
  safeLocalStorageSet(MATCH_SELECTED_SPELLBOOK_KEY, id);
  if (els.matchSpellbookSelectNotice) els.matchSpellbookSelectNotice.textContent = `Seleccionado: ${spellbook.name}`;
  if (els.matchSpellbookSelectConfirmBtn) els.matchSpellbookSelectConfirmBtn.disabled = false;
  els.matchSpellbookSelectList?.querySelectorAll('[data-match-spellbook-id]').forEach(button => {
    button.classList.toggle('selected', button.dataset.matchSpellbookId === id);
    button.setAttribute('aria-pressed', button.dataset.matchSpellbookId === id ? 'true' : 'false');
  });
}

function createMatchSpellbookOptionElement(spellbook, options = {}) {
  const caster = CARD_LIBRARY[spellbook?.casterCardId];
  if (!caster) return null;
  const issue = getSpellbookMatchIssue(spellbook);
  const cardCount = getSpellbookMatchCardCount(spellbook);
  const elementEntries = Object.entries(normalizeSpellbookElementDistribution(spellbook.elementDistribution))
    .filter(([, amount]) => Number(amount) > 0);
  const option = document.createElement('button');
  option.type = 'button';
  option.className = `match-spellbook-option${issue ? ' unavailable' : ''}${options.selected ? ' selected' : ''}`;
  option.dataset.matchSpellbookId = spellbook.id;
  option.disabled = Boolean(issue);
  option.setAttribute('aria-pressed', options.selected ? 'true' : 'false');
  const visual = document.createElement('span');
  visual.className = 'match-spellbook-option-visual';
  const mini = createCardElement(caster);
  mini.classList.add('match-spellbook-option-card');
  visual.appendChild(mini);
  const info = document.createElement('span');
  info.className = 'match-spellbook-option-info';
  const name = document.createElement('strong');
  name.textContent = spellbook.name;
  const casterName = document.createElement('small');
  casterName.textContent = caster.name;
  const stats = document.createElement('span');
  stats.className = 'match-spellbook-option-stats';
  stats.innerHTML = `<b>${cardCount}</b> cartas <i>·</i> <b>${getSpellbookElementTotal(spellbook.elementDistribution)}</b> elementos`;
  const elements = document.createElement('span');
  elements.className = 'match-spellbook-option-elements';
  elementEntries.forEach(([elementId, amount]) => {
    const profile = DOMAIN_ART_DB[elementId] || DOMAIN_ART_DB.oscuridad;
    const chip = document.createElement('span');
    chip.innerHTML = `<img src="${getElementCostIcon(elementId)}" alt="${profile.elementLabel}"><b>${amount}</b>`;
    elements.appendChild(chip);
  });
  info.append(name, casterName, stats, elements);
  if (issue) {
    const warning = document.createElement('em');
    warning.textContent = issue;
    info.appendChild(warning);
  } else if (typeof options.onSelect === 'function') {
    option.addEventListener('click', () => options.onSelect(spellbook.id));
  }
  option.append(visual, info);
  return option;
}

function renderMatchSpellbookSelector() {
  loadSpellbookStorage();
  if (!els.matchSpellbookSelectList) return;
  els.matchSpellbookSelectList.innerHTML = '';
  let usableCount = 0;

  savedSpellbooks.forEach(spellbook => {
    const issue = getSpellbookMatchIssue(spellbook);
    const option = createMatchSpellbookOptionElement(spellbook, {
      onSelect: id => selectMatchSpellbook(id),
    });
    if (!option) return;
    if (!issue) usableCount += 1;
    els.matchSpellbookSelectList.appendChild(option);
  });

  if (els.matchSpellbookSelectEmpty) els.matchSpellbookSelectEmpty.hidden = savedSpellbooks.length > 0;
  if (els.matchSpellbookSelectConfirmBtn) els.matchSpellbookSelectConfirmBtn.disabled = true;
  if (els.matchSpellbookSelectNotice) {
    els.matchSpellbookSelectNotice.textContent = usableCount
      ? 'Selecciona el Spellbook que utilizarás en esta partida.'
      : 'No hay un Spellbook con cartas y Fuente elemental configurada.';
  }

  const preferredId = safeLocalStorageGet(MATCH_SELECTED_SPELLBOOK_KEY);
  if (preferredId && !getSpellbookMatchIssue(getSavedSpellbookById(preferredId))) selectMatchSpellbook(preferredId);
}

function openMatchSpellbookSelector(mode = 'bot') {
  matchSpellbookSelectMode = mode === 'online' ? 'online' : (mode === 'bot-test' ? 'bot-test' : 'bot');
  matchSpellbookSelectedId = null;
  if (els.matchSpellbookSelectKicker) els.matchSpellbookSelectKicker.textContent = matchSpellbookSelectMode === 'online'
    ? 'PLAYER VS PLAYER'
    : (matchSpellbookSelectMode === 'bot-test' ? 'PARTIDA DE PRUEBA' : 'PLAYER VS BOT');
  if (els.matchSpellbookSelectCopy) els.matchSpellbookSelectCopy.textContent = matchSpellbookSelectMode === 'online'
    ? 'El Kaster, las cartas y la Fuente elemental elegidos se compartirán con la sala PvP.'
    : (matchSpellbookSelectMode === 'bot-test'
      ? 'Selecciona tu Spellbook. El rival será el bot de prueba con Kouuten como única carta y ambos recibirán 30 elementos de cada tipo.'
      : 'El Kaster, las cartas y la Fuente elemental se cargarán para el Jugador 1.');
  renderMatchSpellbookSelector();
  if (els.matchSpellbookSelectModal) {
    els.matchSpellbookSelectModal.classList.add('open');
    els.matchSpellbookSelectModal.setAttribute('aria-hidden', 'false');
  }
}

function confirmMatchSpellbookSelection() {
  const spellbook = getSavedSpellbookById(matchSpellbookSelectedId);
  const issue = getSpellbookMatchIssue(spellbook);
  if (!spellbook || issue) {
    if (els.matchSpellbookSelectNotice) els.matchSpellbookSelectNotice.textContent = issue || 'Selecciona un Spellbook válido.';
    return;
  }
  const mode = matchSpellbookSelectMode;
  const loadout = serializeSpellbookMatchLoadout(spellbook);
  closeMatchSpellbookSelector();
  if (mode === 'online') {
    pendingOnlineSpellbookLoadout = loadout;
    void window.ROK_ONLINE_PVP?.setLobbyLoadout?.(loadout);
    window.ROK_ONLINE_PVP?.openLobby?.();
    return;
  }
  startBotBattleFromMainMenu(loadout, { matchMode: mode === 'bot-test' ? TEST_MATCH_MODE_ID : 'normal' });
}

window.ROK_SPELLBOOK_MATCH = {
  getPendingOnlineLoadout: () => cloneMatchData(pendingOnlineSpellbookLoadout),
  openOnlineSelector: () => openMatchSpellbookSelector('online'),
  clearPendingOnlineLoadout: () => { pendingOnlineSpellbookLoadout = null; },
  applyLoadoutToPlayer: (playerId, loadout) => applySpellbookLoadoutToPlayer(Number(playerId), loadout),
  getEffectiveCasterLevel: cardId => getCasterMatchProgress(cardId)?.level || 1,
  normalizeRuntimeCaster: playerId => applyEffectiveCasterStatsToRuntimePlayer(Number(playerId)),
  getLoadoutIssue: loadout => getSpellbookMatchIssue(loadout),
  getOnlineOptions() {
    loadSpellbookStorage();
    return savedSpellbooks
      .filter(spellbook => !getSpellbookMatchIssue(spellbook))
      .map(spellbook => ({ id: spellbook.id, name: spellbook.name, casterCardId: spellbook.casterCardId }));
  },
  getOnlineLoadoutById(id) {
    loadSpellbookStorage();
    const spellbook = getSavedSpellbookById(id);
    if (!spellbook || getSpellbookMatchIssue(spellbook)) return null;
    safeLocalStorageSet(MATCH_SELECTED_SPELLBOOK_KEY, spellbook.id);
    pendingOnlineSpellbookLoadout = serializeSpellbookMatchLoadout(spellbook);
    return cloneMatchData(pendingOnlineSpellbookLoadout);
  },
  getPreferredOnlineId() {
    loadSpellbookStorage();
    const pendingId = pendingOnlineSpellbookLoadout?.id || pendingOnlineSpellbookLoadout?.spellbookId || '';
    if (pendingId && !getSpellbookMatchIssue(getSavedSpellbookById(pendingId))) return pendingId;
    const stored = safeLocalStorageGet(MATCH_SELECTED_SPELLBOOK_KEY) || '';
    if (stored && !getSpellbookMatchIssue(getSavedSpellbookById(stored))) return stored;
    return savedSpellbooks.find(spellbook => !getSpellbookMatchIssue(spellbook))?.id || '';
  },
  createOnlineOptionElement(id) {
    loadSpellbookStorage();
    const spellbook = getSavedSpellbookById(id);
    if (!spellbook || getSpellbookMatchIssue(spellbook)) return null;
    const node = createMatchSpellbookOptionElement(spellbook, { selected: false });
    if (node) { node.tabIndex = -1; node.disabled = false; }
    return node;
  },
};

function loadSpellbookStorage() {
  const raw = safeLocalStorageGet(SPELLBOOK_STORAGE_KEY);
  let userSpellbooks = [];
  if (raw) {
    try {
      const parsed = JSON.parse(raw);
      userSpellbooks = (Array.isArray(parsed) ? parsed : [])
        .map(normalizeSavedSpellbook)
        .filter(Boolean)
        .map(entry => ({ ...entry, builtIn: false, readOnly: false }));
    } catch (error) {
      console.warn('[ROK Spellbooks] Datos guardados inválidos; se cargarán los Spellbooks base.', error);
      userSpellbooks = [];
    }
  }
  savedSpellbooks = mergeBuiltInSpellbooks(userSpellbooks);
}

function persistSpellbookStorage() {
  const userSpellbooks = savedSpellbooks
    .filter(entry => !entry?.builtIn)
    .map(entry => normalizeSavedSpellbook({ ...entry, builtIn: false, readOnly: false }))
    .filter(Boolean)
    .sort((a, b) => b.updatedAt - a.updatedAt);
  savedSpellbooks = mergeBuiltInSpellbooks(userSpellbooks);
  return safeLocalStorageSet(SPELLBOOK_STORAGE_KEY, JSON.stringify(userSpellbooks));
}

function createSpellbookId() {
  const random = Math.random().toString(36).slice(2, 8);
  return `spellbook_${Date.now().toString(36)}_${random}`;
}

function getSavedSpellbookById(id) {
  return savedSpellbooks.find(entry => entry.id === id) || null;
}

function getLibraryBuilderDraft() {
  const raw = safeLocalStorageGet(SPELLBOOK_DRAFT_KEY);
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== 'object') return null;
    const casterCardId = typeof parsed.casterCardId === 'string' && CARD_LIBRARY[parsed.casterCardId] ? parsed.casterCardId : null;
    const changingCaster = Boolean(parsed.changingCaster && casterCardId);
    const parsedMode = parsed.mode === 'selectCaster' || parsed.mode === 'build' ? parsed.mode : null;
    return {
      mode: parsedMode || (casterCardId ? 'build' : 'selectCaster'),
      currentSpellbookId: typeof parsed.currentSpellbookId === 'string' ? parsed.currentSpellbookId : null,
      casterCardId,
      changingCaster,
      previousCasterCardId: typeof parsed.previousCasterCardId === 'string' && CARD_LIBRARY[parsed.previousCasterCardId] ? parsed.previousCasterCardId : null,
      spellbookName: typeof parsed.spellbookName === 'string' && parsed.spellbookName.trim() ? parsed.spellbookName.trim().slice(0, 48) : 'Nuevo Spellbook',
      spellbookCards: normalizeSpellbookCardSlots(parsed.spellbookCards),
      elementDistribution: normalizeSpellbookElementDistribution(parsed.elementDistribution),
      elementDistributionConfigured: parsed.elementDistributionConfigured === true,
      page: Math.max(0, Math.min(SPELLBOOK_PAGE_COUNT - 1, Number(parsed.page) || 0)),
    };
  } catch (_) {
    return null;
  }
}

function persistLibraryBuilderDraft() {
  if (libraryBuilderState.mode !== 'build' && libraryBuilderState.mode !== 'selectCaster') return;
  const payload = {
    currentSpellbookId: libraryBuilderState.currentSpellbookId,
    casterCardId: libraryBuilderState.casterCardId,
    changingCaster: libraryBuilderState.changingCaster,
    previousCasterCardId: libraryBuilderState.previousCasterCardId,
    mode: libraryBuilderState.mode,
    spellbookName: libraryBuilderState.spellbookName,
    spellbookCards: normalizeSpellbookCardSlots(libraryBuilderState.spellbookCards),
    elementDistribution: normalizeSpellbookElementDistribution(libraryBuilderState.elementDistribution),
    elementDistributionConfigured: libraryBuilderState.elementDistributionConfigured === true,
    page: libraryBuilderState.page,
    updatedAt: Date.now(),
    schemaVersion: SPELLBOOK_SCHEMA_VERSION,
  };
  safeLocalStorageSet(SPELLBOOK_DRAFT_KEY, JSON.stringify(payload));
}

function clearLibraryBuilderDraft() {
  safeLocalStorageRemove(SPELLBOOK_DRAFT_KEY);
}

function setLibraryBuilderIdle() {
  libraryBuilderState.mode = 'idle';
  libraryBuilderState.currentSpellbookId = null;
  libraryBuilderState.casterCardId = null;
  libraryBuilderState.changingCaster = false;
  libraryBuilderState.previousCasterCardId = null;
  libraryBuilderState.spellbookName = 'Nuevo Spellbook';
  libraryBuilderState.selectedLibraryCardId = null;
  libraryBuilderState.selectedSpellbookIndex = null;
  libraryBuilderState.spellbookCards = Array(SPELLBOOK_MAX_CARDS).fill(null);
  libraryBuilderState.elementDistribution = {};
  libraryBuilderState.elementDistributionConfigured = false;
  libraryBuilderState.page = 0;
}

function beginNewSpellbook() {
  libraryBuilderState.mode = 'selectCaster';
  libraryBuilderState.currentSpellbookId = null;
  libraryBuilderState.casterCardId = null;
  libraryBuilderState.changingCaster = false;
  libraryBuilderState.previousCasterCardId = null;
  libraryBuilderState.spellbookName = 'Nuevo Spellbook';
  libraryBuilderState.selectedLibraryCardId = null;
  libraryBuilderState.selectedSpellbookIndex = null;
  libraryBuilderState.spellbookCards = Array(SPELLBOOK_MAX_CARDS).fill(null);
  libraryBuilderState.elementDistribution = {};
  libraryBuilderState.elementDistributionConfigured = false;
  libraryBuilderState.page = 0;
  persistLibraryBuilderDraft();
}

function restoreLibraryBuilderDraft() {
  const draft = getLibraryBuilderDraft();
  if (!draft) {
    beginNewSpellbook();
    return;
  }
  libraryBuilderState.mode = draft.mode;
  libraryBuilderState.currentSpellbookId = draft.currentSpellbookId;
  libraryBuilderState.casterCardId = draft.casterCardId;
  libraryBuilderState.changingCaster = Boolean(draft.changingCaster);
  libraryBuilderState.previousCasterCardId = draft.previousCasterCardId || null;
  libraryBuilderState.spellbookName = draft.spellbookName;
  libraryBuilderState.spellbookCards = draft.spellbookCards;
  libraryBuilderState.elementDistribution = normalizeSpellbookElementDistribution(draft.elementDistribution);
  libraryBuilderState.elementDistributionConfigured = draft.elementDistributionConfigured === true;
  libraryBuilderState.page = draft.page;
  libraryBuilderState.selectedLibraryCardId = null;
  libraryBuilderState.selectedSpellbookIndex = null;
}

function loadSpellbookIntoBuilder(spellbook) {
  const normalized = normalizeSavedSpellbook(spellbook);
  if (!normalized) {
    setLibraryBuilderIdle();
    return;
  }
  libraryBuilderState.mode = 'build';
  libraryBuilderState.currentSpellbookId = normalized.id;
  libraryBuilderState.casterCardId = normalized.casterCardId;
  libraryBuilderState.changingCaster = false;
  libraryBuilderState.previousCasterCardId = null;
  libraryBuilderState.spellbookName = normalized.name;
  libraryBuilderState.spellbookCards = normalizeSpellbookCardSlots(normalized.cards);
  libraryBuilderState.elementDistribution = normalizeSpellbookElementDistribution(normalized.elementDistribution);
  libraryBuilderState.elementDistributionConfigured = normalized.elementDistributionConfigured === true;
  libraryBuilderState.page = 0;
  libraryBuilderState.selectedLibraryCardId = null;
  libraryBuilderState.selectedSpellbookIndex = null;
  safeLocalStorageSet(SPELLBOOK_ACTIVE_KEY, normalized.id);
  persistLibraryBuilderDraft();
}

function selectLibraryBuilderCaster() {
  const cardId = libraryBuilderState.selectedLibraryCardId;
  const card = CARD_LIBRARY[cardId];
  if (!card || getCardTypeId(card) !== 'kaster') {
    showLibraryBuilderNotice('Selecciona una carta de Kaster primero.');
    return;
  }

  const wasChangingCaster = Boolean(libraryBuilderState.changingCaster);
  const previousCasterId = libraryBuilderState.casterCardId || libraryBuilderState.previousCasterCardId;
  libraryBuilderState.casterCardId = cardId;
  libraryBuilderState.mode = 'build';
  libraryBuilderState.changingCaster = false;
  libraryBuilderState.previousCasterCardId = null;
  if (!wasChangingCaster) {
    libraryBuilderState.spellbookName = `${card.shortName || card.name || 'Nuevo'} Spellbook`;
    libraryBuilderState.elementDistribution = {};
    libraryBuilderState.elementDistributionConfigured = false;
    libraryBuilderState.page = 0;
  }
  libraryBuilderState.selectedLibraryCardId = null;
  libraryBuilderState.selectedSpellbookIndex = null;
  persistLibraryBuilderDraft();

  const incompatibleCount = countIncompatibleBuilderSpellbookCards();
  if (wasChangingCaster && previousCasterId !== cardId) {
    showLibraryBuilderNotice(incompatibleCount
      ? `${card.name} seleccionado. ${incompatibleCount} carta${incompatibleCount === 1 ? '' : 's'} quedó${incompatibleCount === 1 ? '' : 'aron'} marcada${incompatibleCount === 1 ? '' : 's'} con foil rojo por incompatibilidad.`
      : `${card.name} seleccionado. Todas las cartas actuales siguen siendo compatibles.`);
  } else {
    showLibraryBuilderNotice(`${card.name} seleccionado como Kaster del Spellbook.`);
  }
  renderLibraryBuilder();
}

function getCurrentBuilderCaster() {
  return CARD_LIBRARY[libraryBuilderState.casterCardId] || null;
}

function normalizeBuilderMetadataList(value) {
  if (Array.isArray(value)) return value.filter(item => typeof item === 'string' && item);
  if (typeof value === 'string' && value) return [value];
  return [];
}

function builderListsIntersect(left, right) {
  const required = normalizeBuilderMetadataList(right);
  if (!required.length) return true;
  const available = new Set(normalizeBuilderMetadataList(left));
  return required.some(item => available.has(item));
}

function getBuilderEntityProfile(card) {
  if (!card) return null;
  return {
    id: card.id,
    typeId: getCardTypeId(card),
    elementId: getCardElementId(card),
    qualities: normalizeBuilderMetadataList(card.qualities),
    specializations: normalizeBuilderMetadataList(card.allowedInvocationQualities || card.specializations),
    races: normalizeBuilderMetadataList(card.races),
    families: normalizeBuilderMetadataList(card.families || card.family),
    origins: normalizeBuilderMetadataList(card.origins || card.origin),
  };
}

function getBuilderUserRule(card) {
  if (!card || typeof card !== 'object') return null;
  return card.userRules
    || card.userRule
    || card.spellRules?.user
    || card.abilityRules?.user
    || card.casterAbilityRules?.user
    || card.equipmentRules?.user
    || card.structureRules?.user
    || null;
}

function getBuilderPotentialUsers(casterCardId = libraryBuilderState.casterCardId, spellbookCards = libraryBuilderState.spellbookCards) {
  const caster = CARD_LIBRARY[casterCardId];
  const users = [];
  const casterProfile = getBuilderEntityProfile(caster);
  if (casterProfile) users.push(casterProfile);
  normalizeSpellbookCardSlots(spellbookCards).forEach(cardId => {
    const card = CARD_LIBRARY[cardId];
    if (getCardTypeId(card) !== 'invocation') return;
    const profile = getBuilderEntityProfile(card);
    if (profile) users.push(profile);
  });
  return users;
}

function builderEntityMatchesRule(entity, rule) {
  if (!entity || !rule) return false;
  const checks = [];
  const cardTypes = normalizeBuilderMetadataList(rule.cardTypes || rule.userCardTypes || rule.types);
  const elements = normalizeBuilderMetadataList(rule.elements || rule.userElements);
  const qualities = normalizeBuilderMetadataList(rule.qualities || rule.userQualities);
  const races = normalizeBuilderMetadataList(rule.races || rule.userRaces);
  const families = normalizeBuilderMetadataList(rule.families || rule.userFamilies);
  const origins = normalizeBuilderMetadataList(rule.origins || rule.userOrigins);

  if (cardTypes.length) checks.push(cardTypes.includes(entity.typeId));
  if (elements.length) checks.push(elements.includes(entity.elementId));
  if (qualities.length) {
    const availableQualities = entity.typeId === 'kaster'
      ? [...normalizeBuilderMetadataList(entity.qualities), ...normalizeBuilderMetadataList(entity.specializations)]
      : normalizeBuilderMetadataList(entity.qualities);
    checks.push(builderListsIntersect(availableQualities, qualities));
  }
  if (races.length) checks.push(builderListsIntersect(entity.races, races));
  if (families.length) checks.push(builderListsIntersect(entity.families, families));
  if (origins.length) checks.push(builderListsIntersect(entity.origins, origins));
  if (!checks.length) return true;
  return String(rule.requirementMode || rule.matchMode || 'all').toLowerCase() === 'any'
    ? checks.some(Boolean)
    : checks.every(Boolean);
}

function evaluateBuilderUserRule(rule, casterCardId, spellbookCards) {
  if (!rule || rule.mode === 'universal' || rule.mode === 'unrestricted' || rule.mode === 'any') return true;
  const users = getBuilderPotentialUsers(casterCardId, spellbookCards);
  const caster = users.find(user => user.typeId === 'kaster') || null;
  if (!caster) return false;

  const requirementMode = String(rule.requirementMode || rule.matchMode || 'all').toLowerCase();
  const checks = [];
  const casterIds = normalizeBuilderMetadataList(rule.casterIds || rule.kasterIds);
  const casterQualities = normalizeBuilderMetadataList(rule.casterQualities || rule.kasterQualities);
  const casterElements = normalizeBuilderMetadataList(rule.casterElements || rule.kasterElements);
  if (casterIds.length) checks.push(casterIds.includes(caster.id));
  if (casterQualities.length) checks.push(builderListsIntersect(caster.qualities, casterQualities));
  if (casterElements.length) checks.push(casterElements.includes(caster.elementId));

  const hasCasterScopedFields = casterIds.length || casterQualities.length || casterElements.length;
  const hasExplicitInvocationTypes = normalizeBuilderMetadataList(rule.cardTypes || rule.userCardTypes || rule.types).includes('invocation');
  const genericPool = hasCasterScopedFields && !hasExplicitInvocationTypes ? [caster] : users;
  const hasGenericRequirements = [
    rule.cardTypes, rule.userCardTypes, rule.types,
    rule.elements, rule.userElements,
    rule.qualities, rule.userQualities,
    rule.races, rule.userRaces,
    rule.families, rule.userFamilies,
    rule.origins, rule.userOrigins,
  ].some(value => normalizeBuilderMetadataList(value).length);
  if (hasGenericRequirements) checks.push(genericPool.some(user => builderEntityMatchesRule(user, rule)));

  if (!checks.length) return true;
  return requirementMode === 'any' ? checks.some(Boolean) : checks.every(Boolean);
}

function getBuilderCardCompatibility(cardOrId, casterCardId = libraryBuilderState.casterCardId, spellbookCards = libraryBuilderState.spellbookCards) {
  const card = typeof cardOrId === 'string' ? CARD_LIBRARY[cardOrId] : cardOrId;
  const caster = CARD_LIBRARY[casterCardId];
  if (!card) return { compatible: false, reason: 'La carta ya no existe en la Biblioteca.' };
  if (!caster || getCardTypeId(caster) !== 'kaster') return { compatible: false, reason: 'Primero debes seleccionar un Kaster.' };

  const typeId = getCardTypeId(card);
  if (typeId === 'kaster') return { compatible: card.id === casterCardId, reason: 'El Spellbook solo puede tener un Kaster activo.' };

  if (typeId === 'invocation') {
    const casterQualities = normalizeBuilderMetadataList(caster.allowedInvocationQualities || caster.qualities);
    const cardQualities = normalizeBuilderMetadataList(card.qualities);
    const qualityCompatible = casterQualities.length > 0 && builderListsIntersect(cardQualities, casterQualities);
    if (qualityCompatible) return { compatible: true, reason: '' };

    const casterQualityLabels = casterQualities.map(id => getQualityProfile(id)?.label || id).join(', ') || 'ninguna especialización definida';
    const cardQualityLabels = cardQualities.map(id => getQualityProfile(id)?.label || id).join(', ') || 'ninguna cualidad definida';
    return {
      compatible: false,
      reason: `${card.name || card.id} es incompatible porque sus cualidades (${cardQualityLabels}) no coinciden con las especializaciones del Kaster: ${casterQualityLabels}.`,
    };
  }

  const userRule = getBuilderUserRule(card);
  if (!userRule) return { compatible: true, reason: '' };
  const compatible = evaluateBuilderUserRule(userRule, casterCardId, spellbookCards);
  return {
    compatible,
    reason: compatible ? '' : (userRule.description || userRule.label || `${card.name || card.id} no tiene un usuario compatible dentro de este Spellbook.`),
  };
}

function countIncompatibleBuilderSpellbookCards() {
  if (!libraryBuilderState.casterCardId) return 0;
  return libraryBuilderState.spellbookCards.reduce((count, cardId) => {
    if (!cardId) return count;
    return count + (getBuilderCardCompatibility(cardId).compatible ? 0 : 1);
  }, 0);
}

function getSpellbookCardCount(spellbookOrCards) {
  const cards = Array.isArray(spellbookOrCards) ? spellbookOrCards : spellbookOrCards?.cards;
  return (Array.isArray(cards) ? cards : []).filter(Boolean).length;
}

function openCasterChangeModal() {
  if (libraryBuilderState.mode !== 'build' || !getCurrentBuilderCaster()) {
    showLibraryBuilderNotice('Primero selecciona un Kaster.');
    return;
  }
  if (els.casterChangeModal) els.casterChangeModal.setAttribute('aria-hidden', 'false');
}

function closeCasterChangeModal() {
  if (els.casterChangeModal) els.casterChangeModal.setAttribute('aria-hidden', 'true');
}

function beginLibraryBuilderCasterReplacement() {
  const currentCaster = getCurrentBuilderCaster();
  if (!currentCaster || libraryBuilderState.mode !== 'build') {
    closeCasterChangeModal();
    return;
  }
  closeCasterChangeModal();
  libraryBuilderState.mode = 'selectCaster';
  libraryBuilderState.changingCaster = true;
  libraryBuilderState.previousCasterCardId = currentCaster.id;
  libraryBuilderState.selectedLibraryCardId = null;
  libraryBuilderState.selectedSpellbookIndex = null;
  persistLibraryBuilderDraft();
  renderLibraryBuilder();
  showLibraryBuilderNotice('Selecciona el nuevo Kaster. Las cartas actuales se conservarán y se revisarán al confirmar.');
}

function openSpellbookNameModal(mode, spellbook = null) {
  if (!els.spellbookNameModal || !els.spellbookNameInput) return;
  spellbookNameModalState = { mode, spellbookId: spellbook?.id || libraryBuilderState.currentSpellbookId || null };
  const isRename = mode === 'rename';
  if (els.spellbookNameTitle) els.spellbookNameTitle.textContent = isRename ? 'Cambiar nombre' : 'Guardar Spellbook';
  if (els.spellbookNameCopy) els.spellbookNameCopy.textContent = isRename
    ? 'Escribe el nuevo nombre del Spellbook.'
    : 'Primero escribe el nombre. Después configurarás la Fuente elemental.';
  if (els.spellbookNameConfirmBtn) els.spellbookNameConfirmBtn.textContent = isRename ? 'Cambiar nombre' : 'Continuar';
  const initialName = isRename ? (spellbook?.name || '') : (libraryBuilderState.spellbookName || 'Nuevo Spellbook');
  els.spellbookNameInput.value = initialName;
  if (els.spellbookNameError) els.spellbookNameError.textContent = '';
  els.spellbookNameModal.setAttribute('aria-hidden', 'false');
  setTimeout(() => {
    els.spellbookNameInput.focus();
    els.spellbookNameInput.select();
  }, 0);
}

function closeSpellbookNameModal() {
  spellbookNameModalState = null;
  if (els.spellbookNameModal) els.spellbookNameModal.setAttribute('aria-hidden', 'true');
  if (els.spellbookNameError) els.spellbookNameError.textContent = '';
}

function cancelSpellbookNameModal() {
  libraryBuilderExitAfterSave = null;
  closeSpellbookNameModal();
}

function requestSaveCurrentSpellbook() {
  if (libraryBuilderState.mode !== 'build' || !getCurrentBuilderCaster()) {
    showLibraryBuilderNotice('Primero crea un Spellbook y selecciona su Kaster.');
    return false;
  }
  if (isRokUserModeActive()) {
    const collectionIssue = getRokUserSpellbookCollectionIssue({ cards: libraryBuilderState.spellbookCards });
    if (collectionIssue) {
      showLibraryBuilderNotice(collectionIssue);
      return false;
    }
  }
  openSpellbookNameModal('save');
  return true;
}

function confirmSpellbookNameModal() {
  if (!spellbookNameModalState || !els.spellbookNameInput) return;
  const name = els.spellbookNameInput.value.trim().slice(0, 48);
  if (!name) {
    if (els.spellbookNameError) els.spellbookNameError.textContent = 'Escribe un nombre para continuar.';
    return;
  }

  if (spellbookNameModalState.mode === 'rename') {
    const target = getSavedSpellbookById(spellbookNameModalState.spellbookId);
    if (!target) {
      if (els.spellbookNameError) els.spellbookNameError.textContent = 'No se encontró el Spellbook.';
      return;
    }
    target.name = name;
    target.updatedAt = Date.now();
    if (!persistSpellbookStorage()) {
      if (els.spellbookNameError) els.spellbookNameError.textContent = 'El navegador bloqueó el guardado local.';
      return;
    }
    closeSpellbookNameModal();
    renderSpellbooksCollection();
    showSpellbooksCollectionNotice(`“${name}” cambió de nombre.`);
    return;
  }

  closeSpellbookNameModal();
  openSpellbookElementModal(name);
}

function openSpellbookElementModal(name, distribution = null) {
  if (!els.spellbookElementsModal || !els.spellbookElementsRows) return;
  const allowedElementIds = getSpellbookElementOptionIds(libraryBuilderState.casterCardId, libraryBuilderState.spellbookCards);
  const sourceDistribution = distribution || libraryBuilderState.elementDistribution || {};
  spellbookElementModalState = {
    name: String(name || libraryBuilderState.spellbookName || 'Nuevo Spellbook').trim().slice(0, 48),
    spellbookId: libraryBuilderState.currentSpellbookId || null,
    allowedElementIds,
    distribution: normalizeSpellbookElementDistribution(sourceDistribution, allowedElementIds),
  };
  if (els.spellbookElementsError) els.spellbookElementsError.textContent = '';
  renderSpellbookElementModal();
  els.spellbookElementsModal.setAttribute('aria-hidden', 'false');
}

function closeSpellbookElementModal() {
  spellbookElementModalState = null;
  if (els.spellbookElementsModal) els.spellbookElementsModal.setAttribute('aria-hidden', 'true');
  if (els.spellbookElementsError) els.spellbookElementsError.textContent = '';
}

function cancelSpellbookElementModal() {
  libraryBuilderExitAfterSave = null;
  closeSpellbookElementModal();
}

function setSpellbookElementAmount(elementId, requestedAmount) {
  if (!spellbookElementModalState || !spellbookElementModalState.allowedElementIds.includes(elementId)) return;
  const current = spellbookElementModalState.distribution;
  const otherTotal = spellbookElementModalState.allowedElementIds.reduce((sum, id) => id === elementId ? sum : sum + (Number(current[id]) || 0), 0);
  const maxForElement = Math.max(0, SPELLBOOK_ELEMENT_MAX_TOTAL - otherTotal);
  current[elementId] = Math.max(0, Math.min(maxForElement, Math.floor(Number(requestedAmount) || 0)));
  renderSpellbookElementModal();
}

function renderSpellbookElementModal() {
  if (!spellbookElementModalState || !els.spellbookElementsRows) return;
  const state = spellbookElementModalState;
  els.spellbookElementsRows.innerHTML = '';
  state.allowedElementIds.forEach(elementId => {
    const element = getElementById(elementId);
    const amount = Number(state.distribution[elementId]) || 0;
    const row = document.createElement('div');
    row.className = 'spellbook-element-config-row';

    const identity = document.createElement('div');
    identity.className = 'spellbook-element-config-identity';
    const icon = document.createElement('img');
    icon.src = getElementCostIcon(elementId);
    icon.alt = element?.label || elementId;
    const copy = document.createElement('div');
    const label = document.createElement('strong');
    label.textContent = element?.label || elementId;
    const domain = document.createElement('small');
    domain.textContent = elementId === getSpellbookCountedDomainId(libraryBuilderState.casterCardId) ? 'Elemento base del Kaster' : 'Elemento del Spellbook';
    copy.append(label, domain);
    identity.append(icon, copy);

    const stepper = document.createElement('div');
    stepper.className = 'spellbook-element-stepper';
    const minus = document.createElement('button');
    minus.type = 'button';
    minus.textContent = '−';
    minus.disabled = amount <= 0;
    minus.addEventListener('click', () => setSpellbookElementAmount(elementId, amount - 1));
    const input = document.createElement('input');
    input.type = 'number';
    input.min = '0';
    input.max = String(SPELLBOOK_ELEMENT_MAX_TOTAL);
    input.value = String(amount);
    input.inputMode = 'numeric';
    input.setAttribute('aria-label', `Cantidad de ${element?.label || elementId}`);
    input.addEventListener('change', () => setSpellbookElementAmount(elementId, input.value));
    input.addEventListener('keydown', event => {
      if (event.key === 'Enter') {
        event.preventDefault();
        setSpellbookElementAmount(elementId, input.value);
      }
    });
    const plus = document.createElement('button');
    plus.type = 'button';
    plus.textContent = '+';
    plus.disabled = getSpellbookElementTotal(state.distribution) >= SPELLBOOK_ELEMENT_MAX_TOTAL;
    plus.addEventListener('click', () => setSpellbookElementAmount(elementId, amount + 1));
    stepper.append(minus, input, plus);
    row.append(identity, stepper);
    els.spellbookElementsRows.appendChild(row);
  });

  const total = getSpellbookElementTotal(state.distribution);
  if (els.spellbookElementsTotal) {
    els.spellbookElementsTotal.textContent = `${total} / ${SPELLBOOK_ELEMENT_MAX_TOTAL}`;
    els.spellbookElementsTotal.classList.toggle('complete', total === SPELLBOOK_ELEMENT_MAX_TOTAL);
  }
  if (els.spellbookElementsRemaining) els.spellbookElementsRemaining.textContent = `${SPELLBOOK_ELEMENT_MAX_TOTAL - total} disponibles`;
}

function confirmSpellbookElementsModal() {
  if (!spellbookElementModalState) return;
  const pending = {
    name: spellbookElementModalState.name,
    distribution: normalizeSpellbookElementDistribution(spellbookElementModalState.distribution, spellbookElementModalState.allowedElementIds),
  };
  libraryBuilderState.elementDistribution = pending.distribution;
  libraryBuilderState.elementDistributionConfigured = true;
  const warnings = getSpellbookMissingElementWarnings(libraryBuilderState.spellbookCards, pending.distribution);
  closeSpellbookElementModal();
  if (warnings.length) {
    openSpellbookElementWarningModal(pending.name, pending.distribution, warnings);
    return;
  }
  finalizeCurrentSpellbookSave(pending.name, pending.distribution);
}

function openSpellbookElementWarningModal(name, distribution, warnings) {
  spellbookElementWarningModalState = {
    name,
    distribution: normalizeSpellbookElementDistribution(distribution),
    warnings: Array.isArray(warnings) ? warnings : [],
  };
  if (els.spellbookElementWarningList) {
    els.spellbookElementWarningList.innerHTML = '';
    spellbookElementWarningModalState.warnings.forEach(warning => {
      const item = document.createElement('li');
      const missingNames = warning.missingElementIds.map(elementId => getElementById(elementId)?.label || elementId).join(', ');
      item.innerHTML = `<strong>${warning.name}</strong><span>Falta: ${missingNames}</span>`;
      els.spellbookElementWarningList.appendChild(item);
    });
  }
  if (els.spellbookElementWarningCount) {
    const count = spellbookElementWarningModalState.warnings.length;
    els.spellbookElementWarningCount.textContent = `${count} carta${count === 1 ? '' : 's'} no podrá${count === 1 ? '' : 'n'} kastearse con esta distribución.`;
  }
  if (els.spellbookElementWarningModal) els.spellbookElementWarningModal.setAttribute('aria-hidden', 'false');
}

function closeSpellbookElementWarningModal() {
  spellbookElementWarningModalState = null;
  if (els.spellbookElementWarningModal) els.spellbookElementWarningModal.setAttribute('aria-hidden', 'true');
}

function returnToEditFromElementWarning() {
  const pending = spellbookElementWarningModalState;
  if (!pending) return;
  libraryBuilderExitAfterSave = null;
  libraryBuilderState.elementDistribution = normalizeSpellbookElementDistribution(pending.distribution);
  libraryBuilderState.elementDistributionConfigured = true;
  closeSpellbookElementWarningModal();
  persistLibraryBuilderDraft();
  renderLibraryBuilder();
  showLibraryBuilderNotice('Revisa las cartas marcadas en rojo: falta al menos uno de sus elementos en la Fuente.');
}

function saveSpellbookDespiteElementWarnings() {
  const pending = spellbookElementWarningModalState;
  if (!pending) return;
  const { name, distribution } = pending;
  closeSpellbookElementWarningModal();
  finalizeCurrentSpellbookSave(name, distribution, { withWarnings: true });
}

function finalizeCurrentSpellbookSave(name, distribution, options = {}) {
  const now = Date.now();
  const existing = getSavedSpellbookById(libraryBuilderState.currentSpellbookId);
  const saved = normalizeSavedSpellbook({
    id: existing?.id || createSpellbookId(),
    name,
    casterCardId: libraryBuilderState.casterCardId,
    cards: libraryBuilderState.spellbookCards,
    elementDistribution: distribution,
    elementDistributionConfigured: true,
    createdAt: existing?.createdAt || now,
    updatedAt: now,
  });
  if (!saved) {
    showLibraryBuilderNotice('El Spellbook no tiene un Kaster válido.');
    return;
  }
  const existingIndex = savedSpellbooks.findIndex(entry => entry.id === saved.id);
  if (existingIndex >= 0) savedSpellbooks[existingIndex] = saved;
  else savedSpellbooks.push(saved);
  if (!persistSpellbookStorage()) {
    showLibraryBuilderNotice('El navegador bloqueó el guardado local.');
    return;
  }
  libraryBuilderState.currentSpellbookId = saved.id;
  libraryBuilderState.spellbookName = saved.name;
  libraryBuilderState.elementDistribution = normalizeSpellbookElementDistribution(saved.elementDistribution);
  libraryBuilderState.elementDistributionConfigured = true;
  safeLocalStorageSet(SPELLBOOK_ACTIVE_KEY, saved.id);
  persistLibraryBuilderDraft();
  renderLibraryBuilder();
  const suffix = options.withWarnings ? ' con advertencias elementales' : '';
  showLibraryBuilderNotice(`Spellbook “${saved.name}” guardado${suffix} en este navegador.`);
  if (libraryBuilderExitAfterSave) {
    const destination = libraryBuilderExitAfterSave;
    libraryBuilderExitAfterSave = null;
    leaveLibraryBuilderImmediately(destination);
  }
}

function showSpellbooksCollectionNotice(message) {
  if (!els.spellbooksCollectionNotice) return;
  els.spellbooksCollectionNotice.textContent = message || '';
}

function renderSpellbooksCollection() {
  loadSpellbookStorage();
  if (!els.spellbooksCollectionGrid) return;
  els.spellbooksCollectionGrid.innerHTML = '';
  const hasSpellbooks = savedSpellbooks.length > 0;
  if (els.spellbooksCollectionEmpty) els.spellbooksCollectionEmpty.hidden = hasSpellbooks;

  const typeConfigs = [
    { id: 'invocation', label: 'Invocaciones', icon: CARD_TYPE_DB.invocation.icon },
    { id: 'spell', label: 'Hechizos', icon: CARD_TYPE_DB.spell.icon },
    { id: 'ability', label: 'Habilidades', icon: CARD_TYPE_DB.ability.icon },
    { id: 'artifact', label: 'Equipos', icon: CARD_TYPE_DB.artifact.icon },
    { id: 'structure', label: 'Estructuras', icon: CARD_TYPE_DB.structure.icon },
    { id: 'casterAbility', label: 'Habilidades de Kaster', icon: CARD_TYPE_DB.ability.icon, casterIcon: CARD_TYPE_DB.kaster.icon },
  ];

  savedSpellbooks.forEach(spellbook => {
    const caster = CARD_LIBRARY[spellbook.casterCardId];
    if (!caster) return;
    const domains = getSpellbookDomainEntries(spellbook.casterCardId, spellbook.cards);
    const typeCounts = getSpellbookTypeCounts(spellbook);
    const focusTags = getSpellbookFocusSummary(spellbook);
    const battlePoints = getSpellbookBattlePointsTotal(spellbook);
    const elementEntries = getSavedSpellbookElementEntries(spellbook);
    const card = document.createElement('article');
    card.className = 'saved-spellbook-card';
    card.dataset.spellbookId = spellbook.id;
    if (spellbook.builtIn) {
      card.classList.add('built-in');
      card.dataset.spellbookBuiltIn = 'true';
      card.title = 'Spellbook base de prueba incluido con R.O.K Lite.';
    }

    const visual = document.createElement('div');
    visual.className = 'saved-spellbook-caster';

    // La miniatura reutiliza la composición real de las cartas del juego:
    // fondo + arte + skin, sin reconstrucciones visuales paralelas.
    const miniatureCard = createCardElement(caster);
    miniatureCard.classList.add('saved-spellbook-miniature-card');
    visual.appendChild(miniatureCard);

    // Cada dominio usa la misma composición de tres capas de las cartas:
    // fondo del emblema + elemento + atributo central.
    const domainStack = document.createElement('div');
    domainStack.className = 'saved-spellbook-domain-stack';
    domains.slice(0, SPELLBOOK_MAX_DOMAINS).forEach((entry, index) => {
      const domainIcon = document.createElement('span');
      domainIcon.className = `saved-spellbook-domain-emblem ${index === 0 ? 'primary' : 'secondary'}`;
      domainIcon.title = `Dominio: ${entry.profile.elementLabel} · Atributo: ${entry.profile.attributeLabel}${entry.isBase ? ' · dominio base del Kaster' : ''}`;

      const domainBg = document.createElement('span');
      domainBg.className = 'saved-spellbook-domain-layer saved-spellbook-domain-bg';

      const elementArt = document.createElement('img');
      elementArt.className = 'saved-spellbook-domain-layer saved-spellbook-domain-element';
      elementArt.src = entry.profile.elementArt;
      elementArt.alt = `Elemento ${entry.profile.elementLabel}`;

      const attributeArt = document.createElement('img');
      attributeArt.className = 'saved-spellbook-domain-layer saved-spellbook-domain-attribute';
      attributeArt.src = entry.profile.attributeArt;
      attributeArt.alt = `Atributo ${entry.profile.attributeLabel}`;

      domainIcon.append(domainBg, elementArt, attributeArt);
      domainStack.appendChild(domainIcon);
    });
    visual.appendChild(domainStack);

    const info = document.createElement('div');
    info.className = 'saved-spellbook-info';
    const title = document.createElement('h2');
    title.textContent = spellbook.name;
    title.title = spellbook.name;

    const typeRow = document.createElement('div');
    typeRow.className = 'saved-spellbook-type-row';
    typeConfigs.forEach(config => {
      const chip = document.createElement('span');
      chip.className = `saved-spellbook-summary-chip type-${config.id}`;
      chip.title = `${config.label}: ${typeCounts[config.id] || 0}`;
      const iconWrap = document.createElement('span');
      iconWrap.className = 'saved-spellbook-chip-icon';
      const icon = document.createElement('img');
      icon.src = config.icon;
      icon.alt = config.label;
      iconWrap.appendChild(icon);
      if (config.casterIcon) {
        const casterBadge = document.createElement('img');
        casterBadge.className = 'saved-spellbook-chip-caster-badge';
        casterBadge.src = config.casterIcon;
        casterBadge.alt = '';
        iconWrap.appendChild(casterBadge);
      }
      const value = document.createElement('strong');
      value.textContent = String(typeCounts[config.id] || 0);
      chip.append(iconWrap, value);
      typeRow.appendChild(chip);
    });
    const pbChip = document.createElement('span');
    pbChip.className = 'saved-spellbook-pb-chip';
    pbChip.title = `Puntos de Batalla totales: ${battlePoints}`;
    pbChip.innerHTML = `<span>PB</span><strong>${battlePoints}</strong>`;
    typeRow.appendChild(pbChip);

    const distribution = document.createElement('div');
    distribution.className = 'saved-spellbook-element-distribution';
    const distributionLabel = document.createElement('span');
    distributionLabel.className = 'saved-spellbook-section-label';
    distributionLabel.textContent = 'DISTRIBUCIÓN DE ELEMENTOS';
    const distributionRow = document.createElement('div');
    distributionRow.className = 'saved-spellbook-element-row';
    distributionRow.setAttribute('aria-label', spellbook.elementDistributionConfigured ? 'Distribución de elementos configurada' : 'Distribución de elementos pendiente de configurar');
    if (elementEntries.length) {
      elementEntries.forEach(entry => {
        const chip = document.createElement('span');
        chip.className = `saved-spellbook-element-chip element-${entry.id}`;
        chip.title = `${entry.label}: ${entry.amount}`;
        const icon = document.createElement('img');
        icon.src = entry.icon;
        icon.alt = entry.label;
        const amount = document.createElement('strong');
        amount.textContent = String(entry.amount);
        chip.append(icon, amount);
        distributionRow.appendChild(chip);
      });
      const totalChip = document.createElement('span');
      totalChip.className = 'saved-spellbook-element-total-chip';
      totalChip.innerHTML = `<span>TOTAL</span><strong>${getSpellbookElementTotal(spellbook.elementDistribution)}/${SPELLBOOK_ELEMENT_MAX_TOTAL}</strong>`;
      distributionRow.appendChild(totalChip);
    } else if (spellbook.elementDistributionConfigured) {
      const empty = document.createElement('span');
      empty.className = 'saved-spellbook-element-empty';
      empty.textContent = 'Sin elementos asignados';
      distributionRow.appendChild(empty);
    }
    distribution.append(distributionLabel, distributionRow);

    const focus = document.createElement('div');
    focus.className = 'saved-spellbook-focus';
    const focusLabel = document.createElement('span');
    focusLabel.className = 'saved-spellbook-section-label';
    focusLabel.textContent = 'ENFOQUE';
    const focusRow = document.createElement('div');
    focusRow.className = 'saved-spellbook-focus-row';
    focusTags.forEach((tag, index) => {
      const chip = document.createElement('span');
      chip.className = `saved-spellbook-focus-tag ${index === 0 ? 'primary' : ''}`;
      chip.textContent = tag;
      focusRow.appendChild(chip);
    });
    focus.append(focusLabel, focusRow);
    info.append(title, typeRow, distribution, focus);

    const actions = document.createElement('div');
    actions.className = 'saved-spellbook-actions';
    const makeButton = (label, className, handler) => {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = className;
      button.textContent = label;
      button.addEventListener('click', handler);
      return button;
    };
    if (spellbook.builtIn) {
      actions.append(
        makeButton('Duplicar para editar', 'saved-spellbook-action primary', () => duplicateSavedSpellbook(spellbook.id)),
      );
    } else {
      actions.append(
        makeButton('Editar', 'saved-spellbook-action primary', () => openLibraryBuilderScreen({ mode: 'edit', spellbook })),
        makeButton('Duplicar', 'saved-spellbook-action', () => duplicateSavedSpellbook(spellbook.id)),
        makeButton('Cambiar nombre', 'saved-spellbook-action', () => openSpellbookNameModal('rename', spellbook)),
        makeButton('Borrar', 'saved-spellbook-action danger', () => deleteSavedSpellbook(spellbook.id)),
      );
    }

    card.append(visual, info, actions);
    els.spellbooksCollectionGrid.appendChild(card);
  });
}

function duplicateSavedSpellbook(id) {
  const source = getSavedSpellbookById(id);
  if (!source) return;
  const now = Date.now();
  const duplicate = normalizeSavedSpellbook({
    ...source,
    id: createSpellbookId(),
    name: `${source.name} — Copia`,
    cards: [...source.cards],
    elementDistribution: { ...(source.elementDistribution || {}) },
    elementDistributionConfigured: source.elementDistributionConfigured === true,
    builtIn: false,
    readOnly: false,
    createdAt: now,
    updatedAt: now,
  });
  if (!duplicate) return;
  savedSpellbooks.push(duplicate);
  persistSpellbookStorage();
  renderSpellbooksCollection();
  showSpellbooksCollectionNotice(`Se creó “${duplicate.name}”.`);
}

function deleteSavedSpellbook(id) {
  const target = getSavedSpellbookById(id);
  if (!target) return;
  if (target.builtIn) {
    showSpellbooksCollectionNotice('Los Spellbooks base no se borran. Duplica el preset si quieres crear una versión editable.');
    return;
  }
  const accepted = window.confirm(`¿Borrar el Spellbook “${target.name}”? Esta acción no se puede deshacer.`);
  if (!accepted) return;

  // Evita que el modal conserve una carta y una acción pertenecientes al
  // constructor que acaba de quedarse sin Spellbook activo.
  try { closeCardMetaInfo?.(); } catch (_) {}
  try { closeCardInfo?.(); } catch (_) {}

  savedSpellbooks = savedSpellbooks.filter(entry => entry.id !== id);
  persistSpellbookStorage();

  const deletedActiveBuilder = libraryBuilderState.currentSpellbookId === id;
  if (deletedActiveBuilder) setLibraryBuilderIdle();

  if (safeLocalStorageGet(SPELLBOOK_ACTIVE_KEY) === id) safeLocalStorageRemove(SPELLBOOK_ACTIVE_KEY);
  if (safeLocalStorageGet(MATCH_SELECTED_SPELLBOOK_KEY) === id) safeLocalStorageRemove(MATCH_SELECTED_SPELLBOOK_KEY);

  const draft = getLibraryBuilderDraft();
  if (draft?.currentSpellbookId === id) clearLibraryBuilderDraft();

  renderSpellbooksCollection();
  if (document.body.classList.contains('rok-library-mode')) renderLibraryBuilder();
  showSpellbooksCollectionNotice(`“${target.name}” fue borrado.`);
}

const LIBRARY_BUILDER_RARITY_ORDER = ['ordinary', 'uncommon', 'infrequent', 'unusual', 'extraordinary', 'strange', 'singular', 'legendary', 'mythic'];

function normalizeLibraryBuilderSearchText(value = '') {
  return String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim();
}

function getLibraryBuilderCardPower(card) {
  const value = getCardBattlePointsValue(card);
  return Number.isFinite(value) ? value : 0;
}

function getLibraryBuilderCardRarityId(card) {
  try {
    return getCardVisualRarity(card)?.id || normalizeCardRarityId(card?.rarity);
  } catch (_) {
    return normalizeCardRarityId(card?.rarity);
  }
}

function getLibraryBuilderPinnedIds() {
  return libraryBuilderState.mode === 'selectCaster'
    ? ['kasterHanzoDark', 'kasterTokugawaLight', 'kasterKiaraWater']
    : ['ninjaKurayami', 'ninjaMinokageNoKurai', 'ninjaIchikawaGoemon', 'ninjaJunkaiButai1', 'ninjaKurokagiButai3', 'ninjaJunkaiButai2', 'ninjaSaqueadorNovato', 'ninjaYasuganaHattori', 'samuraiTakedaShingen', 'miyamotoMusashi', 'samuraiBushiInquebrantable', 'samuraiBushiIniciado', 'samuraiOSenseiUeshiba', 'samuraiRegenteKishimoto', 'samuraiKaguya', 'samuraiNobunagaOda', 'ninjaOdaNoKage', 'samuraiKarunobuTaicho', 'samuraiShiroNoBushi', 'samuraiShinraHitokiri'];
}

function libraryBuilderCardMatchesCost(card, filterValue) {
  if (!filterValue || filterValue === 'all') return true;
  const total = getCardTotalCost(card);
  if (filterValue === '6plus') return total >= 6;
  return total === Math.max(0, Number(filterValue) || 0);
}

function libraryBuilderCardMatchesPb(card, filterValue) {
  if (!filterValue || filterValue === 'all') return true;
  const pb = getLibraryBuilderCardPower(card);
  if (filterValue === '475plus') return pb >= 475;
  const [minRaw, maxRaw] = String(filterValue).split('-');
  const min = Number(minRaw);
  const max = Number(maxRaw);
  if (!Number.isFinite(min) || !Number.isFinite(max)) return true;
  return pb >= min && pb <= max;
}

function libraryBuilderCardMatchesFilters(card) {
  const filters = libraryBuilderState.libraryFilters || {};
  const typeId = getCardTypeId(card);
  const elementId = getCardElementId(card);
  if (filters.type && filters.type !== 'all' && typeId !== filters.type) return false;
  if (filters.element && filters.element !== 'all' && elementId !== filters.element) return false;
  if (!libraryBuilderCardMatchesCost(card, filters.cost)) return false;
  if (!libraryBuilderCardMatchesPb(card, filters.pb)) return false;
  if (filters.rarity && filters.rarity !== 'all' && getLibraryBuilderCardRarityId(card) !== filters.rarity) return false;

  const query = normalizeLibraryBuilderSearchText(filters.query);
  if (!query) return true;
  const typeLabel = getCardTypeProfile(typeId)?.label || typeId;
  const elementLabel = getElementById(elementId)?.label || elementId;
  const rarityLabel = getCardVisualRarity(card)?.label || '';
  const searchable = normalizeLibraryBuilderSearchText([
    card.name,
    card.shortName,
    card.id,
    typeLabel,
    elementLabel,
    rarityLabel,
    ...(Array.isArray(card.qualities) ? card.qualities : []),
    ...(Array.isArray(card.races) ? card.races : []),
    ...getCardSemanticSearchTerms(card),
  ].filter(Boolean).join(' '));
  return searchable.includes(query);
}

function compareLibraryBuilderCards(a, b) {
  const sortMode = libraryBuilderState.librarySort || 'recommended';
  const nameA = String(a?.name || a?.id || '');
  const nameB = String(b?.name || b?.id || '');
  const typeA = getCardTypeProfile(getCardTypeId(a))?.label || '';
  const typeB = getCardTypeProfile(getCardTypeId(b))?.label || '';
  const elementA = getElementById(getCardElementId(a))?.label || '';
  const elementB = getElementById(getCardElementId(b))?.label || '';
  const costA = getCardTotalCost(a);
  const costB = getCardTotalCost(b);
  const pbA = getLibraryBuilderCardPower(a);
  const pbB = getLibraryBuilderCardPower(b);
  const rarityA = LIBRARY_BUILDER_RARITY_ORDER.indexOf(getLibraryBuilderCardRarityId(a));
  const rarityB = LIBRARY_BUILDER_RARITY_ORDER.indexOf(getLibraryBuilderCardRarityId(b));
  const byName = () => nameA.localeCompare(nameB, 'es', { sensitivity: 'base' });

  if (sortMode === 'nameAsc') return byName();
  if (sortMode === 'nameDesc') return -byName();
  if (sortMode === 'type') return typeA.localeCompare(typeB, 'es') || byName();
  if (sortMode === 'element') return elementA.localeCompare(elementB, 'es') || typeA.localeCompare(typeB, 'es') || byName();
  if (sortMode === 'costAsc') return costA - costB || byName();
  if (sortMode === 'costDesc') return costB - costA || byName();
  if (sortMode === 'pbAsc') return pbA - pbB || byName();
  if (sortMode === 'pbDesc') return pbB - pbA || byName();
  if (sortMode === 'rarityAsc') return rarityA - rarityB || pbA - pbB || byName();
  if (sortMode === 'rarityDesc') return rarityB - rarityA || pbB - pbA || byName();

  const pinnedIds = getLibraryBuilderPinnedIds();
  const pinA = pinnedIds.includes(a.id) ? pinnedIds.indexOf(a.id) : Number.MAX_SAFE_INTEGER;
  const pinB = pinnedIds.includes(b.id) ? pinnedIds.indexOf(b.id) : Number.MAX_SAFE_INTEGER;
  if (pinA !== pinB) return pinA - pinB;
  return typeA.localeCompare(typeB, 'es') || byName();
}

function getLibraryBuilderCards() {
  const mode = libraryBuilderState.mode;
  const creatorMode = isCardCreatorModeActive();
  return Object.values(CARD_LIBRARY || {})
    .filter(card => card && card.id && (!isCatalystCard(card) || card.libraryVisible === true || card.upcoming === true))
    .filter(card => !creatorMode || (CARD_CREATOR_SUPPORTED_TYPES.has(getCardTypeId(card)) && !card.boosterDebugSample))
    .filter(card => {
      const typeId = getCardTypeId(card);
      if (mode === 'selectCaster') return typeId === 'kaster';
      if (mode === 'build') {
        if (typeId === 'kaster') return false;
        return getBuilderCardCompatibility(card).compatible;
      }
      return true;
    })
    .filter(libraryBuilderCardMatchesFilters)
    .sort(compareLibraryBuilderCards);
}

function getLibraryBuilderActiveFilterCount() {
  const filters = libraryBuilderState.libraryFilters || {};
  return [
    normalizeLibraryBuilderSearchText(filters.query),
    filters.type && filters.type !== 'all' ? filters.type : '',
    filters.element && filters.element !== 'all' ? filters.element : '',
    filters.cost && filters.cost !== 'all' ? filters.cost : '',
    filters.pb && filters.pb !== 'all' ? filters.pb : '',
    filters.rarity && filters.rarity !== 'all' ? filters.rarity : '',
  ].filter(Boolean).length;
}

function updateLibraryBuilderControlsUi(cardCount = null) {
  const filters = libraryBuilderState.libraryFilters || {};
  const syncValue = (node, value) => {
    if (node && node.value !== String(value ?? '')) node.value = String(value ?? '');
  };
  syncValue(els.libraryBuilderSearchInput, filters.query || '');
  syncValue(els.libraryBuilderTypeFilter, filters.type || 'all');
  syncValue(els.libraryBuilderElementFilter, filters.element || 'all');
  syncValue(els.libraryBuilderCostFilter, filters.cost || 'all');
  syncValue(els.libraryBuilderPbFilter, filters.pb || 'all');
  syncValue(els.libraryBuilderRarityFilter, filters.rarity || 'all');
  syncValue(els.libraryBuilderSortSelect, libraryBuilderState.librarySort || 'recommended');

  const isOpen = libraryBuilderState.libraryControlsOpen === true;
  if (els.libraryBuilderControlsPanel) els.libraryBuilderControlsPanel.hidden = !isOpen;
  const activeCount = getLibraryBuilderActiveFilterCount();
  const filterButtons = [els.libraryBuilderFilterBtn, els.libraryBuilderFilterToolbarBtn].filter(Boolean);
  const sortButtons = [els.libraryBuilderSortBtn, els.libraryBuilderSortToolbarBtn].filter(Boolean);

  for (const button of filterButtons) {
    button.disabled = false;
    button.classList.remove('planned');
    button.classList.toggle('active', isOpen || activeCount > 0);
    button.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
    button.textContent = activeCount ? `Filtros (${activeCount})` : 'Filtros';
  }
  for (const button of sortButtons) {
    button.disabled = false;
    button.hidden = false;
    button.classList.remove('planned');
    button.classList.toggle('active', isOpen || libraryBuilderState.librarySort !== 'recommended');
    button.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
    button.textContent = 'Ordenar por';
  }
  if (els.libraryBuilderResultCount && Number.isFinite(cardCount)) {
    if (isRokUserModeActive() || isCardCreatorModeActive()) {
      const visibleCards = getLibraryBuilderCards();
      const unlocked = visibleCards.filter(card => isRokUserCardUnlocked(card)).length;
      els.libraryBuilderResultCount.textContent = `${cardCount} visible${cardCount === 1 ? '' : 's'} · ${unlocked} desbloqueada${unlocked === 1 ? '' : 's'}`;
    } else {
      els.libraryBuilderResultCount.textContent = `${cardCount} carta${cardCount === 1 ? '' : 's'} visible${cardCount === 1 ? '' : 's'}`;
    }
  }
}

function setLibraryBuilderControlsOpen(open, focusTarget = '') {
  libraryBuilderState.libraryControlsOpen = Boolean(open);
  updateLibraryBuilderControlsUi();
  if (!libraryBuilderState.libraryControlsOpen) return;
  requestAnimationFrame(() => {
    if (focusTarget === 'sort') els.libraryBuilderSortSelect?.focus();
    else if (focusTarget === 'search') els.libraryBuilderSearchInput?.focus();
  });
}

function updateLibraryBuilderFilter(key, value) {
  if (!libraryBuilderState.libraryFilters) libraryBuilderState.libraryFilters = {};
  libraryBuilderState.libraryFilters[key] = value;
  renderLibraryBuilderLibrary();
}

function clearLibraryBuilderFilters() {
  libraryBuilderState.libraryFilters = {
    query: '',
    type: 'all',
    element: 'all',
    cost: 'all',
    pb: 'all',
    rarity: 'all',
  };
  renderLibraryBuilderLibrary();
  showLibraryBuilderNotice('Filtros de la Biblioteca restablecidos.');
}

function buildLibraryBuilderQuickCostRibbon(card) {
  if (getCardTypeId(card) === 'kaster') return '';
  if (card?.dynamicCost?.display === '?') {
    return `<div class="library-builder-quick-cost dynamic" title="${card.dynamicCost.description || 'Costo variable'}"><span class="library-builder-cost-zero">Costo ?</span></div>`;
  }
  const entries = getCardCostEntries(card)
    .map(([elementId, amount]) => [elementId, Math.max(0, Math.round(Number(amount) || 0))])
    .filter(([, amount]) => amount > 0);
  const total = entries.reduce((sum, [, amount]) => sum + amount, 0);
  const summary = getCardCostSummary(card);
  if (!total) {
    return `<div class="library-builder-quick-cost empty" title="Costo: 0"><span class="library-builder-cost-zero">Costo 0</span></div>`;
  }
  const compact = total >= 6;
  const pieces = entries.map(([elementId, amount]) => {
    const icon = getElementCostIcon(elementId);
    const label = elementId === 'random' ? 'Costo aleatorio' : `Costo ${elementId}`;
    if (compact) {
      return `<span class="library-builder-cost-pack" title="${label}: ${amount}"><img src="${icon}" alt="${label}"><strong>x${amount}</strong></span>`;
    }
    return Array.from({ length: amount }, () => `<span class="library-builder-cost-dot" title="${label}"><img src="${icon}" alt="${label}"></span>`).join('');
  }).join('');
  return `<div class="library-builder-quick-cost ${compact ? 'compact' : 'expanded'}" title="Costo: ${summary}">${pieces}</div>`;
}

function buildGameSpellbookInvocationCostRibbon(card) {
  const gameSpellbookCostTypeId = getCardTypeId(card);
  if (gameSpellbookCostTypeId !== 'invocation' && gameSpellbookCostTypeId !== 'spell') return '';
  if (card?.dynamicCost?.display === '?') {
    return `<div class="game-spellbook-element-cost dynamic" title="${card.dynamicCost.description || 'Costo variable'}"><span class="game-spellbook-cost-zero">?</span></div>`;
  }
  const entries = getEffectiveCardCostEntries(card, LOCAL_PLAYER_ID)
    .map(([elementId, amount]) => [elementId, Math.max(0, Math.round(Number(amount) || 0))])
    .filter(([, amount]) => amount > 0);
  const total = entries.reduce((sum, [, amount]) => sum + amount, 0);
  const summary = getEffectiveCardCostSummary(card, LOCAL_PLAYER_ID);
  if (!total) {
    return `<div class="game-spellbook-element-cost empty" title="Costo: 0"><span class="game-spellbook-cost-zero">0</span></div>`;
  }
  const compact = total >= 7;
  const pieces = entries.map(([elementId, amount]) => {
    const icon = getElementCostIcon(elementId);
    const label = elementId === 'random' ? 'Costo aleatorio' : `Costo ${elementId}`;
    if (compact) {
      return `<span class="game-spellbook-cost-pack" title="${label}: ${amount}"><img src="${icon}" alt="${label}"><strong>x${amount}</strong></span>`;
    }
    return Array.from({ length: amount }, () => `<span class="game-spellbook-cost-dot" title="${label}"><img src="${icon}" alt="${label}"></span>`).join('');
  }).join('');
  return `<div class="game-spellbook-element-cost ${compact ? 'compact' : 'expanded'}" title="Costo: ${summary}">${pieces}</div>`;
}

function buildLibraryBuilderQuickStats(card) {
  const typeId = getCardTypeId(card);
  if (typeId !== 'invocation') return '';
  const weapon = getWeaponProfile(card);
  const attackValue = Math.max(0, Math.round(Number(card?.attackProfile?.damage ?? card?.stats?.damage ?? card?.stats?.atk ?? 0) || 0));
  const lifeValue = Math.max(0, Math.round(Number(card?.stats?.life ?? card?.stats?.def ?? 0) || 0));
  const weaponIcon = weapon?.icon || WEAPON_DB.golpe.icon;
  const weaponLabel = weapon?.label || 'Ataque';
  return `<div class="library-builder-quick-stats" aria-label="Ataque y vida">
    <span class="library-builder-stat-chip attack" title="Ataque: ${weaponLabel} ${attackValue}"><img src="${weaponIcon}" alt="${weaponLabel}"><strong>${attackValue}</strong></span>
    <span class="library-builder-stat-chip life" title="Vida: ${lifeValue}"><span class="unit-heart-icon" aria-hidden="true"></span><strong>${lifeValue}</strong></span>
  </div>`;
}

function createLibraryBuilderCardTile(cardId, origin, index = null) {
  const card = CARD_LIBRARY[cardId];
  const tile = document.createElement('button');
  tile.type = 'button';
  tile.className = 'library-builder-card-tile';
  tile.dataset.origin = origin;
  tile.dataset.cardId = cardId || '';
  if (index !== null) tile.dataset.index = String(index);

  if (!card) {
    tile.classList.add('empty');
    tile.innerHTML = '<span class="library-builder-empty-mark">✦</span>';
    return tile;
  }

  const cardNode = createCardElement(card);
  cardNode.classList.add('library-builder-card-visual');
  const creatorCollectionLocked = Boolean(origin === 'library' && isCardCreatorModeActive() && getRokUserOwnedCopies(card) <= 0);
  const userCollectionLocked = Boolean(origin === 'library' && ((isRokUserModeActive() && !isRokUserCardUnlocked(card)) || creatorCollectionLocked));
  if (userCollectionLocked) {
    tile.classList.add('user-collection-locked');
    tile.dataset.collectionLockReason = `No posees ${card.name || card.id} en tu colección.`;
  }
  if (card.upcoming || card.spellbookLocked) tile.classList.add('upcoming');
  const compatibility = origin === 'spellbook' && libraryBuilderState.casterCardId
    ? getBuilderCardCompatibility(card)
    : { compatible: true, reason: '' };
  const elementWarning = origin === 'spellbook'
    ? getSpellbookElementWarningForCard(card)
    : { incompatible: false, reason: '', missingElementIds: [] };
  const domainStatus = origin === 'library' && libraryBuilderState.mode === 'build'
    ? getBuilderCardDomainStatus(card)
    : { canAdd: true, reason: '' };
  if (!domainStatus.canAdd) {
    tile.classList.add('domain-locked');
    tile.dataset.domainLockReason = domainStatus.reason || `Máximo de ${SPELLBOOK_MAX_DOMAINS} dominios alcanzado.`;
    tile.title = tile.dataset.domainLockReason;
  }
  if (!compatibility.compatible) {
    tile.classList.add('incompatible');
    tile.dataset.incompatibilityReason = compatibility.reason || 'Carta incompatible con el Kaster seleccionado.';
    tile.title = tile.dataset.incompatibilityReason;
  }
  if (elementWarning.incompatible) {
    tile.classList.add('element-incompatible');
    tile.dataset.elementIncompatibilityReason = elementWarning.reason;
    tile.title = elementWarning.reason;
  }
  tile.appendChild(cardNode);
  if (origin === 'library') {
    const quickLayer = document.createElement('div');
    quickLayer.className = 'library-builder-quick-layer';
    quickLayer.innerHTML = `${buildLibraryBuilderQuickStats(card)}${buildLibraryBuilderQuickCostRibbon(card)}`;
    tile.appendChild(quickLayer);
    const traitBadges = createLibraryBuilderTraitBadge(card);
    if (traitBadges) tile.appendChild(traitBadges);
    if (isRokUserModeActive() || isCardCreatorModeActive()) {
      const collectionBadge = document.createElement('span');
      collectionBadge.className = `library-builder-collection-count${userCollectionLocked ? ' locked' : ''}${getCardTypeId(card) === 'kaster' ? ' free' : ''}`;
      if (getCardTypeId(card) === 'kaster') {
        collectionBadge.textContent = 'LIBRE';
        collectionBadge.title = 'Kaster disponible sin booster durante esta etapa.';
      } else {
        const owned = getRokUserOwnedCopies(card);
        collectionBadge.textContent = `×${owned}`;
        collectionBadge.title = `${owned} copia${owned === 1 ? '' : 's'} en tu colección`;
      }
      tile.appendChild(collectionBadge);
    }
  }
  if (!compatibility.compatible) {
    const warning = document.createElement('span');
    warning.className = 'library-builder-incompatible-badge';
    warning.textContent = '!';
    warning.setAttribute('aria-label', 'Carta incompatible');
    tile.appendChild(warning);
  }
  if (elementWarning.incompatible) {
    const elementBadge = document.createElement('span');
    elementBadge.className = 'library-builder-element-warning-badge';
    elementBadge.textContent = 'E';
    elementBadge.setAttribute('aria-label', 'Falta un elemento en la Fuente');
    tile.appendChild(elementBadge);
  }
  if (!domainStatus.canAdd) {
    const domainWarning = document.createElement('span');
    domainWarning.className = 'library-builder-domain-lock-badge';
    domainWarning.textContent = '3D';
    domainWarning.setAttribute('aria-label', `Máximo de ${SPELLBOOK_MAX_DOMAINS} dominios alcanzado`);
    tile.appendChild(domainWarning);
  }

  if (origin === 'library' && libraryBuilderState.selectedLibraryCardId === cardId) tile.classList.add('selected');
  if (origin === 'spellbook' && libraryBuilderState.selectedSpellbookIndex === index) tile.classList.add('selected');

  tile.addEventListener('click', (event) => {
    event.preventDefault();
    event.stopPropagation();
    if (origin === 'library') {
      libraryBuilderState.selectedLibraryCardId = cardId;
      libraryBuilderState.selectedSpellbookIndex = null;
      const selectingCaster = libraryBuilderState.mode === 'selectCaster' && getCardTypeId(card) === 'kaster';
      showLibraryBuilderNotice(isCardCreatorModeActive()
        ? (creatorCollectionLocked
          ? `${card.name || card.id}: no posees una copia para descomponer; Crear sigue disponible si tienes recursos.`
          : `${card.name || card.id} seleccionada · puedes agregarla al mezclador o crear otra copia.`)
        : (userCollectionLocked
          ? `Bloqueada en Modo Usuario: todavía no posees ${card.name || card.id}.`
          : (!domainStatus.canAdd
            ? domainStatus.reason
            : (selectingCaster
              ? `${card.name || card.id} seleccionado. Pulsa Seleccionar Kaster.`
              : `${card.name || card.id} seleccionado en Biblioteca.`))));
      renderLibraryBuilder();
      setTimeout(() => openCardInfo(cardId, null, null, { source: isCardCreatorModeActive() ? 'cardCreator' : 'libraryBuilder', origin }), 0);
      return;
    }
    if (origin === 'spellbook') {
      libraryBuilderState.selectedSpellbookIndex = index;
      libraryBuilderState.selectedLibraryCardId = null;
      showLibraryBuilderNotice(!compatibility.compatible
        ? `Incompatible: ${compatibility.reason}`
        : (elementWarning.incompatible
          ? `Advertencia elemental: ${elementWarning.reason}`
          : `${card.name || card.id} seleccionado en Spellbook.`));
      renderLibraryBuilder();
      setTimeout(() => openCardInfo(cardId, null, null, { source: 'libraryBuilder', origin, spellbookIndex: index }), 0);
    }
  });

  tile.addEventListener('dblclick', (event) => {
    event.preventDefault();
    event.stopPropagation();
    openCardInfo(cardId, null, null, { source: (origin === 'library' && isCardCreatorModeActive()) ? 'cardCreator' : 'libraryBuilder', origin, ...(origin === 'spellbook' ? { spellbookIndex: index } : {}) });
  });

  return tile;
}

function createLibraryBuilderLockedTile() {
  const tile = document.createElement('div');
  tile.className = 'library-builder-card-tile empty locked';
  tile.setAttribute('aria-label', 'Espacio no disponible');
  tile.innerHTML = '<span class="library-builder-empty-mark">×</span><span class="library-builder-locked-label">Límite 30</span>';
  return tile;
}

function renderLibraryBuilder() {
  updateLibraryBuilderModeUi();
  renderLibraryBuilderLibrary();
  renderLibraryBuilderSpellbook();
  updateLibraryBuilderSummary();
  if (isCardCreatorModeActive()) renderCardCreatorWorkshop();
}

function updateLibraryBuilderModeUi() {
  const mode = libraryBuilderState.mode;
  const isIdle = mode === 'idle';
  const isCasterSelection = mode === 'selectCaster';
  const isCasterReplacement = isCasterSelection && libraryBuilderState.changingCaster;
  const isBuild = mode === 'build';
  const caster = getCurrentBuilderCaster();
  const draftExists = Boolean(getLibraryBuilderDraft());

  if (els.libraryBuilderDeckName) {
    els.libraryBuilderDeckName.textContent = isBuild || isCasterReplacement
      ? libraryBuilderState.spellbookName
      : (isCasterSelection ? 'Nuevo Spellbook' : 'Sin Spellbook activo');
  }
  if (els.libraryBuilderLibraryModeTitle) {
    els.libraryBuilderLibraryModeTitle.textContent = isCasterSelection
      ? (isCasterReplacement ? 'Cambiar Kaster' : 'Seleccionar Kaster')
      : (isBuild ? 'Cartas compatibles' : 'Biblioteca general');
  }
  if (els.libraryBuilderLibraryModeCopy) {
    els.libraryBuilderLibraryModeCopy.textContent = isCasterSelection
      ? (isCasterReplacement
        ? 'Elige el nuevo Kaster. Las cartas actuales no se borrarán; las incompatibles quedarán marcadas en rojo.'
        : 'Elige primero el Kaster que utilizará este Spellbook.')
      : (isBuild
        ? (isRokUserModeActive()
          ? `Modo Usuario: solo puedes agregar las copias que posees. El Spellbook admite un máximo de ${SPELLBOOK_MAX_DOMAINS} dominios.`
          : `La Biblioteca muestra cartas compatibles. El Spellbook admite un máximo de ${SPELLBOOK_MAX_DOMAINS} dominios; las cartas de un cuarto dominio permanecen visibles, pero bloqueadas.`)
        : (isRokUserModeActive() ? 'Modo Usuario: las cartas no obtenidas permanecen visibles, pero bloqueadas.' : 'Consulta las cartas o crea un Spellbook nuevo.'));
  }
  if (els.libraryBuilderLibraryTitle) {
    els.libraryBuilderLibraryTitle.textContent = isCasterSelection ? 'Kasters disponibles' : (isBuild ? 'Conjuros compatibles' : 'Todas las cartas existentes');
  }
  if (els.libraryBuilderSpellbookTitle) {
    els.libraryBuilderSpellbookTitle.textContent = isBuild
      ? 'Cartas agregadas'
      : (isCasterSelection ? (isCasterReplacement ? 'Selecciona el nuevo Kaster' : 'Selecciona un Kaster') : 'Ninguno activo');
  }

  if (els.libraryBuilderGate) {
    els.libraryBuilderGate.hidden = isBuild;
    els.libraryBuilderGate.classList.toggle('caster-selection', isCasterSelection);
  }
  if (els.libraryBuilderGateTitle) {
    els.libraryBuilderGateTitle.textContent = isCasterSelection
      ? (isCasterReplacement ? 'Selecciona el nuevo Kaster' : 'Selecciona un Kaster')
      : 'No hay un Spellbook seleccionado';
  }
  if (els.libraryBuilderGateCopy) {
    els.libraryBuilderGateCopy.hidden = !isCasterSelection;
    els.libraryBuilderGateCopy.textContent = isCasterSelection
      ? (isCasterReplacement
        ? 'Selecciona una carta de Kaster y pulsa Cambiar Kaster. El contenido actual se conservará para comprobar su compatibilidad.'
        : 'Selecciona una carta de Kaster en la Biblioteca y pulsa Seleccionar Kaster.')
      : '';
  }
  if (els.libraryBuilderGateCreateBtn) els.libraryBuilderGateCreateBtn.hidden = isCasterSelection;
  if (els.libraryBuilderGateOpenBtn) els.libraryBuilderGateOpenBtn.hidden = isCasterSelection;
  if (els.libraryBuilderGateContinueBtn) {
    els.libraryBuilderGateContinueBtn.hidden = isCasterSelection || !draftExists;
  }

  if (els.libraryBuilderSpellbookGrid) els.libraryBuilderSpellbookGrid.hidden = !isBuild;
  if (els.libraryBuilderPrevPageBtn) els.libraryBuilderPrevPageBtn.disabled = !isBuild || libraryBuilderState.page <= 0;
  if (els.libraryBuilderNextPageBtn) els.libraryBuilderNextPageBtn.disabled = !isBuild || libraryBuilderState.page >= SPELLBOOK_PAGE_COUNT - 1;
  if (els.libraryBuilderPageLabel) els.libraryBuilderPageLabel.textContent = String(libraryBuilderState.page + 1);

  if (els.libraryBuilderAddBtn) {
    els.libraryBuilderAddBtn.textContent = isCasterSelection
      ? (isCasterReplacement ? 'Cambiar Kaster' : 'Seleccionar Kaster')
      : (isBuild ? 'Agregar carta' : 'Crear Spellbook');
    const selectedCard = isBuild ? CARD_LIBRARY[libraryBuilderState.selectedLibraryCardId] : null;
    const selectedCopyStatus = selectedCard && getCardTypeId(selectedCard) !== 'kaster'
      ? getBuilderCardCopyStatus(selectedCard)
      : null;
    const selectedDomainStatus = selectedCard && getCardTypeId(selectedCard) !== 'kaster'
      ? getBuilderCardDomainStatus(selectedCard)
      : null;
    const copyLimitReached = Boolean(selectedCopyStatus && !selectedCopyStatus.canAdd);
    const domainLimitReached = Boolean(selectedDomainStatus && !selectedDomainStatus.canAdd);
    els.libraryBuilderAddBtn.disabled = copyLimitReached || domainLimitReached;
    els.libraryBuilderAddBtn.title = domainLimitReached
      ? selectedDomainStatus.reason
      : (copyLimitReached ? selectedCopyStatus.reason : '');
  }
  if (els.libraryBuilderRemoveBtn) els.libraryBuilderRemoveBtn.disabled = !isBuild;
  if (els.libraryBuilderClearSelectionBtn) els.libraryBuilderClearSelectionBtn.disabled = isIdle;
  if (els.libraryBuilderSaveBtn) els.libraryBuilderSaveBtn.disabled = !isBuild;
  if (els.libraryBuilderTestBtn) els.libraryBuilderTestBtn.disabled = !isBuild;

  if (els.libraryBuilderCasterChip) {
    els.libraryBuilderCasterChip.innerHTML = '';
    const showCasterButton = Boolean(isBuild && caster);
    els.libraryBuilderCasterChip.setAttribute('aria-hidden', showCasterButton ? 'false' : 'true');
    els.libraryBuilderCasterChip.disabled = !showCasterButton;
    if (showCasterButton) {
      const image = document.createElement('img');
      image.src = caster.tokenImage || caster.artImage || 'assets/caster-hanzo.png';
      image.alt = caster.name || 'Kaster';
      const copy = document.createElement('span');
      copy.className = 'library-builder-caster-chip-copy';
      const name = document.createElement('strong');
      name.textContent = caster.shortName || caster.name || 'Kaster';
      const action = document.createElement('small');
      action.textContent = 'Cambiar Kaster';
      copy.append(name, action);
      els.libraryBuilderCasterChip.append(image, copy);
      els.libraryBuilderCasterChip.title = `Cambiar a ${caster.name || 'otro Kaster'}`;
    }
  }

  if (isCardCreatorModeActive()) {
    if (els.libraryBuilderDeckName) els.libraryBuilderDeckName.textContent = 'Recursos del usuario';
    if (els.libraryBuilderDeckSummary) els.libraryBuilderDeckSummary.textContent = 'Descompón copias repetidas o crea nuevas cartas usando Cristal Puro, elementos y rareza.';
    if (els.libraryBuilderLibraryModeTitle) els.libraryBuilderLibraryModeTitle.textContent = 'Creador de Cartas';
    if (els.libraryBuilderLibraryModeCopy) els.libraryBuilderLibraryModeCopy.textContent = 'Las cartas sin copias siguen visibles: no pueden descomponerse, pero sí pueden crearse con recursos.';
    if (els.libraryBuilderLibraryTitle) els.libraryBuilderLibraryTitle.textContent = 'Catálogo de creación';
    if (els.libraryBuilderSpellbookPanel) els.libraryBuilderSpellbookPanel.hidden = true;
    if (els.cardCreatorWorkshopPanel) els.cardCreatorWorkshopPanel.hidden = false;
  } else {
    if (els.cardCreatorWorkshopPanel) els.cardCreatorWorkshopPanel.hidden = true;
    if (els.libraryBuilderSpellbookPanel) els.libraryBuilderSpellbookPanel.hidden = false;
  }
}

function renderLibraryBuilderLibrary() {
  if (!els.libraryBuilderLibraryGrid) return;
  els.libraryBuilderLibraryGrid.innerHTML = '';
  const cards = getLibraryBuilderCards();
  cards.forEach(card => {
    els.libraryBuilderLibraryGrid.appendChild(createLibraryBuilderCardTile(card.id, 'library'));
  });
  if (!cards.length) {
    const empty = document.createElement('div');
    empty.className = 'library-builder-filter-empty';
    empty.innerHTML = '<strong>No hay cartas con esos filtros.</strong><span>Prueba otra combinación o limpia los filtros.</span>';
    els.libraryBuilderLibraryGrid.appendChild(empty);
  }
  updateLibraryBuilderControlsUi(cards.length);
}

function renderLibraryBuilderSpellbook() {
  if (!els.libraryBuilderSpellbookGrid) return;
  els.libraryBuilderSpellbookGrid.innerHTML = '';
  if (libraryBuilderState.mode !== 'build') return;
  const start = libraryBuilderState.page * libraryBuilderState.pageSize;
  for (let i = 0; i < libraryBuilderState.pageSize; i++) {
    const index = start + i;
    if (index >= SPELLBOOK_MAX_CARDS) {
      els.libraryBuilderSpellbookGrid.appendChild(createLibraryBuilderLockedTile());
      continue;
    }
    const cardId = libraryBuilderState.spellbookCards[index] || null;
    els.libraryBuilderSpellbookGrid.appendChild(createLibraryBuilderCardTile(cardId, 'spellbook', index));
  }
}

function updateLibraryBuilderSummary() {
  if (isCardCreatorModeActive()) {
    if (els.libraryBuilderDeckSummary) els.libraryBuilderDeckSummary.textContent = `Mezclador ${cardCreatorState.queue.length}/${CARD_CREATOR_MAX_QUEUE} · crea o descompón cartas usando los recursos de tu perfil.`;
    return;
  }
  const mode = libraryBuilderState.mode;
  if (mode !== 'build') {
    if (els.libraryBuilderDeckSummary) {
      els.libraryBuilderDeckSummary.textContent = mode === 'selectCaster'
        ? (libraryBuilderState.changingCaster
          ? `${libraryBuilderState.spellbookCards.filter(Boolean).length}/${SPELLBOOK_MAX_CARDS} cartas conservadas · selecciona el nuevo Kaster`
          : 'El Kaster debe seleccionarse antes de agregar cartas.')
        : 'Selecciona Crear nuevo Spellbook para comenzar.';
    }
    return;
  }
  const total = libraryBuilderState.spellbookCards.filter(Boolean).length;
  const counts = {};
  libraryBuilderState.spellbookCards.filter(Boolean).forEach(cardId => {
    const card = CARD_LIBRARY[cardId];
    const element = getElementById(getCardElementId(card));
    const label = element?.label || 'Sin elemento';
    counts[label] = (counts[label] || 0) + 1;
  });
  const elementText = Object.entries(counts).map(([label, count]) => `${label}: ${count}`).join(' · ') || 'sin elementos todavía';
  const domainCount = getSpellbookDomainEntries(libraryBuilderState.casterCardId, libraryBuilderState.spellbookCards).length;
  const domainText = `${domainCount}/${SPELLBOOK_MAX_DOMAINS} dominios`;
  const saveStatus = libraryBuilderState.currentSpellbookId ? 'guardado' : 'sin guardar';
  const sourceTotal = getSpellbookElementTotal(libraryBuilderState.elementDistribution);
  const sourceText = libraryBuilderState.elementDistributionConfigured
    ? `Fuente ${sourceTotal}/${SPELLBOOK_ELEMENT_MAX_TOTAL}`
    : 'Fuente sin configurar';
  const elementWarningCount = libraryBuilderState.elementDistributionConfigured
    ? getSpellbookMissingElementWarnings(libraryBuilderState.spellbookCards, libraryBuilderState.elementDistribution).length
    : 0;
  const incompatibleCount = countIncompatibleBuilderSpellbookCards();
  const compatibilityText = incompatibleCount
    ? ` · ⚠ ${incompatibleCount} incompatible${incompatibleCount === 1 ? '' : 's'}`
    : ' · compatibilidad correcta';
  const elementWarningText = elementWarningCount
    ? ` · ⚠ ${elementWarningCount} sin elemento`
    : '';
  if (els.libraryBuilderDeckSummary) {
    els.libraryBuilderDeckSummary.textContent = `${total}/${SPELLBOOK_MAX_CARDS} cartas · ${domainText} · ${elementText} · ${sourceText}${compatibilityText}${elementWarningText} · ${saveStatus}`;
  }
}

function addSelectedLibraryCardToSpellbook() {
  if (libraryBuilderState.mode === 'idle') {
    beginNewSpellbook();
    showLibraryBuilderNotice('Selecciona el Kaster que utilizará el nuevo Spellbook.');
    renderLibraryBuilder();
    return false;
  }
  if (libraryBuilderState.mode === 'selectCaster') {
    selectLibraryBuilderCaster();
    return false;
  }
  const cardId = libraryBuilderState.selectedLibraryCardId;
  if (!cardId || !CARD_LIBRARY[cardId]) {
    showLibraryBuilderNotice('Selecciona una carta de la Biblioteca primero.');
    return false;
  }
  const selectedCard = CARD_LIBRARY[cardId];
  if (getCardTypeId(selectedCard) === 'kaster') {
    showLibraryBuilderNotice('El Kaster se selecciona antes de construir el Spellbook.');
    return false;
  }
  if (selectedCard.upcoming || selectedCard.spellbookLocked) {
    showLibraryBuilderNotice(`${selectedCard.name || cardId} está marcado como Próximamente y todavía no puede agregarse al Spellbook.`);
    return false;
  }
  if (isRokUserModeActive() && !isRokUserCardUnlocked(selectedCard)) {
    showLibraryBuilderNotice(`No puedes agregar ${selectedCard.name || cardId}: todavía no la has obtenido en tu colección.`);
    return false;
  }
  const compatibility = getBuilderCardCompatibility(selectedCard);
  if (!compatibility.compatible) {
    showLibraryBuilderNotice(`No se puede agregar: ${compatibility.reason}`);
    renderLibraryBuilder();
    return false;
  }
  const domainStatus = getBuilderCardDomainStatus(selectedCard);
  if (!domainStatus.canAdd) {
    showLibraryBuilderNotice(domainStatus.reason);
    renderLibraryBuilder();
    return false;
  }
  const copyStatus = getBuilderCardCopyStatus(selectedCard);
  if (!copyStatus.canAdd) {
    showLibraryBuilderNotice(copyStatus.reason);
    renderLibraryBuilder();
    return false;
  }
  const firstEmpty = libraryBuilderState.spellbookCards.findIndex(value => !value);
  if (firstEmpty < 0 || firstEmpty >= SPELLBOOK_MAX_CARDS) {
    showLibraryBuilderNotice(`El Spellbook alcanzó el límite de ${SPELLBOOK_MAX_CARDS} cartas.`);
    return false;
  }
  libraryBuilderState.spellbookCards[firstEmpty] = cardId;
  libraryBuilderState.page = Math.floor(firstEmpty / libraryBuilderState.pageSize);
  libraryBuilderState.selectedSpellbookIndex = firstEmpty;
  persistLibraryBuilderDraft();
  showLibraryBuilderNotice(`${CARD_LIBRARY[cardId].name || cardId} agregada al Spellbook.`);
  renderLibraryBuilder();
  return true;
}

function removeSpellbookCardAtIndex(index) {
  if (libraryBuilderState.mode !== 'build') {
    showLibraryBuilderNotice('No hay un Spellbook activo.');
    return false;
  }
  const normalizedIndex = Number(index);
  if (!Number.isInteger(normalizedIndex) || !libraryBuilderState.spellbookCards[normalizedIndex]) {
    showLibraryBuilderNotice('Esa carta ya no está dentro del Spellbook.');
    return false;
  }
  const cardId = libraryBuilderState.spellbookCards[normalizedIndex];
  libraryBuilderState.spellbookCards[normalizedIndex] = null;
  libraryBuilderState.selectedSpellbookIndex = null;
  persistLibraryBuilderDraft();
  showLibraryBuilderNotice(`${CARD_LIBRARY[cardId]?.name || cardId} eliminada del Spellbook.`);
  renderLibraryBuilder();
  return true;
}

function removeSelectedSpellbookCard() {
  const index = libraryBuilderState.selectedSpellbookIndex;
  if (!Number.isInteger(Number(index)) || !libraryBuilderState.spellbookCards[Number(index)]) {
    showLibraryBuilderNotice('Selecciona una carta del Spellbook para eliminar.');
    return;
  }
  removeSpellbookCardAtIndex(Number(index));
}

function clearLibraryBuilderSelection() {
  libraryBuilderState.selectedLibraryCardId = null;
  libraryBuilderState.selectedSpellbookIndex = null;
  showLibraryBuilderNotice('Selección limpia.');
  renderLibraryBuilder();
}

function changeLibraryBuilderPage(delta) {
  if (libraryBuilderState.mode !== 'build') return;
  const nextPage = Math.max(0, Math.min(SPELLBOOK_PAGE_COUNT - 1, libraryBuilderState.page + delta));
  if (nextPage === libraryBuilderState.page) return;
  libraryBuilderState.page = nextPage;
  libraryBuilderState.selectedSpellbookIndex = null;
  persistLibraryBuilderDraft();
  renderLibraryBuilder();
}


function showLibraryBuilderPlanned(label) {
  showLibraryBuilderNotice(`${label} · previsto`);
}

