  powerCooldown: 10,
  diversion: 15,
  dodgeProjectile: 17,
  evasion: 16,
  criticalHit: 14,
  attackSpeed: 10,
  extraAttack: 25,
  extraWeapon: 18,
  weaponCopy: 28,
  weaponSwitch: 14,
  limitCapacity: 22,
  positioning: 14,
  teleport: 22,
  silence: 25,
  destroy: 32,
  create: 18,
  draw: 15,
